/// The children the two ceiling tests below need, spelled per host. Unix
/// has `/usr/bin/true`, `/usr/bin/false` and `/bin/sleep`; Windows has no
/// `/usr/bin`, so `cmd /c exit <n>` answers the two exit codes and a long
/// `ping` is the child that never exits on its own — ONE process, because
/// `Child::kill` is `TerminateProcess` on the handle it holds, and a
/// `cmd /c` wrapper would die leaving its real sleeper orphaned.
fn exiting_child(code: i32) -> aterm_uds::spawnfd::Command {
    if cfg!(windows) {
        let mut cmd = aterm_uds::spawnfd::command("cmd");
        cmd.args(["/c", &format!("exit {code}")]);
        cmd
    } else {
        aterm_uds::spawnfd::command(if code == 0 {
            "/usr/bin/true"
        } else {
            "/usr/bin/false"
        })
    }
}

/// Ten minutes, past the minute hang detector that judges it: a wait that
/// sat the child out instead of killing it at the ceiling takes that long.
fn never_exiting_child() -> aterm_uds::spawnfd::Command {
    let mut cmd = if cfg!(windows) {
        let mut cmd = aterm_uds::spawnfd::command("ping");
        cmd.args(["-n", "601", "127.0.0.1"]);
        cmd
    } else {
        let mut cmd = aterm_uds::spawnfd::command("/bin/sleep");
        cmd.arg("600");
        cmd
    };
    cmd.stdout(aterm_uds::spawnfd::Stdio::null());
    cmd
}

/// The main thread may never wait on `tccd` without a ceiling. A child that
/// never exits must be killed, reaped, and reported as a DECLINE — never as
/// a success, and never as `ToolAbsent` (the tool did run).
///
/// This is the 2026-08-17 hazard class: WindowServer's main thread sat in a
/// `tccd` preflight for forty seconds and the watchdog took the whole GUI
/// session down. `run_tccutil_reset` runs on the main thread from the
/// Settings reducer, so its wait is bounded by construction.
#[test]
fn a_reset_invocation_can_never_hold_the_main_thread_open_ended() {
    let ceiling = std::time::Duration::from_millis(150);
    let mut child = never_exiting_child()
        .spawn()
        .expect("spawn a child that will not exit on its own");

    let started = std::time::Instant::now();
    let code = wait_bounded(&mut child, ceiling);
    let waited = started.elapsed();

    // A hang detector, never a latency budget: a wait that ignored its
    // ceiling would sit out the child's ten minutes.
    assert!(
        waited < aterm_spec::wait::MUST_HAPPEN,
        "the bounded wait returned after {waited:?}; it must give up at the ceiling"
    );
    // Unix: a signalled child has no exit code. Windows: `Child::kill` is
    // `TerminateProcess(handle, 1)`, so the killed child reports code 1 —
    // still non-zero, still a decline, never a success.
    let killed = if cfg!(windows) { Some(1) } else { None };
    assert_eq!(
        code, killed,
        "a killed child reports what the host's kill leaves, which folds to a decline"
    );
    // The kill must also REAP: a second wait on a reaped child cannot block.
    assert!(
        !ResetAttempt::from_exit_status(Folder::Documents, code).is_reset(),
        "a timed-out invocation must never read as a successful reset"
    );
}

/// A child that exits promptly is reported by its real exit code — the
/// ceiling is a ceiling, not a delay.
///
/// The ceiling HERE is a hang detector, not the product's
/// [`RESET_INVOCATION_CEILING`]: what is proved is that the exit code of
/// a child that exits comes back, and a `/usr/bin/true` that a loaded gate
/// takes more than that 1 s to exec and reap is killed and reads `None`
/// (red under a 24-way CPU load, 2026-09-29). "Not a delay" is asserted
/// against it: a wait that sat out its ceiling before looking would take a
/// whole minute per child.
#[test]
fn a_prompt_invocation_is_reported_by_its_own_exit_code() {
    const CEILING: std::time::Duration = std::time::Duration::from_secs(60);
    let started = std::time::Instant::now();
    let mut ok = exiting_child(0).spawn().expect("spawn the exit-0 child");
    assert_eq!(wait_bounded(&mut ok, CEILING), Some(0));

    let mut bad = exiting_child(1).spawn().expect("spawn the exit-1 child");
    let code = wait_bounded(&mut bad, CEILING);
    assert!(matches!(code, Some(n) if n != 0), "got {code:?}");
    assert!(!ResetAttempt::from_exit_status(Folder::Desktop, code).is_reset());
    let took = started.elapsed();
    // A hang detector: a wait that sat out each ceiling before looking takes
    // two of them, twice this bound.
    assert!(
        took < aterm_spec::wait::MUST_HAPPEN,
        "two prompt children took {took:?}: the ceiling was spent as a delay"
    );
}

fn compile_settings_view(
    runtime: &NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    cx: &ViewCx<'_>,
) -> crate::native_ui::CompiledUi {
    runtime
        .render(instance, view, cx)
        .expect("Settings renders")
        .compile(cx.viewport)
        .expect("Settings compiles")
}

/// The Home page's welcome flourish: on a roomy host the rainbow banner is
/// present with a descriptive semantic label, decorative (no action,
/// unfocusable), and paint-clean; ornamental chrome yields on short hosts
/// and under Serious Mode.
#[test]
fn top_settings_rainbow_banner_present_and_yielding() {
    let key = UiKey::new("settings/top/rainbow");
    let (runtime, instance, view) = setup();
    let cx = view_cx_at(1_200.0, 810.0);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let node = compiled
        .semantic(&key)
        .expect("roomy Home page shows the rainbow banner");
    assert_eq!(node.label, "A rainbow arcs over the settings");
    assert!(node.action.is_none(), "the banner is pure decoration");
    assert_zero_top_paint(&compiled, "rainbow banner at 1200x810 1x");

    // A host below the fit gate keeps today's exact layout.
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_200.0, 700.0));
    assert!(
        compiled.semantic(&key).is_none(),
        "short hosts must not gain the banner"
    );

    // Serious Mode hides the unapologetically playful.
    let mut serious = view_cx_at(1_200.0, 810.0);
    serious.motion = crate::native_app::ViewMotionCx {
        serious: true,
        ..crate::native_app::ViewMotionCx::default()
    };
    let compiled = compile_settings_view(&runtime, instance, view, &serious);
    assert!(
        compiled.semantic(&key).is_none(),
        "Serious Mode must not show the banner"
    );
}

/// Run `rung` once per Dynamic Type scale, each on a thread of its own and
/// ALL AT ONCE, so a sweep's wall is its slowest rung, not the sum of its
/// rungs. Under `cfg(test)` the text scale
/// ([`crate::native_appearance::install_preferences`]) and the chrome font
/// stores are PER THREAD, so a fresh thread is a clean context for one
/// scale and it needs no process of its own — which these rungs used to
/// re-exec the whole test binary for (a 290 MB image started 2-3 times per
/// test: measured 2026-09-30, 0.4-0.6 s of CPU per rung saved). Every
/// thread is joined before anything is asserted, and the failure names
/// every rung that failed with what it panicked with.
fn at_each_text_scale(rungs: &[f32], what: &str, rung: impl Fn(f32) + Sync) {
    let rung = &rung;
    let failed = std::thread::scope(|scope| {
        let runs = rungs
            .iter()
            .map(|&scale| {
                let run = std::thread::Builder::new()
                    .name(format!("{what} at {scale}\u{d7}"))
                    // The main thread's, where each rung used to run.
                    .stack_size(8 << 20)
                    .spawn_scoped(scope, move || {
                        crate::native_appearance::install_preferences(
                            crate::native_appearance::AppearancePreferences {
                                text_scale: scale,
                                ..crate::native_appearance::current_preferences()
                            },
                        );
                        rung(scale);
                    })
                    .unwrap_or_else(|error| panic!("launch {what} at {scale}\u{d7}: {error}"));
                (scale, run)
            })
            .collect::<Vec<_>>();
        runs.into_iter()
            .filter_map(|(scale, run)| {
                let payload = run.join().err()?;
                let said = payload
                    .downcast_ref::<String>()
                    .map(String::as_str)
                    .or_else(|| payload.downcast_ref::<&str>().copied())
                    .unwrap_or("a non-text panic");
                Some(format!("{scale}\u{d7} ({said})"))
            })
            .collect::<Vec<_>>()
    });
    assert!(failed.is_empty(), "{what} failed at {}", failed.join(", "));
}

/// Sample `at` over `from..=to`: every `coarse` points, then bisect each
/// interval whose two ends disagree down to `resolution`, so the samples
/// fall where the answer CHANGES — a threshold — and not where it stays
/// what it was. With `resolution >= coarse` it is the plain uniform sweep.
fn sample_where_it_changes<T: PartialEq + Copy>(
    from: f32,
    to: f32,
    coarse: f32,
    resolution: f32,
    mut at: impl FnMut(f32) -> T,
) {
    let mut points = Vec::new();
    let mut x = from;
    while x <= to {
        points.push((x, at(x)));
        x += coarse;
    }
    let mut open: Vec<((f32, T), (f32, T))> = points
        .windows(2)
        .filter(|pair| pair[0].1 != pair[1].1)
        .map(|pair| (pair[0], pair[1]))
        .collect();
    while let Some(((lo, at_lo), (hi, at_hi))) = open.pop() {
        if hi - lo <= resolution {
            continue;
        }
        let mid = (lo + hi) / 2.0;
        let at_mid = at(mid);
        if at_mid != at_lo {
            open.push(((lo, at_lo), (mid, at_mid)));
        }
        if at_mid != at_hi {
            open.push(((mid, at_mid), (hi, at_hi)));
        }
    }
}

fn assert_zero_top_paint(compiled: &crate::native_ui::CompiledUi, context: &str) {
    compiled
        .validate_parity()
        .unwrap_or_else(|error| panic!("{context}: {error:?}"));
    // The cheap form of the full audit's verdict — zero overflowing text,
    // zero materially clipped nodes, no clip-truncated editor — and the full
    // audit is rendered only to explain a failure.
    let failures = compiled.fit_failures();
    assert!(
        failures.is_empty(),
        "{context}: renderer text overflow or clip:\n{}\n\nfull paint audit:\n{}",
        failures.join("\n"),
        compiled.paint_audit_lines().join("\n")
    );
    for node in compiled
        .semantics
        .iter()
        .filter(|node| node.action.is_some())
    {
        assert!(
            node.rect.x >= compiled.bounds.x - 0.01
                && node.rect.y >= compiled.bounds.y - 0.01
                && node.rect.right() <= compiled.bounds.right() + 0.01
                && node.rect.bottom() <= compiled.bounds.bottom() + 0.01,
            "{context}: actionable {:?} escapes {:?}: {:?}",
            node.key,
            compiled.bounds,
            node.rect
        );
    }
}

fn assert_picker_descendants_contained(
    compiled: &crate::native_ui::CompiledUi,
    key: &str,
    context: &str,
) {
    let picker = compiled
        .semantic(&UiKey::new(format!("settings/choice-picker/{key}")))
        .unwrap_or_else(|| panic!("{context}: missing picker"));
    let contains = |rect: LogicalRect| {
        rect.x >= picker.rect.x - 0.01
            && rect.y >= picker.rect.y - 0.01
            && rect.right() <= picker.rect.right() + 0.01
            && rect.bottom() <= picker.rect.bottom() + 0.01
    };
    for node in compiled.semantics.iter().filter(|node| {
        node.key.as_str().starts_with("settings/choice/")
            || matches!(
                node.key.as_str(),
                "settings/choice-close" | "settings/choice-page-prev" | "settings/choice-page-next"
            )
    }) {
        assert!(
            contains(node.rect),
            "{context}: semantic {:?} escapes picker {:?}: {:?}",
            node.key,
            picker.rect,
            node.rect
        );
    }
    for hit in compiled.hits.iter().filter(|hit| {
        hit.key.as_str().starts_with("settings/choice/")
            || matches!(
                hit.key.as_str(),
                "settings/choice-close" | "settings/choice-page-prev" | "settings/choice-page-next"
            )
    }) {
        assert!(
            contains(hit.rect),
            "{context}: hit {:?} escapes picker {:?}: {:?}",
            hit.key,
            picker.rect,
            hit.rect
        );
    }
}

fn assert_material_hit(compiled: &crate::native_ui::CompiledUi, key: &str, context: &str) {
    let semantic = compiled
        .semantic(&UiKey::new(key))
        .unwrap_or_else(|| panic!("{context}: missing semantic action {key}"));
    assert!(
        semantic.action.is_some(),
        "{context}: {key} lost its semantic action"
    );
    let hit = compiled
        .hits
        .iter()
        .find(|hit| hit.key.as_str() == key)
        .unwrap_or_else(|| panic!("{context}: missing hit region {key}"));
    assert!(
        hit.rect.width >= 20.0 && hit.rect.height >= 20.0,
        "{context}: {key} is not a material hit target: {:?}",
        hit.rect
    );
    assert!(
        hit.rect.x >= compiled.bounds.x - 0.01
            && hit.rect.y >= compiled.bounds.y - 0.01
            && hit.rect.right() <= compiled.bounds.right() + 0.01
            && hit.rect.bottom() <= compiled.bounds.bottom() + 0.01,
        "{context}: {key} hit escapes {:?}: {:?}",
        compiled.bounds,
        hit.rect
    );
}

fn assert_all_hits_material_and_contained(compiled: &crate::native_ui::CompiledUi, context: &str) {
    for hit in &compiled.hits {
        assert!(
            hit.rect.width >= 20.0 && hit.rect.height >= 20.0,
            "{context}: {:?} is not a material hit target: {:?}",
            hit.key,
            hit.rect
        );
        assert!(
            hit.rect.x >= compiled.bounds.x - 0.01
                && hit.rect.y >= compiled.bounds.y - 0.01
                && hit.rect.right() <= compiled.bounds.right() + 0.01
                && hit.rect.bottom() <= compiled.bounds.bottom() + 0.01,
            "{context}: {:?} hit escapes {:?}: {:?}",
            hit.key,
            compiled.bounds,
            hit.rect
        );
    }
}

fn assert_short_landscape_geometry(
    compiled: &crate::native_ui::CompiledUi,
    scale: f32,
    context: &str,
) {
    const WIDTH: f32 = 568.0;
    const HEIGHT: f32 = 320.0;
    compiled
        .validate_parity()
        .unwrap_or_else(|error| panic!("{context}: {error:?}"));
    for semantic in compiled
        .semantics
        .iter()
        .filter(|semantic| semantic.action.is_some())
    {
        assert!(
            semantic.rect.x >= -0.01
                && semantic.rect.y >= -0.01
                && semantic.rect.right() <= WIDTH + 0.01
                && semantic.rect.bottom() <= HEIGHT + 0.01,
            "{context}: actionable semantic {:?} escapes the viewport: {:?}",
            semantic.key,
            semantic.rect
        );
        if scale >= 2.0 {
            assert!(
                semantic.rect.height >= scaled_control_height_at_scale(2.0) - 0.01,
                "{context}: {:?} was clipped below its 2× control allocation: {:?}",
                semantic.key,
                semantic.rect
            );
        }
    }
    for hit in &compiled.hits {
        let paint = compiled
            .paint
            .iter()
            .find(|paint| paint.key == hit.key)
            .unwrap_or_else(|| panic!("{context}: {:?} has no paint", hit.key));
        assert_eq!(paint.rect, hit.rect, "{context}: {:?} hit parity", hit.key);
        assert!(
            hit.rect.x >= -0.01
                && hit.rect.y >= -0.01
                && hit.rect.right() <= WIDTH + 0.01
                && hit.rect.bottom() <= HEIGHT + 0.01,
            "{context}: {:?} escapes the viewport: {:?}",
            hit.key,
            hit.rect
        );
    }
}

fn assert_accessible_pager(
    compiled: &crate::native_ui::CompiledUi,
    key: &str,
    page: usize,
    total: usize,
    context: &str,
) {
    assert!(total > 1);
    let previous = compiled
        .semantic(&UiKey::new(format!("{key}/previous")))
        .unwrap_or_else(|| panic!("{context}: missing accessible Previous"));
    let next = compiled
        .semantic(&UiKey::new(format!("{key}/next")))
        .unwrap_or_else(|| panic!("{context}: missing accessible Next"));
    assert_eq!(
        previous.state.expect("pager state").enabled,
        page > 0,
        "{context}: Previous enabled state"
    );
    assert_eq!(
        next.state.expect("pager state").enabled,
        page + 1 < total,
        "{context}: Next enabled state"
    );
}

fn pager_total(compiled: &crate::native_ui::CompiledUi, status_key: &str) -> usize {
    compiled
        .semantic(&UiKey::new(status_key))
        .unwrap_or_else(|| panic!("missing pager status {status_key}"))
        .label
        .rsplit_once(" of ")
        .and_then(|(_, total)| total.parse::<usize>().ok())
        .unwrap_or_else(|| panic!("invalid pager status {status_key}"))
}

#[test]
fn smart_title_health_is_runtime_backed_and_transport_truthful() {
    let (mut runtime, instance, view) = setup();
    let health = TitleSummaryHealth {
        state: TitleSummaryRuntimeState::Error,
        provider: crate::app_config::TitleSummaryProvider::Ollama,
        model: Some("qwen3.5:4b-q4_K_M".to_string()),
        endpoint: Some("http://127.0.0.1:11434/api/chat".to_string()),
        locality: TitleSummaryLocality::UnattestedLoopback,
        managed_install_present: false,
        model_ready: false,
        last_error: Some("managed runtime is not installed".to_string()),
        next_retry_after: Some(std::time::Duration::from_secs(9)),
        next_refresh_after: None,
        timeout: Some(std::time::Duration::from_secs(42)),
        proxy_mode: Some(crate::app_config::TitleSummaryProxyMode::Direct),
        ca_file: None,
    };
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::WindowTabs);
        assert!(state.replace_title_summary_health(health.clone()));
        assert!(!state.replace_title_summary_health(health));
    }

    let cx = view_cx();
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    let label = |key: &str| {
        compiled
            .semantic(&UiKey::new(format!("settings/smart-titles/health/{key}")))
            .unwrap_or_else(|| panic!("missing Smart Titles health row {key}"))
            .label
            .clone()
    };
    assert!(label("state").contains("Needs attention"));
    assert!(label("locality").contains("not proof of local-only"));
    assert!(label("transport").contains("42s timeout"));
    assert!(label("transport").contains("direct connection (forced)"));
    assert!(label("transport").contains("TLS/CA not used"));
    assert!(
        label("readiness")
            .contains("aterm-managed Ollama not installed (aterm does not download it)")
    );
    assert!(label("readiness").contains("model not confirmed yet"));
    assert!(label("detail").contains("managed runtime is not installed"));
    assert!(label("detail").contains("Error retry"));

    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.replace_title_summary_health(TitleSummaryHealth {
            state: TitleSummaryRuntimeState::Ready,
            provider: crate::app_config::TitleSummaryProvider::OpenAiCompatible,
            model: Some("private-model".to_string()),
            endpoint: Some("https://127.0.0.1:9443/v1/chat/completions".to_string()),
            locality: TitleSummaryLocality::UnattestedLoopback,
            managed_install_present: false,
            model_ready: true,
            last_error: None,
            next_retry_after: None,
            next_refresh_after: Some(std::time::Duration::from_secs(30)),
            timeout: Some(std::time::Duration::from_secs(20)),
            proxy_mode: Some(crate::app_config::TitleSummaryProxyMode::Direct),
            ca_file: Some("/tmp/private-model-ca.pem".to_string()),
        });
    }
    let openai = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    let openai_transport = openai
        .semantic(&UiKey::new("settings/smart-titles/health/transport"))
        .unwrap()
        .label
        .clone();
    assert!(openai_transport.contains("direct connection"));
    assert!(openai_transport.contains("platform roots replaced"));
    let openai_detail = openai
        .semantic(&UiKey::new("settings/smart-titles/health/detail"))
        .unwrap()
        .label
        .clone();
    assert!(openai_detail.contains("Routine activity refresh"));

    for (width, height) in [(320.0, 568.0), (568.0, 320.0)] {
        let compact_cx = view_cx_at(width, height);
        let compact = runtime
            .render(instance, view, &compact_cx)
            .unwrap()
            .compile(compact_cx.viewport)
            .unwrap();
        let keys = if height <= 420.0 {
            vec!["state", "summary"]
        } else {
            vec!["state", "locality", "transport", "readiness", "detail"]
        };
        for key in keys {
            let node = compact
                .semantic(&UiKey::new(format!("settings/smart-titles/health/{key}")))
                .unwrap_or_else(|| panic!("{width}×{height} loses health row {key}"));
            assert!(
                node.rect.bottom() <= compact_cx.viewport.bottom() + 0.01,
                "{width}×{height} clips health row {key}: {:?}",
                node.rect
            );
        }
    }
}

#[test]
fn smart_title_health_never_infers_locality_and_invalidates_on_authority_change() {
    let mut state = SettingsViewState::new(&Config::default());
    state.navigate(SettingsRoute::WindowTabs);
    state.common.last_focus = Some(UiKey::new(format!(
        "settings/control/{}",
        prefs::EDIT_TITLE_SUMMARY_PROVIDER
    )));
    let cx = view_cx();
    let unavailable = settings_tree(
        &state,
        &UpdateState::from_status(1, "0.1.0", None, false).projection(),
        &PackagesState::unobserved().projection(),
        &MessagesState::empty(),
        &cx,
    )
    .compile(cx.viewport)
    .unwrap();
    assert!(
        unavailable
            .semantic(&UiKey::new("settings/smart-titles/health/state"))
            .expect("unavailable headline")
            .label
            .contains("Status unavailable")
    );
    assert!(
        unavailable
            .semantic(&UiKey::new("settings/smart-titles/health/locality"))
            .is_none(),
        "no runtime status: the headline says so once, and no locality is inferred"
    );

    state.replace_title_summary_health(TitleSummaryHealth {
        state: TitleSummaryRuntimeState::Error,
        provider: crate::app_config::TitleSummaryProvider::OpenAiCompatible,
        model: Some("private-model".to_string()),
        endpoint: None,
        locality: TitleSummaryLocality::Remote,
        managed_install_present: false,
        model_ready: false,
        last_error: Some("OpenAI-compatible provider requires an endpoint".to_string()),
        next_retry_after: None,
        next_refresh_after: None,
        timeout: Some(std::time::Duration::from_secs(20)),
        proxy_mode: Some(crate::app_config::TitleSummaryProxyMode::Environment),
        ca_file: None,
    });
    let missing_endpoint = settings_tree(
        &state,
        &UpdateState::from_status(1, "0.1.0", None, false).projection(),
        &PackagesState::unobserved().projection(),
        &MessagesState::empty(),
        &cx,
    )
    .compile(cx.viewport)
    .unwrap();
    assert!(
        missing_endpoint
            .semantic(&UiKey::new("settings/smart-titles/health/locality"))
            .expect("missing-endpoint locality status")
            .label
            .contains("no terminal context was sent")
    );
    assert!(
        missing_endpoint
            .semantic(&UiKey::new("settings/smart-titles/health/transport"))
            .expect("missing-endpoint transport status")
            .label
            .contains("environment proxy + NO_PROXY")
    );

    state.replace_title_summary_health(TitleSummaryHealth {
        state: TitleSummaryRuntimeState::Builtin,
        provider: crate::app_config::TitleSummaryProvider::Builtin,
        model: None,
        endpoint: None,
        locality: TitleSummaryLocality::NotApplicable,
        managed_install_present: false,
        model_ready: false,
        last_error: None,
        next_retry_after: None,
        next_refresh_after: None,
        timeout: None,
        proxy_mode: None,
        ca_file: None,
    });
    let service = VersionedConfigService::new(
        "title_summary_provider = \"openai-compatible\"\n\
         title_summary_endpoint = \"https://models.example.test/v1/chat/completions\"\n\
         title_summary_allow_remote = true\n"
            .to_string(),
    )
    .unwrap();
    state.replace_snapshot(&service.snapshot()).unwrap();
    assert!(
        state.title_summary_health.is_none(),
        "a provider-authority change must retire stale locality/readiness"
    );
}

#[test]
fn maximum_text_scale_keeps_smart_title_health_and_a_control_whole() {
    at_each_text_scale(
        &[2.0],
        "Smart Titles Dynamic Type test",
        maximum_text_scale_keeps_smart_title_health_and_a_control_whole_at_scale,
    );
}

/// [`maximum_text_scale_keeps_smart_title_health_and_a_control_whole`] at 2.0× ([`at_each_text_scale`]).
fn maximum_text_scale_keeps_smart_title_health_and_a_control_whole_at_scale(_scale: f32) {
    let (mut runtime, instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!()
    };
    state.navigate(SettingsRoute::WindowTabs);
    state.replace_title_summary_health(TitleSummaryHealth {
        state: TitleSummaryRuntimeState::Builtin,
        provider: crate::app_config::TitleSummaryProvider::Builtin,
        model: None,
        endpoint: None,
        locality: TitleSummaryLocality::NotApplicable,
        managed_install_present: false,
        model_ready: true,
        last_error: None,
        next_retry_after: None,
        next_refresh_after: Some(std::time::Duration::from_secs(15)),
        timeout: None,
        proxy_mode: None,
        ca_file: None,
    });

    for (width, height) in [(568.0, 320.0), (320.0, 420.0), (320.0, 568.0)] {
        let cx = view_cx_at(width, height);
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        compiled.validate_parity().unwrap();
        let health = compiled
            .semantic(&UiKey::new("settings/smart-titles/health"))
            .expect("Smart Titles health remains visible");
        let health_paint = compiled
            .paint
            .iter()
            .find(|paint| paint.key == health.key)
            .expect("Smart Titles health has authored paint geometry");
        assert_eq!(
            health_paint.rect, health.rect,
            "{width}×{height} partially clips Smart Titles health"
        );
        assert!(
            health.rect.bottom() <= height + 0.01,
            "{width}×{height} clips Smart Titles health: {:?}",
            health.rect
        );
        let controls = compiled
            .semantics
            .iter()
            .filter(|node| node.key.as_str().starts_with("settings/control/"))
            .collect::<Vec<_>>();
        assert!(
            !controls.is_empty(),
            "{width}×{height} must retain a real Window & Tabs control"
        );
        for control in controls {
            let paint = compiled
                .paint
                .iter()
                .find(|paint| paint.key == control.key)
                .unwrap_or_else(|| panic!("{} has paint geometry", control.key.as_str()));
            let hit = compiled
                .hits
                .iter()
                .find(|hit| hit.key == control.key)
                .unwrap_or_else(|| panic!("{} has hit geometry", control.key.as_str()));
            assert_eq!(
                paint.rect,
                control.rect,
                "{width}×{height} partially clips {}",
                control.key.as_str()
            );
            assert_eq!(
                hit.rect,
                control.rect,
                "{width}×{height} hit geometry diverges for {}",
                control.key.as_str()
            );
            assert!(
                control.rect.bottom() <= height + 0.01,
                "{width}×{height} clips {}: {:?}",
                control.key.as_str(),
                control.rect
            );
        }
    }
}

