#[test]
fn page_subtitles_fit_compact_and_minimum_medium_content_measure() {
    crate::tray_raster::prepare_ui_fonts_for_direct_view_test();
    let mut copies = SettingsRoute::ALL
        .into_iter()
        .filter(|route| route.section().is_some())
        .map(|route| settings_fields_subtitle(route, SettingsWidth::Compact, false, false))
        .filter(|copy| !copy.is_empty())
        .collect::<Vec<_>>();
    copies.extend([
        settings_fields_subtitle(
            SettingsRoute::Appearance,
            SettingsWidth::Compact,
            true,
            false,
        ),
        settings_fields_subtitle(SettingsRoute::Modified, SettingsWidth::Compact, false, true),
        update_page_subtitle(SettingsWidth::Compact, true),
        update_page_subtitle(SettingsWidth::Compact, false),
        packages_page_subtitle(SettingsWidth::Compact),
        messages_page_subtitle(SettingsWidth::Compact),
    ]);
    for copy in copies {
        let measured = crate::tray_raster::ui_text_width(copy, 13.0);
        assert!(
            measured <= 254.5,
            "compact subtitle overflows the 286.5pt phone page: {copy:?} is {measured:.1}pt",
        );
    }

    let mut medium_copies = SettingsRoute::ALL
        .into_iter()
        .filter(|route| route.section().is_some())
        .map(|route| settings_fields_subtitle(route, SettingsWidth::Medium, false, false))
        .filter(|copy| !copy.is_empty())
        .collect::<Vec<_>>();
    medium_copies.extend([
        settings_fields_subtitle(
            SettingsRoute::Appearance,
            SettingsWidth::Medium,
            true,
            false,
        ),
        settings_fields_subtitle(SettingsRoute::Modified, SettingsWidth::Medium, false, true),
        update_page_subtitle(SettingsWidth::Medium, true),
        update_page_subtitle(SettingsWidth::Medium, false),
        packages_page_subtitle(SettingsWidth::Medium),
        messages_page_subtitle(SettingsWidth::Medium),
    ]);
    for copy in medium_copies {
        let measured = crate::tray_raster::ui_text_width(copy, 13.0);
        assert!(
            measured <= 516.5,
            "Medium subtitle overflows the minimum 516pt content page: {copy:?} is {measured:.1}pt",
        );
    }
}

/// A live packages snapshot exactly as the host builds one: through the
/// service reducer (begin → worker report → finish), never hand-assembled.
fn live_packages_state(busy: Option<crate::packages_screen::PackagesBusy>) -> PackagesState {
    live_packages_state_with_policy(busy, true, true, true)
}

fn live_packages_state_with_policy(
    busy: Option<crate::packages_screen::PackagesBusy>,
    master_enabled: bool,
    auto_install: bool,
    loop_running: bool,
) -> PackagesState {
    let mut programs = std::collections::BTreeMap::new();
    programs.insert(
        "ay".to_string(),
        atpkg::ProgramStatus {
            installed_build: Some(1971),
            state: "active".to_string(),
            tree_root: String::new(),
        },
    );
    let status = atpkg::Status {
        schema: 1,
        updated_at: "2026-07-21T00:00:00Z".to_string(),
        enabled: true,
        index_source: "alabsystems/aterm".to_string(),
        outcome: "up to date".to_string(),
        seams: Vec::new(),
        last_success_at: String::new(),
        last_index_build: 0,
        index_build_changed_at: String::new(),
        last_pass: String::new(),
        last_pass_at: String::new(),
        last_pass_attempted_index_build: 0,
        last_pass_attempted_at: String::new(),
        pass_seq: 0,
        stale_index_only_pass_seq: 0,
        programs,
        extra: Default::default(),
    };
    let mut service = crate::packages_screen::PackagesService::new();
    let sequence = service.begin(None).unwrap();
    assert!(service.finish(
        sequence,
        crate::packages_screen::PackagesWorkerCompletion::refresh(
            crate::packages_screen::PackagesStatusReport::from_parts(
                true,
                true,
                "fp".to_string(),
                Some(&status),
                &[],
            ),
        ),
    ));
    if busy.is_some() {
        let _ = service.begin(busy).unwrap();
    }
    service.state(master_enabled, auto_install, loop_running)
}

/// A live packages snapshot whose machine read has ALSO completed — the exact
/// path the host takes (`replace_machine_state` after the status worker), so
/// the card is fed the way it is fed in production.
fn live_packages_state_with_machine(
    busy: Option<crate::packages_screen::PackagesBusy>,
    machine: Result<atpkg::machine::MachineState, String>,
) -> PackagesState {
    live_packages_state_with_machine_reads(busy, true, None, vec![machine])
}

/// The general form: `manager_enabled` and a collection error seed the report
/// (the package-manager gate), and `reads` are reduced in order — so a read
/// error AFTER a good record is built the way the host builds it.
fn live_packages_state_with_machine_reads(
    busy: Option<crate::packages_screen::PackagesBusy>,
    manager_enabled: bool,
    collection_error: Option<&str>,
    reads: Vec<Result<atpkg::machine::MachineState, String>>,
) -> PackagesState {
    let mut programs = std::collections::BTreeMap::new();
    programs.insert(
        "ay".to_string(),
        atpkg::ProgramStatus {
            installed_build: Some(1971),
            state: "active".to_string(),
            tree_root: String::new(),
        },
    );
    let status = atpkg::Status {
        schema: 1,
        updated_at: "2026-07-21T00:00:00Z".to_string(),
        enabled: true,
        index_source: "alabsystems/aterm".to_string(),
        outcome: "up to date".to_string(),
        seams: Vec::new(),
        last_success_at: String::new(),
        last_index_build: 0,
        index_build_changed_at: String::new(),
        last_pass: String::new(),
        last_pass_at: String::new(),
        last_pass_attempted_index_build: 0,
        last_pass_attempted_at: String::new(),
        pass_seq: 0,
        stale_index_only_pass_seq: 0,
        programs,
        extra: Default::default(),
    };
    let mut service = crate::packages_screen::PackagesService::new();
    let sequence = service.begin(None).unwrap();
    let mut report = crate::packages_screen::PackagesStatusReport::from_parts(
        true,
        manager_enabled,
        "fp".to_string(),
        Some(&status),
        &[],
    );
    report.collection_error = collection_error.map(str::to_string);
    assert!(service.finish(
        sequence,
        crate::packages_screen::PackagesWorkerCompletion::refresh(report),
    ));
    for read in reads {
        let _ = service.replace_machine_state(read);
    }
    if busy.is_some() {
        let _ = service.begin(busy).unwrap();
    }
    service.state(true, true, true)
}

fn machine_state_fixture(
    uc: atpkg::machine::UcPosture,
    would_migrate: usize,
    home: atpkg::machine::HomePosture,
) -> atpkg::machine::MachineState {
    atpkg::machine::MachineState {
        universal_control: uc,
        policy: atpkg::config::UniversalControlPolicy::Off,
        spotlight_noindex: true,
        exposed: would_migrate + 1,
        hidden: 8,
        would_migrate,
        scan_complete: true,
        home,
        config_unreadable: false,
        open: None,
    }
}

fn failed_packages_state() -> PackagesState {
    let mut service = crate::packages_screen::PackagesService::new();
    let old = crate::packages_screen::PackagesStatusReport::from_parts(
        true,
        true,
        "fp".to_string(),
        Some(&atpkg::Status {
            schema: 1,
            updated_at: "2026-07-20T00:00:00Z".to_string(),
            enabled: true,
            index_source: "alabsystems/aterm".to_string(),
            outcome: "up to date".to_string(),
            seams: Vec::new(),
            last_success_at: String::new(),
            last_index_build: 0,
            index_build_changed_at: String::new(),
            last_pass: String::new(),
            last_pass_at: String::new(),
            last_pass_attempted_index_build: 0,
            last_pass_attempted_at: String::new(),
            pass_seq: 0,
            stale_index_only_pass_seq: 0,
            programs: std::collections::BTreeMap::new(),
            extra: Default::default(),
        }),
        &[],
    );
    let observed = service.begin(None).unwrap();
    assert!(service.finish(
        observed,
        crate::packages_screen::PackagesWorkerCompletion::refresh(old.clone())
    ));
    let sequence = service
        .begin(Some(crate::packages_screen::PackagesBusy::Check))
        .unwrap();
    assert!(service.finish(
        sequence,
        crate::packages_screen::PackagesWorkerCompletion::command(
            old,
            crate::packages_screen::PackagesCommandOutcome::Failed {
                operation: crate::packages_screen::PackagesBusy::Check,
                message: "atpkg update exited with status 7".to_string(),
            },
        )
    ));
    service.state(true, true, true)
}

/// The Packages route is a first-class destination: rail entry, special
/// page with both action buttons, the maintenance switches, the program list,
/// and the contextual command all derive from one route + one projection.
#[test]
fn packages_route_renders_status_actions_switches_and_programs() {
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(live_packages_state(None), 2));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Packages),
                value: None,
            }),
        )
        .unwrap();
    let cx = view_cx();
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    compiled.validate_parity().unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new("settings/page/packages"))
            .is_some(),
        "the /packages route owns its own page"
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/nav/packages"))
            .is_some(),
        "the rail exposes the Packages destination"
    );
    for key in ["packages/check", "packages/install-default"] {
        let control = compiled
            .semantic(&UiKey::new(key))
            .unwrap_or_else(|| panic!("{key} button renders"));
        assert!(
            control.state.is_none_or(|state| state.enabled),
            "{key} is enabled on a live manager"
        );
        assert!(
            compiled.hits.iter().any(|hit| hit.key.as_str() == key),
            "{key} is activatable"
        );
    }
    for key in PACKAGES_PAGE_SWITCHES {
        assert!(
            compiled
                .semantic(&UiKey::new(format!("settings/control/{key}")))
                .is_some(),
            "the {key} consent switch renders on the special page"
        );
    }
    // ONE switch for updates (Phase 4; 2026-09-23): the retired `auto_update` is no
    // second one on the page — it is folded into "Automatic updates".
    for retired in ["packages.auto_update", "packages.seed_install"] {
        assert!(
            compiled
                .semantic(&UiKey::new(format!("settings/control/{retired}")))
                .is_none(),
            "{retired} is retired: no row of its own"
        );
    }
    let tray = compiled.tray(aterm_render::Theme::default(), 13.0);
    for (key, visible_label) in [
        (prefs::EDIT_PACKAGES_ENABLED, "Automatic updates"),
        (prefs::EDIT_PACKAGES_AUTO_INSTALL, "Install ALab tools"),
    ] {
        assert_eq!(
            compiled
                .semantic(&UiKey::new(format!("settings/label/{key}")))
                .map(|node| node.label.as_str()),
            Some(visible_label),
            "the {key} semantic switch label must also have a visible text node"
        );
        assert!(
            tray.prims.iter().any(|prim| matches!(
                prim,
                crate::widget::DrawPrim::Text { s, .. } if s == visible_label
            )),
            "the {key} label must survive lowering into the pixel tray"
        );
    }
    // The program card rides the first card page when it fits and the next one when it
    // does not: whole cards are packed into pages the content height holds
    // (`pack_card_pages`), and three switch rows beside the Activity card (the merge of
    // the one-path switches with Phase 4's page) move it on at this size.
    let seen = packages_page_semantics(&mut runtime, instance, view, &cx);
    assert!(
        seen.iter().any(|(key, _)| key == "packages/programs/ay"),
        "installed programs render as read-only rows"
    );

    let commands = runtime.commands(instance, view).unwrap();
    assert!(
        commands.iter().any(|command| command.id.as_str()
            == format!("settings/route{}", SettingsRoute::Packages.path())),
        "the route loop exports Go to Packages"
    );
    let check = commands
        .iter()
        .find(|command| command.id.as_str() == "packages/check")
        .expect("contextual packages/check command on the Packages route");
    assert!(check.enabled);
}

/// atpkg's whole-toolset pseudo-row is spelled `*toolset*` in its status
/// ledger; the native page must present the product name, never literal
/// Markdown-style asterisks (2026-08 settings audit). The raw name stays
/// in the node key so the row's identity is stable across renames.
#[test]
fn packages_toolset_pseudo_row_paints_its_product_name_without_asterisks() {
    let mut programs = std::collections::BTreeMap::new();
    programs.insert(
        "*toolset*".to_string(),
        atpkg::ProgramStatus {
            installed_build: None,
            state: "unavailable: no build for this architecture".to_string(),
            tree_root: String::new(),
        },
    );
    let status = atpkg::Status {
        schema: 1,
        updated_at: "2026-08-22T00:00:00Z".to_string(),
        enabled: true,
        index_source: "alabsystems/aterm".to_string(),
        outcome: "up to date".to_string(),
        seams: Vec::new(),
        last_success_at: String::new(),
        last_index_build: 0,
        index_build_changed_at: String::new(),
        last_pass: String::new(),
        last_pass_at: String::new(),
        last_pass_attempted_index_build: 0,
        last_pass_attempted_at: String::new(),
        pass_seq: 0,
        stale_index_only_pass_seq: 0,
        programs,
        extra: Default::default(),
    };
    let mut service = crate::packages_screen::PackagesService::new();
    let sequence = service.begin(None).unwrap();
    assert!(service.finish(
        sequence,
        crate::packages_screen::PackagesWorkerCompletion::refresh(
            crate::packages_screen::PackagesStatusReport::from_parts(
                true,
                true,
                "fp".to_string(),
                Some(&status),
                &[],
            ),
        ),
    ));
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(service.state(true, true, true), 2));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Packages),
                value: None,
            }),
        )
        .unwrap();
    let cx = view_cx();
    // Whichever card page carries the program list (`pack_card_pages`).
    let seen = packages_page_semantics(&mut runtime, instance, view, &cx);
    let row = seen
        .iter()
        .find(|(key, _)| key == "packages/programs/*toolset*")
        .map(|(_, label)| label)
        .expect("the pseudo-row keeps its raw-name key");
    assert!(
        row.starts_with("ALab tools")
            && row.contains("unavailable: no build for this architecture"),
        "the toolset meta-row names the product: {row}"
    );
    assert!(
        !row.contains('*'),
        "no literal ledger asterisks reach the page: {row}"
    );
    assert_eq!(package_program_display_name("*toolset*"), "ALab tools");
    assert_eq!(package_program_display_name("*beta*"), "beta");
    assert_eq!(package_program_display_name("ay"), "ay");
    assert_eq!(package_program_display_name("*"), "*");
}

/// THE PACKAGES BADGE ON THE SETTINGS RAIL (2026-09-22): a toolchain
/// failure's one surface is Settings, so while the Packages projection names
/// one the rail's Packages entry wears the dot and SAYS it — its semantic value
/// is the page's own headline words, so the dot is never the only carrier —
/// and no other entry does; once the condition clears, neither remains.
#[test]
fn the_packages_rail_entry_wears_the_badge_while_a_failure_is_named() {
    let (mut runtime, instance, view) = setup();
    let rail = |runtime: &NativeRuntime| {
        let cx = view_cx();
        let compiled = compile_settings_view(runtime, instance, view, &cx);
        SettingsRoute::ALL
            .into_iter()
            .map(|route| {
                let key = UiKey::new(format!("settings/nav{}", route.path()));
                let value = compiled
                    .semantic(&key)
                    .unwrap_or_else(|| panic!("{} is on the rail", route.label()))
                    .value
                    .clone();
                let badge = compiled.paint.iter().any(|node| {
                    node.key == key && matches!(&node.content, UiContent::Button(c) if c.spec.badge)
                });
                (route, value, badge)
            })
            .collect::<Vec<_>>()
    };
    assert!(runtime.replace_settings_packages(
        packages_state_with_program_state("error: ay stage failed: no space left on device"),
        2,
    ));
    for (route, value, badge) in rail(&runtime) {
        if route == SettingsRoute::Packages {
            assert!(badge, "the Packages entry wears the dot");
            assert_eq!(
                value,
                SemanticValue::Text("Needs attention: ay failed".to_string()),
                "…and says it"
            );
        } else {
            assert!(!badge && value == SemanticValue::None, "{}", route.label());
        }
    }
    assert!(runtime.replace_settings_packages(
        packages_state_with_program_state(&atpkg::state::managed(1971, 44)),
        3,
    ));
    for (route, value, badge) in rail(&runtime) {
        assert!(
            !badge && value == SemanticValue::None,
            "{}: cleared, the badge is gone",
            route.label()
        );
    }
}

/// The danger dots a compiled Settings view PAINTS, as centres.
fn painted_badge_dots(compiled: &crate::native_ui::CompiledUi) -> Vec<(f32, f32)> {
    let theme = aterm_render::Theme::default();
    let danger = crate::settings::Roles::from_theme(theme).danger;
    compiled
        .tray(theme, 13.0)
        .prims
        .iter()
        .filter_map(|p| match p {
            crate::widget::DrawPrim::Dot { cx, cy, color, .. } if color[..3] == danger => {
                Some((*cx, *cy))
            }
            _ => None,
        })
        .collect()
}

/// The compact categories page, compiled on the page that shows `route`.
fn compact_categories_showing(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    route: SettingsRoute,
) -> crate::native_ui::CompiledUi {
    let cx = view_cx_at(568.0, 900.0);
    let key = UiKey::new(format!("settings/categories{}", route.path()));
    for page in 0..SettingsRoute::ALL.len() {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.compact_navigation = true;
        state.page_scroll = page;
        let compiled = compile_settings_view(runtime, instance, view, &cx);
        if compiled.semantic(&key).is_some() {
            return compiled;
        }
    }
    panic!("{} is on no page of the compact categories", route.label());
}

/// THE BADGE ON THE COMPACT CATEGORIES PAGE (review, 2026-09-22) — the second
/// place the Packages entry is drawn, a full-width row whose spec also carries a
/// Forward chevron: it wears the dot and says it, and the glass shows exactly
/// one dot, inside that row and at its end, and none once the failure clears.
#[test]
fn the_compact_categories_page_wears_the_packages_badge() {
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(
        packages_state_with_program_state("error: ay stage failed: no space left on device"),
        2,
    ));
    let compiled =
        compact_categories_showing(&mut runtime, instance, view, SettingsRoute::Packages);
    let key = UiKey::new(format!(
        "settings/categories{}",
        SettingsRoute::Packages.path()
    ));
    let node = compiled
        .paint
        .iter()
        .find(|node| node.key == key)
        .expect("the Packages row is painted");
    assert!(
        matches!(&node.content, UiContent::Button(c) if c.spec.badge
            && c.spec.trailing_icon == Some(ButtonIcon::Forward)),
        "the chevron row wears the badge"
    );
    assert_eq!(
        compiled.semantic(&key).expect("semantics").value,
        SemanticValue::Text("Needs attention: ay failed".to_string()),
    );
    let dots = painted_badge_dots(&compiled);
    assert_eq!(dots.len(), 1, "one dot on the glass: {dots:?}");
    let (x, y) = dots[0];
    assert!(
        node.rect.contains(x, y) && x > node.rect.x + node.rect.width * 0.75,
        "inside the Packages row, at its end: ({x}, {y}) in {:?}",
        node.rect
    );
    assert!(runtime.replace_settings_packages(
        packages_state_with_program_state(&atpkg::state::managed(1971, 44)),
        3,
    ));
    let compiled =
        compact_categories_showing(&mut runtime, instance, view, SettingsRoute::Packages);
    assert!(painted_badge_dots(&compiled).is_empty(), "cleared");
}

/// VISUAL CAPTURE of the Packages badge — the wide and medium rails and the
/// compact categories page — dumped as PNGs so the dot can be read as PIXELS
/// (read back 2026-09-22: one dot past the label on each, clear of the text). Not a gate: `#[ignore]`d (it needs a real UI face) and asserted
/// only for "it produced a frame".
///
/// ```sh
/// SETTINGS_BADGE_PNG_DIR=/tmp/badge targo --unverified test -p aterm-gui --lib \
///     settings_badge_visual_capture -- --ignored --nocapture
/// ```
#[test]
#[ignore = "visual capture: needs a system UI face; run with --ignored"]
fn settings_badge_visual_capture() {
    let dir = std::env::var("SETTINGS_BADGE_PNG_DIR").map_or_else(
        |_| std::env::temp_dir().join("settings-badge"),
        std::path::PathBuf::from,
    );
    std::fs::create_dir_all(&dir).expect("output dir");
    let theme = aterm_render::Theme::default();
    let surface = crate::settings::Roles::from_theme(theme).surface;
    for (name, width, height, compact) in [
        ("wide", 1_200.0_f32, 820.0_f32, false),
        ("medium", 900.0, 820.0, false),
        ("compact", 568.0, 900.0, true),
    ] {
        let (mut runtime, instance, view) = setup();
        assert!(runtime.replace_settings_packages(
            packages_state_with_program_state("error: ay stage failed: no space left on device"),
            2,
        ));
        let compiled = if compact {
            compact_categories_showing(&mut runtime, instance, view, SettingsRoute::Packages)
        } else {
            compile_settings_view(&runtime, instance, view, &view_cx_at(width, height))
        };
        assert_eq!(painted_badge_dots(&compiled).len(), 1, "{name}");
        let scale = 2.0;
        let (rgba, pw, ph) = crate::tray_raster::rasterize_tray(
            &compiled.tray(theme, 13.0).prims,
            width as u32,
            height as u32,
            scale,
            [surface[0], surface[1], surface[2], 255],
        );
        let mut out = Vec::new();
        {
            let mut enc = aterm_png::Encoder::new(&mut out, pw, ph);
            enc.set_color(aterm_png::ColorType::Rgba);
            enc.set_depth(aterm_png::BitDepth::Eight);
            enc.write_header()
                .expect("png header")
                .write_image_data(&rgba)
                .expect("png data");
        }
        let path = dir.join(format!("{name}.png"));
        std::fs::write(&path, &out).expect("write png");
        crate::logging::stderr_line!("wrote {} ({pw}x{ph})", path.display());
    }
}

/// The wall clock now, in Unix seconds — the Packages page says every time relative
/// to it (Phase 4), so its fixtures stamp their events against it.
fn wall_now() -> i64 {
    aterm_time::unix_secs().map_or(0, |s| i64::try_from(s).unwrap_or(0))
}

/// A Packages page as a working Mac shows it (Phase 4): claude at Anthropic's latest,
/// codex keeping 0.156.0 after refusing 0.157.0, the ALab toolset on index 44 (one
/// program held), and `events` lines of package activity, the newest a minute old.
fn packages_state_with_activity(events: usize) -> PackagesState {
    packages_state_with_activity_policy(events, true)
}

/// [`packages_state_with_activity`] with Automatic updates resolved to `master_enabled`.
fn packages_state_with_activity_policy(events: usize, master_enabled: bool) -> PackagesState {
    use atpkg::packages_log::{Entry, kind};
    let vendor = |v: &str| atpkg::vendor_direct::Version::parse(v).unwrap().build_id();
    let mut programs = std::collections::BTreeMap::new();
    for (name, build, state) in [
        (
            "claude",
            vendor("2.1.280"),
            atpkg::state::vendor_managed("2.1.280", "Anthropic"),
        ),
        (
            "codex",
            vendor("0.156.0"),
            "error: codex 0.157.0 refused: digest mismatch \u{2014} keeping 0.156.0".to_string(),
        ),
        ("ay", 1971, atpkg::state::managed(1971, 44)),
        ("ty", 812, atpkg::state::managed(812, 44)),
        (
            "nn",
            108,
            atpkg::state::held_unpublished(None, 112, "aarch64-apple-darwin", 108),
        ),
    ] {
        programs.insert(
            name.to_string(),
            atpkg::ProgramStatus {
                installed_build: Some(build),
                state,
                tree_root: String::new(),
            },
        );
    }
    let now = wall_now();
    let status = atpkg::Status {
        schema: 1,
        updated_at: aterm_types::rfc3339::format_rfc3339(u64::try_from(now - 60).unwrap()),
        enabled: true,
        index_source: "alabsystems/aterm".to_string(),
        outcome: "up to date (index build 44)".to_string(),
        seams: Vec::new(),
        last_success_at: aterm_types::rfc3339::format_rfc3339(u64::try_from(now - 60).unwrap()),
        last_index_build: 44,
        index_build_changed_at: String::new(),
        last_pass: String::new(),
        last_pass_at: String::new(),
        last_pass_attempted_index_build: 0,
        last_pass_attempted_at: String::new(),
        pass_seq: 0,
        stale_index_only_pass_seq: 0,
        programs,
        extra: Default::default(),
    };
    let mut report = crate::packages_screen::PackagesStatusReport::from_parts(
        true,
        true,
        "fp".to_string(),
        Some(&status),
        &[],
    );
    for row in &mut report.programs {
        let (updated, latest, checked) = match row.name.as_str() {
            "claude" => (now - 3 * 3600, "2.1.280", Some(now - 240)),
            "codex" => (now - 3 * 86_400, "0.157.0", Some(now - 240)),
            "ay" => (now - 86_400, "build 1971", None),
            "ty" => (now - 5 * 86_400, "build 815", None),
            _ => (now - 20 * 86_400, "build 112", None),
        };
        row.update.updated_at = Some(updated);
        row.update.latest_known = Some(latest.to_string());
        row.update.checked_at = checked;
    }
    let line = |i: usize| -> Entry {
        let at = now - 60 - 3600 * i as i64;
        let fields: Vec<(&str, String)> = match i % 4 {
            0 => vec![
                ("lane", "window".into()),
                ("verb", "update".into()),
                ("exit", "0".into()),
                ("secs", "7".into()),
                ("outcome", "up to date (index build 44)".into()),
            ],
            1 => vec![
                ("program", "claude".into()),
                ("from", "2.1.278".into()),
                ("to", "2.1.280".into()),
                ("source", "Anthropic latest".into()),
                ("result", "updated".into()),
            ],
            2 => vec![
                ("program", "codex".into()),
                ("from", "0.156.0".into()),
                ("source", "OpenAI latest".into()),
                ("result", "refused".into()),
                (
                    "reason",
                    "error: codex 0.157.0 refused: digest mismatch \u{2014} keeping 0.156.0".into(),
                ),
            ],
            _ => vec![
                ("lane", "head watch".into()),
                ("verb", "update codex".into()),
                ("exit", "69".into()),
            ],
        };
        Entry {
            at: Some(at),
            kind: if matches!(i % 4, 1 | 2) {
                kind::PROGRAM
            } else {
                kind::PASS_END
            }
            .to_string(),
            pid: 1000 + i as u32,
            fields: fields
                .into_iter()
                .map(|(k, v)| (k.to_string(), v))
                .collect(),
        }
    };
    report.activity = (0..events).map(line).collect();
    report.clock = crate::packages_screen::LocalClock::fixed(0);
    report.log_path = Some(std::path::PathBuf::from(
        "/Users//who/Library/Logs/aterm/packages.log",
    ));
    let mut service = crate::packages_screen::PackagesService::new();
    let sequence = service.begin(None).unwrap();
    assert!(service.finish(
        sequence,
        crate::packages_screen::PackagesWorkerCompletion::refresh(report),
    ));
    service.state(master_enabled, true, true)
}

/// Every semantic key and label the Packages page shows across its card pages.
fn packages_page_semantics(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    cx: &ViewCx<'_>,
) -> Vec<(String, String)> {
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Packages);
    }
    let mut out = Vec::new();
    for page in 0..6 {
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.page_scroll = page;
        }
        let compiled = compile_settings_view(runtime, instance, view, cx);
        out.extend(
            compiled
                .semantics
                .iter()
                .map(|n| (n.key.as_str().to_string(), n.label.clone())),
        );
    }
    out
}

/// Whole cards packed in order into pages the content holds: a card joins the page
/// before it while it fits, and a card taller than a page has one of its own.
#[test]
fn package_cards_pack_into_pages_in_order() {
    assert_eq!(
        pack_card_pages(&[100.0, 100.0, 100.0], 400.0, 10.0),
        vec![0..3]
    );
    assert_eq!(
        pack_card_pages(&[200.0, 150.0, 300.0, 120.0], 400.0, 12.0),
        vec![0..2, 2..3, 3..4]
    );
    assert_eq!(
        pack_card_pages(&[500.0, 100.0, 100.0], 400.0, 12.0),
        vec![0..1, 1..3],
        "an over-tall card has a page of its own"
    );
    assert!(pack_card_pages(&[], 400.0, 12.0).is_empty());
}

/// THE PROGRAM LIST SAYS EACH ROW'S FACTS (Phase 4): version and source, when it was
/// updated, the latest known — relative, never raw UTC. A state those words say is not
/// repeated; a refusal keeps its own words whole under its row, a hold its canonical
/// words, and a SHADOWED row its per-shell truth.
#[test]
fn program_lines_say_version_source_updated_and_latest_known() {
    let packages = packages_state_with_activity(0).projection();
    let lines = packages_program_lines(&packages, SettingsWidth::Wide);
    let text = |key: &str| {
        lines
            .iter()
            .filter(|l| l.key == key || l.key.starts_with(&format!("{key}/")))
            .map(|l| l.text.clone())
            .collect::<Vec<_>>()
            .join(" | ")
    };
    // An agent's product facts follow its own words; the detail that no longer fits
    // beside them moves under the row, whole.
    assert_eq!(
        text("packages/programs/claude"),
        "claude  \u{b7}  2.1.280  \u{b7}  latest from Anthropic  \u{b7}  Updated 3 h ago  \
         \u{b7}  Checked 4 min ago  \u{b7}  Anthropic Claude Code  \u{b7}  proprietary  \
         \u{b7}  ~200 MB"
    );
    // A day old: the LOCAL calendar's words (`yesterday 09:30`), whatever the clock.
    let yesterday = crate::packages_screen::when_words(
        wall_now() - 86_400,
        wall_now(),
        crate::packages_screen::LocalClock::fixed(0),
    );
    assert!(yesterday.starts_with("yesterday "), "{yesterday}");
    // The words, not the minute: the fixture stamped "a day ago" at its own
    // clock read, and one crossing a minute before this one reads 14:05
    // where this reads 14:06.
    let ay = text("packages/programs/ay");
    assert!(
        ay.starts_with("ay  \u{b7}  build 1971  \u{b7}  up to date  \u{b7}  Updated yesterday "),
        "{ay}"
    );
    let codex = text("packages/programs/codex");
    assert!(
        codex.starts_with("codex  \u{b7}  0.156.0  \u{b7}  from OpenAI"),
        "{codex}"
    );
    assert!(
        codex.contains("error: codex 0.157.0 refused: digest mismatch"),
        "a refusal's own words stay on the row: {codex}"
    );
    assert!(codex.contains("Latest known 0.157.0"), "{codex}");
    let nn = text("packages/programs/nn");
    assert!(
        nn.starts_with(
            "nn  \u{b7}  kept at build 108 \u{2014} 112 isn\u{2019}t available for this Mac"
        ),
        "{nn}"
    );
    let nn_line = lines
        .iter()
        .find(|line| line.key == "packages/programs/nn")
        .unwrap();
    assert!(
        nn_line
            .state
            .as_deref()
            .is_some_and(|state| state.starts_with("held: ")),
        "a held row keeps its canonical words as its accessible value: {nn_line:?}"
    );
    for line in &lines {
        assert!(
            !line.text.contains("T00:") && !line.text.ends_with('Z'),
            "no raw UTC on a row: {}",
            line.text
        );
    }
    // SHADOWED is said after the facts.
    let shadowed = packages_state_with_program_state(&atpkg::state::shadowed(
        1971,
        std::path::Path::new("/opt/homebrew/bin/ay"),
    ))
    .projection();
    let line = &packages_program_lines(&shadowed, SettingsWidth::Wide)[0];
    assert!(line.text.contains("build 1971"), "{}", line.text);
    assert!(
        line.text
            .contains("another copy runs first: /opt/homebrew/bin/ay"),
        "{}",
        line.text
    );
    assert!(
        line.state
            .as_deref()
            .is_some_and(|state| state.contains("SHADOWED")),
        "the canonical line is the row's accessible value: {line:?}"
    );
}

/// A ROW'S WORDS ARE PLAIN, ITS STATE STAYS CANONICAL (2026-09-23 audit, SB-18): the
/// page paints `ay · build 1971 · up to date`, and the row's one semantic node carries
/// atpkg's own line after the words — what `status.toml`, `doctor` and the log say.
#[test]
fn a_program_rows_accessible_value_is_atpkgs_own_state() {
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(packages_state_with_activity(0), 2));
    let seen = packages_page_semantics(&mut runtime, instance, view, &view_cx());
    let label = |key: &str| {
        seen.iter()
            .find(|(k, _)| k == key)
            .map(|(_, l)| l.clone())
            .unwrap_or_else(|| panic!("{key} on the page"))
    };
    let ay = label("packages/programs/ay");
    assert!(
        ay.starts_with("ay  \u{b7}  build 1971  \u{b7}  up to date"),
        "{ay}"
    );
    assert!(
        ay.ends_with(&format!("\n{}", atpkg::state::managed(1971, 44))),
        "{ay}"
    );
    // The short-landscape compact page, whose rows are atomic label/value pairs, says the
    // same in its value column.
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(packages_state_with_activity(0), 2));
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Packages);
    }
    let cx = view_cx_at(568.0, 320.0);
    let mut value = None;
    for page in 0..64 {
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.page_scroll = page;
        }
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        if let Some(node) = compiled.semantic(&UiKey::new("packages/programs/ay/value")) {
            value = Some(node.label.clone());
            break;
        }
    }
    let value = value.expect("the atomic compact page has the ay row's value");
    assert!(
        value.starts_with("ay  \u{b7}  build 1971  \u{b7}  up to date")
            && value.ends_with(&format!("\n{}", atpkg::state::managed(1971, 44))),
        "{value}"
    );
}

/// THE ACTIVITY CARD (Phase 4): the package log's newest events on the page, a card's
/// worth at a time with relative times — trouble painted as such — its own Newer/Older
/// pager, and "Open Log", which asks the host to open the file (NSWorkspace; no shell,
/// no Terminal). An empty log says so and offers nothing to open.
#[test]
fn the_activity_card_pages_the_log_and_opens_it() {
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(packages_state_with_activity(20), 2));
    let cx = view_cx();
    let seen = packages_page_semantics(&mut runtime, instance, view, &cx);
    let label = |key: &str| {
        seen.iter()
            .find(|(k, _)| k == key)
            .map(|(_, l)| l.clone())
            .unwrap_or_else(|| panic!("{key} on the page"))
    };
    assert!(label("packages/activity/0").starts_with("1 min ago  \u{b7}  Update check"));
    assert!(
        label("packages/activity/1").contains("claude 2.1.278 \u{2192} 2.1.280"),
        "{}",
        label("packages/activity/1")
    );
    assert!(
        label("packages/activity/2").contains("codex 0.157.0 refused: digest mismatch"),
        "{}",
        label("packages/activity/2")
    );
    assert_eq!(label("packages/activity/range"), "1\u{2013}6 of 20");
    assert!(
        !seen.iter().any(|(k, _)| k == "packages/activity/6"),
        "one card's worth"
    );
    assert!(seen.iter().any(|(k, _)| k == "packages/activity/open-log"));

    let act = |runtime: &mut NativeRuntime, id: &str| {
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(id),
                    value: None,
                }),
            )
            .unwrap()
    };
    act(&mut runtime, "packages/activity/older");
    let seen = packages_page_semantics(&mut runtime, instance, view, &cx);
    assert!(seen.iter().any(|(k, _)| k == "packages/activity/6"));
    assert!(
        seen.iter()
            .any(|(k, l)| k == "packages/activity/range" && l == "7\u{2013}12 of 20")
    );
    for _ in 0..10 {
        act(&mut runtime, "packages/activity/older");
    }
    let seen = packages_page_semantics(&mut runtime, instance, view, &cx);
    assert!(
        seen.iter()
            .any(|(k, l)| k == "packages/activity/range" && l == "19\u{2013}20 of 20"),
        "Older stops at the last page"
    );
    act(&mut runtime, "packages/activity/newer");
    let seen = packages_page_semantics(&mut runtime, instance, view, &cx);
    assert!(seen.iter().any(|(k, _)| k == "packages/activity/12"));

    let opened = act(&mut runtime, "packages/activity/open-log");
    let asked = opened
        .effects
        .iter()
        .any(|e| matches!(e, AppEffect::OpenPackagesLog));
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    if cfg!(target_os = "macos") {
        assert!(asked, "the host opens the file");
        assert_eq!(state.feedback.as_deref(), Some("Opening the package log…"));
    } else {
        assert!(!asked, "nothing is spawned off macOS");
        assert!(state.feedback.as_deref().unwrap().contains("packages.log"));
    }

    // Nothing recorded: the card says so, and Open Log is off.
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(packages_state_with_activity(0), 2));
    let seen = packages_page_semantics(&mut runtime, instance, view, &cx);
    assert!(seen.iter().any(|(k, l)| k == "packages/activity/empty"
        && l.starts_with("No package activity recorded yet")));
    assert!(!seen.iter().any(|(k, _)| k == "packages/activity/range"));
    let opened = act(&mut runtime, "packages/activity/open-log");
    assert!(
        !opened
            .effects
            .iter()
            .any(|e| matches!(e, AppEffect::OpenPackagesLog))
    );
}

/// Settings ▸ Software Update links to its record — Settings ▸ Messages with the
/// update chip down — and the link is whole on the page that shows it. (Packages'
/// Activity is that page's own log, ruling 41: it carries no second log link.)
#[test]
fn software_update_links_to_its_messages() {
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(packages_state_with_activity(9), 2));
    for (width, height) in [
        (1_200.0, 820.0),
        (864.0, 518.0),
        (849.0, 513.0),
        (320.0, 568.0),
    ] {
        let cx = view_cx_at(width, height);
        for (route, key) in [(SettingsRoute::SoftwareUpdate, "updates/messages")] {
            let mut found = false;
            for page in 0..200 {
                {
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!();
                    };
                    state.navigate(route);
                    state.page_scroll = page;
                }
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                if let Some(hit) = compiled.hits.iter().find(|hit| hit.key.as_str() == key) {
                    assert_eq!(hit.action, ActionId::new(MESSAGES_SHOW_UPDATE));
                    assert!(
                        hit.rect.bottom() <= cx.viewport.bottom() + 0.01,
                        "{key} at {width}×{height} is below the page"
                    );
                    let clipped = compiled.paint_audit_lines().into_iter().any(|line| {
                        line.contains(&format!("key=\"{key}\""))
                            && (line.contains("overflow=true")
                                || line.contains("clip-truncated=true"))
                    });
                    assert!(!clipped, "{key} at {width}×{height} is clipped");
                    found = true;
                    break;
                }
                let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
                    unreachable!();
                };
                if state
                    .result_page_limit
                    .get()
                    .is_some_and(|limit| page >= limit)
                {
                    break;
                }
            }
            assert!(
                found,
                "{} at {width}×{height} links to its messages",
                route.label()
            );
        }
    }
}

/// VISUAL CAPTURE of Settings ▸ Packages (Phase 4) — the wide page's card pages and
/// the compact page's first sections — dumped as PNGs so the program facts, the one
/// Automatic-updates switch and the Activity card can be read as PIXELS. Not a gate:
/// `#[ignore]`d (it needs a real UI face) and asserted only for "it produced a frame".
///
/// ```sh
/// SETTINGS_PACKAGES_PNG_DIR=/tmp/packages targo --unverified test -p aterm-gui --lib \
///     settings_packages_visual_capture -- --ignored --nocapture
/// ```
#[test]
#[ignore = "visual capture: needs a system UI face; run with --ignored"]
fn settings_packages_visual_capture() {
    let dir = std::env::var("SETTINGS_PACKAGES_PNG_DIR").map_or_else(
        |_| std::env::temp_dir().join("settings-packages"),
        std::path::PathBuf::from,
    );
    std::fs::create_dir_all(&dir).expect("output dir");
    let theme = aterm_render::Theme::default();
    let surface = crate::settings::Roles::from_theme(theme).surface;
    for (name, width, height, pages) in [
        ("wide", 1_200.0_f32, 820.0_f32, 3usize),
        ("medium", 900.0, 820.0, 3),
        ("compact", 568.0, 900.0, 4),
    ] {
        for page in 0..pages {
            let (mut runtime, instance, view) = setup();
            assert!(runtime.replace_settings_packages(packages_state_with_activity(20), 2));
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::Packages);
                state.page_scroll = page;
            }
            let compiled =
                compile_settings_view(&runtime, instance, view, &view_cx_at(width, height));
            let scale = 2.0;
            let (rgba, pw, ph) = crate::tray_raster::rasterize_tray(
                &compiled.tray(theme, 13.0).prims,
                width as u32,
                height as u32,
                scale,
                [surface[0], surface[1], surface[2], 255],
            );
            let mut out = Vec::new();
            {
                let mut enc = aterm_png::Encoder::new(&mut out, pw, ph);
                enc.set_color(aterm_png::ColorType::Rgba);
                enc.set_depth(aterm_png::BitDepth::Eight);
                enc.write_header()
                    .expect("png header")
                    .write_image_data(&rgba)
                    .expect("png data");
            }
            let path = dir.join(format!("{name}-{page}.png"));
            std::fs::write(&path, &out).expect("write png");
            crate::logging::stderr_line!("wrote {} ({pw}x{ph})", path.display());
        }
    }
}

/// THE SOFTWARE UPDATE CARD CARRIES BOTH `[update]` SWITCHES (2026-09-23): "Check for
/// updates automatically" (`[update] enabled`, until now only on Terminal ▸ Updates)
/// above "Install updates automatically" (`auto_apply`), each the registry's own
/// control — so the check switch's semantic label carries the reader's timing
/// ("Applies next launch": `aterm_update_core::settings` reads the key once per
/// process) and a press writes the key the updater reads. One wording serves the pair,
/// the longest whose lines fit, so no width ellipsizes either label (the medium
/// workbench painted "Automati…" before), and the caption says when checking changes.
/// Where only the verbs fit ("Check", "Install") the card paints its "Automatic
/// updates" heading, so no width leaves the switches saying nothing of updates
/// (2026-09-23 review); the off headline fits the medium workbench too. Search finds
/// each switch by the words the card paints. The `linux-` rows project an enrolled
/// Linux copy (`UpdateProjection::linux_host`) — the page a shipping Linux build
/// shows, both switches live — so that card is checked on every host, not only on a
/// Linux build, where the plain rows render the no-updater page (2026-09-24 review).
#[test]
fn the_update_card_carries_both_switches_and_their_labels_fit() {
    let macos = update_automatic_caption(SettingsWidth::Wide, true, false);
    assert!(
        macos.contains("turn the install switch off to install only when you press"),
        "the macOS caption names the install switch: {macos}"
    );
    assert!(!macos.contains("turn it off"), "{macos}");
    let (mut runtime, instance, view) = setup_with_update(UpdateState::from_status(
        1,
        "0.1.0",
        Some(&update_status(false)),
        false,
    ));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let checks = UiKey::new(format!("settings/control/{}", prefs::EDIT_UPDATE_ENABLED));
    let install = UiKey::new("settings/control/update.auto_apply");
    let mut revision = 1;
    let wide = ["Auto-check updates", "Auto-install updates"];
    let verbs = ["Check", "Install"];
    let whole = [
        "Check for updates automatically",
        "Install updates automatically",
    ];
    for (variant, cx, pair, running, linux) in [
        ("wide", view_cx_at(1_200.0, 820.0), wide, true, false),
        ("medium", view_cx_at(849.0, 513.0), verbs, true, false),
        ("medium-off", view_cx_at(849.0, 513.0), verbs, false, false),
        ("compact", view_cx_at(600.0, 820.0), whole, true, false),
        ("linux-wide", view_cx_at(1_200.0, 820.0), wide, true, true),
        ("linux-medium", view_cx_at(849.0, 513.0), verbs, true, true),
        (
            "linux-medium-off",
            view_cx_at(849.0, 513.0),
            verbs,
            false,
            true,
        ),
        ("linux-compact", view_cx_at(600.0, 820.0), whole, true, true),
    ] {
        revision += 1;
        let mut status = update_status(false);
        status.linux = linux.then_some(aterm_update::LinuxUpdateStatus {
            installed_build: 1,
            installed_version: String::new(),
            staged_build: None,
            staged_version: None,
            staged_commit: None,
            trial_phase: None,
            trial_starts: 0,
            trial_healthy: false,
            refused_newer: false,
        });
        assert!(
            runtime.replace_settings_update(
                UpdateState::from_status(1, "0.1.0", Some(&status), false)
                    .with_automatic_checks(running, running),
                revision,
            )
        );
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let headline = compiled
            .semantic(&UiKey::new("updates/headline"))
            .unwrap_or_else(|| panic!("{variant}: the headline is on the first page"));
        assert_eq!(
            headline.label,
            match (running, linux) {
                (true, false) => "You\u{2019}re up to date.",
                (true, true) => "No update staged.",
                (false, _) => "Automatic checks are off.",
            },
            "{variant}"
        );
        if !linux && cfg!(target_os = "macos") {
            // The macOS caption NAMES the switch that makes installing manual: after
            // a plural "Updates", "turn it off" could only mean the check switch,
            // which stops background checks and never makes installing manual
            // (2026-09-24 post-push review).
            let caption = compiled
                .semantic(&UiKey::new("updates/automatic/caption"))
                .map(|node| node.label.clone());
            if variant == "wide" {
                assert_eq!(
                    caption.as_deref(),
                    Some(update_automatic_caption(SettingsWidth::Wide, true, false).as_str()),
                    "{variant}: the wide card paints the whole sentence"
                );
            }
            assert!(
                caption
                    .as_deref()
                    .is_none_or(|caption| !caption.contains("turn it off")),
                "{variant}: {caption:?}"
            );
        }
        if linux {
            let caption = compiled
                .semantic(&UiKey::new("updates/automatic/caption"))
                .unwrap_or_else(|| panic!("{variant}: the Linux card keeps its caption"));
            assert!(
                caption.label.contains("applies next launch")
                    && caption.label.contains("downloads only")
                    && caption.label.contains("`aterm update apply`")
                    && !caption.label.contains("no effect"),
                "{variant}: {:?}",
                caption.label
            );
        }
        let card = compiled
            .semantic(&UiKey::new("updates/automatic"))
            .unwrap_or_else(|| panic!("{variant}: the card is on the first page"))
            .rect;
        let mut tops = Vec::new();
        let mut painted_pair = Vec::new();
        for key in [&checks, &install] {
            let switch = compiled
                .semantic(key)
                .unwrap_or_else(|| panic!("{variant}: {key:?} is on the card"));
            assert!(
                switch.rect.y >= card.y && switch.rect.bottom() <= card.bottom() + 0.01,
                "{variant}: {key:?} inside the card"
            );
            assert_eq!(
                switch.state.expect("a control carries state").enabled,
                linux || cfg!(target_os = "macos"),
                "{variant}: live where the updater runs, disabled elsewhere"
            );
            tops.push(switch.rect.y);
            let field_key = key.as_str().trim_start_matches("settings/control/");
            let painted = compiled
                .paint
                .iter()
                .find(|node| node.key.as_str() == format!("settings/label/{field_key}/visual"))
                .unwrap_or_else(|| panic!("{variant}: {field_key}'s label is painted"));
            let UiContent::Text(text) = &painted.content else {
                panic!(
                    "{variant}: {field_key}'s label is text: {:?}",
                    painted.content
                );
            };
            painted_pair.push(text.text.clone());
        }
        assert!(tops[0] < tops[1], "{variant}: checking comes first");
        // Which wording fits is the UI face's to decide, so the exact pair is pinned
        // where the face is known; everywhere the pair is one rung, and the heading is
        // there exactly when that rung is the verbs alone.
        let rung = UPDATE_SWITCH_LABELS
            .iter()
            .position(|rung| rung.as_slice() == painted_pair.as_slice())
            .unwrap_or_else(|| panic!("{variant}: one wording for the pair: {painted_pair:?}"));
        if cfg!(target_os = "macos") {
            assert_eq!(painted_pair, pair, "{variant}");
        }
        let title = compiled
            .paint
            .iter()
            .find(|node| node.key.as_str() == "updates/automatic/title");
        if rung == UPDATE_SWITCH_LABELS.len() - 1 {
            assert!(
                matches!(title.map(|node| &node.content),
                    Some(UiContent::Text(text)) if text.text == "Automatic updates"),
                "{variant}: the verbs alone come under the card's heading"
            );
        } else {
            assert!(
                title.is_none(),
                "{variant}: a wording that says it all needs no heading"
            );
        }
        assert!(
            compiled
                .semantic(&checks)
                .unwrap()
                .label
                .contains("Applies next launch"),
            "{variant}: the check switch says when it applies"
        );
        let overflowing = compiled
            .paint_audit_lines()
            .into_iter()
            .filter(|line| line.contains("overflow=true") || line.contains("clip-truncated=true"))
            .filter(|line| {
                line.contains("paint-text key=\"updates/")
                    || line.contains("paint-text key=\"settings/label/update.")
            })
            .collect::<Vec<_>>();
        assert!(
            overflowing.is_empty(),
            "{variant}: the card's copy overflows its slot:\n{}",
            overflowing.join("\n")
        );
    }
    if cfg!(target_os = "macos") {
        let compiled = compile_settings_view(&runtime, instance, view, &view_cx());
        let caption = compiled
            .semantic(&UiKey::new("updates/automatic/caption"))
            .expect("the desktop card keeps its caption");
        assert!(
            caption
                .label
                .starts_with("The check switch applies next launch."),
            "{:?}",
            caption.label
        );
    }
    // A press writes `[update] enabled` alone — the key the updater reads.
    let off = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_UPDATE_ENABLED)),
                value: Some(SemanticInput::Bool(false)),
            }),
        )
        .unwrap();
    let written: Vec<(String, Option<String>)> = emitted_config_patch(&off)
        .edits
        .iter()
        .map(|edit| (edit.key.clone(), edit.value.clone()))
        .collect();
    assert_eq!(
        written,
        vec![(prefs::EDIT_UPDATE_ENABLED.to_string(), Some("false".into()))]
    );
    // Search finds each switch by the words the card paints.
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    for (query, key) in [
        ("check", prefs::EDIT_UPDATE_ENABLED),
        ("automatically", prefs::EDIT_UPDATE_ENABLED),
        ("auto-check", prefs::EDIT_UPDATE_ENABLED),
        ("install", "update.auto_apply"),
        ("automatically", "update.auto_apply"),
        ("auto-install", "update.auto_apply"),
    ] {
        let field = state.field_by_key(key).unwrap();
        assert!(
            field_match_score(field, query).is_some(),
            "{query} finds {key}"
        );
    }
}

/// A SHORT PHONE STILL SHOWS A SWITCH ON PAGE 1 (2026-09-23 review). With two switches
/// the card no longer fits beside the status card at 600x560, and the whole card moved
/// to page 2 — the status card alone on page 1 over ~370pt of nothing, the friction
/// the pairing exists to avoid. The check half now rides with the status card and the
/// install half, with the caption, takes page 2; a taller phone keeps the whole card.
#[test]
fn a_short_compact_page_pairs_the_status_card_with_the_check_switch() {
    let (mut runtime, instance, view) = setup_with_update(UpdateState::from_status(
        1,
        "0.1.0",
        Some(&update_status(false)),
        false,
    ));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let checks = UiKey::new(format!("settings/control/{}", prefs::EDIT_UPDATE_ENABLED));
    let install = UiKey::new("settings/control/update.auto_apply");
    let page = |runtime: &mut NativeRuntime, cx: &ViewCx<'static>, index: usize| {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.page_scroll = index;
        let compiled = compile_settings_view(runtime, instance, view, cx);
        let overflowing = compiled
            .paint_audit_lines()
            .into_iter()
            .filter(|line| line.contains("overflow=true") || line.contains("clip-truncated=true"))
            .filter(|line| line.contains("paint-text key=\"updates/"))
            .collect::<Vec<_>>();
        assert!(overflowing.is_empty(), "{}", overflowing.join("\n"));
        compiled
    };
    let short = view_cx_at(600.0, 560.0);
    let first = page(&mut runtime, &short, 0);
    assert!(
        first
            .semantic(&UiKey::new("updates/compact-status"))
            .is_some(),
        "page 1 pairs the status card with a switch card"
    );
    assert!(first.semantic(&UiKey::new("updates/headline")).is_some());
    assert!(
        first.semantic(&checks).is_some(),
        "the check switch is on page 1"
    );
    assert!(first.semantic(&install).is_none());
    let second = page(&mut runtime, &short, 1);
    assert!(
        second.semantic(&install).is_some(),
        "the install switch is on page 2"
    );
    assert!(
        second
            .semantic(&UiKey::new("updates/automatic-install"))
            .is_some()
    );
    assert!(
        second
            .semantic(&UiKey::new("updates/automatic/caption"))
            .is_some(),
        "the caption rides with the install half"
    );
    let tall = view_cx_at(600.0, 820.0);
    let whole = page(&mut runtime, &tall, 0);
    assert!(whole.semantic(&checks).is_some() && whole.semantic(&install).is_some());
    assert!(
        whole
            .semantic(&UiKey::new("updates/automatic-install"))
            .is_none(),
        "a phone with room keeps the card whole"
    );

    // AN ENROLLED LINUX COPY TOO, WHATEVER ITS DETAIL (2026-09-24 review). Its detail
    // runs longer — the Linux facts, and before them the timing sentence while
    // automatic checks are off — and at three lines it left the check half no room
    // beside the status card, so the switch that turns checks back on sat on page 2.
    // The detail now paints a line fewer there; its whole sentence stays the value.
    let linux = |staged: Option<u64>| aterm_update::LinuxUpdateStatus {
        installed_build: 1,
        installed_version: String::new(),
        staged_build: staged,
        staged_version: staged.map(|_| "0.2.0".to_string()),
        staged_commit: staged.map(|_| "ab".repeat(20)),
        trial_phase: None,
        trial_starts: 0,
        trial_healthy: false,
        refused_newer: false,
    };
    let mut revision = 1;
    for (state, staged, running, saved) in [
        ("idle, checks off", None, false, false),
        ("idle, checks on", None, true, true),
        ("idle, checks stop next launch", None, true, false),
        ("downloaded", Some(2), true, true),
    ] {
        let mut status = update_status(false);
        status.linux = Some(linux(staged));
        revision += 1;
        let update = UpdateState::from_status(1, "0.1.0", Some(&status), false)
            .with_automatic_checks(running, saved);
        let full_detail = update.projection().detail.expect("the Linux detail");
        assert!(runtime.replace_settings_update(update, revision));
        for face in [LinuxLayoutFace::Host, LinuxLayoutFace::LinuxLadder] {
            let Some(short) = linux_layout_cx(face, 600.0, 560.0) else {
                continue;
            };
            let first = page(&mut runtime, &short, 0);
            assert!(
                first
                    .semantic(&UiKey::new("updates/compact-status"))
                    .is_some()
                    && first.semantic(&checks).is_some(),
                "{face:?} Linux {state}: the check switch is on page 1 beside the status card"
            );
            let detail = first
                .semantic(&UiKey::new("updates/detail"))
                .expect("the detail is on page 1");
            assert_eq!(
                detail.label, full_detail,
                "{face:?} Linux {state}: the painted lines are bounded, the value is whole"
            );
        }
    }
}

/// ONE "Automatic updates" switch, LIVE (Phase 4; the one-path collapse, 2026-09-23):
/// `[packages] enabled` off paints the switch off and the service line says nothing
/// updates by itself — no "next launch", and no retired `auto_update` row beside it
/// (it is folded into the switch). The install consent keeps its authored value while
/// the switch is off (dormant: no unattended pass runs to install anything). Replaces
/// the two-switch master/child page the launch-time gates needed.
#[test]
fn packages_page_shows_one_live_switch_and_the_dormant_install_consent() {
    let service = VersionedConfigService::new(
        "[packages]\nenabled = false\nauto_install = true\n".to_string(),
    )
    .unwrap();
    let (mut runtime, instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    **state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    // The lane runs whatever the switch says (it stands by, live), so the loop is up.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_policy(None, false, true, true),
        2,
    ));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Packages),
                value: None,
            }),
        )
        .unwrap();
    let cx = view_cx();
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    let switch = compiled
        .semantic(&UiKey::new(format!(
            "settings/control/{}",
            prefs::EDIT_PACKAGES_ENABLED
        )))
        .unwrap();
    assert_eq!(switch.value, SemanticValue::Bool(false));
    assert!(
        switch.label.starts_with("Automatic updates"),
        "{}",
        switch.label
    );
    assert!(
        !switch.label.contains("launch"),
        "a live switch discloses no launch timing: {}",
        switch.label
    );
    assert_eq!(
        compiled
            .semantic(&UiKey::new(format!(
                "settings/control/{}",
                prefs::EDIT_PACKAGES_AUTO_INSTALL
            )))
            .unwrap()
            .value,
        SemanticValue::Bool(true),
        "the consent keeps its authored value while the switch is off"
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/control/packages.auto_update"))
            .is_none(),
        "no auto-update row: the retired key is folded into the switch"
    );
    let status = &compiled
        .semantic(&UiKey::new("packages/loop-status/value"))
        .unwrap()
        .label;
    assert!(
        status.contains("Off \u{2014} nothing updates by itself"),
        "{status}"
    );
}

/// A MACHINE THE RETIRED SECOND SWITCH TURNED OFF (review of Phase 4, 2026-09-23),
/// through the ONE model (the one-path collapse, same day): `enabled = true,
/// auto_update = false` holds every update off, so "Automatic updates" reads Off — its
/// seed is the folded `Config::packages_enabled`, the reader the loop's gate shares —
/// on the page and in Search, and the service line names the retired key and the
/// control that clears it. Turning it on writes `enabled = true` ALONE, and the one
/// writer (`prefs::apply_prefs_edits`, `RETIRED_PACKAGES_SPELLINGS`) takes the retired
/// key out of the file with it: after the patch the file reads on. Off writes
/// `enabled = false` alone.
#[test]
fn automatic_updates_reads_and_restores_auto_update() {
    let mut service = VersionedConfigService::new(
        "[packages]\nenabled = true\nauto_update = false\n".to_string(),
    )
    .unwrap();
    let (mut runtime, instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    **state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    let config: Config =
        aterm_toml::from_str("[packages]\nenabled = true\nauto_update = false\n").unwrap();
    assert!(
        runtime.replace_settings_packages(
            live_packages_state_with_policy(None, config.packages_enabled(), true, true)
                .with_retired_switch_note(config.packages_retired_switch_note()),
            2,
        )
    );
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Packages),
                value: None,
            }),
        )
        .unwrap();
    // The switches' card is on whichever page the wide page packs it onto: the wrapped
    // service line and the retired key's note make it taller than the one-line rows did.
    let cx = view_cx();
    let control = UiKey::new(format!("settings/control/{}", prefs::EDIT_PACKAGES_ENABLED));
    let compiled = (0..4)
        .map(|page| {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.page_scroll = page;
            runtime
                .render(instance, view, &cx)
                .unwrap()
                .compile(cx.viewport)
                .unwrap()
        })
        .find(|compiled| compiled.semantic(&control).is_some())
        .expect("the Automatic updates switch is on a page");
    assert_eq!(
        compiled.semantic(&control).unwrap().value,
        SemanticValue::Bool(false),
        "nothing updates, so the switch is off"
    );
    assert_eq!(
        compiled
            .semantic(&UiKey::new("packages/retired-note"))
            .map(|note| note.label.clone()),
        config.packages_retired_switch_note(),
        "atpkg's sentence is under the switch it explains"
    );
    let status = &compiled
        .semantic(&UiKey::new("packages/loop-status/value"))
        .unwrap()
        .label;
    assert!(
        status.contains("auto_update = false") && status.contains("Automatic updates on"),
        "the line names the key and the control that clears it: {status}"
    );
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!();
        };
        assert!(
            !field_bool(state, prefs::EDIT_PACKAGES_ENABLED, true),
            "Search's row reads the same value"
        );
    }
    let on = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_PACKAGES_ENABLED)),
                value: Some(SemanticInput::Bool(true)),
            }),
        )
        .unwrap();
    let patch = emitted_config_patch(&on);
    let written: Vec<(String, Option<String>)> = patch
        .edits
        .iter()
        .map(|edit| (edit.key.clone(), edit.value.clone()))
        .collect();
    assert_eq!(
        written,
        vec![(
            prefs::EDIT_PACKAGES_ENABLED.to_string(),
            Some("true".into())
        )],
        "one key written: the switch"
    );
    let (after, _) = apply_real_config_patch(&mut service, &patch);
    assert!(
        !after.text.contains("auto_update"),
        "the writer drops the retired key with it: {:?}",
        after.text
    );
    let reread: Config = aterm_toml::from_str(&after.text).unwrap();
    assert!(reread.packages_enabled(), "on turns updates on");
    assert_eq!(reread.packages_retired_switch_note(), None);

    // Off: `enabled = false` alone, from a machine where it is on.
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(live_packages_state(None), 2));
    let off = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_PACKAGES_ENABLED)),
                value: Some(SemanticInput::Bool(false)),
            }),
        )
        .unwrap();
    let written: Vec<(String, Option<String>)> = emitted_config_patch(&off)
        .edits
        .into_iter()
        .map(|edit| (edit.key, edit.value))
        .collect();
    assert_eq!(
        written,
        vec![(
            prefs::EDIT_PACKAGES_ENABLED.to_string(),
            Some("false".into())
        )]
    );
}

/// A RETIRED `[packages]` SPELLING ON MODIFIED IS NAMED, READ AND RESETTABLE (review of
/// the Phase 4 merge, 2026-09-23). Under the one model `auto_update` and `seed_install`
/// have no field, so Modified called each a "Forward-compatible config key" — a key from
/// a NEWER build, with no Reset — and Reset All, which resets fields, left an
/// `auto_update = false` holding Automatic updates off after "Reset all settings". Each
/// row now names the switch it is the retired spelling of and what it does to it, its
/// Reset removes that key alone, Reset All removes it with the rest (and Undo writes it
/// back as the Bool atpkg reads), and Search finds each switch by the old name.
#[test]
fn a_retired_packages_spelling_is_named_resettable_and_reset_by_reset_all() {
    let source = "[packages]\nauto_update = false\nseed_install = false\n";
    let mut service = VersionedConfigService::new(source.to_string()).unwrap();
    let (mut runtime, instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    **state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    state.navigate(SettingsRoute::Modified);
    let overrides = authored_manual_overrides(state);
    let row = |key: &str| -> ManualOverride {
        overrides
            .iter()
            .find(|entry| entry.key == key)
            .cloned()
            .unwrap_or_else(|| panic!("{key} is listed: {overrides:?}"))
    };
    let auto_update = row(prefs::RETIRED_PACKAGES_AUTO_UPDATE);
    assert_eq!(auto_update.label, "Retired spelling of Automatic updates");
    assert_eq!(
        auto_update.preview,
        "Keeps Automatic updates off \u{b7} Open Manual\u{2026}"
    );
    assert!(auto_update.known && auto_update.reset_safe);
    let seed = row(prefs::RETIRED_PACKAGES_SEED_INSTALL);
    assert_eq!(seed.label, "Retired spelling of Install ALab tools");
    assert_eq!(
        seed.preview,
        "Read as Install ALab tools off \u{b7} Open Manual\u{2026}"
    );
    assert!(
        overrides
            .iter()
            .all(|entry| !entry.label.contains("Forward-compatible")),
        "{overrides:?}"
    );
    // Search finds each switch by the key a person actually has.
    for (query, key) in [
        ("auto_update", prefs::EDIT_PACKAGES_ENABLED),
        ("auto-update", prefs::EDIT_PACKAGES_ENABLED),
        ("seed_install", prefs::EDIT_PACKAGES_AUTO_INSTALL),
    ] {
        let field = state.field_by_key(key).unwrap();
        assert!(
            field_match_score(field, query).is_some(),
            "{query} finds {key}"
        );
    }

    // The row carries its Reset, which removes that key alone, CAS on the value shown.
    state.page_scroll = overrides
        .iter()
        .position(|entry| entry.key == prefs::RETIRED_PACKAGES_AUTO_UPDATE)
        .unwrap();
    let cx = view_cx_at(1_080.0, 720.0);
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new(format!(
                "settings/modified/manual/reset/{}",
                key_fragment(prefs::RETIRED_PACKAGES_AUTO_UPDATE)
            )))
            .is_some(),
        "a retired spelling has an exact Reset"
    );
    let reset = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: manual_override_reset_action(prefs::RETIRED_PACKAGES_AUTO_UPDATE).unwrap(),
                value: None,
            }),
        )
        .unwrap();
    let patch = emitted_config_patch(&reset);
    assert_eq!(patch.edits.len(), 1);
    assert_eq!(patch.edits[0].key, prefs::RETIRED_PACKAGES_AUTO_UPDATE);
    assert_eq!(patch.edits[0].value, None);
    assert_eq!(
        patch.edits[0].expected,
        ExpectedConfigValue::Exact(Some("false".to_string()))
    );
    let (after, _) = apply_real_config_patch(&mut service, &patch);
    assert!(!after.text.contains("auto_update"), "{:?}", after.text);
    assert!(after.text.contains("seed_install"), "that key alone");
    let reread: Config = aterm_toml::from_str(&after.text).unwrap();
    assert!(reread.packages_enabled(), "Automatic updates reads on");

    // Written beside the key that replaced it, the row says that key decides.
    let beside = SettingsViewState::from_snapshot(
        &VersionedConfigService::new(
            "[packages]\nenabled = false\nauto_update = false\n".to_string(),
        )
        .unwrap()
        .snapshot(),
    )
    .unwrap();
    assert!(authored_manual_overrides(&beside).iter().any(|entry| {
        entry.key == prefs::RETIRED_PACKAGES_AUTO_UPDATE
            && entry
                .preview
                .starts_with("No effect \u{2014} packages.enabled decides")
    }),);

    // Reset All takes the retired spelling with the fields, and Undo writes it back.
    let source = "font_px = 14.0\n[packages]\nauto_update = false\n";
    let mut service = VersionedConfigService::new(source.to_string()).unwrap();
    let (mut runtime, instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    **state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    for id in ["settings/reset-all", "settings/reset-all-confirm"] {
        let outcome = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(id),
                    value: None,
                }),
            )
            .unwrap();
        if id != "settings/reset-all-confirm" {
            continue;
        }
        let patch = emitted_config_patch(&outcome);
        let keys: BTreeSet<&str> = patch.edits.iter().map(|edit| edit.key.as_str()).collect();
        assert_eq!(
            keys,
            BTreeSet::from([prefs::EDIT_FONT_PX, prefs::RETIRED_PACKAGES_AUTO_UPDATE])
        );
        let request = ConfigPatchRequest {
            base_revision: patch.base_revision,
            edits: patch
                .edits
                .iter()
                .map(|edit| ConfigKeyEdit {
                    key: edit.key.clone(),
                    expected: ExpectedValue::Any,
                    value: edit.value.clone(),
                })
                .collect(),
        };
        let ConfigPatchResult::Applied { snapshot, undo } = service.patch(request) else {
            panic!("Reset All applies");
        };
        assert!(
            !snapshot.text.contains("auto_update"),
            "{:?}",
            snapshot.text
        );
        let reset: Config = aterm_toml::from_str(&snapshot.text).unwrap();
        assert!(reset.packages_enabled(), "after Reset All, updates are on");
        let ConfigPatchResult::Applied { snapshot, .. } = service.undo(undo) else {
            panic!("Undo applies");
        };
        let undone: Config = aterm_toml::from_str(&snapshot.text).unwrap();
        assert!(
            snapshot.text.contains("auto_update = false") && !undone.packages_enabled(),
            "Undo restores the Bool: {:?}",
            snapshot.text
        );
    }
}

/// A RETIRED `auto_update = false`'S WAY OUT IS READ WHOLE, AT EVERY WIDTH (review of the
/// Phase 4 merge, 2026-09-23). The one-line Background service row cut the retired key's
/// line at every width ("…(turning Automatic updates on r…", "…auto_update = false h…"),
/// and atpkg's sentence rode the hero's one-line detail, which cut its remedy ("…remove
/// it and se…"); the ordinary Off and On lines lost "Update Now still works" and the
/// last full check (the hero's detail now) at the medium and compact widths. Now the
/// service line wraps in its
/// column and the note is its own wrapped quiet lines under the switch — measured by the
/// painter at each layout's narrowest viewport and the review's own, every line fits
/// and every word of the remedy paints; the hero detail no longer carries the note.
#[test]
fn the_retired_switch_note_and_the_service_line_paint_whole_at_every_width() {
    let note = atpkg::config::auto_update_note(false, Some(true));
    let painted = |line: &str| -> String {
        let quoted = line
            .rsplit_once("painted=")
            .map_or("", |(_, painted)| painted);
        quoted
            .strip_prefix('"')
            .and_then(|rest| rest.strip_suffix('"'))
            .unwrap_or(quoted)
            .replace("\\\"", "\"")
    };
    let line_index = |line: &str| -> usize {
        line.split("/line/")
            .nth(1)
            .and_then(|rest| rest.split('"').next())
            .and_then(|n| n.parse().ok())
            .unwrap_or(0)
    };
    for (state_name, master, retired) in [
        ("on", true, false),
        ("off", false, false),
        ("retired", false, true),
    ] {
        for (viewport_width, viewport_height) in [
            (474.0_f32, 658.0_f32),
            (568.0, 900.0),
            (760.0, 820.0),
            (900.0, 820.0),
            (1_040.0, 820.0),
            (1_200.0, 820.0),
        ] {
            let context = format!("{state_name} at {viewport_width}");
            let (mut runtime, instance, view) = setup();
            let mut packages = packages_state_with_activity_policy(2, master);
            if retired {
                packages = packages.with_retired_switch_note(Some(note.clone()));
            }
            assert!(runtime.replace_settings_packages(packages, 2));
            let cx = view_cx_at(viewport_width, viewport_height);
            let mut service = std::collections::BTreeMap::new();
            let mut notes = std::collections::BTreeMap::new();
            let mut audits = Vec::new();
            let mut note_semantic = None;
            for page in 0..40 {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::Packages);
                state.page_scroll = page;
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                if let Some(detail) = compiled.semantic(&UiKey::new("packages/detail")) {
                    assert!(!detail.label.contains(&note), "{context}: {}", detail.label);
                }
                if let Some(semantic) = compiled.semantic(&UiKey::new("packages/retired-note")) {
                    note_semantic = Some(semantic.label.clone());
                }
                for line in compiled.paint_audit_lines() {
                    if line.contains("paint-text key=\"packages/loop-status/value/line/") {
                        service.insert(line_index(&line), painted(&line));
                        audits.push(line);
                    } else if line.contains("paint-text key=\"packages/retired-note/line/") {
                        notes.insert(line_index(&line), painted(&line));
                        audits.push(line);
                    }
                }
                if !service.is_empty() && (!retired || !notes.is_empty()) {
                    break;
                }
            }
            assert!(!service.is_empty(), "{context}: the service line paints");
            assert!(
                audits
                    .iter()
                    .all(|line| line.contains("overflow=false")
                        && line.contains("clip-truncated=false")),
                "{context}: every line fits its box:\n{}",
                audits.join("\n")
            );
            let service = service.into_values().collect::<Vec<_>>().join(" ");
            if master {
                assert!(service.starts_with("On \u{2014}"), "{context}: {service}");
            } else {
                assert!(
                    service.contains("Check & Update Now still works"),
                    "{context}: {service}"
                );
            }
            if retired {
                assert!(
                    service.contains("auto_update = false")
                        && service.contains("turning Automatic updates on removes it"),
                    "{context}: {service}"
                );
                assert_eq!(note_semantic.as_deref(), Some(note.as_str()), "{context}");
                let painted_note = notes.into_values().collect::<Vec<_>>().join(" ");
                assert_eq!(
                    painted_note, note,
                    "{context}: every word of the note paints"
                );
            } else {
                assert!(notes.is_empty() && note_semantic.is_none(), "{context}");
            }
        }
    }
}

/// A LONG ACTIVITY LINE WRAPS (review of Phase 4, 2026-09-23): the ~700-character refusal
/// class the program rows were reworked to show was cut by the painter's ellipsis in
/// Activity. Now it wraps to the page's measure — every line of it painted as trouble,
/// bounded, the rest in Open Log — and the compact page keeps the danger colour and
/// names each line as package activity, not "Managed program reason".
#[test]
fn a_long_activity_line_wraps_and_keeps_its_trouble() {
    use crate::packages_screen::{ActivityLine, MAX_ACTIVITY_LINES};
    let mut packages = packages_state_with_activity(2).projection();
    let long = format!(
        "claude 2.1.281 refused: {} \u{2014} keeping 2.1.280",
        "the platform signer check reported an unexpected team identifier ".repeat(8)
    );
    packages.activity[0] = ActivityLine {
        when: "2 h ago".into(),
        text: long.clone(),
        trouble: true,
    };
    for width in [SettingsWidth::Compact, SettingsWidth::Wide] {
        let rows = packages_activity_rows(0, &packages, width);
        let first: Vec<&ActivityRow> = rows
            .iter()
            .filter(|r| r.key == "packages/activity/0" || r.key.starts_with("packages/activity/0/"))
            .collect();
        assert!(first.len() > 1, "{width:?}: wrapped, not cut");
        assert!(first.len() <= MAX_ACTIVITY_LINES, "{width:?}: bounded");
        assert!(first[0].text.starts_with("2 h ago"), "{:?}", first[0].text);
        assert!(first.iter().all(|r| r.trouble), "every line is trouble");
        assert!(first.iter().skip(1).all(|r| r.continuation));
        assert!(
            first.iter().all(|r| crate::packages_screen::fits_one_line(
                &r.text,
                packages_reason_wrap_chars(width)
            )),
            "{width:?}: no line meets the ellipsis"
        );
        assert!(
            first.last().unwrap().text.contains("more)"),
            "the bound says what it hid"
        );
        // The next event keeps its own key.
        assert!(
            rows.iter()
                .any(|r| r.key == "packages/activity/1" && !r.continuation)
        );
    }
    let rows = packages_activity_rows(0, &packages, SettingsWidth::Compact);
    let (node, _) = compact_packages_activity_line(rows[1].clone());
    assert!(
        matches!(&node.content, UiContent::Group(g)
            if g.label.as_deref() == Some("Package activity, continued")),
        "{:?}",
        node.content
    );
    assert!(
        matches!(&node.children[0].content, UiContent::Text(t) if t.style == StyleRef::Danger),
        "trouble keeps the danger colour on the compact page"
    );
    let (node, _) = compact_packages_activity_line(rows[0].clone());
    assert!(matches!(&node.content, UiContent::Group(g)
        if g.label.as_deref() == Some("Package activity")));
}

/// The Security page's "This Mac" card exists only on macOS and only once the
/// host's machine read has completed; it carries the measured lines, the
/// "Apply now would" verdict, the last-change memory and the Apply now button
/// (enabled exactly when the verdict says something is left to do); and it is
/// absent from Modified and from a global search. On a short landscape window
/// it is a slice of its own, never shed.
/// THE OTHER DOOR THE PROMISE OFFERS. "Apply now" exists as a button on the card
/// AND as a palette command; the command had no test at all, so its id, its title,
/// its enabled bit and its absence off the Security route were free to drift.
#[cfg(target_os = "macos")]
#[test]
fn the_security_route_offers_the_machine_apply_command_in_the_palette() {
    use atpkg::machine::{HomePosture, UcPosture};
    let (mut runtime, instance, view) = setup();
    let command_named = |runtime: &NativeRuntime, view| {
        runtime
            .commands(instance, view)
            .unwrap()
            .into_iter()
            .find(|command| command.id.as_str() == "machine/apply")
    };
    // Another route: absent, however the machine reads.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Default,
                2,
                HomePosture::Account
            )),
        ),
        2,
    ));
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Packages);
    }
    assert!(
        command_named(&runtime, view).is_none(),
        "the command belongs to Security"
    );

    // Security, with something to apply: offered and ENABLED.
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Security);
    }
    let offered = command_named(&runtime, view).expect("Security offers it");
    assert_eq!(offered.title, "This Mac: Apply Machine Settings Now");
    assert!(offered.enabled, "something is left to apply");

    // Nothing left to apply: still offered (the card is there), but disabled —
    // the same bit the button reads, so the two doors never disagree.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Disabled,
                0,
                HomePosture::Account
            )),
        ),
        3,
    ));
    let settled = command_named(&runtime, view).expect("still offered");
    assert!(!settled.enabled, "nothing to apply ⇒ nothing to press");
}

/// THE PAGE LIMIT MUST COUNT EVERY SLICE THE RENDERER DRAWS. The landscape pager
/// bounds `page_scroll` by `record_result_page_limit`, and that count omitted the
/// macOS-access and This Mac cards — which the renderer DOES count as slices — so on
/// a window that pages, the rows after them could not be reached: on Security, that
/// is the two `[machine]` switches, the whole point of the card above them.
#[cfg(target_os = "macos")]
#[test]
fn the_landscape_pager_reaches_the_last_security_row_with_both_cards_present() {
    use aterm_containment::FdaScope;
    use atpkg::machine::{HomePosture, UcPosture};
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Security);
        assert!(state.replace_macos_access(access_fixture(
            FdaState::Denied,
            DrClass::Identity,
            FdaScope::Unknown
        )));
    }
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Default,
                2,
                HomePosture::Account
            )),
        ),
        3,
    ));
    let cx = view_cx_at(624.0, 348.0);
    // Page through with the PAGE-DOWN ACTION, not by writing `page_scroll`: the
    // limit is what clamps that reducer, so a test that sets the field directly
    // cannot see a limit that is too small.
    let mut seen: std::collections::BTreeSet<String> = std::collections::BTreeSet::new();
    for page in 0..64 {
        if page > 0 {
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new("settings/page-down"),
                        value: None,
                    }),
                )
                .unwrap();
        }
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        compiled.validate_parity().unwrap();
        let rows: Vec<String> = compiled
            .semantics
            .iter()
            .filter(|node| node.key.as_str().starts_with("settings/row/"))
            .map(|node| node.key.as_str().to_string())
            .collect();
        // No early break: the first pages are the two cards and carry no control
        // row at all, which is exactly the shape that made the old limit too short.
        seen.extend(rows);
    }
    for key in ["machine.universal_control", "machine.spotlight_noindex"] {
        assert!(
            seen.iter().any(|row| row.contains(key)),
            "paging never reached {key}: {seen:?}"
        );
    }
}

#[test]
fn the_security_page_paints_the_machine_card_only_on_macos_once_observed() {
    use atpkg::machine::{HomePosture, UcPosture};
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Security);
    }
    let cx = view_cx_at(1100.0, 760.0);
    // Unobserved: no card on any platform — nothing invented.
    assert!(runtime.replace_settings_packages(live_packages_state(None), 2));
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new("settings/machine/heading"))
            .is_none(),
        "no machine read yet ⇒ no card"
    );

    // Observed with something left to do.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Default,
                2,
                HomePosture::Account
            )),
        ),
        3,
    ));
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    let heading = compiled.semantic(&UiKey::new("settings/machine/heading"));
    assert_eq!(
        heading.is_some(),
        cfg!(target_os = "macos"),
        "the card is a macOS host-settings surface"
    );
    if !cfg!(target_os = "macos") {
        return;
    }
    let text = |key: &str| {
        compiled
            .semantic(&UiKey::new(key))
            .unwrap_or_else(|| panic!("{key} is painted"))
            .label
            .clone()
    };
    assert_eq!(
        text("settings/machine/universal-control"),
        "Universal Control: at the OS default — the cursor roams to other Macs and iPads"
    );
    assert_eq!(
        text("settings/machine/spotlight"),
        "Build output: 8 target dirs hidden, 3 open to Spotlight — 2 a pass would hide"
    );
    assert_eq!(
        text("settings/machine/next"),
        "Apply now would set: Universal Control off for this host; 2 target dir(s) hidden from Spotlight"
    );
    assert_eq!(
        text("settings/machine/last-applied"),
        "No change recorded this launch"
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/machine/debugger"))
            .is_none(),
        "no Debugger access row on this page ⇒ no line pointing at it"
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/machine/home"))
            .is_none(),
        "nothing in the way ⇒ no reason line"
    );

    let apply = compiled
        .semantic(&UiKey::new(MACHINE_APPLY))
        .expect("Apply now is a hit target");
    assert!(apply.state.as_ref().is_some_and(|s| s.enabled));

    // Nothing left: the verdict line says so and the button is disabled.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Disabled,
                0,
                HomePosture::Account
            )),
        ),
        4,
    ));
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/machine/universal-control"))
            .unwrap()
            .label,
        "Universal Control: disabled on this Mac"
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/machine/next"))
            .unwrap()
            .label
            .starts_with("Nothing an apply can do")
    );
    assert!(
        compiled
            .semantic(&UiKey::new(MACHINE_APPLY))
            .unwrap()
            .state
            .as_ref()
            .is_some_and(|s| !s.enabled)
    );

    // A home mismatch names the reason and disables the button.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Default,
                2,
                HomePosture::Mismatch
            )),
        ),
        5,
    ));
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new("settings/machine/home"))
            .unwrap()
            .label
            .starts_with("Not applied here")
    );
    assert!(
        compiled
            .semantic(&UiKey::new(MACHINE_APPLY))
            .unwrap()
            .state
            .as_ref()
            .is_some_and(|s| !s.enabled)
    );

    // A read error after a good record: the measured lines say they are prior,
    // the reason line names the error, and Apply now is off.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine_reads(
            None,
            true,
            None,
            vec![
                Ok(machine_state_fixture(
                    UcPosture::Default,
                    2,
                    HomePosture::Account
                )),
                Err("atpkg machine printed no state".to_string()),
            ],
        ),
        6,
    ));
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new("settings/machine/universal-control"))
            .unwrap()
            .label
            .ends_with("(from the last successful read)")
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/machine/home"))
            .unwrap()
            .label
            .starts_with("Could not read the machine state")
    );
    assert!(
        compiled
            .semantic(&UiKey::new(MACHINE_APPLY))
            .unwrap()
            .state
            .as_ref()
            .is_some_and(|s| !s.enabled)
    );

    // Modified and a global search never carry the card.
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Modified);
    }
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert!(
        compiled
            .semantic(&UiKey::new("settings/machine/heading"))
            .is_none()
    );
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Security);
        state.search = "spotlight".to_string();
    }
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert!(
        compiled
            .semantic(&UiKey::new("settings/machine/heading"))
            .is_none(),
        "a search lists rows, not the card"
    );

    // Short landscape (624x348 takes the landscape pager): page 0 is the card.
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.search.clear();
        state.page_scroll = 0;
    }
    let landscape = view_cx_at(624.0, 348.0);
    let compiled = compile_settings_view(&runtime, instance, view, &landscape);
    compiled.validate_parity().unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new("settings/machine/heading"))
            .is_some(),
        "the landscape pager keeps the card as its own slice"
    );
    assert!(
        compiled.semantic(&UiKey::new(MACHINE_APPLY)).is_some(),
        "and Apply now is a hit target there"
    );

    // With the macOS access block drawn above it, the card points at the
    // Debugger access row in that block.
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.replace_macos_access(debugger_access(debugger_facts(
            aterm_containment::consent::DebuggerMode::Disabled,
            aterm_containment::consent::DebuggerMember::Admin,
            aterm_containment::consent::SelfHardening::Hardened,
        )));
    }
    let with_row = compile_settings_view(&runtime, instance, view, &view_cx_at(1100.0, 2400.0));
    with_row.validate_parity().unwrap();
    assert!(
        with_row
            .semantic(&UiKey::new("settings/macos-access/debugger/state"))
            .is_some(),
        "the Debugger access row is drawn"
    );
    assert_eq!(
        with_row
            .semantic(&UiKey::new("settings/machine/debugger"))
            .map(|node| node.label.clone())
            .as_deref(),
        Some(
            "Machine-wide, like Debugger access above, but applied automatically; Debugger \
             access is changed only by you."
        )
    );
}

/// `machine/apply` goes through the same reducer as every package verb: refused
/// honestly before the machine is read (no effect minted), dispatched as the
/// typed `MachineApply` request when the measured state says something is left
/// to do, settled through PackagesFinished, refused while a verb runs, and
/// refused — with the verdict — when there is nothing to apply.
#[test]
fn machine_apply_gates_dispatch_and_finish() {
    use atpkg::machine::{HomePosture, UcPosture};
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Security),
                value: None,
            }),
        )
        .unwrap();
    let apply = || {
        AppEvent::Action(ActionInvocation {
            id: ActionId::new(MACHINE_APPLY),
            value: None,
        })
    };
    let no_effect = |result: &crate::native_app::DispatchOutcome| {
        result
            .effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::Packages { .. }))
    };
    let feedback = |runtime: &NativeRuntime| -> String {
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!();
        };
        state.feedback.clone().unwrap_or_default()
    };

    // Unobserved (fresh controller): refuse without an effect.
    let refused = runtime.dispatch(instance, view, apply()).unwrap();
    assert!(
        no_effect(&refused),
        "no effect before the first observation"
    );
    assert!(feedback(&runtime).contains("still being read"));

    // Packages observed, machine not yet read: still refused, in machine words.
    assert!(runtime.replace_settings_packages(live_packages_state(None), 3));
    let refused = runtime.dispatch(instance, view, apply()).unwrap();
    assert!(no_effect(&refused));
    if cfg!(target_os = "macos") {
        assert!(
            feedback(&runtime).contains("machine state is still being read"),
            "{}",
            feedback(&runtime)
        );
    } else {
        assert!(feedback(&runtime).contains("macOS host settings"));
        return;
    }

    // Nothing to apply: refused with the verdict, no effect.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Disabled,
                0,
                HomePosture::Account
            )),
        ),
        4,
    ));
    let refused = runtime.dispatch(instance, view, apply()).unwrap();
    assert!(no_effect(&refused));
    assert!(
        feedback(&runtime).starts_with("Nothing to apply"),
        "{}",
        feedback(&runtime)
    );

    // A home mismatch: refused with the reason.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Default,
                2,
                HomePosture::Mismatch
            )),
        ),
        5,
    ));
    let refused = runtime.dispatch(instance, view, apply()).unwrap();
    assert!(no_effect(&refused));
    assert!(
        feedback(&runtime).starts_with("Not applied here"),
        "{}",
        feedback(&runtime)
    );

    // Something left to do: the typed request reaches the host executor.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            None,
            Ok(machine_state_fixture(
                UcPosture::Default,
                2,
                HomePosture::Account
            )),
        ),
        6,
    ));
    let accepted = runtime.dispatch(instance, view, apply()).unwrap();
    let operation = accepted
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::Packages { request, reply } => {
                assert_eq!(*request, crate::native_app::PackagesRequest::MachineApply);
                Some(reply.operation)
            }
            _ => None,
        })
        .expect("a live machine dispatches the machine apply");
    assert_eq!(feedback(&runtime), "Applying the machine settings…");
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert_eq!(state.pending.len(), 1);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::PackagesFinished {
                operation,
                outcome: crate::native_app::PackagesOutcome::Accepted,
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(state.pending.is_empty());
    // Admission says nothing in the footer (ruling 265): the card's
    // headline already says the verb is running.
    assert_eq!(state.feedback, None);

    // Busy with the apply itself: a second press is refused without an effect.
    assert!(runtime.replace_settings_packages(
        live_packages_state_with_machine(
            Some(crate::packages_screen::PackagesBusy::MachineApply),
            Ok(machine_state_fixture(
                UcPosture::Default,
                2,
                HomePosture::Account
            )),
        ),
        7,
    ));
    let busy = runtime.dispatch(instance, view, apply()).unwrap();
    assert!(no_effect(&busy), "a running verb blocks a second one");
    assert!(
        feedback(&runtime).contains("already running"),
        "{}",
        feedback(&runtime)
    );
}

/// With the package manager inert (no pinned root key) or the status collection
/// torn, `packages/check` is refused with the true
/// cause — and `machine/apply`, a local verb, still dispatches.
#[test]
fn machine_apply_dispatches_with_the_manager_off() {
    use atpkg::machine::{HomePosture, UcPosture};
    for (manager_enabled, collection_error) in
        [(false, None), (true, Some("status.toml: torn record"))]
    {
        let (mut runtime, instance, view) = setup();
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::Security),
                    value: None,
                }),
            )
            .unwrap();
        assert!(runtime.replace_settings_packages(
            live_packages_state_with_machine_reads(
                None,
                manager_enabled,
                collection_error,
                vec![Ok(machine_state_fixture(
                    UcPosture::Default,
                    2,
                    HomePosture::Account
                ))],
            ),
            3,
        ));
        let outcome = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(MACHINE_APPLY),
                    value: None,
                }),
            )
            .unwrap();
        let dispatched = outcome.effects.iter().any(|effect| {
            matches!(
                effect,
                AppEffect::Packages {
                    request: crate::native_app::PackagesRequest::MachineApply,
                    ..
                }
            )
        });
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!();
        };
        let feedback = state.feedback.clone().unwrap_or_default();
        if cfg!(target_os = "macos") {
            assert!(
                dispatched,
                "manager_enabled={manager_enabled} error={collection_error:?}: {feedback}"
            );
            assert_eq!(feedback, "Applying the machine settings…");
        } else {
            assert!(!dispatched);
            assert!(feedback.contains("macOS host settings"), "{feedback}");
            continue;
        }
        if !manager_enabled {
            // The package verb in the same state is still refused, with the cause.
            let refused = runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new("packages/check"),
                        value: None,
                    }),
                )
                .unwrap();
            assert!(
                refused
                    .effects
                    .iter()
                    .all(|effect| !matches!(effect, AppEffect::Packages { .. }))
            );
            let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
                unreachable!();
            };
            let feedback = state.feedback.clone().unwrap_or_default();
            assert!(
                feedback.contains("can\u{2019}t install packages") && !feedback.contains("ATPKG_"),
                "{feedback}"
            );
        }
    }
}

/// The action reducer refuses honestly (unobserved / busy) without minting
/// an effect, dispatches the typed request when live, and settles pending
/// state through PackagesFinished — the full effect-quartet contract.
#[test]
fn packages_actions_gate_dispatch_and_finish() {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Packages),
                value: None,
            }),
        )
        .unwrap();
    let check = || {
        AppEvent::Action(ActionInvocation {
            id: ActionId::new("packages/check"),
            value: None,
        })
    };

    // Unobserved (fresh controller): refuse without an effect.
    let refused = runtime.dispatch(instance, view, check()).unwrap();
    assert!(
        refused
            .effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::Packages { .. })),
        "no effect before the first worker observation"
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(
        state
            .feedback
            .as_deref()
            .unwrap()
            .contains("still being read")
    );

    // Live manager: the typed request goes to the host executor.
    assert!(runtime.replace_settings_packages(live_packages_state(None), 3));
    let accepted = runtime.dispatch(instance, view, check()).unwrap();
    let operation = accepted
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::Packages { request, reply } => {
                assert_eq!(*request, crate::native_app::PackagesRequest::CheckUpdate);
                Some(reply.operation)
            }
            _ => None,
        })
        .expect("a live manager dispatches the packages effect");
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert_eq!(state.pending.len(), 1);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::PackagesFinished {
                operation,
                outcome: crate::native_app::PackagesOutcome::Accepted,
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(state.pending.is_empty());
    // Admission says nothing in the footer (ruling 265): the card's
    // headline already says the verb is running.
    assert_eq!(state.feedback, None);

    // The worker later exits non-zero while status.toml still contains an
    // older success. Typed completion must replace the admission message.
    assert!(runtime.replace_settings_packages(failed_packages_state(), 4));
    runtime
        .dispatch(instance, view, AppEvent::PackagesChanged { revision: 4 })
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    // The failure is the card's headline and detail, not a footer that
    // repeats them (ruling 265).
    assert_eq!(state.feedback, None);
    let card = failed_packages_state().projection();
    assert_eq!(card.headline, "Package check failed");
    assert!(
        card.detail
            .as_deref()
            .is_some_and(|d| d.contains("atpkg update exited with status 7")),
        "{:?}",
        card.detail
    );

    // Busy: the second verb is refused without a second effect.
    assert!(runtime.replace_settings_packages(
        live_packages_state(Some(crate::packages_screen::PackagesBusy::Check)),
        5,
    ));
    let busy = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("packages/install-default"),
                value: None,
            }),
        )
        .unwrap();
    assert!(
        busy.effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::Packages { .. })),
        "a running verb blocks a second one"
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(
        state
            .feedback
            .as_deref()
            .unwrap()
            .contains("already running")
    );
}

/// A live packages snapshot whose one program carries `state` VERBATIM — the shape
/// of the 2026-09-14 incident when `state` is the recorded refusal.
fn packages_state_with_program_state(state: &str) -> PackagesState {
    let mut programs = std::collections::BTreeMap::new();
    programs.insert(
        "ay".to_string(),
        atpkg::ProgramStatus {
            installed_build: Some(1971),
            state: state.to_string(),
            tree_root: String::new(),
        },
    );
    let status = atpkg::Status {
        schema: 1,
        updated_at: "2026-09-14T00:00:00Z".to_string(),
        enabled: true,
        index_source: "alabsystems/aterm".to_string(),
        outcome: "install failed".to_string(),
        seams: Vec::new(),
        last_success_at: String::new(),
        last_index_build: 0,
        index_build_changed_at: String::new(),
        last_pass: String::new(),
        last_pass_at: String::new(),
        last_pass_attempted_index_build: 0,
        last_pass_attempted_at: String::new(),
        pass_seq: 0,
        stale_index_only_pass_seq: 0,
        programs,
        extra: Default::default(),
    };
    let mut service = crate::packages_screen::PackagesService::new();
    let sequence = service.begin(None).unwrap();
    assert!(service.finish(
        sequence,
        crate::packages_screen::PackagesWorkerCompletion::refresh(
            crate::packages_screen::PackagesStatusReport::from_parts(
                true,
                true,
                "fp".to_string(),
                Some(&status),
                &[],
            ),
        ),
    ));
    service.state(true, true, true)
}

/// 2026-09-14: the install pass recorded a ~700-character `error: stage: …` state
/// whose `fix:` clause came LAST; the row ellipsized it to one line, cutting exactly
/// the fix. Now the fix leads, whole, on continuation lines under its row at every
/// width — measured by the painter, not just the character budget — and a short
/// state still paints byte-for-byte as before.
#[test]
fn packages_long_reason_rows_put_the_fix_first_and_keep_short_states_stable() {
    let incident = crate::packages_screen::INCIDENT_2026_09_14_REASON.to_string();
    assert!(
        incident.chars().count() > 600,
        "{}",
        incident.chars().count()
    );
    let fix_at = incident
        .find(" fix: ")
        .expect("atpkg spells the remedy ` fix: `");
    let fix_clause = &incident[fix_at + " fix: ".len()..];
    let widths = [
        SettingsWidth::Compact,
        SettingsWidth::Medium,
        SettingsWidth::Wide,
    ];

    // The common case: one line, the row's facts inline (Phase 4: version, source,
    // latest known — the pinned state is what those words say), identical at every
    // width.
    let short =
        packages_state_with_program_state("managed 1971 \u{2014} pinned by index 41").projection();
    for width in widths {
        let lines = packages_program_lines(&short, width);
        assert_eq!(lines.len(), 1, "{width:?}");
        assert_eq!(
            lines[0].text, "ay  \u{b7}  build 1971  \u{b7}  up to date",
            "{width:?}"
        );
        assert!(!lines[0].continuation);
        assert_eq!(packages_program_row_count(&short, width), 1);
    }

    // The incident: the state leaves the row, and the fix is the first line under it.
    let long = packages_state_with_program_state(&incident).projection();
    for width in widths {
        let budget = packages_reason_wrap_chars(width);
        let lines = packages_program_lines(&long, width);
        assert_eq!(lines[0].key, "packages/programs/ay");
        assert_eq!(
            lines[0].text, "ay  \u{b7}  build 1971  \u{b7}  from ALab",
            "{width:?}: a FAULT keeps its own words, whole, below the row's facts"
        );
        assert!(!lines[0].continuation);
        let reason: Vec<String> = lines[1..].iter().map(|line| line.text.clone()).collect();
        assert_eq!(
            reason,
            crate::packages_screen::reason_lines(&incident, budget),
            "{width:?}"
        );
        for (index, line) in lines[1..].iter().enumerate() {
            assert!(line.continuation);
            assert_eq!(
                line.key,
                format!("packages/programs/ay/reason/{}", index + 1)
            );
            // The wrap measures glyph ADVANCE, not characters (a line of narrow
            // glyphs may hold more than `budget` of them); the paint audit below is
            // what says the line fits the row.
            assert!(
                line.text.chars().count() <= budget * 5 / 4,
                "{width:?}: {:?}",
                line.text
            );
        }
        assert!(
            lines[1]
                .text
                .starts_with("fix: unset ATPKG_REFUSE_TRACKED_INSTALL"),
            "{width:?}: {:?}",
            lines[1].text
        );
        let fix_lines: Vec<&str> = reason
            .iter()
            .map(String::as_str)
            .take_while(|line| !line.starts_with("error: stage:") && !line.starts_with('\u{2026}'))
            .collect();
        assert_eq!(
            fix_lines.join(" "),
            format!("fix: {fix_clause}"),
            "{width:?}: nothing of the fix is cut"
        );
        assert_eq!(packages_program_row_count(&long, width), lines.len());
    }

    // Painted, every continuation line fits its box at the compact and the wide
    // viewport — the painter's own overflow audit, not the character budget.
    for (viewport_width, viewport_height) in [(474.0_f32, 658.0_f32), (1_280.0, 800.0)] {
        let (mut runtime, instance, view) = setup();
        assert!(runtime.replace_settings_packages(packages_state_with_program_state(&incident), 2));
        let cx = view_cx_at(viewport_width, viewport_height);
        let mut reason_audit = Vec::new();
        for page in 0..16 {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Packages);
            state.page_scroll = page;
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            let painted: Vec<String> = compiled
                .paint_audit_lines()
                .into_iter()
                .filter(|line| line.contains("paint-text key=\"packages/programs/ay/reason/"))
                .collect();
            if !painted.is_empty() {
                reason_audit = painted;
                break;
            }
        }
        assert!(
            reason_audit
                .iter()
                .any(|line| line.contains("packages/programs/ay/reason/1")),
            "{viewport_width}: the fix line paints:\n{}",
            reason_audit.join("\n")
        );
        assert!(
            reason_audit.iter().all(
                |line| line.contains("overflow=false") && !line.contains("clip-truncated=true")
            ),
            "{viewport_width}:\n{}",
            reason_audit.join("\n")
        );
    }
}

/// The program list (§17.2 states verbatim): one flat list with no group headings and
/// no Install controls — the Extras and Needs-admin groups went with the extras and the
/// OS-installer protocols (design 2026-09-22 §5.3(b)/(c), 2026-09-24). A vendor row
/// names its version and source, and a row an older atpkg wrote in a retired
/// spelling rides verbatim. (No install id reaches the reducer: its packages arms
/// are exact matches and `PackagesRequest` has no install-one variant.)
#[test]
fn packages_rows_are_one_list_with_no_install_controls() {
    let mut programs = std::collections::BTreeMap::new();
    let claude = atpkg::vendor_direct::Version::parse("2.1.280")
        .unwrap()
        .build_id();
    for (name, state, build) in [
        ("ay", atpkg::state::managed(1971, 41), Some(1971)),
        (
            "claude",
            atpkg::state::vendor_managed("2.1.280", "Anthropic"),
            Some(claude),
        ),
        (
            "clt",
            "needs admin — run: aterm pkg install clt".to_string(),
            None,
        ),
    ] {
        programs.insert(
            name.to_string(),
            atpkg::ProgramStatus {
                installed_build: build,
                state,
                tree_root: String::new(),
            },
        );
    }
    let status = atpkg::Status {
        schema: 1,
        programs,
        ..Default::default()
    };
    let mut service = crate::packages_screen::PackagesService::new();
    let sequence = service.begin(None).unwrap();
    assert!(service.finish(
        sequence,
        crate::packages_screen::PackagesWorkerCompletion::refresh(
            crate::packages_screen::PackagesStatusReport::from_parts(
                true,
                true,
                "fp".to_string(),
                Some(&status),
                &[],
            ),
        ),
    ));
    let state = service.state(true, true, true);
    let projection = state.projection();
    let lines = packages_program_lines(&projection, SettingsWidth::Wide);
    let keys: Vec<&str> = lines.iter().map(|line| line.key.as_str()).collect();
    assert_eq!(
        keys,
        vec![
            "packages/programs/ay",
            "packages/programs/claude",
            "packages/programs/clt",
        ]
    );
    let line = |key: &str| lines.iter().find(|line| line.key == key).unwrap();
    assert_eq!(
        line("packages/programs/ay").text,
        "ay  ·  build 1971  ·  up to date"
    );
    // A vendor program's row names its version and source — never its store id.
    let claude = &line("packages/programs/claude").text;
    assert!(
        claude.contains("  ·  2.1.280  ·  latest from Anthropic"),
        "{claude}"
    );
    assert!(!claude.contains("build "), "{claude}");
    assert!(
        line("packages/programs/clt")
            .text
            .contains("needs admin — run: aterm pkg install clt"),
        "a retired spelling rides verbatim"
    );
    assert_eq!(
        packages_program_row_count(&projection, SettingsWidth::Wide),
        lines.len()
    );
}

/// The two switches on the special page are ordinary registry rows: activation
/// flips the RESOLVED value through the dotted-key ConfigPatch (both default ON →
/// the first flip writes false), with per-key OCC expectations.
#[test]
fn packages_consent_switches_patch_the_dotted_keys() {
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(live_packages_state(None), 2));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Packages),
                value: None,
            }),
        )
        .unwrap();
    for (key, expected_write) in [
        (prefs::EDIT_PACKAGES_ENABLED, "false"),
        (prefs::EDIT_PACKAGES_AUTO_INSTALL, "false"),
    ] {
        let outcome = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/set/{key}")),
                    value: None,
                }),
            )
            .unwrap();
        let edit = outcome
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::ConfigPatch { patch, .. } => patch.edits.first().cloned(),
                _ => None,
            })
            .unwrap_or_else(|| panic!("{key} switch emits a config patch"));
        assert_eq!(edit.key, key);
        assert_eq!(edit.value.as_deref(), Some(expected_write));
        assert_eq!(
            edit.expected,
            ExpectedConfigValue::Exact(None),
            "an absent [packages] child key carries an exact-absent OCC expectation"
        );
    }
}

/// Packages revision fan-out mirrors the updater: the shared controller
/// snapshot advances and every view bumps its presentation revision.
#[test]
fn packages_changed_revision_repaints_every_view() {
    let (mut runtime, instance, view) = setup();
    let before = match runtime.view_state(view) {
        Some(AppViewState::Settings(state)) => state.common.presentation_revision,
        _ => unreachable!(),
    };
    runtime
        .dispatch(instance, view, AppEvent::PackagesChanged { revision: 7 })
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(state.common.presentation_revision > before);
}

#[test]
fn responsive_boundaries_keep_every_actionable_node_whole() {
    assert_eq!(SettingsWidth::for_viewport(759.99), SettingsWidth::Compact);
    assert_eq!(SettingsWidth::for_viewport(760.0), SettingsWidth::Medium);
    assert_eq!(SettingsWidth::for_viewport(1_039.99), SettingsWidth::Medium);
    assert_eq!(SettingsWidth::for_viewport(1_040.0), SettingsWidth::Wide);
    assert_eq!(
        SettingsWidth::for_viewport_at_scale(1_200.0, 2.0),
        SettingsWidth::Compact,
        "2× content responds to effective measure instead of clipping a desktop rail"
    );
    assert_eq!(SettingsWidth::Compact.row_height_at_scale(2.0), 108.0);
    assert_eq!(SettingsWidth::Medium.row_height_at_scale(2.0), 80.0);
    assert_eq!(scaled_control_height_at_scale(2.0), 64.0);
    assert_eq!(compact_toolbar_height_at_scale(2.0), 80.0);

    let (runtime, instance, view) = setup();
    for width in [360.0, 759.0, 760.0, 1_039.0, 1_040.0, 1_280.0] {
        let cx = view_cx_at(width, 820.0);
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        compiled.validate_parity().unwrap();
        for hit in &compiled.hits {
            let painted = compiled
                .paint
                .iter()
                .find(|node| node.key == hit.key)
                .expect("action is painted");
            let delta = (painted.rect.x - hit.rect.x).abs()
                + (painted.rect.y - hit.rect.y).abs()
                + (painted.rect.width - hit.rect.width).abs()
                + (painted.rect.height - hit.rect.height).abs();
            assert!(
                delta < 0.01,
                "{:?} clips at width {width}: paint={:?}, hit={:?}",
                hit.key,
                painted.rect,
                hit.rect
            );
            assert!(hit.rect.width > 0.0 && hit.rect.height > 0.0);
        }
    }
}

#[test]
fn visual_preview_matrix_covers_four_viewports_at_three_text_scales() {
    at_each_text_scale(
        &[1.0, 1.5, 2.0],
        "Settings viewport/scale matrix",
        visual_preview_matrix_covers_four_viewports_at_three_text_scales_at_scale,
    );
}

/// One rung of [`visual_preview_matrix_covers_four_viewports_at_three_text_scales`] ([`at_each_text_scale`]).
fn visual_preview_matrix_covers_four_viewports_at_three_text_scales_at_scale(scale: f32) {
    let mut renderer = aterm_render::Renderer::from_bytes(
        include_bytes!("../../aterm-render/tests/fixtures/jetbrains-mono.ttf"),
        14.0,
        aterm_render::Theme::default(),
    )
    .expect("matrix semantic renderer");
    renderer.set_runtime_font_discovery(false);
    renderer.prepare_semantic_typography("Bold Italic != => 你好 ∑✓♥ 😀 🚀 👩‍💻");
    // SETTLED install: `set_chrome_fonts` would park an async prewarm
    // worker whose landing between two paints of one state could swap the
    // semantic cascade mid-assertion (cross-test flake under a parallel
    // suite run). The fixture warms the cascade inline instead.
    crate::tray_raster::install_settled_chrome_fonts_for_test(renderer);

    let compile = |runtime: &NativeRuntime,
                   instance: crate::native_app::AppInstanceId,
                   view: crate::native_app::ViewId,
                   width: f32,
                   height: f32| {
        let mut cx = view_cx_at(width, height);
        let state = match runtime.view_state(view) {
            Some(AppViewState::Settings(state)) => state,
            _ => panic!("Settings view state"),
        };
        cx.semantic_font = state
            .preview_font_candidate(
                cx.animation_phase_ms,
                cx.motion,
                cx.terminal_font_px,
                cx.terminal_theme,
            )
            .map(|candidate| crate::tray_raster::prepare_semantic_font(&candidate));
        runtime
            .render(instance, view, &cx)
            .expect("Settings renders")
            .compile(cx.viewport)
            .expect("Settings compiles")
    };
    let assert_whole =
        |compiled: &crate::native_ui::CompiledUi, width: f32, height: f32, context: &str| {
            compiled
                .validate_parity()
                .unwrap_or_else(|error| panic!("{context}: {error:?}"));
            for hit in &compiled.hits {
                let paint = compiled
                    .paint
                    .iter()
                    .find(|paint| paint.key == hit.key)
                    .unwrap_or_else(|| panic!("{context}: {:?} has no paint", hit.key));
                let parity_delta = (paint.rect.x - hit.rect.x).abs()
                    + (paint.rect.y - hit.rect.y).abs()
                    + (paint.rect.width - hit.rect.width).abs()
                    + (paint.rect.height - hit.rect.height).abs();
                assert!(
                    parity_delta < 0.001,
                    "{context}: {:?} parity differs by {parity_delta}: paint={:?}, hit={:?}",
                    hit.key,
                    paint.rect,
                    hit.rect,
                );
                assert!(
                    hit.rect.x >= -0.01
                        && hit.rect.y >= -0.01
                        && hit.rect.right() <= width + 0.01
                        && hit.rect.bottom() <= height + 0.01,
                    "{context}: {:?} is clipped: {:?}",
                    hit.key,
                    hit.rect,
                );
            }
        };

    let viewports = [
        (624.0, 404.0),
        (320.0, 568.0),
        (390.0, 844.0),
        (568.0, 320.0),
        (1_280.0, 800.0),
    ];
    let routes = [
        SettingsRoute::Appearance,
        SettingsRoute::TextFonts,
        SettingsRoute::CursorMotion,
        SettingsRoute::WindowTabs,
    ];
    for (width, height) in viewports {
        for route in routes {
            let (mut runtime, instance, view) = setup();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!()
            };
            state.navigate(route);
            let compiled = compile(&runtime, instance, view, width, height);
            let context = format!("{} {width}×{height} at {scale}×", route.label());
            assert_whole(&compiled, width, height, &context);
            let preview_key = UiKey::new(format!("settings/preview{}", route.path()));
            let preview = compiled
                .semantic(&preview_key)
                .unwrap_or_else(|| panic!("{context}: live preview is visible"));
            let expected_height =
                renderer_preview_height(SettingsWidth::for_viewport_at_scale(width, scale));
            if route == SettingsRoute::TextFonts {
                assert!(
                    preview.rect.height >= expected_height,
                    "{context}: typography keeps its minimum"
                );
                assert!(
                    preview.rect.bottom() <= height + 0.01,
                    "{context}: whole specimen card"
                );
                let paint = compiled
                    .paint
                    .iter()
                    .find(|paint| paint.key == preview_key)
                    .unwrap();
                let UiContent::SettingsPreview(spec) = &paint.content else {
                    unreachable!()
                };
                let mut prims = Vec::new();
                spec.paint(
                    &mut prims,
                    paint.rect,
                    aterm_render::Theme::default(),
                    crate::settings::Roles::from_theme(aterm_render::Theme::default()),
                );
                let (y, specimen) = prims
                    .iter()
                    .find_map(|prim| match prim {
                        crate::widget::DrawPrim::TerminalSpecimen { y, spec, .. } => {
                            Some((*y, spec))
                        }
                        _ => None,
                    })
                    .expect("typography paints complete specimen rows");
                if width == 624.0 && height == 404.0 && scale == 1.0 {
                    assert_eq!(
                        specimen.input.rows, 5,
                        "the default desktop viewport shows the complete typography sample"
                    );
                }
                let pill_y = prims
                    .iter()
                    .find_map(|prim| match prim {
                        crate::widget::DrawPrim::Panel { y, radius, .. } if *radius == 6.0 => {
                            Some(*y)
                        }
                        _ => None,
                    })
                    .expect("separate status band");
                for dpi in [1.0, 1.25, 2.0, 3.0] {
                    let variations = specimen
                        .variations
                        .iter()
                        .map(|v| (v.tag, v.value()))
                        .collect::<Vec<_>>();
                    let row_h = specimen
                        .prepared_font
                        .specimen_cell_height(
                            specimen.font_px * dpi,
                            specimen.line_height,
                            &variations,
                        )
                        .unwrap() as f32
                        / dpi;
                    assert!(
                        y + specimen.input.rows as f32 * row_h <= pill_y - 4.0,
                        "{context} at {dpi}dpi: specimen rows never meet the status badge"
                    );
                }
            } else {
                assert!(
                    (preview.rect.height - expected_height).abs() < 0.01,
                    "{context}: preview height is {:?}, expected {expected_height}",
                    preview.rect,
                );
            }

            if height <= 420.0 {
                let navigation = compiled
                    .semantic(&UiKey::new("settings/results-window"))
                    .expect("short landscape discloses the next virtual slice");
                assert!(navigation.rect.bottom() <= height + 0.01, "{context}");
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!()
                };
                state.page_scroll = 1;
                let controls = compile(&runtime, instance, view, width, height);
                let scrolled_context = format!("{context}, settings slice");
                assert_whole(&controls, width, height, &scrolled_context);
                assert!(
                    controls.semantic(&preview_key).is_none(),
                    "{scrolled_context}: preview yielded its bounded slice"
                );
                assert!(
                    controls
                        .semantics
                        .iter()
                        .any(|node| node.key.as_str().starts_with("settings/control/")),
                    "{scrolled_context}: the first real control is reachable"
                );

                if (scale - 2.0).abs() < f32::EPSILON {
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!()
                    };
                    let section = route.section().expect("preview route has a section");
                    let mut fields = state
                        .legacy
                        .fields
                        .iter()
                        .enumerate()
                        .filter(|(_, field)| prefs::section_of(field.key) == section)
                        .filter(|(_, field)| settings_field_is_visible(field.key, false, false))
                        .collect::<Vec<_>>();
                    fields.sort_by_key(|(index, field)| (prefs::group_of(field.key).1, *index));
                    let last_key = fields.last().expect("preview route has fields").1.key;
                    state.page_scroll = fields.len();
                    let final_window = compile(&runtime, instance, view, width, height);
                    let final_context = format!("{context}, final settings slice");
                    assert_whole(&final_window, width, height, &final_context);
                    assert!(
                        final_window
                            .semantic(&UiKey::new(format!("settings/control/{last_key}")))
                            .is_some(),
                        "{final_context}: last field {last_key} is reachable"
                    );
                }
            }
        }

        let (mut runtime, instance, view) = setup();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.set_search("font".to_string());
        state.common.last_focus = Some(UiKey::new("settings/search"));
        let searched = compile(&runtime, instance, view, width, height);
        let context = format!("font search {width}×{height} at {scale}×");
        assert_whole(&searched, width, height, &context);
        assert!(
            searched
                .semantic(&UiKey::new("settings/preview/search"))
                .is_some(),
            "{context}: global search retains the matching contextual preview"
        );
        assert!(
            searched.semantic(&UiKey::new("settings/search")).is_some(),
            "{context}: the full search surface remains present"
        );
    }
}

#[test]
fn maximum_native_text_scale_keeps_a_phone_page_reachable_and_unclipped() {
    at_each_text_scale(
        &[2.0],
        "phone page Dynamic Type test",
        maximum_native_text_scale_keeps_a_phone_page_reachable_and_unclipped_at_scale,
    );
}

/// [`maximum_native_text_scale_keeps_a_phone_page_reachable_and_unclipped`] at 2.0× ([`at_each_text_scale`]).
fn maximum_native_text_scale_keeps_a_phone_page_reachable_and_unclipped_at_scale(_scale: f32) {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Appearance),
                value: None,
            }),
        )
        .unwrap();
    let cx = view_cx_at(320.0, 568.0);
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    compiled.validate_parity().unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new("settings/navigation"))
            .is_none()
    );
    let preview = compiled
        .semantic(&UiKey::new("settings/preview/appearance"))
        .expect("the live demonstration remains present at maximum text scale");
    assert_eq!(
        preview.rect.height,
        renderer_preview_height(SettingsWidth::Compact)
    );
    assert!(preview.rect.bottom() <= cx.viewport.bottom() + 0.01);
    compiled
        .semantic(&UiKey::new("settings/page/appearance"))
        .expect("the Appearance page group remains reachable when its optional heading sheds");
    let controls = compiled
        .semantics
        .iter()
        .filter(|node| node.key.as_str().starts_with("settings/control/"))
        .collect::<Vec<_>>();
    // The first 2× phone slice may devote its whole body to the live
    // demonstration. Any control that does fit must remain whole; the
    // enabled semantic Next control below proves the rest are reachable.
    for control in controls {
        assert!(
            control.rect.height >= 64.0,
            "{} {:?}",
            control.key.as_str(),
            control.rect
        );
        assert!(control.rect.bottom() <= cx.viewport.bottom() + 0.01);
    }
    let next = compiled
        .semantic(&UiKey::new("settings/results-window/next"))
        .expect("omitted 2× controls remain reachable");
    assert!(next.state.unwrap().enabled);
    assert!(next.rect.bottom() <= cx.viewport.bottom() + 0.01);

    for route in [
        SettingsRoute::Home,
        SettingsRoute::About,
        SettingsRoute::SoftwareUpdate,
    ] {
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(route),
                    value: None,
                }),
            )
            .unwrap();
        for _ in 0..SettingsRoute::ALL.len() {
            let page = runtime
                .render(instance, view, &cx)
                .unwrap()
                .compile(cx.viewport)
                .unwrap();
            page.validate_parity().unwrap();
            for hit in &page.hits {
                assert!(
                    hit.rect.height >= 64.0,
                    "{} shrank below its 2× control allocation on {route:?}: {:?}",
                    hit.key.as_str(),
                    hit.rect
                );
                assert!(hit.rect.bottom() <= cx.viewport.bottom() + 0.01);
            }
            let Some(next) = page
                .hits
                .iter()
                .find(|hit| hit.key.as_str().ends_with("/pagination/next"))
                .map(|hit| hit.action.clone())
            else {
                break;
            };
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: next,
                        value: None,
                    }),
                )
                .unwrap();
        }
    }
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Home),
                value: None,
            }),
        )
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_THEME)),
                value: None,
            }),
        )
        .unwrap();
    let picker = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    picker.validate_parity().unwrap();
    let surface = picker
        .semantic(&UiKey::new(format!(
            "settings/choice-picker/{}",
            prefs::EDIT_THEME
        )))
        .expect("2× Top theme picker");
    assert!(surface.rect.bottom() <= cx.viewport.bottom() + 0.01);
    let option_prefix = format!("settings/choice/{}/", prefs::EDIT_THEME);
    assert_eq!(
        picker
            .semantics
            .iter()
            .filter(|node| node.key.as_str().starts_with(&option_prefix))
            .count(),
        ChoicePicker::MAX_TEXT_PAGE_SIZE
    );
    for key in [
        "settings/choice-close",
        "settings/choice-page-prev",
        "settings/choice-page-next",
    ] {
        let node = picker
            .semantic(&UiKey::new(key))
            .unwrap_or_else(|| panic!("2× picker retains {key}"));
        assert!(node.rect.height >= 64.0);
        assert!(node.rect.bottom() <= cx.viewport.bottom() + 0.01);
    }
}

#[test]
fn appearance_uses_a_bounded_semantic_renderer_preview_at_every_width() {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Appearance),
                value: None,
            }),
        )
        .unwrap();
    let cx = view_cx_at(1_280.0, 820.0);
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    compiled.validate_parity().unwrap();

    let preview = compiled
        .semantic(&UiKey::new("settings/preview/appearance"))
        .expect("Appearance has a first-class renderer preview node");
    assert!(preview.rect.bottom() <= cx.viewport.bottom());
    let SemanticValue::Text(value) = &preview.value else {
        panic!("preview exposes truthful semantic context");
    };
    assert!(value.contains("Color theme sample"));
    assert!(!value.contains("CursorGlow"));
    assert!(!value.contains("tone-map"));
    assert!(
        value.len() < 240,
        "accessibility summary stays concise: {value}"
    );

    let medium = view_cx_at(900.0, 820.0);
    let medium = runtime
        .render(instance, view, &medium)
        .unwrap()
        .compile(medium.viewport)
        .unwrap();
    assert!(
        medium
            .semantic(&UiKey::new("settings/preview/appearance"))
            .is_some(),
        "responsive widths retain the same semantic demonstration"
    );
}

#[test]
fn window_preview_consumes_the_real_smart_title_controls() {
    let config = Config {
        descriptive_titles: Some(false),
        tab_title_format: Some(crate::app_config::TitleFormat::DescriptionTitle),
        window_title_format: Some(crate::app_config::TitleFormat::Description),
        ..Config::default()
    };
    let mut state = SettingsViewState::new(&config);
    state.navigate(SettingsRoute::WindowTabs);
    state.common.last_focus = Some(UiKey::new(format!(
        "settings/control/{}",
        prefs::EDIT_TAB_TITLE_FORMAT
    )));
    let spec = renderer_preview_spec(
        &state,
        0,
        crate::native_app::ViewMotionCx::default(),
        14.0,
        1.0,
        aterm_render::Theme::default(),
    )
    .expect("Window & Tabs has a renderer preview");
    assert_eq!(spec.scene, PreviewScene::WindowTabs);
    assert!(!spec.window_tabs.generate_activity);
    assert_eq!(spec.window_tabs.tab_title_format, "description-title");
    assert_eq!(spec.window_tabs.window_title_format, "description");
    assert_eq!(
        spec.animation(),
        crate::settings_preview::PreviewAnimation::None
    );
    let semantics = spec.audit_value();
    assert!(semantics.contains("Activity fallback `running tests` is off"));
    assert!(semantics.contains("tab format description-title"));
    assert!(semantics.contains("window format description"));
    assert!(semantics.contains("no live provider-health claim"));
}

#[test]
fn window_preview_provider_off_disables_activity_semantics_and_pixels() {
    let preview = |provider| {
        let config = Config {
            descriptive_titles: Some(true),
            title_summary_provider: Some(provider),
            ..Config::default()
        };
        let mut state = SettingsViewState::new(&config);
        state.navigate(SettingsRoute::WindowTabs);
        renderer_preview_spec(
            &state,
            0,
            crate::native_app::ViewMotionCx::default(),
            14.0,
            1.0,
            aterm_render::Theme::default(),
        )
        .expect("Window & Tabs has a renderer preview")
    };

    let enabled = preview(crate::app_config::TitleSummaryProvider::Builtin);
    let disabled = preview(crate::app_config::TitleSummaryProvider::Off);
    assert!(enabled.window_tabs.generate_activity);
    assert!(!disabled.window_tabs.generate_activity);
    assert!(
        disabled
            .audit_value()
            .contains("Activity fallback `running tests` is off")
    );
    assert_ne!(
        compile_preview_for_pixels(enabled).1,
        compile_preview_for_pixels(disabled).1,
        "provider=off must visibly remove the generated Activity fallback"
    );
}

