#[test]
fn about_and_updates_use_top_aligned_responsive_dashboards() {
    let (mut runtime, instance, view) = setup();
    let wide = view_cx_at(1_424.0, 658.0);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::About),
                value: None,
            }),
        )
        .unwrap();
    let about = runtime
        .render(instance, view, &wide)
        .unwrap()
        .compile(wide.viewport)
        .unwrap();
    let hero = about.semantic(&UiKey::new("about/hero")).unwrap();
    // WHETHER THIS VIEWPORT STACKS OR PAGES IS THE CONTENT'S DECISION, and
    // it sits right on the line: hero 238 + gap 12 + card 346 = 596 against
    // 594 of content. TWO POINTS. It stacked until `about_fields` learned to
    // name the running copy and, when a second install exists, the other one
    // — 64pt of new facts. The page concedes by paging.
    //
    // `hero.rect.y <= 40` and "details sit below the hero" together say ONE
    // thing: this viewport does not paginate. That was an arithmetic
    // coincidence, not a contract, and pinning it meant the test reported a
    // missing node the moment the facts outgrew it. Assert instead what the
    // page still owes: the hero opens its section, the details are whole and
    // inside the viewport, and they follow the hero when the two do share a
    // page.
    let details_bottom = if let Some(details) = about.semantic(&UiKey::new("about/details")) {
        assert!(
            hero.rect.y <= 40.0,
            "an unpaged About starts at the page rhythm"
        );
        assert!(
            details.rect.y > hero.rect.bottom(),
            "details follow the hero"
        );
        details.rect.bottom()
    } else {
        let next = about
            .hits
            .iter()
            .find(|hit| hit.key.as_str() == "about/pagination/next")
            .expect("a paged About exports a semantic Next");
        let action = next.action.clone();
        // The rhythm claim, without an arithmetic bound to keep in step with
        // the pager. The hero is the FIRST CONTENT of its section: nothing
        // but the pagination chrome may sit above it. That is what
        // "About starts at the page rhythm" means, and unlike a `y <= 40`
        // it stays true whether or not a pager is present.
        let chrome = |key: &str| key.starts_with("about/pagination") || key == "about/range";
        for node in about
            .semantics
            .iter()
            .filter(|node| node.key.as_str().starts_with("about/"))
            .filter(|node| !chrome(node.key.as_str()))
        {
            assert!(
                node.rect.y >= hero.rect.y,
                "{} starts above the hero at {} vs {} — the hero must open its \
                 section, with only the pager above it",
                node.key.as_str(),
                node.rect.y,
                hero.rect.y,
            );
        }
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: action,
                    value: None,
                }),
            )
            .unwrap();
        let paged = runtime
            .render(instance, view, &wide)
            .unwrap()
            .compile(wide.viewport)
            .unwrap();
        let bottom = paged
            .semantic(&UiKey::new("about/details"))
            .expect("the details card is on the next About page")
            .rect
            .bottom();
        // Back to the first section the way we left it — page UP, the
        // inverse of the page-down above. Re-dispatching the About route
        // does NOT rewind `page_scroll`, so the compact assertions further
        // down would have started on section two.
        let previous = paged
            .hits
            .iter()
            .find(|hit| hit.key.as_str() == "about/pagination/previous")
            .expect("the second About section exports a semantic Previous");
        let back = previous.action.clone();
        assert_eq!(back.as_str(), "settings/page-up");
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: back,
                    value: None,
                }),
            )
            .unwrap();
        bottom
    };
    assert!(details_bottom <= wide.viewport.bottom());

    let tall = view_cx_at(1_424.0, 900.0);
    let tall_about = runtime
        .render(instance, view, &tall)
        .unwrap()
        .compile(tall.viewport)
        .unwrap();
    assert!(
        tall_about
            .semantic(&UiKey::new("about/principles"))
            .is_none(),
        "About carries facts about this copy, not design principles"
    );

    let compact_about_cx = view_cx_at(474.0, 658.0);
    let compact_hero = runtime
        .render(instance, view, &compact_about_cx)
        .unwrap()
        .compile(compact_about_cx.viewport)
        .unwrap();
    assert!(compact_hero.semantic(&UiKey::new("about/hero")).is_some());
    assert!(
        compact_hero
            .semantic(&UiKey::new("about/provenance"))
            .is_none()
    );
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(1))
        .unwrap();
    let compact_build = runtime
        .render(instance, view, &compact_about_cx)
        .unwrap()
        .compile(compact_about_cx.viewport)
        .unwrap();
    let build = compact_build
        .semantic(&UiKey::new("about/provenance"))
        .unwrap();
    assert!(build.rect.bottom() <= compact_about_cx.viewport.bottom());
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(1))
        .unwrap();
    let compact_support = runtime
        .render(instance, view, &compact_about_cx)
        .unwrap()
        .compile(compact_about_cx.viewport)
        .unwrap();
    let support = compact_support
        .semantic(&UiKey::new("about/support"))
        .unwrap();
    assert!(support.rect.bottom() <= compact_about_cx.viewport.bottom());

    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let updates = runtime
        .render(instance, view, &wide)
        .unwrap()
        .compile(wide.viewport)
        .unwrap();
    // Desktop Update is the status card beside the automatic-updates
    // switch, with the release notes beneath — the whole page, unpaginated,
    // on an ordinary window. The three-row service card that used to own
    // that right-hand slot and the "How aterm updates" explainer below it
    // are retired at every width.
    let status = updates.semantic(&UiKey::new("updates/hero")).unwrap();
    let automatic = updates.semantic(&UiKey::new("updates/automatic")).unwrap();
    let notes = updates
        .semantic(&UiKey::new("updates/release-notes-card"))
        .unwrap();
    assert!(status.rect.right() < automatic.rect.x);
    assert_eq!(status.rect.y, automatic.rect.y);
    assert_eq!(status.rect.bottom(), automatic.rect.bottom());
    assert!(notes.rect.y >= status.rect.bottom());
    assert!(notes.rect.bottom() <= wide.viewport.bottom());
    assert!(
        updates
            .semantic(&UiKey::new("updates/pagination"))
            .is_none(),
        "an ordinary desktop window shows the whole Update page at once"
    );
    // The switch is the real config control, not a lookalike.
    assert!(
        updates
            .semantic(&UiKey::new("settings/control/update.auto_apply"))
            .is_some(),
        "the automatic-updates switch is bound to the update.auto_apply leaf"
    );

    let compact = view_cx_at(600.0, 820.0);
    let compact_updates = runtime
        .render(instance, view, &compact)
        .unwrap()
        .compile(compact.viewport)
        .unwrap();
    let compact_status = compact_updates
        .semantic(&UiKey::new("updates/hero"))
        .unwrap();
    assert!(compact_status.rect.bottom() <= compact.viewport.bottom());
    // Both controls are small enough to share the first narrow page, so
    // nobody has to page past an empty screen to reach the switch.
    let compact_automatic = compact_updates
        .semantic(&UiKey::new("updates/automatic"))
        .unwrap();
    assert!(compact_automatic.rect.y >= compact_status.rect.bottom());
    assert!(compact_automatic.rect.bottom() <= compact.viewport.bottom());
    // Whatever does not fit stays reachable whole.
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(1))
        .unwrap();
    let compact_next = runtime
        .render(instance, view, &compact)
        .unwrap()
        .compile(compact.viewport)
        .unwrap();
    let compact_notes = compact_next
        .semantic(&UiKey::new("updates/release-notes-card"))
        .unwrap();
    assert!(compact_notes.rect.bottom() <= compact.viewport.bottom());
}

#[test]
fn ordinary_medium_about_pages_complete_build_and_support_metadata() {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::About),
                value: None,
            }),
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    state.feedback = Some("Copied build information".to_string());
    // Exercise the genuine medium workbench. Shorter heights that cannot
    // fit all 14 labeled routes intentionally select compact navigation.
    let cx = view_cx_at(849.0, 513.0);
    let hero = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    hero.validate_parity().unwrap();
    assert!(hero.semantic(&UiKey::new("about/hero")).is_some());
    assert!(hero.semantic(&UiKey::new("about/details")).is_none());
    for key in ["about/copy-build-info", "about/open-site"] {
        let node = hero.semantic(&UiKey::new(key)).unwrap();
        assert!(node.rect.bottom() <= cx.viewport.bottom() + 0.01);
    }
    let next = hero
        .hits
        .iter()
        .find(|hit| hit.key.as_str() == "about/pagination/next")
        .expect("About exports a visible semantic Next action");
    assert_eq!(next.action.as_str(), "settings/page-down");
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: next.action.clone(),
                value: None,
            }),
        )
        .unwrap();

    let details = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    details.validate_parity().unwrap();
    let details_card = details.semantic(&UiKey::new("about/details")).unwrap();
    assert!(details_card.rect.bottom() <= cx.viewport.bottom() + 0.01);
    // WALK EVERY SECTION. The provenance facts no longer all live on one
    // page: when the card cannot fit the section budget the medium path
    // chunks them across further sections, exactly as compact About does.
    // So the contract is "every fact is reachable at its full height on
    // SOME page", not "every fact is on page two" — and collecting them
    // this way is strictly stronger, because a fact that silently vanished
    // from every page now fails here instead of passing on a machine that
    // happens not to have it.
    let mut seen: std::collections::HashMap<String, f32> = std::collections::HashMap::new();
    for page in 0..8usize {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.page_scroll = page;
        let Ok(tree) = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
        else {
            break;
        };
        tree.validate_parity().unwrap();
        for (label, _) in crate::build_info::about_fields() {
            if matches!(label, "tagline" | "author" | "company" | "site") {
                continue;
            }
            let key = format!("about/provenance/row/{}", key_fragment(label));
            if let Some(node) = tree.semantic(&UiKey::new(key.clone())) {
                seen.insert(key, node.rect.height);
                // Every rendered row must also sit inside the viewport.
                let node = tree
                    .semantic(&UiKey::new(format!(
                        "about/provenance/row/{}",
                        key_fragment(label)
                    )))
                    .unwrap();
                assert!(
                    node.rect.bottom() <= cx.viewport.bottom() + 0.01,
                    "About row {label} on page {page} extends past the viewport"
                );
            }
        }
        let key = format!("about/support/row/{}", key_fragment("Website"));
        if let Some(node) = tree.semantic(&UiKey::new(key.clone())) {
            seen.insert(key, node.rect.height);
            assert!(
                node.rect.bottom() <= cx.viewport.bottom() + 0.01,
                "Support row Website on page {page} extends past the viewport"
            );
        }
    }
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    state.page_scroll = 1;
    let provenance = crate::build_info::about_fields()
        .into_iter()
        .filter(|(key, _)| !matches!(*key, "tagline" | "author" | "company" | "site"));
    for (label, _) in provenance {
        let key = format!("about/provenance/row/{}", key_fragment(label));
        let height = seen
            .get(&key)
            .copied()
            .unwrap_or_else(|| panic!("missing complete Medium metadata {key} on every page"));

        // Names the row, because this loop walks KEYS THAT VARY BY MACHINE:
        // `about_fields` appends `running` and, when a second install
        // exists, `another copy`. A bare `assert!` here reports only
        // "assertion failed" for a row the reader cannot identify and may
        // not even have.
        assert!(
            height >= 28.0,
            "About row {key} collapsed to {:.1}pt (rows are 28pt at a 32pt \
             pitch). The card is laid out at a FIXED height with FIXED rows, \
             so a card taller than its section pushes the whole deficit into \
             the last row rather than clipping — chunk the facts instead.",
            height,
        );
    }
    let key = format!("about/support/row/{}", key_fragment("Website"));
    let height = seen
        .get(&key)
        .copied()
        .unwrap_or_else(|| panic!("missing complete Medium support metadata {key} on every page"));
    assert!(
        height >= 28.0,
        "Support row {key} collapsed to {height:.1}pt (rows are 28pt)"
    );
    let previous = details
        .hits
        .iter()
        .find(|hit| hit.key.as_str() == "about/pagination/previous")
        .expect("second About section exports semantic Previous");
    assert_eq!(previous.action.as_str(), "settings/page-up");
}

/// Where a Linux-layout test takes its UI face from ([`linux_layout_cx`]).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum LinuxLayoutFace {
    /// The host's own UI face — Helvetica Neue on the Mac that runs the gate.
    Host,
    /// The Linux ladder's first readable pair (Noto Sans, else DejaVu Sans): the
    /// host's Linux font tree, or the directory `ATERM_TEST_LINUX_UI_FONTS` names.
    LinuxLadder,
    /// No UI face at all: every string measures at the 0.6 em mono approximation, as
    /// on a Linux host with neither Noto nor DejaVu Sans installed — wider than both.
    NoUiFace,
}

/// A `ViewCx` whose compile measures in `face`, or `None` when this host cannot read
/// the Linux ladder's faces. Compile with it before building another: `view_cx_at`
/// reinstalls the host's faces.
fn linux_layout_cx(face: LinuxLayoutFace, width: f32, height: f32) -> Option<ViewCx<'static>> {
    let cx = view_cx_at(width, height);
    match face {
        LinuxLayoutFace::Host => {}
        LinuxLayoutFace::LinuxLadder => {
            let root = std::env::var_os("ATERM_TEST_LINUX_UI_FONTS").map(std::path::PathBuf::from);
            crate::tray_raster::install_linux_ui_fonts_for_test(root.as_deref())?;
        }
        LinuxLayoutFace::NoUiFace => crate::tray_raster::clear_ui_fonts_for_test(),
    }
    Some(cx)
}

/// THE LIVE LINUX UPDATE PAGE, ON EVERY HOST AND IN LINUX'S OWN FACES (2026-09-24
/// review). This test was compiled on Linux alone, so the Mac that runs the gate never
/// saw it, and every other check of the Linux card measured in Helvetica Neue — while
/// in Noto Sans, the Linux UI face, the merged caption wrapped to seven lines and ran
/// the medium workbench's two cards 13pt past their section. Now it runs everywhere,
/// in the host's face, in the Linux ladder's where this host can read it, and with
/// no UI face at all: an enrolled copy idle (automatic checks on, off, and saved the
/// other way), with a download, needing attention, and awaiting its startup trial,
/// at the wide, medium and compact widths and the short phone. In a real face the page
/// paints clean; with none, where every line is wider than any Linux face draws it,
/// the cards still fit their sections. Manual authority holds: the apply button is
/// disabled and names `aterm update apply`, and both `[update]` switches are live.
#[test]
fn linux_update_status_settings_preserves_manual_authority_and_effective_policy() {
    let facts = |staged: Option<u64>| aterm_update::LinuxUpdateStatus {
        installed_build: 1,
        installed_version: String::new(),
        staged_build: staged,
        staged_version: staged.map(|_| "0.2.0".to_string()),
        staged_commit: staged.map(|_| "ab".repeat(20)),
        trial_phase: None,
        trial_starts: 0,
        trial_healthy: false,
        refused_newer: false,
    };
    let mut status = update_status(false);
    status.linux = Some(facts(Some(2)));
    let (mut runtime, instance, view) =
        setup_with_update(UpdateState::from_status(1, "0.1.0", Some(&status), false));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_200.0, 820.0));
    assert_zero_top_paint(&compiled, "wide Linux downloaded update");
    let headline = compiled.semantic(&UiKey::new("updates/headline")).unwrap();
    assert!(headline.label.contains("downloaded"), "{}", headline.label);
    let apply = compiled
        .semantic(&UiKey::new("updates/install-now"))
        .unwrap();
    assert!(!apply.state.unwrap().enabled);
    assert!(apply.label.contains("aterm update apply"));
    // Both `[update]` switches are live: the Linux updater reads `enabled` (its
    // background checker, once per process) and `auto_apply` (each replacement).
    for key in [
        "settings/control/update.enabled",
        "settings/control/update.auto_apply",
    ] {
        let switch = compiled.semantic(&UiKey::new(key)).unwrap();
        assert!(switch.state.unwrap().enabled, "{key} is live on Linux");
    }
    let caption = compiled
        .semantic(&UiKey::new("updates/automatic/caption"))
        .unwrap();
    assert!(caption.label.contains("downloads only"));
    assert!(caption.label.contains("applies next launch"));
    assert!(!caption.label.contains("macOS"));
    assert!(!caption.label.contains("no effect"));

    let mut trial = facts(None);
    trial.installed_build = 2;
    trial.trial_phase = Some("Installed".into());
    trial.trial_starts = 1;
    let mut attention = update_status(false);
    attention.linux = Some(facts(None));
    attention.failing_checks = 1;
    attention.outcome = "linux-update: GitHub answered 503 Service Unavailable while \
                         listing releases for alabsystems/aterm"
        .into();
    let mut states = Vec::new();
    for (running, saved) in [(true, true), (false, false), (false, true), (true, false)] {
        for (name, linux) in [("idle", facts(None)), ("downloaded", facts(Some(2)))] {
            let mut status = update_status(false);
            status.linux = Some(linux);
            states.push((
                format!("{name} r{running} s{saved}"),
                status,
                running,
                saved,
            ));
        }
    }
    let mut pending = update_status(false);
    pending.linux = Some(trial);
    states.push(("trial r0 s0".to_string(), pending, false, false));
    states.push(("attention".to_string(), attention, true, true));

    let mut measured_linux_faces = false;
    let mut revision = 1;
    for face in [
        LinuxLayoutFace::Host,
        LinuxLayoutFace::LinuxLadder,
        LinuxLayoutFace::NoUiFace,
    ] {
        for (state, status, running, saved) in &states {
            revision += 1;
            assert!(
                runtime.replace_settings_update(
                    UpdateState::from_status(1, "0.1.0", Some(status), false)
                        .with_automatic_checks(*running, *saved),
                    revision,
                )
            );
            for (size, width, height) in [
                ("wide", 1_200.0, 820.0),
                ("medium", 849.0, 513.0),
                ("compact", 600.0, 820.0),
                ("short compact", 600.0, 560.0),
            ] {
                let Some(cx) = linux_layout_cx(face, width, height) else {
                    continue;
                };
                measured_linux_faces |= face == LinuxLayoutFace::LinuxLadder;
                let context = format!("{face:?} {size} Linux {state}");
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                if face == LinuxLayoutFace::NoUiFace {
                    // The approximation is wider than any face, so a line may
                    // ellipsize; a card may not outgrow its section.
                    let clipped = compiled
                        .paint_audit_lines()
                        .into_iter()
                        .filter(|line| {
                            line.contains("clipped=true") && line.contains("key=\"updates/")
                        })
                        .collect::<Vec<_>>();
                    assert!(
                        clipped.is_empty(),
                        "{context}: a card outgrows its section:\n{}",
                        clipped.join("\n")
                    );
                } else {
                    assert_zero_top_paint(&compiled, &context);
                }
            }
        }
    }
    if !measured_linux_faces {
        crate::logging::stderr_line!(
            "NOTICE: the Linux UI faces (Noto Sans, DejaVu Sans) are not readable on this \
             host, so the Linux update page was measured in the host's face and with no UI \
             face only; point ATERM_TEST_LINUX_UI_FONTS at a directory holding \
             NotoSans-Regular.ttf and NotoSans-Bold.ttf to measure it in Linux's own"
        );
    }
}

/// Every page of the Software Update route in a `width`×`height` window, first to
/// last: the pager's Next pressed until it disables. A fresh runtime per walk, so the
/// walk starts on page 1 and measures in the host's face.
fn update_route_pages(
    update: UpdateState,
    width: f32,
    height: f32,
) -> Vec<crate::native_ui::CompiledUi> {
    let (mut runtime, instance, view) = setup_with_update(update);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let cx = view_cx_at(width, height);
    let mut pages = Vec::new();
    loop {
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let next = compiled
            .semantic(&UiKey::new("updates/pagination/next"))
            .and_then(|node| node.state)
            .is_some_and(|state| state.enabled)
            .then(|| {
                compiled
                    .hits
                    .iter()
                    .find(|hit| hit.key.as_str() == "updates/pagination/next")
                    .map(|hit| hit.action.clone())
            })
            .flatten();
        pages.push(compiled);
        let Some(action) = next else {
            break;
        };
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: action,
                    value: None,
                }),
            )
            .unwrap();
        assert!(pages.len() < 64, "bounded Update page traversal");
    }
    pages
}

/// The text a compiled page PAINTS (not its semantic labels, which keep complete
/// sentences whatever fits).
fn painted_texts(compiled: &crate::native_ui::CompiledUi) -> Vec<String> {
    compiled
        .paint
        .iter()
        .filter_map(|node| match &node.content {
            UiContent::Text(text) => Some(text.text.clone()),
            _ => None,
        })
        .collect()
}

/// THE macOS STATUS CARD FITS ITS SECTION BESIDE A FAILED CHECK, UNDER EVERY SWITCH
/// STATE (2026-09-24 post-push review). The merge fitted the Linux card and left the
/// macOS one: at the medium workbench a non-routine outcome line under the
/// switch's three-line timing sentence, above the action row and main's Settings ▸
/// Messages link row, made the card 360pt in a 327pt section — the link button cut
/// to 23 of its 36pt. The card now steps its outcome, then its detail, down to the
/// section it is windowed into. Checked for the four running/saved pairs, at the
/// wide, medium and compact widths and the short phone, in the host's face (clean)
/// and with no UI face at all (no card outgrows its section), and the failed check's
/// cause stays on the desktop page.
#[test]
fn the_status_card_fits_its_section_beside_a_failed_check_under_every_switch_state() {
    let outcome = "check failed (network): error sending request for url \
                   (https://api.github.com/repos/alabsystems/aterm/releases?per_page=20): \
                   operation timed out";
    let failed_check = |running: bool, saved: bool| {
        let mut status = update_status(false);
        status.failing_checks = 1;
        status.failing_kind = "network".into();
        status.failing_checks_kind = "network".into();
        status.outcome = outcome.into();
        UpdateState::from_status(1, "0.1.0", Some(&status), false)
            .with_automatic_checks(running, saved)
    };
    let (mut runtime, instance, view) = setup_with_update(failed_check(true, true));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let mut revision = 1;
    for face in [LinuxLayoutFace::Host, LinuxLayoutFace::NoUiFace] {
        for (running, saved) in [(true, true), (false, false), (false, true), (true, false)] {
            revision += 1;
            let state = failed_check(running, saved);
            let projection = state.projection();
            assert!(
                !projection.failing_persistent && update_outcome_line(&projection).is_some(),
                "the fixture is one failed check, a non-routine outcome the card paints"
            );
            assert!(runtime.replace_settings_update(state, revision));
            for (size, width, height) in [
                ("wide", 1_200.0, 820.0),
                ("medium", 849.0, 513.0),
                ("compact", 600.0, 820.0),
                ("short compact", 600.0, 560.0),
            ] {
                let Some(cx) = linux_layout_cx(face, width, height) else {
                    continue;
                };
                let context = format!("{face:?} {size} macOS r{running} s{saved}");
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                if face == LinuxLayoutFace::NoUiFace {
                    let clipped = compiled
                        .paint_audit_lines()
                        .into_iter()
                        .filter(|line| {
                            line.contains("clipped=true") && line.contains("key=\"updates/")
                        })
                        .collect::<Vec<_>>();
                    assert!(
                        clipped.is_empty(),
                        "{context}: a card outgrows its section:\n{}",
                        clipped.join("\n")
                    );
                } else {
                    assert_zero_top_paint(&compiled, &context);
                }
                if matches!(size, "wide" | "medium") {
                    let painted = compiled
                        .semantic(&UiKey::new("updates/outcome"))
                        .unwrap_or_else(|| {
                            panic!("{context}: the failed check's cause stays on the card")
                        });
                    assert_eq!(painted.label, outcome, "{context}");
                }
            }
        }
    }
}

/// THE LAST CHECK STAYS ON THE macOS PAGE WHILE THE SWITCH EXPLAINS ITSELF (2026-09-24).
/// With the automatic-checks switch saved one way and running the other (or off both
/// ways), its timing sentence took the detail slot and "Checked N ago." left the page
/// until the next launch. Both paint now, on the status card's first page, inside the
/// section at the wide and medium workbenches, the compact page and the short phone.
#[test]
fn the_checked_line_paints_beside_the_switch_sentence_at_every_width() {
    let state = |running: bool, saved: bool| {
        let mut status = update_status(false);
        status.updated_at = "2026-01-01T00:00:00Z".to_string();
        UpdateState::from_status(1, "0.1.0", Some(&status), false)
            .with_automatic_checks(running, saved)
    };
    for (running, saved, switch) in [
        (true, false, "Automatic checks stop next launch"),
        (false, true, "Automatic checks start next launch"),
        (false, false, "Nothing checks for updates by itself"),
    ] {
        for (size, width, height) in [
            ("wide", 1_200.0, 820.0),
            ("medium", 849.0, 513.0),
            ("compact", 600.0, 820.0),
            ("short compact", 600.0, 560.0),
        ] {
            let context = format!("{size} r{running} s{saved}");
            let pages = update_route_pages(state(running, saved), width, height);
            let first = &pages[0];
            assert_zero_top_paint(first, &context);
            let painted = painted_texts(first)
                .join(" ")
                .split_whitespace()
                .collect::<Vec<_>>()
                .join(" ");
            assert!(
                painted.contains("Checked ") && painted.contains(switch),
                "{context}: the last check and the switch's sentence both paint: \
                 {painted}"
            );
        }
    }
}

/// A LINUX PAGE IN THE SHORT-LANDSCAPE PAGER STILL PAINTS A FAILED CHECK'S CAUSE
/// (2026-09-24 post-push review). The full Linux status card carries the updater
/// outcome in its detail, so it paints no second outcome line; but the pager's
/// two-column summary says only "See terminal status", and the outcome's own section
/// there is the one place the cause paints. The merge had silenced it on every Linux
/// page.
#[test]
fn a_linux_short_landscape_page_paints_a_failed_checks_cause() {
    let cause = "linux-update: GitHub answered 503 Service Unavailable while listing \
                 releases for alabsystems/aterm";
    let failed_check = || {
        let mut status = update_status(false);
        status.linux = Some(aterm_update::LinuxUpdateStatus {
            installed_build: 1,
            installed_version: String::new(),
            staged_build: None,
            staged_version: None,
            staged_commit: None,
            trial_phase: None,
            trial_starts: 0,
            trial_healthy: false,
            refused_newer: false,
        });
        status.failing_checks = 1;
        status.outcome = cause.into();
        UpdateState::from_status(1, "0.1.0", Some(&status), false)
    };
    let projection = failed_check().projection();
    assert!(projection.linux_host && projection.linux_attention);

    // The full card: the detail carries the cause, so it paints once.
    let medium = update_route_pages(failed_check(), 849.0, 513.0);
    let first = &medium[0];
    assert!(
        first.semantic(&UiKey::new("updates/outcome")).is_none(),
        "the Linux status card does not repeat the outcome its detail carries"
    );
    assert!(
        first
            .semantic(&UiKey::new("updates/detail"))
            .is_some_and(|detail| detail.label.contains("503")),
        "the Linux detail carries the cause"
    );

    // The pager: the cause takes a section of its own.
    let pages = update_route_pages(failed_check(), 568.0, 320.0);
    let painted = pages.iter().flat_map(painted_texts).collect::<Vec<_>>();
    assert!(
        painted
            .iter()
            .any(|text| text.starts_with("linux-update:") && text.contains("503")),
        "some page of the short-landscape pager paints the failed check's cause: \
         {painted:?}"
    );
    for (index, page) in pages.iter().enumerate() {
        assert_zero_top_paint(page, &format!("short-landscape Linux page {index}"));
    }
}

/// THE COMPACT RUNGS NEVER CALL A PAGE CURRENT WHILE NOTHING CHECKS (2026-09-24
/// post-push review). The full headline says "Automatic checks are off." while the
/// running process checks nothing by itself; the compact headline, the short-landscape
/// summary and the tersest detail rung did not know the switch, and painted "Current"
/// / "Up to date" beside it. They carry the RUNNING value (a saved flip applies next
/// launch), below every trouble arm, as the full headline does.
#[test]
fn compact_update_rungs_never_call_a_page_current_while_checks_are_off() {
    let healthy = |running: bool, saved: bool| {
        UpdateState::from_status(1, "0.1.0", Some(&update_status(false)), false)
            .with_automatic_checks(running, saved)
    };
    for (running, saved) in [(true, true), (false, false), (false, true), (true, false)] {
        let projection = healthy(running, saved).projection();
        let context = format!("r{running} s{saved}");
        assert_eq!(projection.automatic_checks, running, "{context}");
        let words = (
            compact_update_headline(&projection),
            compact_update_summary_detail(&projection),
            compact_update_detail_minimum(&projection),
        );
        if running {
            assert_eq!(
                words,
                (
                    "Current".to_string(),
                    "Up to date",
                    "Up to date.".to_string()
                ),
                "{context}"
            );
        } else {
            assert_eq!(
                words,
                (
                    "Checks off".to_string(),
                    "Manual checks",
                    "Manual checks.".to_string()
                ),
                "{context}"
            );
        }
        // Painted, in the short-landscape pager the review measured.
        let painted = update_route_pages(healthy(running, saved), 568.0, 320.0)
            .iter()
            .flat_map(painted_texts)
            .collect::<Vec<_>>();
        let claims_current = painted
            .iter()
            .any(|text| text == "Current" || text.starts_with("Up to date"));
        assert_eq!(claims_current, running, "{context}: {painted:?}");
    }

    // Trouble still outranks the switch.
    let mut failing = update_status(false);
    failing.failing_checks = aterm_update::PERSISTENT_AFTER;
    failing.failing_persistent = true;
    failing.failing_kind = "network".into();
    let failing = UpdateState::from_status(1, "0.1.0", Some(&failing), false)
        .with_automatic_checks(false, false)
        .projection();
    assert_eq!(compact_update_headline(&failing), "Failing");
    assert_eq!(compact_update_summary_detail(&failing), "Checks failing");

    // A stranded channel is not "Up to date" in the summary either.
    let mut stranded = update_status(false);
    stranded.channel_unreadable = true;
    let stranded = UpdateState::from_status(1, "0.1.0", Some(&stranded), false).projection();
    assert_eq!(compact_update_headline(&stranded), "Can\u{2019}t check");
    assert_ne!(compact_update_summary_detail(&stranded), "Up to date");

    // An idle Linux copy says so too, below its disk and trouble facts.
    let mut linux = update_status(false);
    linux.linux = Some(aterm_update::LinuxUpdateStatus {
        installed_build: 1,
        installed_version: String::new(),
        staged_build: None,
        staged_version: None,
        staged_commit: None,
        trial_phase: None,
        trial_starts: 0,
        trial_healthy: false,
        refused_newer: false,
    });
    let idle = |running: bool| {
        compact_update_headline(
            &UpdateState::from_status(1, "0.1.0", Some(&linux), false)
                .with_automatic_checks(running, running)
                .projection(),
        )
    };
    assert_eq!(idle(true), "None staged");
    assert_eq!(idle(false), "Checks off");
}

/// L4 (2026-08 Windows audit): where there is no native updater (neither macOS
/// nor Linux) the lane does not exist, so the page must not headline "Automatic
/// updates are off." over a live switch. `enabled == false` with no Linux status —
/// the only value a real build without an updater ever projects — flips the page
/// to the platform-true copy and DISABLES, never hides, both switches. Not asserted
/// on macOS, whose copy is unchanged; on Linux it drives the same no-updater
/// projection (the shipping Linux page is `linux_host` and keeps its switches live).
#[cfg(not(target_os = "macos"))]
#[test]
fn off_macos_update_page_names_the_real_lane_and_disables_the_switch() {
    let mut status = update_status(false);
    status.enabled = false;
    let (mut runtime, instance, view) =
        setup_with_update(UpdateState::from_status(1, "0.1.0", Some(&status), false));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    for (variant, cx) in [
        ("wide", view_cx_at(1_200.0, 820.0)),
        // The genuine Medium workbench — the narrowest status card, where
        // the one-line detail has ~320pt to fit in.
        ("medium", view_cx_at(849.0, 513.0)),
        ("compact", view_cx_at(600.0, 820.0)),
    ] {
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let headline = compiled
            .semantic(&UiKey::new("updates/headline"))
            .unwrap_or_else(|| panic!("{variant}: the status headline is on the first page"));
        assert_eq!(
            headline.label, "No in-app updater here.",
            "{variant}: the headline names the platform truth"
        );
        for key in [
            "settings/control/update.enabled",
            "settings/control/update.auto_apply",
        ] {
            let switch = compiled
                .semantic(&UiKey::new(key))
                .unwrap_or_else(|| panic!("{variant}: {key} stays on the page"));
            assert!(
                !switch.state.expect("a control carries state").enabled,
                "{variant}: {key} is disabled, not hidden"
            );
        }
        if let Some(subtitle) =
            compiled.semantic(&UiKey::new("settings/page-subtitle/software-update"))
        {
            assert!(
                subtitle.label.contains("reinstalling"),
                "{variant}: the subtitle names the real lane: {:?}",
                subtitle.label
            );
        }
        if variant == "wide" {
            let detail = compiled
                .semantic(&UiKey::new("updates/detail"))
                .expect("the detail line is on the desktop page");
            assert!(
                detail.label.to_lowercase().contains("reinstall"),
                "the detail names the real lane: {:?}",
                detail.label
            );
            let caption = compiled
                .semantic(&UiKey::new("updates/automatic/caption"))
                .expect("the desktop card keeps its caption");
            assert!(
                caption.label.contains("do nothing here") && !caption.label.contains("macOS"),
                "the caption says why the switches are inert, without calling the \
                 updater macOS-only (Linux has one too): {:?}",
                caption.label
            );
        }
        // The page's own copy and shared navigation must fit at every width: the
        // `updates/` nodes and the two switches' labels, whose wording is chosen
        // to fit (`update_switch_labels` — the retitled "Automatic updates" label
        // overflowed the narrow Medium column until 2026-09-23).
        let overflowing = compiled
            .paint_audit_lines()
            .into_iter()
            .filter(|line| line.contains("overflow=true") || line.contains("clip-truncated=true"))
            .filter(|line| {
                line.contains("paint-text key=\"updates/")
                    || line.contains("paint-text key=\"settings/label/update.")
            })
            .collect::<Vec<_>>();
        assert!(
            overflowing.is_empty(),
            "{variant}: off-macOS Update copy overflows its slot:\n{}",
            overflowing.join("\n")
        );
        assert_zero_top_paint(&compiled, &format!("{variant} off-macOS Update page"));
    }
}

/// A HEALTHY UPDATE PAGE (2026-09-23 audit, SB-07/SB-21): "You're up to date." over
/// "aterm 0.1.0" and when it last checked — no build number (About has it) and no
/// updater decision sentence, whose cadence detail stays in `aterm ctl update status`
/// and the log.
#[test]
fn a_healthy_update_page_paints_the_version_and_when_it_checked() {
    let mut status = update_status(false);
    // The decision sentence the updater writes today (`github::cadence_note`).
    status.outcome = "up to date (latest release build 1) \u{b7} checks every 30 min".to_string();
    status.updated_at =
        aterm_types::rfc3339::format_rfc3339(aterm_time::unix_secs().unwrap() - 12 * 60);
    let state = UpdateState::from_status(1, "0.1.0", Some(&status), false);
    assert_eq!(update_outcome_line(&state.projection()), None);
    let (mut runtime, instance, view) = setup_with_update(state);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_224.0, 722.0));
    let label = |key: &str| {
        compiled
            .semantic(&UiKey::new(key))
            .map(|node| node.label.clone())
            .unwrap_or_else(|| panic!("{key} is on the page"))
    };
    assert_eq!(label("updates/current"), "aterm 0.1.0");
    assert_eq!(label("updates/detail"), "Checked 12 min ago.");
    assert!(
        compiled
            .semantics
            .iter()
            .all(|node| !node.key.as_str().starts_with("updates/outcome")),
        "a healthy decision authors no outcome row"
    );
    // A non-routine outcome the page does not otherwise say still gets its line.
    status.outcome = "no release carries an update manifest".to_string();
    let projection = UpdateState::from_status(1, "0.1.0", Some(&status), false).projection();
    assert_eq!(
        update_outcome_line(&projection).as_deref(),
        Some("no release carries an update manifest")
    );
}

/// THE NOTES CARD CLAIMS "NEWEST VERSION" ONLY AFTER A COMPARISON (2026-09-27 audit).
/// A stranded machine records zero ledger failures and falls past the failing arm;
/// a copy no check has completed on beside "Not checked yet." has compared nothing.
/// Neither says "is the newest version". A persistent failure whose checks work (an
/// install streak) never says checks can't run. A checked, healthy page still says
/// "newest" (the negative control).
#[test]
fn the_notes_card_says_newest_only_after_a_check() {
    let notes = |edit: &dyn Fn(&mut aterm_update::UpdateStatus)| {
        let mut status = update_status(false);
        status.updated_at = "2026-09-23T12:00:00Z".to_string();
        edit(&mut status);
        update_notes_lines(&UpdateState::from_status(1, "0.1.0", Some(&status), false).projection())
            .join(" ")
    };
    let only_when_ready = "Release notes appear here when an update is ready.";

    assert_eq!(
        notes(&|_| {}),
        "aterm 0.1.0 is the newest version. Notes for the next one appear here when \
         it\u{2019}s ready."
    );
    assert_eq!(notes(&|s| s.channel_unreadable = true), only_when_ready);
    assert_eq!(notes(&|s| s.updated_at = String::new()), only_when_ready);
    assert_eq!(
        notes(&|s| {
            s.failing_persistent = true;
            s.failing_kind = "apply".into();
            s.failing_applies = 3;
        }),
        only_when_ready
    );
    assert_eq!(
        notes(&|s| {
            s.enabled = false;
            s.updated_at = String::new();
        }),
        "Update checks are unavailable for this installation, so no release notes can \
         be shown."
    );
}

#[test]
fn ordinary_medium_staged_update_pages_workbench_and_notes() {
    let status = update_status(true);
    let (mut runtime, instance, view) =
        setup_with_update(UpdateState::from_status(1, "0.1.0", Some(&status), false));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    state.feedback = Some("Update will install when safe".to_string());
    // Exercise the genuine medium workbench. Shorter heights that cannot
    // fit all 14 labeled routes intentionally select compact navigation.
    let cx = view_cx_at(849.0, 513.0);
    let mut seen = BTreeSet::new();
    for section in 0..2 {
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        compiled.validate_parity().unwrap();
        assert!(
            compiled
                .semantic(&UiKey::new("settings/page-heading/software-update"))
                .is_some(),
            "every paged update section retains its route identity"
        );
        for node in &compiled.semantics {
            if node.key.as_str().starts_with("updates/") {
                assert!(
                    node.rect.bottom() <= cx.viewport.bottom() + 0.01,
                    "{} clips at 849x460: {:?}",
                    node.key.as_str(),
                    node.rect
                );
                seen.insert(node.key.as_str().to_string());
            }
        }
        for (key, minimum_height) in [
            ("updates/workbench", 220.0),
            ("updates/actions", 36.0),
            ("updates/release-notes-card", 210.0),
            ("updates/outcome", 24.0),
        ] {
            if let Some(node) = compiled.semantic(&UiKey::new(key)) {
                assert!(
                    node.rect.height >= minimum_height,
                    "{key} is vertically clipped: {:?}",
                    node.rect
                );
            }
        }
        if section == 0 {
            let next = compiled
                .hits
                .iter()
                .find(|hit| hit.key.as_str() == "updates/pagination/next")
                .expect("staged update exports semantic Next");
            assert_eq!(next.action.as_str(), "settings/page-down");
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: next.action.clone(),
                        value: None,
                    }),
                )
                .unwrap();
        } else if section < 1 {
            // Wheel/keyboard and the visible Next control reduce to the
            // same bounded page_scroll state.
            runtime
                .dispatch(instance, view, AppEvent::ScrollLines(1))
                .unwrap();
        }
    }
    for key in [
        "updates/workbench",
        "updates/install-now",
        "updates/headline",
        "updates/automatic",
        "updates/release-notes",
        "updates/outcome",
    ] {
        assert!(seen.contains(key), "missing paged Medium update node {key}");
    }
}

#[test]
fn desktop_terminal_route_has_zero_paint_overflow_at_captured_viewport() {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Terminal),
                value: None,
            }),
        )
        .unwrap();
    let cx = view_cx_at(1_224.0, 722.0);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_zero_top_paint(&compiled, "desktop Terminal route");

    let timing = prefs::application_timing(prefs::EDIT_AMBIGUOUS_WIDTH).unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new(format!(
                "settings/label/{}",
                prefs::EDIT_AMBIGUOUS_WIDTH
            )))
            .is_some_and(|node| node.label.contains(timing)),
        "the compact visual lifecycle copy must not weaken complete semantics"
    );
    let visual = compiled
        .paint_audit_lines()
        .into_iter()
        .find(|line| {
            line.contains(&format!(
                "paint-text key=\"settings/label/{}/visual\"",
                prefs::EDIT_AMBIGUOUS_WIDTH
            ))
        })
        .expect("ambiguous-width visual label is audited");
    assert!(visual.contains("overflow=false"), "{visual}");
    assert!(visual.contains("New text only"), "{visual}");

    let wrapper = compiled
        .paint
        .iter()
        .find(|node| node.key.as_str() == format!("settings/label/{}", prefs::EDIT_AMBIGUOUS_WIDTH))
        .expect("semantic label wrapper is retained for paint traversal");
    assert!(matches!(
        &wrapper.content,
        UiContent::Group(spec) if spec.style == StyleRef::Plain
    ));
    let isolated = crate::native_ui::CompiledUi {
        bounds: wrapper.rect,
        paint: vec![wrapper.clone()],
        hits: Vec::new(),
        semantics: Vec::new(),
        focus_order: Vec::new(),
        default_action: None,
    };
    let prims = isolated.tray(aterm_render::Theme::default(), 13.0).prims;
    assert!(
        prims.iter().all(|primitive| !matches!(
            primitive,
            crate::widget::DrawPrim::Panel { .. } | crate::widget::DrawPrim::Stroke { .. }
        )),
        "semantic-only setting label wrappers must not paint a card or border: {prims:?}",
    );
}

#[test]
fn desktop_and_compact_update_pages_fit_wrapped_long_notes_and_outcome() {
    let mut status = update_status(true);
    status.changelog = Some(
        (0..48)
            .map(|index| {
                format!(
                    "{}- Change {index}: {}{} {}",
                    if index == 0 { "\t  " } else { "" },
                    "retained native Settings copy stays reachable and measurable across every renderer-authored page; ".repeat(3),
                    if index == 1 { "\u{2003}\u{2003}" } else { "" },
                    if index == 0 { "終".repeat(160) } else { format!("tail-{index}") },
                )
            })
            .collect::<Vec<_>>()
            .join("\n"),
    );
    status.outcome = "\t  The update is still ready; the install stopped: live terminals and visible screens remain attached;\u{2003}\u{2003}review the sessions before retrying the handoff.\n\nThe protected live-PTY and visible-screen handoff keeps every session running until an explicit retry is safe."
        .to_string();
    let expected_outcome = status.outcome.clone();
    let without_whitespace = |text: &str| {
        text.chars()
            .filter(|character| !character.is_whitespace())
            .collect::<String>()
    };

    for (variant, viewport_width, viewport_height) in
        [("desktop", 1_224.0, 722.0), ("compact", 568.0, 658.0)]
    {
        let update_state = UpdateState::from_status(1, "0.1.0", Some(&status), false);
        let expected_notes = update_state.projection().changelog.join("\n");
        let (mut runtime, instance, view) = setup_with_update(update_state);
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::SoftwareUpdate),
                    value: None,
                }),
            )
            .unwrap();
        let cx = view_cx_at(viewport_width, viewport_height);
        let first = compile_settings_view(&runtime, instance, view, &cx);
        let total = pager_total(&first, "updates/range");
        assert!(total >= 4, "{variant}: workbench, note pages, outcome");

        let mut saw_notes = false;
        let mut painted_notes = String::new();
        let mut saw_outcome = false;
        let mut painted_outcome = String::new();
        let mut outcome_line_keys = BTreeSet::new();
        for page in 0..total {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.page_scroll = page;
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            assert_zero_top_paint(&compiled, &format!("{variant} Update page {page}/{total}"));
            assert_eq!(
                compiled
                    .semantic(&UiKey::new("updates/range"))
                    .map(|node| node.label.as_str()),
                Some(format!("Page {} of {total}", page + 1).as_str()),
                "{variant}: atomic Update sections use page language",
            );
            for node in &compiled.paint {
                if node.key.as_str().starts_with("updates/release-notes")
                    && let UiContent::RichText(spec) = &node.content
                {
                    saw_notes = true;
                    assert_eq!(
                        spec.semantic_text, expected_notes,
                        "{variant}: responsive wrapping must not replace exact release-note semantics",
                    );
                    painted_notes.push_str(&spec.text);
                }
                if node.key.as_str().starts_with("updates/outcome/line-")
                    && let UiContent::Text(spec) = &node.content
                {
                    assert!(
                        outcome_line_keys.insert(node.key.clone()),
                        "{variant}: outcome lines need unique stable keys",
                    );
                    assert!(
                        crate::tray_raster::ui_text_width(
                            &spec.text,
                            11.0 * crate::native_appearance::text_scale(),
                        ) <= node.rect.width + 0.5,
                        "{variant}: outcome line {:?} exceeds its authored rect",
                        node.key,
                    );
                    painted_outcome.push_str(&spec.text);
                }
            }
            if let Some(outcome) = compiled
                .semantics
                .iter()
                .find(|node| node.key.as_str().starts_with("updates/outcome"))
            {
                saw_outcome = true;
                assert_eq!(outcome.label, expected_outcome);
            }
        }
        assert!(saw_notes, "{variant}: release-note pages remain reachable");
        assert_eq!(
            without_whitespace(&painted_notes),
            without_whitespace(&expected_notes),
            "{variant}: visual release-note pagination must not drop visible content",
        );
        assert!(saw_outcome, "{variant}: the outcome remains reachable");
        assert!(
            !outcome_line_keys.is_empty(),
            "{variant}: outcome must use inspectable per-line paint nodes",
        );
        // The outcome is a BOUNDED summary inside the status card now,
        // not its own paginated section: at most a few lines, elided
        // rather than dropped, with the exact ledger string retained on
        // the semantic parent asserted above. What it must never do is
        // scramble or reorder what it does show.
        assert!(
            outcome_line_keys.len() <= MAX_UPDATE_OUTCOME_LINES,
            "{variant}: outcome is bounded to {MAX_UPDATE_OUTCOME_LINES} lines, saw {}",
            outcome_line_keys.len(),
        );
        let painted = without_whitespace(&painted_outcome);
        let complete =
            without_whitespace(&expected_outcome.split('\n').collect::<Vec<_>>().join(" "));
        let shown = painted.trim_end_matches('\u{2026}');
        assert!(
            complete.starts_with(shown) && !shown.is_empty(),
            "{variant}: the visible outcome is an exact leading run of the real one\n  shown: {shown}\n  whole: {complete}",
        );
    }
}

/// Widest UI-face text in an authored subtree, measured EXACTLY as
/// `native_ui`'s paint audit measures a `Text` node whose role/style resolve
/// to the Body step in the UI face — every `updates/outcome/line-*` does.
///
/// Returns `(worst required width, the box it was given, its key)`, walking
/// the same padding arithmetic the compiler performs so the answer is the
/// PAINTED measure, not the authoring intent.
fn widest_authored_text(node: &UiNode, width: f32) -> Option<(f32, f32, String)> {
    let inner = (width - node.layout.padding.left - node.layout.padding.right).max(0.0);
    let px = 13.0 * crate::native_appearance::text_scale();
    let face = crate::widget::TextFace::Ui;
    let mut worst = match &node.content {
        UiContent::Text(spec) => {
            let required = crate::tray_raster::ui_text_width_for(face, &spec.text, px);
            Some((required, width, node.key.as_str().to_string()))
        }
        _ => None,
    };
    for child in &node.children {
        let Some(found) = widest_authored_text(child, inner) else {
            continue;
        };
        let worse = match &worst {
            Some((required, available, _)) => found.0 - found.1 > required - available,
            None => true,
        };
        if worse {
            worst = Some(found);
        }
    }
    worst
}

/// MEASURE == PAINT for the compact updater-outcome card, at every text
/// scale the appearance store can hand it.
///
/// The card wraps prose greedily to a measure it is told, and paints those
/// lines inside a box it authors itself. When those two numbers came from
/// different subtractions the wrapper packed lines the painter could not
/// fit: the card was handed the RELEASE-NOTES card's text measure, which
/// [`update_release_notes_padding`] narrows to 14pt above 1.25× text, while
/// the card itself insets 16pt. Identical at 1×, four points apart at 2× —
/// so a greedy line landed in the gap and painted past its own edge
/// (`updates/outcome/line-2`, required 263.3 in a 262.0 box, Windows 2×).
///
/// This pins the property at the seam rather than through one page: the box
/// is read back off the node's OWN authored padding, so re-padding the card
/// without re-measuring its prose fails here, on every platform, at 1× too.
#[test]
fn compact_update_outcome_wraps_to_the_box_it_paints_in() {
    crate::tray_raster::prepare_ui_fonts_for_direct_view_test();
    let restore = crate::native_appearance::current_preferences();
    let mut status = update_status(true);
    // Long enough to wrap past the bound at every scale, so no width under
    // test can pass by having nothing to break.
    status.outcome =
        "The protected live terminal remains attached until the verified handoff retries."
            .to_string();
    let projection = UpdateState::from_status(1, "0.1.0", Some(&status), false).projection();

    for scale in [0.85_f32, 1.0, 1.25, 1.5, 1.75, 2.0] {
        crate::native_appearance::install_preferences(
            crate::native_appearance::AppearancePreferences {
                text_scale: scale,
                ..restore
            },
        );
        // 294.0 is the real short-landscape section width (568×320 at 2×).
        for card_width in [180.0_f32, 240.0, 294.0, 360.0, 480.0, 620.0] {
            let (card, _) = compact_update_outcome(&projection, card_width)
                .expect("a non-routine outcome authors the card");
            // Font-independent half of the property, true on every
            // platform: the measure the prose wrapped to IS the box the
            // authored insets leave. Only the second half — whether a
            // greedy break happens to land in a gap — depends on the host
            // UI face, which is why this defect could hide off-Windows.
            let insets = card.layout.padding.left + card.layout.padding.right;
            assert_eq!(
                compact_update_outcome_text_width(card_width),
                card_width - insets,
                "{scale}x card {card_width}: wrap measure vs authored box",
            );
            let (required, available, key) =
                widest_authored_text(&card, card_width).expect("the card paints its wrapped lines");
            // The paint audit's own overflow predicate
            // (`native_ui::finish_text_fit`): whatever it would flag, this
            // flags first.
            assert!(
                required <= available + 0.5,
                "{scale}x card {card_width}: {key} wraps to \
                 {required:.1} in a {available:.1} box",
            );
        }
    }
    crate::native_appearance::install_preferences(restore);
}

/// Every section of the simplified Update page stays reachable, complete and
/// overflow-free at the platform maximum Dynamic Type in short landscape —
/// the shape that used to clip whatever followed the status card.
///
/// The retired paginated "LAST UPDATE RESULT" section is what this test
/// originally audited. The updater outcome is now ONE line inside the status
/// card, so the property to hold is that it is still surfaced exactly once
/// and still fits, alongside the two controls the page exists for.
#[test]
fn maximum_type_landscape_update_sections_are_complete() {
    at_each_text_scale(
        &[2.0],
        "2x Update section audit",
        maximum_type_landscape_update_sections_are_complete_at_scale,
    );
}

/// [`maximum_type_landscape_update_sections_are_complete`] at 2.0× ([`at_each_text_scale`]).
fn maximum_type_landscape_update_sections_are_complete_at_scale(_scale: f32) {
    let mut status = update_status(true);
    status.outcome =
        "The protected live terminal remains attached until the verified handoff retries."
            .to_string();
    let expected_outcome = status.outcome.clone();
    let update_state = UpdateState::from_status(1, "0.1.0", Some(&status), false);
    let (mut runtime, instance, view) = setup_with_update(update_state);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();

    let cx = view_cx_at(568.0, 320.0);
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(compact_page_budget(state, cx.viewport).side_by_side_pager);

    let mut global_total = None;
    let mut visited_pages = 0usize;
    let mut keys = BTreeSet::new();
    let mut saw_outcome = 0usize;
    loop {
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let total = pager_total(&compiled, "updates/range");
        assert_eq!(*global_total.get_or_insert(total), total);
        let context = format!("2x landscape Update page {visited_pages}/{total}");
        compiled
            .validate_parity()
            .unwrap_or_else(|error| panic!("{context}: {error:?}"));
        assert_short_landscape_geometry(&compiled, 2.0, &context);
        assert_accessible_pager(
            &compiled,
            "updates/pagination",
            visited_pages,
            total,
            &context,
        );
        assert_eq!(
            compiled
                .semantic(&UiKey::new("updates/range"))
                .map(|node| node.label.as_str()),
            Some(format!("Page {} of {total}", visited_pages + 1).as_str()),
            "{context}: exact page identity",
        );
        assert_zero_top_paint(&compiled, &context);

        if let Some(hero) = compiled.semantic(&UiKey::new("updates/hero")) {
            assert_eq!(hero.role, SemanticRole::Status, "{context}: hero is Status");
            assert!(
                hero.label.contains("Update ready"),
                "{context}: the status summary states where the build stands, saw {:?}",
                hero.label,
            );
        }
        // Whichever slice it lands on, the outcome keeps the EXACT ledger
        // string on its semantic node — the paint beside it is bounded.
        if let Some(outcome) = compiled.semantic(&UiKey::new("updates/outcome")) {
            assert_eq!(
                outcome.label, expected_outcome,
                "{context}: exact updater outcome retained",
            );
            saw_outcome += 1;
        }
        keys.extend(
            compiled
                .semantics
                .iter()
                .filter(|node| {
                    node.key.as_str().starts_with("updates/")
                        || node.key.as_str().starts_with("settings/control/update.")
                })
                .map(|node| node.key.as_str().to_string()),
        );

        visited_pages += 1;
        let next = compiled
            .semantic(&UiKey::new("updates/pagination/next"))
            .expect("accessible Update Next");
        if !next.state.expect("pager state").enabled {
            break;
        }
        let action = compiled
            .hits
            .iter()
            .find(|hit| hit.key.as_str() == "updates/pagination/next")
            .expect("enabled Update Next hit")
            .action
            .clone();
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: action,
                    value: None,
                }),
            )
            .unwrap();
        assert!(visited_pages < 64, "bounded Update page traversal");
    }

    assert_eq!(visited_pages, global_total.unwrap());
    assert_eq!(
        saw_outcome, 1,
        "the outcome is surfaced on exactly one page"
    );
    // Both `[update]` switches, whole: here the card splits, one to a section.
    for key in [
        "updates/hero",
        "updates/install-now",
        "updates/automatic",
        "updates/automatic-install",
        "settings/control/update.enabled",
        "settings/control/update.auto_apply",
        "updates/release-notes",
    ] {
        assert!(
            keys.contains(key),
            "2x landscape Update page never reached {key}; saw {keys:?}",
        );
    }
}

/// 2026-08 settings audit: navigating Home → an ordinary form page moved
/// the content column ~130pt because each page centered around its OWN
/// route maximum. Sibling pages of one rail must share a left edge; the
/// narrower page keeps its deliberate width by yielding on the right.
#[test]
fn rail_sibling_pages_share_one_content_left_edge() {
    let (mut runtime, instance, view) = setup();
    let cx = view_cx_at(1_275.0, 828.0);
    let mut heading_x = |route: SettingsRoute| {
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(route),
                    value: None,
                }),
            )
            .unwrap();
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        compiled
            .paint
            .iter()
            .find(|node| {
                // The About page leads with its hero card instead of the
                // shared page heading; both start at the content column.
                node.key.as_str().starts_with("settings/page-heading/")
                    || node.key.as_str() == "about/hero"
            })
            .unwrap_or_else(|| panic!("{route:?} paints a leading content node"))
            .rect
            .x
    };
    let home = heading_x(SettingsRoute::Home);
    for route in [
        SettingsRoute::CursorKitty,
        SettingsRoute::Appearance,
        SettingsRoute::Terminal,
        SettingsRoute::SoftwareUpdate,
        SettingsRoute::About,
    ] {
        let x = heading_x(route);
        assert!(
            (x - home).abs() <= 0.5,
            "{route:?} content column starts at {x}, Home at {home}"
        );
    }
}

/// 2026-08 settings audit: the About compiler row ellipsized mid-token
/// ("release · tr…"). A non-code value that overflows its column now
/// wraps at its own " · " separators — every token whole, every line
/// inside the measure — while code identifiers keep two-ended elision.
#[test]
fn long_noncode_metadata_values_wrap_at_separators_not_mid_token() {
    let value = "trustc 1.99.0-dev (dcc900ad) · trust · release · trust_verify off";
    let width = 340.0;
    let lines = metadata_value_lines("compiler", value, width);
    assert!(lines.len() >= 2, "the audited value wraps: {lines:?}");
    assert!(lines.len() <= MAX_METADATA_VALUE_LINES);
    assert!(
        lines.iter().all(|line| !line.contains('…')),
        "no token is chopped: {lines:?}"
    );
    assert_eq!(
        lines.join(" · "),
        value,
        "the wrap is a partition of the value at its separators"
    );
    let px = 13.0 * crate::native_appearance::text_scale();
    for line in &lines {
        assert!(
            metadata_value_text_width(line, px, false) <= width - ABOUT_METADATA_TEXT_SAFETY + 0.01,
            "every wrapped line fits the column: {line:?}"
        );
    }
    // A short value stays one untouched line; a hash keeps its
    // identifying ends instead of wrapping.
    assert_eq!(
        metadata_value_lines("compiler", "trustc 1.99.0", width),
        vec!["trustc 1.99.0".to_string()]
    );
    let hash = metadata_value_lines("commit", &"0123456789abcdef".repeat(4), 96.0);
    assert_eq!(hash.len(), 1);
    assert!(hash[0].contains('…'));
    // The line-aware measures agree with each other.
    let rows = vec![
        ("compiler".to_string(), value.to_string()),
        ("signature".to_string(), "7a022df9673ccebb".to_string()),
    ];
    assert_eq!(
        metadata_line_count(&rows, width),
        lines.len() + 1,
        "card height buys exactly the painted lines"
    );
    let chunks = chunk_metadata_rows(&rows, lines.len(), width);
    assert_eq!(
        chunks.len(),
        2,
        "chunking spends the wrapped fact's real line budget"
    );
    assert_eq!(chunks[0].len(), 1);
}

#[test]
fn about_metadata_values_fit_responsive_rects_and_keep_full_semantics() {
    let ui_sample = "compiler-終-with-a-long-provenance-suffix";
    let ui_elided = elide_metadata_value(ui_sample, 112.0, false);
    assert!(ui_elided.ends_with('…'));
    assert!(
        metadata_value_text_width(
            &ui_elided,
            13.0 * crate::native_appearance::text_scale(),
            false,
        ) <= 112.0
    );
    let code_sample = "0123456789abcdef0123456789abcdef";
    let code_elided = elide_metadata_value(code_sample, 96.0, true);
    assert!(code_elided.contains('…'));
    assert!(code_elided.starts_with("012"));
    assert!(code_elided.ends_with("def"));
    assert!(
        metadata_value_text_width(
            &code_elided,
            13.0 * crate::native_appearance::text_scale(),
            true,
        ) <= 96.0
    );

    let shared_prefix = format!("same-prefix-{}", "x".repeat(64));
    let shared_suffix = format!("{}-same-tail", "y".repeat(64));
    let first_value = format!("{shared_prefix}A{shared_suffix}");
    let second_value = format!("{shared_prefix}B{shared_suffix}");
    let compile_card = |value: &str| {
        UiTree::new(metadata_card(
            "about/metadata-test",
            "Build information",
            &[("Build".to_string(), value.to_string())],
            200.0,
            72.0,
        ))
        .compile(LogicalRect::new(0.0, 0.0, 320.0, 200.0))
        .unwrap()
    };
    let first = compile_card(&first_value);
    let second = compile_card(&second_value);
    let row_key = UiKey::new("about/metadata-test/row/build");
    assert_eq!(
        first.semantic(&row_key).map(|node| node.label.as_str()),
        Some(format!("Build: {first_value}").as_str()),
        "the stable row owns the complete accessibility contract"
    );
    for visual_key in [
        "about/metadata-test/label/build",
        "about/metadata-test/value/build",
    ] {
        let key = UiKey::new(visual_key);
        assert!(first.semantic(&key).is_none(), "{visual_key} is paint-only");
        assert!(first.paint.iter().any(|node| node.key == key));
    }
    let painted_value = |compiled: &crate::native_ui::CompiledUi| {
        compiled
            .paint
            .iter()
            .find_map(|node| {
                (node.key.as_str() == "about/metadata-test/value/build").then_some(&node.content)
            })
            .and_then(|content| match content {
                UiContent::Text(spec) => Some(spec.text.clone()),
                _ => None,
            })
            .unwrap()
    };
    assert_eq!(
        painted_value(&first),
        painted_value(&second),
        "the hidden middle differs while the bounded visual is identical"
    );
    assert_ne!(
        first.fingerprint(),
        second.fingerprint(),
        "the complete semantic value participates in retained identity"
    );

    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::About),
                value: None,
            }),
        )
        .unwrap();
    let provenance = crate::build_info::about_fields()
        .into_iter()
        .filter(|(key, _)| !matches!(*key, "tagline" | "author" | "company" | "site"))
        .collect::<Vec<_>>();
    let px = 13.0 * crate::native_appearance::text_scale();

    for viewport_width in [474.0, 760.0, 1_040.0, 1_160.0] {
        let width = SettingsWidth::for_viewport(viewport_width);
        if width == SettingsWidth::Compact {
            runtime
                .dispatch(instance, view, AppEvent::ScrollLines(1))
                .unwrap();
        }
        let cx = view_cx_at(viewport_width, 658.0);
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        let expected_value_width = about_metadata_value_width(viewport_width, width);
        let visible_rows = match width {
            SettingsWidth::Compact | SettingsWidth::Wide => provenance.len(),
            SettingsWidth::Medium => 4,
        };

        for (label, full_value) in provenance.iter().take(visible_rows) {
            let fragment = key_fragment(label);
            let row = compiled
                .semantic(&UiKey::new(format!("about/provenance/row/{fragment}")))
                .unwrap();
            assert_eq!(row.label, format!("{label}: {full_value}"));

            let visual_key = UiKey::new(format!("about/provenance/value/{fragment}"));
            assert!(
                compiled.semantic(&visual_key).is_none(),
                "bounded metadata value is a paint-only copy"
            );
            let visual = compiled
                .paint
                .iter()
                .find(|node| node.key == visual_key)
                .unwrap();
            assert!(
                (visual.rect.width - expected_value_width).abs() <= 0.01,
                "{viewport_width}px {label} rect {} != derived budget {expected_value_width}",
                visual.rect.width,
            );
            let visual_text = match &visual.content {
                UiContent::Text(spec) => spec.text.as_str(),
                _ => panic!("metadata value visual must remain text"),
            };
            let measured =
                metadata_value_text_width(visual_text, px, metadata_value_is_code(label));
            assert!(
                measured <= visual.rect.width - ABOUT_METADATA_TEXT_SAFETY + 0.01,
                "{viewport_width}px {label} paints {measured}px into {}px",
                visual.rect.width,
            );
        }
    }
}

#[test]
fn local_settings_eliders_keep_combining_zwj_and_flag_graphemes_atomic() {
    for cluster in ["e\u{301}", "👩\u{200d}💻", "🇺🇳"] {
        let repeated = cluster.repeat(40);
        let tail = elide_metadata_value(&repeated, 72.0, false);
        assert!(tail.ends_with('…'));
        assert!(
            tail.graphemes()
                .all(|grapheme| grapheme == cluster || grapheme == "…"),
            "tail elision split {cluster:?}: {tail:?}"
        );

        let middle_source = format!(
            "{}{}{}",
            cluster.repeat(20),
            "x".repeat(200),
            cluster.repeat(20)
        );
        let middle = elide_metadata_value(&middle_source, 72.0, true);
        assert!(middle.contains('…'));
        assert!(
            middle
                .graphemes()
                .all(|grapheme| grapheme == cluster || grapheme == "x" || grapheme == "…"),
            "middle elision split {cluster:?}: {middle:?}"
        );

        let prefix = cluster.repeat(2);
        let available =
            (crate::tray_raster::ui_text_width(&prefix, group_footnote_text_px()) + 1.0).max(48.0);
        let note = format!("{prefix} {}", cluster.repeat(40));
        let lines = group_footnote_lines(&note, available);
        let first = format!("{prefix} ");
        assert_eq!(lines.first().map(String::as_str), Some(first.as_str()));
        assert_eq!(lines.concat(), note);
        assert!(lines.iter().all(|line| {
            crate::tray_raster::ui_text_width(line, group_footnote_text_px()) <= available + 0.5
                || line.graphemes().count() == 1
        }));
        assert!(
            lines
                .iter()
                .flat_map(|line| line.graphemes())
                .all(|grapheme| {
                    grapheme == cluster || grapheme.chars().all(char::is_whitespace)
                })
        );
    }
}

#[test]
fn bounded_numeric_setting_is_a_real_slider_and_keyboard_steps_exactly() {
    let (mut runtime, instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        panic!("Settings view");
    };
    state.route = SettingsRoute::TextFonts;
    let field = state
        .legacy
        .fields
        .iter_mut()
        .find(|field| field.key == prefs::EDIT_FONT_PX)
        .expect("font size field");
    field.seed = Some("14".to_string());
    field.placeholder = "14 px".to_string();
    state.common.last_focus = Some(UiKey::new(format!(
        "settings/control/{}",
        prefs::EDIT_FONT_PX
    )));

    let cx = view_cx_at(900.0, 820.0);
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    let key = UiKey::new(format!("settings/control/{}", prefs::EDIT_FONT_PX));
    assert_eq!(
        compiled.semantic(&key).unwrap().value,
        SemanticValue::Number {
            value: 14.0,
            minimum: 6.0,
            maximum: 200.0,
        }
    );
    let slider = compiled
        .paint
        .iter()
        .find_map(|node| {
            (node.key == key)
                .then_some(&node.content)
                .and_then(|content| {
                    let UiContent::Slider(control) = content else {
                        return None;
                    };
                    Some(control)
                })
        })
        .expect("numeric field paints as slider");
    assert_eq!(slider.spec.step, 1.0);
    assert_eq!(slider.spec.display_value, "14");

    let outcome = runtime
        .dispatch(
            instance,
            view,
            AppEvent::TextInput(TextInputEvent::Right { extend: false }),
        )
        .unwrap();
    let edit = outcome.effects.iter().find_map(|effect| match effect {
        AppEffect::ConfigPatch { patch, .. } => patch.edits.first(),
        _ => None,
    });
    assert_eq!(edit.and_then(|edit| edit.value.as_deref()), Some("15"));

    let range = prefs::range_of(prefs::EDIT_FONT_PX).unwrap();
    assert_eq!(normalize_slider_value(13.49, range).as_deref(), Some("13"));
    assert_eq!(normalize_slider_value(99.0, range).as_deref(), Some("99"));
    assert_eq!(normalize_slider_value(500.0, range).as_deref(), Some("200"));
    assert_eq!(normalize_slider_value(f64::NAN, range), None);
}

