#[test]
fn manual_route_identity_and_every_action_open_the_typed_editor() {
    let (mut runtime, instance, view) = setup();
    assert_eq!(
        SettingsRoute::from_path("/manual"),
        Some(SettingsRoute::Manual),
        "restore keeps a stable route identity without performing IO"
    );
    assert_eq!(
        route_action(SettingsRoute::Manual).as_str(),
        "settings/manual/open"
    );
    let commands = runtime.commands(instance, view).unwrap();
    let manual = commands
        .iter()
        .find(|command| command.title == "Settings: Go to Manual")
        .expect("Manual participates in the native command surface");
    assert_eq!(manual.id.as_str(), "settings/manual/open");

    let open = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Manual),
                value: None,
            }),
        )
        .unwrap();
    let operation = open
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::OpenConfigEditor { reply, .. } => Some(reply.operation),
            _ => None,
        })
        .expect("Manual emits exactly one path-free editor effect");
    let commands = runtime.commands(instance, view).unwrap();
    assert!(
        !commands
            .iter()
            .find(|command| command.id.as_str() == "settings/manual/open")
            .unwrap()
            .enabled,
        "a duplicate open is disabled only while the typed request is pending"
    );
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ConfigEditorFinished {
                operation,
                outcome: ConfigEditorOutcome::Failed {
                    message: "test denial".to_string(),
                },
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    assert!(state.pending.is_empty());
    assert!(state.feedback.as_deref().unwrap().contains("test denial"));
    let commands = runtime.commands(instance, view).unwrap();
    assert!(
        commands
            .iter()
            .find(|command| command.id.as_str() == "settings/manual/open")
            .unwrap()
            .enabled,
        "the Manual command reopens its editor while Settings remains on /manual"
    );
}

/// THE SOUND MENU, on the NATIVE surface (owner ask: "add the volume and
/// SFX menu to settings"). This pins the native Advanced pane, where the
/// routing actually has to hold: every
/// audible key reachable at all is reachable on ONE route under ONE caption,
/// and nothing audible is left behind in Manual except where the platform
/// has no host for it.
///
/// NON-VACUOUS: it asserts its own preconditions — the menu is non-empty and
/// every member is a live registry row — and then names the six keys that
/// were Manual-only or non-existent before this change, so the test cannot
/// pass by surfacing nothing.
#[test]
fn native_sound_menu_is_one_box_on_one_route() {
    let fields = prefs::editable_fields(&Config::default());
    assert!(
        prefs::SOUND_MENU_KEYS.len() >= 9,
        "the Sound menu lost members: {:?}",
        prefs::SOUND_MENU_KEYS
    );
    for key in prefs::SOUND_MENU_KEYS {
        assert!(
            fields.iter().any(|field| &field.key == key),
            "{key} left the registry; the Sound menu would silently shrink"
        );
    }

    // THE ROUTING CLAIM, SPELLED OUT rather than derived: every audible key
    // must land on the same pane under the same caption. Naming them here
    // means a misrouted key fails loudly instead of quietly dropping out of
    // both sides of a self-derived comparison.
    for key in [
        "trail_sounds",
        "trail_sound_volume",
        "trail_sound_style",
        "tone_melody",
        "trail_sound_bed",
        "trail_sound_riff",
        "bell_sound",
        // The supervisor's choice chime — a synth voice like the rest.
        "choice_sound",
        "sparkle_words.profanity.bonk",
        "sparkle_words.profanity.bonk_detonation",
        // PRISM WAKE's output pip — audible, so it owes the same routing.
        "output_streak.sound",
    ] {
        assert!(
            prefs::SOUND_MENU_KEYS.contains(&key),
            "{key} is audible but absent from SOUND_MENU_KEYS"
        );
        assert_eq!(prefs::section_of(key), prefs::Section::Cursor, "{key}");
        assert_eq!(prefs::group_of(key).0, "Sound", "{key}");
    }
    // Nothing NON-audible smuggled itself into the routing list.
    assert_eq!(
        prefs::SOUND_MENU_KEYS.len(),
        11,
        "the Sound menu's membership changed: {:?}",
        prefs::SOUND_MENU_KEYS
    );

    let shown: Vec<&str> = prefs::SOUND_MENU_KEYS
        .iter()
        .copied()
        .filter(|key| settings_field_is_visible(key, false, false))
        .collect();

    // The SEVEN rows the ordinary Advanced pane must paint: the volume
    // slider, the palette, and the five voice toggles. Four of these shipped
    // but were reachable only by hand-editing `aterm.toml`; one is new. If
    // any regresses to Manual the menu is partial again and this fails by
    // name rather than by a silently shorter list.
    for required in [
        prefs::EDIT_TRAIL_SOUND_VOLUME,
        prefs::EDIT_TRAIL_SOUND_STYLE,
        prefs::EDIT_TONE_MELODY,
        prefs::EDIT_TRAIL_SOUND_BED,
        prefs::EDIT_TRAIL_SOUND_RIFF,
        prefs::EDIT_SPARKLE_BONK,
        prefs::EDIT_SPARKLE_BONK_DETONATION,
        // The supervisor's choice chime (the question-policy contract).
        prefs::EDIT_CHOICE_SOUND,
    ] {
        assert!(
            shown.contains(&required),
            "{required} is not reachable from the native Sound menu"
        );
    }

    // The audible BEL appears exactly where a beep call exists to suppress.
    assert_eq!(
        shown.contains(&prefs::EDIT_BELL_SOUND),
        cfg!(any(target_os = "macos", windows)),
        "the terminal bell row must not promise a beep this platform never makes"
    );

    // The MASTER switch is deliberately not duplicated into the box: it is a
    // Top Setting ("Music effects"), and a second copy would let two
    // controls disagree about one key. It stays findable by search.
    assert!(
        !settings_field_is_visible(prefs::EDIT_TRAIL_SOUNDS, false, false),
        "the master belongs to Top Settings, not a second Advanced row"
    );
    assert!(
        settings_field_is_visible(prefs::EDIT_TRAIL_SOUNDS, false, true),
        "the master must still answer a global search for sound"
    );
    // …but the box must SAY where it went, or a user who opens Sound looking
    // for the on/off switch finds seven rows and no master.
    let note = prefs::group_footnote("Sound").expect("the Sound box needs consequence copy");
    assert!(
        note.contains("Music effects") && note.contains("Top Settings"),
        "the Sound box must point at the master switch it does not host: {note}"
    );
    // …and it must SCOPE that master, because this box holds two
    // independent audio paths. `lib.rs::on_bell` reads neither
    // `trail_sounds` nor `trail_sound_volume`
    // (`sound_menu_keys_are_read_at_their_consumers` pins that), so copy
    // calling Music effects "the master switch" flatly promised a user that
    // muting it would stop the beep. It does not.
    assert!(
        note.contains("synth voices") && note.contains("bell"),
        "the Sound box must scope the master to the synth voices and name \
         the bell as the exception: {note}"
    );

    // The bonk keys' escape from the keyword-toy rule is exact: their
    // sparkle-words siblings stay Manual-only.
    for sibling in [
        "sparkle_words.profanity.density",
        "sparkle_words.profanity.intensity",
    ] {
        assert!(
            !settings_field_is_visible(sibling, false, false),
            "{sibling} must stay a Manual-only keyword-toy internal"
        );
    }
}

/// THE SOUND ROWS DISCLOSE THEIR REAL GATES, AND ONLY THEIR REAL GATES.
///
/// A false "Inactive" note is worse than none — it tells a user a control is
/// dead while the sound keeps playing. The two families in the Sound box
/// have DIFFERENT gates and this pins the difference:
///
///   * the melody and the ambient bed ride `CursorGlow::drain_sound_cues`,
///     so `cursor_trail = false` really does silence them;
///   * the sing-along riff does NOT — it is gated on `glow_cfg.STYLE`, and
///     `resolve_cursor_glow` derives `style` from the style string
///     regardless of `enabled`, so the riff still sings with the trail off.
///     Its honest gate is the master switch.
///
/// NON-VACUOUS: each case asserts the note it SHOULD carry as well as the
/// note it must not, so a projection that stopped disclosing anything at all
/// fails instead of passing the negative half.
#[test]
fn sound_rows_disclose_their_real_gates_and_no_false_ones() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();

    // Cue-borne voices: the trail really is their gate.
    for key in [prefs::EDIT_TONE_MELODY, prefs::EDIT_TRAIL_SOUND_BED] {
        let effect = projected_effect("cursor_trail = false\n", &[], key, availability, motion);
        assert!(
            effect_note_contains(&effect, "Cursor trail is Off"),
            "{key} must disclose the trail gate it actually has: {effect:?}"
        );
        assert!(!effect.has_live_effect, "{key}");
    }

    // The riff: NOT trail-gated. It must not inherit that claim…
    let trail_off = projected_effect(
        "cursor_trail = false\n",
        &[],
        prefs::EDIT_TRAIL_SOUND_RIFF,
        availability,
        motion,
    );
    assert!(
        !effect_note_contains(&trail_off, "Cursor trail is Off"),
        "the riff still sings with the trail off; claiming otherwise is a lie: {trail_off:?}"
    );

    // …and it must disclose the master switch, which IS one of its gates.
    let music_off = projected_effect(
        "trail_sounds = false\n",
        &[],
        prefs::EDIT_TRAIL_SOUND_RIFF,
        availability,
        motion,
    );
    assert!(
        effect_note_contains(&music_off, "Music effects is Off"),
        "the riff must disclose the master switch that does silence it: {music_off:?}"
    );
    assert!(!music_off.has_live_effect);

    // The BONK rides the word-decoration tick, not the glow: the trail being
    // off must not claim it is inactive either.
    let bonk_trail_off = projected_effect(
        "cursor_trail = false\n",
        &[],
        prefs::EDIT_SPARKLE_BONK,
        availability,
        motion,
    );
    assert!(
        !effect_note_contains(&bonk_trail_off, "Cursor trail is Off"),
        "the bonk fires with the trail off: {bonk_trail_off:?}"
    );
    // Its REAL gate, asserted so the negative above cannot pass merely
    // because the bonk stopped disclosing anything at all.
    let bonk_master_off = projected_effect(
        "[sparkle_words]\nenabled = false\n",
        &[],
        prefs::EDIT_SPARKLE_BONK,
        availability,
        motion,
    );
    assert!(
        effect_note_contains(&bonk_master_off, "Sparkle Words master is Off"),
        "the bonk must disclose the sparkle master that does silence it: {bonk_master_off:?}"
    );
    // …and the MUSIC master, which since 2026-08-09 also silences it
    // (`app_render::bonk_sound_gain`'s `trail_sounds` term). Both bonk
    // rows, because both are sound-only leaves: `bonk_detonation` admits a
    // cue KIND into the same synth and moves nothing on glass.
    for key in [
        prefs::EDIT_SPARKLE_BONK,
        prefs::EDIT_SPARKLE_BONK_DETONATION,
    ] {
        let music_off = projected_effect("trail_sounds = false\n", &[], key, availability, motion);
        assert!(
            effect_note_contains(&music_off, "Music effects is Off"),
            "{key} must disclose the Music-effects master that does silence it: {music_off:?}"
        );
        assert!(!music_off.has_live_effect, "{key}");
    }

    // The CHOICE CHIME is a synth voice under the Music master too
    // (`App::chose_chime` reads `trail_sounds` before `choice_sound`).
    // NON-VACUOUS: with the master on, the row carries no such note.
    let chime_music_off = projected_effect(
        "trail_sounds = false\n",
        &[],
        prefs::EDIT_CHOICE_SOUND,
        availability,
        motion,
    );
    assert!(
        effect_note_contains(&chime_music_off, "Music effects is Off"),
        "{chime_music_off:?}"
    );
    assert!(!chime_music_off.has_live_effect);
    let chime_music_on = projected_effect(
        "trail_sounds = true\n",
        &[],
        prefs::EDIT_CHOICE_SOUND,
        availability,
        motion,
    );
    assert!(
        !effect_note_contains(&chime_music_on, "Music effects is Off"),
        "{chime_music_on:?}"
    );

    // Platform truth: with no audio device the synth voices say so, while
    // the terminal bell — an OS alert sound, not a synth voice — does not.
    let silent = SettingsAvailability {
        trail_audio: false,
        ..availability
    };
    let muted_riff = projected_effect("", &[], prefs::EDIT_TRAIL_SOUND_RIFF, silent, motion);
    assert!(
        effect_note_contains(&muted_riff, "Audio unavailable"),
        "{muted_riff:?}"
    );
    let muted_chime = projected_effect("", &[], prefs::EDIT_CHOICE_SOUND, silent, motion);
    assert!(
        effect_note_contains(&muted_chime, "Audio unavailable"),
        "the choice chime is a synth voice: {muted_chime:?}"
    );
    let bell = projected_effect("", &[], prefs::EDIT_BELL_SOUND, silent, motion);
    assert!(
        !effect_note_contains(&bell, "Audio unavailable"),
        "the OS bell does not need the trail-audio device: {bell:?}"
    );
}

/// SERIOUS MODE IS DISCLOSED ON EVERY AUDIBLE ROW IT ACTUALLY SILENCES —
/// and on none that it does not.
///
/// The Sound-menu census (`prefs::SOUND_MENU_KEYS`) deliberately keeps
/// `serious_mode` OUT of this box: it is a whole-product policy with its own
/// "Effect policy" home, and a second control for one key is exactly the
/// hazard that keeps the `trail_sounds` master in Top Settings. But it IS a
/// real gate — `SeriousEffect::TerminalSound` is read at all three
/// `app_render` sound seams and at `lib.rs::on_bell` — so the honest
/// surfacing is a per-row note, not a row. Without this every Sound row
/// reads "On" under Serious Mode while the machine is silent.
///
/// NON-VACUOUS: every case asserts the DEFAULT posture is note-free first,
/// so a projection that started shouting "Serious Mode" at everything (or
/// that returned the note for reasons unrelated to serious mode) fails.
#[test]
fn serious_mode_is_disclosed_on_the_sound_rows_it_silences() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    const TRAIL_ON: &str = "cursor_trail = true\n";
    const TRAIL_ON_SERIOUS: &str = "cursor_trail = true\nserious_mode = true\n";

    for key in [
        prefs::EDIT_TRAIL_SOUND_VOLUME,
        prefs::EDIT_TRAIL_SOUND_STYLE,
        prefs::EDIT_TONE_MELODY,
        prefs::EDIT_TRAIL_SOUND_BED,
        prefs::EDIT_TRAIL_SOUND_RIFF,
        prefs::EDIT_BELL_SOUND,
        // The supervisor's choice chime: `App::chose_chime` reads serious
        // mode first.
        prefs::EDIT_CHOICE_SOUND,
        // The bonks take the same note from the keyword-toy branch; pinning
        // them here keeps the BOX's promise whole rather than one branch's.
        prefs::EDIT_SPARKLE_BONK,
        prefs::EDIT_SPARKLE_BONK_DETONATION,
    ] {
        // Both postures AUTHOR the trail master. It is the top rung of the
        // same disclosure ladder ("Inactive · Cursor trail Off" outranks the
        // Serious Mode note), and its absent-key default is platform-split —
        // so leaving it unwritten would make the quiet case pass for the
        // wrong reason on Windows and the serious case fail outright.
        let quiet = projected_effect(TRAIL_ON, &[], key, availability, motion);
        assert!(
            !effect_note_contains(&quiet, "Serious Mode"),
            "{key} must not claim Serious Mode with Serious Mode off: {quiet:?}"
        );
        let serious = projected_effect(TRAIL_ON_SERIOUS, &[], key, availability, motion);
        assert!(
            effect_note_contains(&serious, "Serious Mode"),
            "{key} is silent under Serious Mode and must say so: {serious:?}"
        );
        assert!(!serious.has_live_effect, "{key}");
    }

    // THE MASTER TOO — via the cursor-trail block's `motion_suppression`,
    // not the sound branch above, which deliberately skips it. Pinned here
    // anyway so the BOX's promise is whole: if the master ever stopped
    // disclosing this, the Sound surface would have one row lying while its
    // eight neighbours told the truth.
    //
    // Note the distinction the copy gets right: this describes the CURRENT
    // STATE (with Serious Mode set, Music effects On is suppressed — true),
    // not the ACTION (toggling this control ON clears Serious Mode rather
    // than being suppressed by it —
    // `top_effect_controls_truthfully_escape_the_serious_mode_override`).
    let master = projected_effect(
        TRAIL_ON_SERIOUS,
        &[],
        prefs::EDIT_TRAIL_SOUNDS,
        availability,
        motion,
    );
    assert!(
        effect_note_contains(&master, "Serious Mode"),
        "Music effects On is silent under Serious Mode and must say so: {master:?}"
    );
}

/// The typing-sound picker's labels: `auto` reads as what it MEANS
/// ("Follow the trail", not the generic "Automatic"), every instrument
/// reads in sentence case, and the popup rows carry the same labels as
/// the button. The static option list is the synth's roster (14 rows).
#[test]
fn typing_sound_choice_labels_read_as_instruments() {
    assert_eq!(
        setting_choice_label(prefs::EDIT_TRAIL_SOUND_STYLE, "auto"),
        "Follow the trail"
    );
    assert_eq!(
        setting_choice_label(prefs::EDIT_TRAIL_SOUND_STYLE, "auto (default)"),
        "Follow the trail (default)",
        "the unset row keeps its default annotation"
    );
    for (value, label) in [
        ("music box", "Music box"),
        ("ice chime", "Ice chime"),
        ("typewriter", "Typewriter"),
        ("mechanical", "Mechanical"),
        ("felt", "Felt"),
    ] {
        assert_eq!(
            setting_choice_label(prefs::EDIT_TRAIL_SOUND_STYLE, value),
            label
        );
    }
    // Other keys' `auto` keeps its generic label.
    assert_eq!(
        setting_choice_label(prefs::EDIT_WINDOW_THEME, "auto"),
        "Automatic"
    );
    let field = prefs::editable_fields(&crate::app_config::Config::default())
        .into_iter()
        .find(|f| f.key == prefs::EDIT_TRAIL_SOUND_STYLE)
        .expect("the typing-sound row");
    let choices = choices_for_field(&field, &[], &crate::app_config::ThemeCatalog::default())
        .expect("static options");
    assert_eq!(choices.len(), 14);
    assert_eq!(choices[0], "auto");
    assert!(choices.iter().any(|c| c == "typewriter"));
    let picker = ChoicePicker::new(
        prefs::EDIT_TRAIL_SOUND_STYLE,
        choices.clone(),
        "auto (default)",
        false,
        false,
        "auto",
        &crate::app_config::ThemeCatalog::default(),
    );
    assert_eq!(picker.options[0].label, "Follow the trail");
    assert!(picker.options.iter().any(|o| o.label == "Music box"));
    assert!(
        picker.options.iter().all(|o| o.label != "Glass bell"),
        "the glass bell died with v1 (§17.3 phase 7)"
    );
}

/// THE UNDERLINE ROW FITS ITS OWN BUTTON. `rainbow kitty underline` is the
/// longest spelling the trail list has ever carried (23 characters, against
/// the previous longest `rainbow kitty pet` at 17), and sentence-cased it
/// measured 133.6 pt inside the 132.0 pt Top control at 1.0× text scale —
/// the renderer clipped it to `Rainbow kitty underl…` and the Top paint
/// audit went red
/// (`top_settings_builtin_and_hidden_state_matrix_has_zero_renderer_overflow`).
///
/// The fix is a PAINT LABEL, like `EDIT_MOTION`'s, not a narrower control
/// and not a renamed config value: the button reads the family's shorter
/// spelling, which stays honest (it names the highlighter-plus-strip mark,
/// the geometry that spelling selects — and, since 2026-08-28, the family
/// default) and stays a legal `cursor_trail_style` — pinned below by
/// canonicalising the label itself.
/// The committed value, the semantics and the open picker's rows keep the
/// complete spelling.
#[test]
fn cursor_trail_underline_choice_label_fits_the_control() {
    // Every spelling the ENGINE routes to the strip gets the one label —
    // the predicate is asked, not a second copy of the list.
    for spelling in [
        "rainbow kitty underline",
        "rainbow underline",
        "underline rainbow",
        "nyan underline",
        "  Rainbow Kitty Underline  ",
    ] {
        assert_eq!(
            setting_choice_label(prefs::EDIT_CURSOR_TRAIL_STYLE, spelling),
            "Rainbow underline",
            "{spelling:?} is an underline spelling and must read as the short label"
        );
    }
    // HONEST: the label is itself a spelling of the style it names, so it
    // resolves back to the value the control is holding.
    assert_eq!(
        prefs::cursor_trail_style_canonical("rainbow underline"),
        Some("rainbow kitty underline")
    );
    // Every other trail entry keeps its plain sentence case…
    for (value, label) in [
        ("rainbow kitty", "Rainbow kitty"),
        ("rainbow kitty pet", "Rainbow kitty pet"),
        ("rainbow kitty flying", "Rainbow kitty flying"),
        ("rainbow kitty tall", "Rainbow kitty tall"),
        ("off", "Off"),
    ] {
        assert_eq!(
            setting_choice_label(prefs::EDIT_CURSOR_TRAIL_STYLE, value),
            label
        );
    }
    // …and the shortening is scoped to this key.
    assert_eq!(
        setting_choice_label(prefs::EDIT_WINDOW_THEME, "rainbow kitty underline"),
        "Rainbow kitty underline"
    );
    // The open list — which has the width for it — still names the config
    // spelling, so the row a screen reader announces is the value written.
    let field = prefs::editable_fields(&crate::app_config::Config::default())
        .into_iter()
        .find(|f| f.key == prefs::EDIT_CURSOR_TRAIL_STYLE)
        .expect("the cursor-trail row");
    let choices = choices_for_field(&field, &[], &crate::app_config::ThemeCatalog::default())
        .expect("static options");
    assert!(choices.iter().any(|c| c == "rainbow kitty underline"));
    let picker = ChoicePicker::new(
        prefs::EDIT_CURSOR_TRAIL_STYLE,
        choices,
        prefs::DEFAULT_CURSOR_TRAIL_STYLE,
        false,
        false,
        prefs::DEFAULT_CURSOR_TRAIL_STYLE,
        &crate::app_config::ThemeCatalog::default(),
    );
    assert!(
        picker
            .options
            .iter()
            .any(|option| option.label == "Rainbow kitty underline"),
        "picker rows: {:?}",
        picker
            .options
            .iter()
            .map(|option| option.label.clone())
            .collect::<Vec<_>>()
    );
}

/// EVERY SOUND-MENU KEY IS READ AT ITS CONSUMER — the pin that stops this
/// panel from shipping a switch that does nothing.
///
/// A row here is a PROMISE: flip it and the machine sounds different. The
/// registry, the schema, the disclosure and the Advanced allowlist can all
/// be satisfied by a key nothing reads, so the only thing that makes the
/// promise true is an accessor call at the emission site. That is a
/// CROSS-FILE property — `app_render.rs` emits the synth voices,
/// `lib.rs::on_bell` emits the OS alert sound — so it is pinned here by
/// reading those sources, alongside the behavioural tests that prove each
/// gate's semantics (`app_render::sing_riff_gain_tests`,
/// `lib::…::a_silenced_bell_never_consumes_the_audible_rate_limit_lane`).
///
/// This replaces an earlier INVERTED handoff pin that asserted the
/// consumers did NOT read the two newest keys. It passed for exactly as
/// long as the switches were inert, which is the failure mode this test now
/// exists to catch.
///
/// NON-VACUOUS: it asserts its own preconditions first — the rows are
/// Advanced-visible, the sources are non-empty, and each emission site it
/// scans for is still present — so it cannot rot into a pass by matching a
/// renamed or emptied file.
#[test]
fn sound_menu_keys_are_read_at_their_consumers() {
    let render = include_str!("app_render.rs");
    let host = include_str!("lib.rs");
    let input = include_str!("app_input.rs");
    let presence = include_str!("app_presence.rs");

    // Precondition: the sources really loaded. An `include_str!` of a
    // renamed file would not compile, but an emptied one would make every
    // `contains` below fail loudly rather than pass — assert anyway so the
    // failure names the cause.
    assert!(
        render.len() > 100_000 && host.len() > 100_000 && input.len() > 10_000,
        "the consumer sources look truncated; the scans below are meaningless"
    );

    // Precondition: the rows really are on the audited Advanced surface, so
    // a missing gate would be a visible lie rather than a dormant key.
    assert!(
        settings_field_is_visible(prefs::EDIT_TRAIL_SOUND_RIFF, false, false),
        "the riff row is on the Advanced surface"
    );
    assert_eq!(
        settings_field_is_visible(prefs::EDIT_BELL_SOUND, false, false),
        cfg!(any(target_os = "macos", windows)),
        "the bell row is on the Advanced surface exactly where a beep exists"
    );

    // Precondition: the emission sites these scans are about still exist.
    assert!(
        render.contains("fn sing_riff_event("),
        "the sing-along riff event constructor moved; re-locate its gate"
    );
    assert_eq!(
        render
            .matches("self.trail_audio.push(sing_riff_event(")
            .count(),
        // Count emission sites, not the definition or the outro's reuse
        // of the pure event constructor. Both render paths read the gate.
        2,
        "the riff is pushed from exactly the two known render paths"
    );
    // W13: the macOS site was `objc2_app_kit::NSBeep()` and is now
    // `appkit::beep()` — the first-party binding of the SAME AppKit
    // function. The scan is for the CALL, not for the crate that used to
    // provide it, so it survives the next rename of the provider and would
    // still fail if the emission itself were removed.
    assert!(
        host.contains("crate::appkit::beep()") && host.contains("win32::beep()"),
        "the audible bel emission sites moved; re-locate their gate"
    );

    // THE WIRING ITSELF. Each Sound-menu key names the accessor its
    // consumer must call and the source that must call it.
    for (key, accessor, consumers) in [
        (
            prefs::EDIT_TRAIL_SOUNDS,
            "trail_sounds_or_default",
            &[render][..],
        ),
        (
            prefs::EDIT_TRAIL_SOUND_VOLUME,
            "trail_sound_volume()",
            &[render][..],
        ),
        (
            prefs::EDIT_TRAIL_SOUND_STYLE,
            "trail_sound_voice()",
            &[render][..],
        ),
        (
            prefs::EDIT_TONE_MELODY,
            "tone_melody_or_default",
            &[render, input][..],
        ),
        (
            prefs::EDIT_TRAIL_SOUND_BED,
            "trail_sound_bed_or_default",
            &[render][..],
        ),
        // The two keys the inverted pin used to certify as UNWIRED.
        (
            prefs::EDIT_TRAIL_SOUND_RIFF,
            "trail_sound_riff_or_default",
            &[render][..],
        ),
        (prefs::EDIT_BELL_SOUND, "bell_sound_or_default", &[host][..]),
        // The supervisor's choice chime (`App::chose_chime`).
        (
            prefs::EDIT_CHOICE_SOUND,
            "choice_sound_or_default",
            &[presence][..],
        ),
        // The two BONK keys are `[sparkle_words]` leaves in the FILE but
        // SFX in the UI; their accessors are named after the feature, not
        // the key path.
        (
            prefs::EDIT_SPARKLE_BONK,
            "curse_bonk_enabled()",
            &[render][..],
        ),
        (
            prefs::EDIT_SPARKLE_BONK_DETONATION,
            "curse_bonk_detonation_enabled()",
            &[render][..],
        ),
    ] {
        assert!(
            prefs::SOUND_MENU_KEYS.contains(&key),
            "{key} is pinned here but is not on the Sound menu"
        );
        assert!(
            consumers.iter().any(|src| src.contains(accessor)),
            "{key} is a Sound-menu row whose consumer never reads \
             `{accessor}` — the switch would do nothing"
        );
    }

    // BOTH riff seams, not just one: a split pane must not sing a song a
    // single pane suppresses. Both go through the one policy author,
    // identified by the argument only a real render seam can pass — the
    // window's RAW focus bit. Counting bare `sing_riff_gain(` instead would
    // also count the function's own definition and its unit tests, which is
    // a pin on this file's test layout rather than on the wiring.
    let production_calls = render
        .match_indices("sing_riff_gain(")
        .filter(|(at, needle)| {
            render[at + needle.len()..]
                .trim_start()
                .starts_with("ws.focused")
        })
        .count();
    // Each render path gates both its bar riff and its new outro through
    // the same focus/master/riff/volume policy. Check all four decisions
    // and both outro emissions, in addition to the two bar pushes above.
    assert_eq!(
        production_calls, 4,
        "both bar and outro pushes must resolve gain through the one policy function"
    );
    assert_eq!(
        render
            .matches("self.trail_audio.push(sing_outro_event(")
            .count(),
        2,
        "both render paths emit their gated outro"
    );

    // BOTH BONK SEAMS MUST FEED THE MASTER IN. This is a LAYOUT pin and it
    // is deliberately not the proof: the law lives in
    // `app_render::curse_bonk_drain_tests::music_effects_off_*`.
    // The SINGLE-PANE seam lives inside `redraw_window`, which needs a real
    // present target and has no headless entry point, so this is what
    // stands between it and silently regressing to the state the skeptic
    // found on 2026-08-09 — a bonk that ignored the switch the Sound menu
    // names as its master. Identified, like the riff pin above, by the
    // argument only a real render seam passes.
    let bonk_calls: Vec<&str> = render
        .match_indices("bonk_sound_gain(")
        .map(|(at, needle)| &render[at + needle.len()..])
        .filter(|rest| rest.trim_start().starts_with("ws.focused"))
        .collect();
    assert_eq!(
        bonk_calls.len(),
        2,
        "both bonk drains must resolve gain through the one policy function"
    );
    for rest in bonk_calls {
        let head = &rest[..rest.len().min(600)];
        assert!(
            head.contains("bonk_master"),
            "a bonk render seam resolves gain without the Music-effects \
             master: {head:?}"
        );
    }

    // The audible bell's rate limiter ends the BEL's gate chain below. That
    // its key is read BEFORE the limiter spends a token is behavioural:
    // `a_silenced_bell_never_consumes_the_audible_rate_limit_lane`, and for
    // the choice chime `app_presence`'s
    // `a_muted_choice_chime_does_not_spend_its_rate_limit`.
    let fire = host
        .find("self.bell_beep.try_fire(now)")
        .expect("the audible bell's rate limiter moved; re-locate the gate");

    // THE TWO PATHS ARE INDEPENDENT — the fact the "Sound" footnote states.
    // The BEL's whole gate chain runs from `fn on_bell(` to the limiter, and
    // it must not contain the synth master or the synth volume: they are
    // cue-borne trail-audio keys and the bell is an OS alert sound. If that
    // ever changes, the footnote (and the bell row's disclosure, which
    // deliberately carries no "Music effects Off" note) becomes a lie.
    let on_bell = host.find("fn on_bell(").expect("the BEL handler moved");
    let chain = &host[on_bell..fire];
    assert!(
        !chain.contains("trail_sounds_or_default") && !chain.contains("trail_sound_volume"),
        "the OS alert sound must stay independent of the synth master and volume"
    );
}

#[test]
fn visual_forms_hide_inert_and_compatibility_only_effect_controls() {
    for key in [
        "matrix_rain.materialize",
        "matrix_rain.ink_text",
        "matrix_rain.phosphor",
        SPARKLE_MASTER_KEY,
    ] {
        assert!(!settings_field_is_visible(key, false, false), "{key}");
        assert!(!settings_field_is_visible(key, false, true), "{key}");
    }
    assert!(settings_field_is_visible(SPARKLE_WORDS_KEY, true, false));
    assert!(!settings_field_is_visible(prefs::EDIT_THEME, false, false));
    assert!(settings_field_is_visible(prefs::EDIT_THEME, true, false));
    for macos_only in [
        prefs::EDIT_FONT_THICKEN,
        prefs::EDIT_BACKGROUND_OPACITY,
        prefs::EDIT_SECURE_KEYBOARD_ENTRY,
    ] {
        assert_eq!(
            settings_field_is_visible(macos_only, false, false),
            cfg!(target_os = "macos"),
            "{macos_only} belongs in ordinary Advanced only where it has a live consumer"
        );
        assert!(
            settings_field_is_visible(macos_only, true, false),
            "Modified preserves authored cross-platform configuration"
        );
    }
    assert!(
        settings_field_is_visible(prefs::EDIT_ALLOW_OSC52_QUERY, false, false),
        "OSC 52 query has a live host: the GUI clipboard callback answers \
         authorized queries, so the switch is an ordinary security policy"
    );
    assert!(
        settings_field_is_visible(prefs::EDIT_ALLOW_OSC52_QUERY, true, false),
        "Modified still lists the authored value"
    );
    assert!(
        settings_field_is_visible(prefs::EDIT_CONFIRM_MULTILINE_PASTE, false, false),
        "the pastejacking confirm has a live host on every platform now \
         (macOS sheet / Windows dialog / Linux in-window banner)"
    );
    {
        let (key, supported) = (
            prefs::EDIT_ALLOW_NOTIFICATIONS,
            crate::notify::delivery_available(),
        );
        assert_eq!(
            settings_field_is_visible(key, false, false),
            supported,
            "{key} belongs in ordinary Advanced only with a real platform host"
        );
        assert_eq!(settings_field_is_visible(key, false, true), supported);
        assert!(
            settings_field_is_visible(key, true, false),
            "Modified preserves authored cross-platform configuration"
        );
    }

    for key in [
        prefs::EDIT_SHELL,
        "net.listen",
        "update.owner",
        "matrix_rain.fps",
        prefs::EDIT_CURSOR_TRAIL_BLOOM_STRENGTH,
        prefs::EDIT_SHOW_BUILD_BADGE,
        prefs::EDIT_COLUMNS,
        prefs::EDIT_LINES,
        prefs::EDIT_GPU,
    ] {
        assert!(!settings_field_is_visible(key, false, false), "{key}");
        assert!(!settings_field_is_visible(key, false, true), "{key}");
        assert!(
            settings_field_is_visible(key, true, false),
            "Modified retains explicit Manual-only key {key}"
        );
    }
    for key in [prefs::EDIT_SHELL_ARGS, prefs::EDIT_FONT_VARIATION] {
        assert!(prefs::manual_collection_key(key), "{key}");
        assert!(
            !settings_field_is_visible(key, true, false),
            "lossless collection {key} stays in Manual instead of a scalar row"
        );
    }
    assert!(prefs::config_asset_source_key(
        prefs::EDIT_CURSOR_NYAN_SPRITE
    ));
    assert!(prefs::manual_only_key(prefs::EDIT_CURSOR_NYAN_SPRITE));
    assert!(
        !settings_field_is_visible(prefs::EDIT_CURSOR_NYAN_SPRITE, true, true),
        "host-backed sprite source is edited through Manual's worker-validated path"
    );

    let fields = prefs::editable_fields(&Config::default());
    let ordinary_advanced_field = |field: &EditField| {
        settings_field_is_visible(field.key, false, false)
            && SettingsRoute::ALL
                .into_iter()
                .filter_map(SettingsRoute::section)
                .any(|section| section == prefs::section_of(field.key))
    };
    let ordinary_groups = fields
        .iter()
        .filter(|field| ordinary_advanced_field(field))
        .map(|field| prefs::group_of(field.key).0)
        .collect::<BTreeSet<_>>();
    let mut group_witnesses = vec![
        ("Colors", prefs::EDIT_FOREGROUND),
        ("Text & Contrast", prefs::EDIT_MINIMUM_CONTRAST),
        ("Font", prefs::EDIT_FONT_FAMILY),
        ("Shaping", prefs::EDIT_LIGATURES),
        ("Line layout", prefs::EDIT_LINE_HEIGHT),
        ("Rendering", prefs::EDIT_FONT_WEIGHT),
        ("Cursor", prefs::EDIT_CURSOR_STYLE),
        ("Motion", prefs::EDIT_MOTION),
        ("Stream fade", prefs::EDIT_STREAM_FADE),
        ("Matrix rain", prefs::EDIT_MATRIX_RAIN_ENABLED),
        ("Window padding", prefs::EDIT_WINDOW_PADDING),
        ("Session", prefs::EDIT_RESTORE_SESSION),
        ("Clipboard", prefs::EDIT_COPY_ON_SELECT),
        ("Keyboard", prefs::EDIT_PREDICTIVE_ECHO),
        ("Scrollback", prefs::EDIT_SCROLLBACK),
        ("Text direction & width", prefs::EDIT_BIDI),
        ("Permissions", prefs::EDIT_ALLOW_WINDOW_OPS),
        // 2026-07-24 UX audit: exposing `cursor_trail_intensity` (plus the
        // two trail-sound keys) surfaced the "Trail effect" caption, which
        // needs its own curated witness like every other group.
        ("Trail effect", prefs::EDIT_CURSOR_TRAIL_INTENSITY),
        // The Sound menu's curated witness is the master VOLUME slider —
        // the one control the owner named first, and the only one every
        // other row in the box is scaled by.
        ("Sound", prefs::EDIT_TRAIL_SOUND_VOLUME),
        // The Cursor Kitty page contributes NO ordinary group box. Its
        // "Companion" caption belongs to `cursor_trail_style`, a Top
        // Setting the ordinary form never draws — the showcase card owns
        // that row — and its one real box, "Rainbow wake", went with the
        // retired dial (2026-09-16).
    ];
    if cfg!(target_os = "macos") {
        group_witnesses.push(("Transparency", prefs::EDIT_BACKGROUND_OPACITY));
        // The Security page's second box: the [machine] host settings the
        // "This Mac" card confirms.
        group_witnesses.push(("This Mac", prefs::EDIT_MACHINE_SPOTLIGHT_NOINDEX));
    }
    group_witnesses.push(("Paste safety", prefs::EDIT_CONFIRM_MULTILINE_PASTE));
    // The Security page's "Notifications" box (`desktop_alerts`): a row only
    // where a desktop notifier exists.
    if crate::notify::delivery_available() {
        group_witnesses.push(("Notifications", prefs::EDIT_DESKTOP_ALERTS));
    }
    assert_eq!(
        ordinary_groups,
        group_witnesses
            .iter()
            .map(|(group, _)| *group)
            .collect::<BTreeSet<_>>(),
        "every Advanced caption needs a retained, curated member",
    );
    for (group, key) in &group_witnesses {
        assert!(
            settings_field_is_visible(key, false, false),
            "{group}: {key}"
        );
        assert_eq!(prefs::group_of(key).0, *group, "{group}: {key}");
    }
    for (group, relevant_copy) in [
        ("Text & Contrast", "contrast"),
        ("Transparency", "opacity"),
        ("Rendering", "weight"),
        ("Motion", "motion"),
        ("Stream fade", "fades"),
        ("Matrix rain", "Rain"),
        ("Window padding", "padding"),
        ("Paste safety", "paste"),
        ("Keyboard", "Predictive echo"),
        ("Scrollback", "Searchable scrollback lines"),
        ("Text direction & width", "right-to-left"),
        ("Permissions", "refuses the program"),
        // Off loses nothing: the note says where the alerts still go.
        ("Notifications", "menu bar"),
        // The This Mac box must say the second way its rows apply — the
        // card's own button — and how each change is undone.
        ("This Mac", "Apply now"),
        // The Sound box's footnote must name what the VOLUME slider does
        // and does not reach — the reason the bell needed its own row.
        ("Sound", "Volume"),
    ] {
        if ordinary_groups.contains(group) {
            let note = prefs::group_footnote(group)
                .unwrap_or_else(|| panic!("{group} needs consequence copy"));
            assert!(
                note.to_lowercase().contains(&relevant_copy.to_lowercase()),
                "{group} copy does not describe its retained control: {note}",
            );
        }
    }
    assert!(
        prefs::group_footnote("Clipboard").is_none(),
        "copy-on-select must not inherit Manual-only paste-safety copy",
    );
    for field in fields.iter().filter(|field| ordinary_advanced_field(field)) {
        assert!(
            native_advanced_effect(field.key).is_some(),
            "Advanced row {} has no audited shipping consumer",
            field.key
        );
    }
    for restart_only in [prefs::EDIT_COLUMNS, prefs::EDIT_LINES, prefs::EDIT_GPU] {
        assert_eq!(
            native_advanced_effect(restart_only),
            None,
            "restart-only {restart_only} must stay in Manual/Modified"
        );
    }
    for route in SettingsRoute::ALL {
        let Some(section) = route.section() else {
            continue;
        };
        let has_ordinary_row = fields.iter().any(|field| {
            prefs::section_of(field.key) == section
                && settings_field_is_visible(field.key, false, false)
        });
        if !has_ordinary_row {
            // AN EMPTY DESTINATION IS THE DEFECT; A ROWLESS ONE IS NOT THE
            // SAME THING. This asked "does the route own a visible ordinary
            // field" as a proxy for "does the route show the user
            // anything", and the proxy held only while every destination
            // was built out of registry rows. Cursor Kitty is not: its
            // content is the companion showcase card (`cursor_kitty_card`,
            // which "can never be shed outright"), and its two filed keys
            // are a Top Setting and a Manual-only asset path. The proxy
            // also passed this page for six weeks while its one row was
            // `cursor_trail_wake_ms`, a dial nothing read — so it was
            // admitting an empty page and is now about to refuse a full
            // one. The exception is therefore enumerated, not widened, and
            // the card itself is pinned by
            // `the_cursor_kitty_page_is_its_showcase_card`.
            assert_eq!(
                route,
                SettingsRoute::CursorKitty,
                "{} must not be an empty Advanced destination",
                route.label()
            );
        }
    }

    let predictive = fields
        .iter()
        .find(|field| field.key == prefs::EDIT_PREDICTIVE_ECHO)
        .unwrap();
    let choices =
        choices_for_field(predictive, &[], &crate::app_config::ThemeCatalog::default()).unwrap();
    assert_eq!(choices, ["off", "adaptive"]);
}

#[test]
fn restart_only_overrides_disclose_timing_in_rows_and_apply_feedback() {
    let snapshot =
        VersionedConfigService::new("columns = 96\nlines = 30\ngpu = false\n".to_string())
            .unwrap()
            .snapshot();
    let state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    for key in [prefs::EDIT_COLUMNS, prefs::EDIT_LINES, prefs::EDIT_GPU] {
        let expected_timing = if key == prefs::EDIT_GPU {
            "Applies next launch"
        } else {
            "Applies next launch; an update keeps the current size"
        };
        let (index, field) = state
            .legacy
            .fields
            .iter()
            .enumerate()
            .find(|(_, field)| field.key == key)
            .unwrap();
        let compiled = UiTree::new(setting_row(
            &state,
            index,
            field,
            true,
            false,
            SettingsWidth::Wide,
        ))
        .compile(LogicalRect::new(0.0, 0.0, 720.0, 80.0))
        .unwrap();
        assert!(
            compiled
                .semantic(&UiKey::new(format!("settings/label/{key}")))
                .unwrap()
                .label
                .contains(expected_timing),
            "Modified visibly discloses timing for {key}"
        );
        assert!(
            compiled
                .semantic(&UiKey::new(format!("settings/control/{key}")))
                .unwrap()
                .label
                .contains(expected_timing),
            "the native control name discloses timing for {key}"
        );
    }

    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(snapshot))
        .unwrap();
    let requested = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_GPU)),
                value: Some(SemanticInput::Bool(true)),
            }),
        )
        .unwrap();
    let operation = requested
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { reply, .. } => Some(reply.operation),
            _ => None,
        })
        .expect("restart-only edit reaches the shared config service");
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ConfigPatchFinished {
                operation,
                outcome: ConfigPatchOutcome::Applied {
                    revision: 2,
                    undo: Some(7),
                },
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    assert_eq!(
        state.feedback.as_deref(),
        Some("Saved · Applies next launch · Undo available")
    );
}

#[test]
fn ambiguous_width_discloses_preserved_cells_but_feedback_remains_applied() {
    let snapshot = VersionedConfigService::new(String::new())
        .unwrap()
        .snapshot();
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(snapshot))
        .unwrap();
    let requested = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_AMBIGUOUS_WIDTH)),
                value: Some(SemanticInput::Text("wide".to_string())),
            }),
        )
        .unwrap();
    let operation = requested
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { reply, .. } => Some(reply.operation),
            _ => None,
        })
        .expect("width edit reaches the shared config service");
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ConfigPatchFinished {
                operation,
                outcome: ConfigPatchOutcome::Applied {
                    revision: 2,
                    undo: Some(8),
                },
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    assert_eq!(
        state.feedback.as_deref(),
        Some(
            "Applied · Applies to newly received text; existing cells keep their current width · Undo available"
        )
    );

    let (index, field) = state
        .legacy
        .fields
        .iter()
        .enumerate()
        .find(|(_, field)| field.key == prefs::EDIT_AMBIGUOUS_WIDTH)
        .unwrap();
    let compiled = UiTree::new(setting_row(
        state,
        index,
        field,
        false,
        false,
        SettingsWidth::Wide,
    ))
    .compile(LogicalRect::new(0.0, 0.0, 900.0, 90.0))
    .unwrap();
    let timing = prefs::application_timing(prefs::EDIT_AMBIGUOUS_WIDTH).unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new(format!(
                "settings/label/{}",
                prefs::EDIT_AMBIGUOUS_WIDTH
            )))
            .unwrap()
            .label
            .contains(timing)
    );
}

#[test]
fn configured_draft_and_pinned_font_sizes_reach_paint_at_physical_size() {
    for physical_px in [6.0, 36.0, 200.0] {
        for scale in [1.0, 1.25, 2.0, 3.0] {
            for source in ["configured", "draft", "environment"] {
                let mut state = SettingsViewState::new(&Config {
                    font_px: Some(if source == "configured" {
                        physical_px
                    } else {
                        14.0
                    }),
                    ..Config::default()
                });
                if source == "draft" {
                    state.field_inputs.insert(
                        prefs::EDIT_FONT_PX.to_string(),
                        crate::native_text_input::TextInputState::new(physical_px.to_string()),
                    );
                } else if source == "environment" {
                    state.environment_overrides.insert(
                        prefs::EDIT_FONT_PX.to_string(),
                        crate::app_config::ActiveEnvironmentOverride {
                            variable: "--font-px",
                            effective: physical_px.to_string(),
                        },
                    );
                }
                let spec = renderer_preview_spec_for_key_with_font(
                    &state,
                    prefs::EDIT_FONT_PX,
                    0,
                    crate::native_app::ViewMotionCx::default(),
                    24.0,
                    scale,
                    aterm_render::Theme::default(),
                    None,
                )
                .unwrap();
                assert_eq!(spec.font_px, physical_px / scale);
                let height = spec.preferred_height(108.0).min(600.0);
                let compiled = UiTree::new(crate::settings_preview::preview_node(
                    "physical-font-preview",
                    spec,
                    height,
                ))
                .compile(LogicalRect::new(0.0, 0.0, 900.0, 700.0))
                .unwrap();
                let painted_px = compiled
                    .tray(aterm_render::Theme::default(), 13.0)
                    .prims
                    .into_iter()
                    .find_map(|prim| match prim {
                        crate::widget::DrawPrim::TerminalSpecimen { spec, .. } => {
                            Some(spec.font_px * scale)
                        }
                        _ => None,
                    })
                    .expect("one complete specimen row reaches paint");
                assert!(
                    (painted_px - physical_px).abs() < 0.001,
                    "{source} {physical_px}px at {scale}x painted {painted_px}px"
                );
            }
        }
    }
}

#[test]
fn active_environment_override_drives_row_preview_and_save_feedback() {
    let snapshot = VersionedConfigService::new("font_px = 18\n".to_string())
        .unwrap()
        .snapshot();
    let mut state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    state.environment_overrides.insert(
        prefs::EDIT_FONT_PX.to_string(),
        crate::app_config::ActiveEnvironmentOverride {
            variable: "--font-px",
            effective: "22".to_string(),
        },
    );
    let (index, field) = state
        .legacy
        .fields
        .iter()
        .enumerate()
        .find(|(_, field)| field.key == prefs::EDIT_FONT_PX)
        .unwrap();
    let compiled = UiTree::new(setting_row(
        &state,
        index,
        field,
        false,
        false,
        SettingsWidth::Wide,
    ))
    .compile(LogicalRect::new(0.0, 0.0, 900.0, 90.0))
    .unwrap();
    let control = compiled
        .semantic(&UiKey::new(format!(
            "settings/control/{}",
            prefs::EDIT_FONT_PX
        )))
        .unwrap();
    assert!(control.label.contains("overridden by --font-px"));
    assert!(control.label.contains("effective 22"));
    let preview = renderer_preview_spec_for_key_with_font(
        &state,
        prefs::EDIT_FONT_PX,
        0,
        crate::native_app::ViewMotionCx::default(),
        12.0,
        1.0,
        aterm_render::Theme::default(),
        None,
    )
    .unwrap();
    assert_eq!(preview.font_px, 22.0);

    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(snapshot))
        .unwrap();
    let Some(AppViewState::Settings(runtime_state)) = runtime.view_state_mut(view) else {
        unreachable!()
    };
    runtime_state.environment_overrides.insert(
        prefs::EDIT_FONT_PX.to_string(),
        crate::app_config::ActiveEnvironmentOverride {
            variable: "--font-px",
            effective: "22".to_string(),
        },
    );
    let requested = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_FONT_PX)),
                value: Some(SemanticInput::Text("19".to_string())),
            }),
        )
        .unwrap();
    let operation = requested
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { reply, .. } => Some(reply.operation),
            _ => None,
        })
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ConfigPatchFinished {
                operation,
                outcome: ConfigPatchOutcome::Applied {
                    revision: 2,
                    undo: None,
                },
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(runtime_state)) = runtime.view_state(view) else {
        unreachable!()
    };
    assert_eq!(
        runtime_state.feedback.as_deref(),
        Some("Saved · --font-px remains active (effective 22)")
    );
}

#[test]
fn modified_manual_override_discloses_lifecycle_and_precedence() {
    let snapshot =
        VersionedConfigService::new("[packages]\naccount = \"alabsystems\"\n".to_string())
            .unwrap()
            .snapshot();
    let mut state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    state.environment_overrides.insert(
        "packages.account".to_string(),
        crate::app_config::ActiveEnvironmentOverride {
            // A fixture label: no `[packages]` key has a real environment
            // override (2026-09-23); the disclosure's rendering is the subject.
            variable: "$ATERM_FIXTURE_OVERRIDE",
            effective: "machine-owner".to_string(),
        },
    );
    let authored = authored_manual_overrides(&state)
        .into_iter()
        .find(|entry| entry.key == "packages.account")
        .expect("packages.account is a Manual-only override");
    let compiled = UiTree::new(manual_override_node(
        &state,
        &authored,
        0,
        1,
        SettingsWidth::Wide,
    ))
    .compile(LogicalRect::new(0.0, 0.0, 900.0, 220.0))
    .unwrap();
    let disclosure = compiled
        .semantic(&UiKey::new("settings/modified/manual/detail"))
        .unwrap();
    assert!(disclosure.label.contains("next package check"));
    assert!(
        disclosure
            .label
            .contains("$ATERM_FIXTURE_OVERRIDE remains active")
    );
    assert!(disclosure.label.contains("effective machine-owner"));
    let visual_lines = compiled
        .paint
        .iter()
        .filter(|node| {
            node.key
                .as_str()
                .starts_with("settings/modified/manual/detail/line-")
        })
        .collect::<Vec<_>>();
    assert!(!visual_lines.is_empty());
    assert!(visual_lines.iter().all(|line| {
        compiled.semantic(&line.key).is_none() && matches!(&line.content, UiContent::Text(_))
    }));
}

#[test]
fn appearance_preview_uses_the_live_renderer_contrast_floor() {
    for (opacity, configured) in [(1.0, 1.0), (1.0, 7.0), (0.5, 1.0), (0.5, 7.0)] {
        let config = Config {
            background_opacity: Some(opacity),
            minimum_contrast: Some(configured),
            ..Config::default()
        };
        let state = SettingsViewState::new(&config);
        let preview = renderer_preview_spec_for_key_with_font(
            &state,
            prefs::EDIT_MINIMUM_CONTRAST,
            0,
            crate::native_app::ViewMotionCx::default(),
            13.0,
            1.0,
            aterm_render::Theme::default(),
            None,
        )
        .unwrap();
        assert_eq!(
            preview.appearance.minimum_contrast,
            config.effective_minimum_contrast(),
            "opacity={opacity}, configured={configured}"
        );
    }
    for group in ["Text & Contrast", "Transparency"] {
        let footnote = prefs::group_footnote(group).unwrap();
        assert!(
            footnote
                .to_ascii_lowercase()
                .contains("translucent background")
                && footnote.contains("at least")
                && footnote.contains("4.5:1"),
            "{group} explains the effective glass floor"
        );
    }
}

#[test]
fn minimum_contrast_row_and_feedback_disclose_the_translucent_floor() {
    let glass: Config =
        aterm_toml::from_str("minimum_contrast = 1.0\nbackground_opacity = 0.7\n").unwrap();
    let state = SettingsViewState::new(&glass);
    assert_eq!(constrained_minimum_contrast(&state), Some((1.0, 4.5)));
    let (index, field) = state
        .legacy
        .fields
        .iter()
        .enumerate()
        .find(|(_, field)| field.key == prefs::EDIT_MINIMUM_CONTRAST)
        .unwrap();
    let compiled = UiTree::new(setting_row(
        &state,
        index,
        field,
        false,
        false,
        SettingsWidth::Wide,
    ))
    .compile(LogicalRect::new(0.0, 0.0, 1_000.0, 90.0))
    .unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new(format!(
                "settings/control/{}",
                prefs::EDIT_MINIMUM_CONTRAST
            )))
            .unwrap()
            .label
            .contains(
                "configured 1:1; effective 4.5:1 because translucent backgrounds enforce the accessibility floor",
            )
    );
    assert!(
        compiled
            .semantic(&UiKey::new(format!(
                "settings/label/{}",
                prefs::EDIT_MINIMUM_CONTRAST
            )))
            .unwrap()
            .label
            .contains("Effective 4.5:1 · Translucent floor")
    );

    for (source, expected) in [
        ("minimum_contrast = 4.5\nbackground_opacity = 0.7\n", None),
        ("minimum_contrast = 7.0\nbackground_opacity = 0.7\n", None),
        ("minimum_contrast = 1.0\nbackground_opacity = 1.0\n", None),
    ] {
        let config: Config = aterm_toml::from_str(source).unwrap();
        assert_eq!(
            constrained_minimum_contrast(&SettingsViewState::new(&config)),
            expected,
            "{source}"
        );
    }

    let mut drafts = SettingsViewState::new(&Config::default());
    drafts.field_inputs.insert(
        prefs::EDIT_BACKGROUND_OPACITY.to_string(),
        crate::native_text_input::TextInputState::new("0.6".to_string()),
    );
    assert_eq!(constrained_minimum_contrast(&drafts), Some((1.0, 4.5)));
    drafts.field_inputs.insert(
        prefs::EDIT_MINIMUM_CONTRAST.to_string(),
        crate::native_text_input::TextInputState::new("5".to_string()),
    );
    assert_eq!(constrained_minimum_contrast(&drafts), None);

    let opaque = SettingsViewState::new(&Config::default());
    let patch = |edits: &[(&str, &str)]| ConfigPatch {
        base_revision: 1,
        edits: edits
            .iter()
            .map(|(key, value)| ConfigEdit {
                key: (*key).to_string(),
                expected: ExpectedConfigValue::Any,
                value: Some((*value).to_string()),
            })
            .collect(),
    };
    assert_eq!(
        post_patch_minimum_contrast_constraint(
            &opaque,
            &patch(&[(prefs::EDIT_BACKGROUND_OPACITY, "0.5")])
        ),
        Some((1.0, 4.5))
    );
    assert_eq!(
        post_patch_minimum_contrast_constraint(
            &opaque,
            &patch(&[
                (prefs::EDIT_BACKGROUND_OPACITY, "0.5"),
                (prefs::EDIT_MINIMUM_CONTRAST, "4.5"),
            ])
        ),
        None,
        "the threshold itself is not raised"
    );
    assert_eq!(
        post_patch_minimum_contrast_constraint(
            &opaque,
            &patch(&[
                (prefs::EDIT_BACKGROUND_OPACITY, "0.5"),
                (prefs::EDIT_MINIMUM_CONTRAST, "2"),
                (prefs::EDIT_COPY_ON_SELECT, "true"),
            ])
        ),
        Some((2.0, 4.5)),
        "mixed patches use the complete post-commit pair"
    );

    let snapshot = VersionedConfigService::new(
        "minimum_contrast = 1.0\nbackground_opacity = 1.0\n".to_string(),
    )
    .unwrap()
    .snapshot();
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(snapshot))
        .unwrap();
    let requested = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_BACKGROUND_OPACITY)),
                value: Some(SemanticInput::Number(0.5)),
            }),
        )
        .unwrap();
    let operation = requested
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { reply, .. } => Some(reply.operation),
            _ => None,
        })
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ConfigPatchFinished {
                operation,
                outcome: ConfigPatchOutcome::Applied {
                    revision: 2,
                    undo: None,
                },
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!()
    };
    assert!(state.feedback.as_deref().unwrap().contains(
        "Effective minimum contrast is 4.5:1 (configured 1:1; translucent background floor)"
    ));
}

#[test]
fn background_opacity_discloses_exact_platform_and_backend_availability() {
    let state = SettingsViewState::new(&Config::default());
    let project = |gpu| {
        setting_effect_projection(
            &state,
            None,
            prefs::EDIT_BACKGROUND_OPACITY,
            SettingsAvailability::runtime(gpu),
            crate::native_app::ViewMotionCx::default(),
        )
    };
    let cpu = project(false);
    assert!(!cpu.has_live_effect);
    assert!(
        cpu.notes
            .iter()
            .any(|note| note.semantic.contains(if cfg!(target_os = "macos") {
                "CPU renderer has an opaque present path"
            } else {
                "this platform keeps the grid solid"
            }))
    );
    let gpu = project(true);
    if cfg!(target_os = "macos") {
        assert!(gpu.has_live_effect, "macOS GPU applies window opacity");
        assert!(gpu.notes.is_empty());
    } else {
        assert!(
            gpu.notes
                .iter()
                .any(|note| note.semantic.contains("macOS GPU windows")),
            "non-macOS GPU renderers keep the grid opaque"
        );
    }
    assert!(
        setting_effect_projection(
            &state,
            None,
            prefs::EDIT_MINIMUM_CONTRAST,
            SettingsAvailability::runtime(false),
            crate::native_app::ViewMotionCx::default(),
        )
        .notes
        .is_empty()
    );
    let note = prefs::group_footnote("Transparency").unwrap();
    assert!(note.contains("macOS GPU"));
    assert!(note.contains("solid"));
}

#[test]
fn unavailable_runtime_controls_stay_truthful_in_modified() {
    let state = SettingsViewState::new(&Config::default());
    let unavailable = |key| {
        setting_effect_projection(
            &state,
            None,
            key,
            SettingsAvailability::runtime(true),
            crate::native_app::ViewMotionCx::default(),
        )
        .notes
        .iter()
        .any(|note| note.kind == EffectNoteKind::Unavailable)
    };
    // allow_osc52_query is a LIVE policy now (the GUI answers authorized
    // queries), so it must NOT read as unavailable anywhere.
    assert!(!unavailable(prefs::EDIT_ALLOW_OSC52_QUERY));
    assert_eq!(
        !unavailable(prefs::EDIT_SECURE_KEYBOARD_ENTRY),
        cfg!(target_os = "macos"),
        "Secure Keyboard Entry actuates on macOS only"
    );
    assert_eq!(
        !unavailable(prefs::EDIT_ALLOW_NOTIFICATIONS),
        crate::notify::delivery_available()
    );
    assert!(
        !unavailable(prefs::EDIT_CONFIRM_MULTILINE_PASTE),
        "the pastejacking confirm actuates on every platform now \
         (macOS sheet / Windows dialog / Linux in-window banner)"
    );
    assert_eq!(
        !unavailable(prefs::EDIT_TRAIL_SOUNDS),
        crate::trail_audio::output_available()
    );
}

/// PARITY, at the one surface that states availability in WORDS. A headless
/// launch keeps its GPU as an intent and runs the CPU renderer until
/// something demands a pixel. Sourcing these rows from the live renderer told
/// the user that HDR glow, cursor bloom, the P3 colour space and backdrop
/// materials are unavailable — about a device the same launch was always
/// entitled to build and would build on its first `image`. Settings reads the
/// CAPABILITY its host presented (`ViewMotionCx::backend_gpu`, which
/// `App::gpu_capable` answers for an unredeemed intent too — that half is
/// `the_settings_capability_read_follows_the_intent_the_app_holds`), and a run
/// that has SETTLED on the CPU renderer — `--cpu`, a windowed CPU launch, a
/// redemption that failed — still says so. The view reads no process global,
/// so nothing another test does can move either reading.
#[test]
fn a_deferred_gpu_intent_projects_the_same_availability_as_a_live_device() {
    let presented = |backend_gpu: bool| {
        let state = SettingsViewState::new(&Config::default());
        state.presented_motion.set(crate::native_app::ViewMotionCx {
            backend_gpu,
            ..crate::native_app::ViewMotionCx::default()
        });
        state
    };
    let (capable, settled) = (presented(true), presented(false));
    let effect = |availability| {
        projected_effect(
            "cursor_trail = true\ncursor_trail_style = \"fire\"\n",
            &[(prefs::EDIT_HDR_GLOW, "true")],
            prefs::EDIT_HDR_GLOW,
            availability,
            crate::native_app::ViewMotionCx::default(),
        )
    };
    let live_device = SettingsAvailability::for_state(&capable);
    let settled_cpu = SettingsAvailability::for_state(&settled);
    assert_eq!(live_device, SettingsAvailability::runtime(true));
    assert_ne!(
        settled_cpu, live_device,
        "the fixture must actually distinguish the two readings"
    );
    assert!(
        effect_note_contains(&effect(settled_cpu), "GPU renderer only"),
        "a run that has settled on the CPU renderer still discloses the denial"
    );
    assert!(
        !effect_note_contains(&effect(live_device), "GPU renderer only"),
        "a GPU-capable run never carries the denial"
    );

    // THE ROUTING, through a real call site rather than a restatement of it:
    // `manual_override_disclosure` is one of the `for_state` callers and returns
    // the sentence a user reads.
    let authored = ManualOverride {
        key: prefs::EDIT_HDR_GLOW.to_string(),
        label: "HDR glow".to_string(),
        preview: "true".to_string(),
        known: true,
        reset_safe: true,
    };
    let settled_disclosure = manual_override_disclosure(&settled, &authored, 0, 1);
    let capable_disclosure = manual_override_disclosure(&capable, &authored, 0, 1);
    assert!(
        settled_disclosure.contains("requires the GPU renderer"),
        "a settled CPU run still discloses the denial: {settled_disclosure}"
    );
    assert!(
        !capable_disclosure.contains("requires the GPU renderer"),
        "a GPU-capable run (an unredeemed intent included) is never denied: \
         {capable_disclosure}"
    );
}

#[test]
fn config_feedback_projection_distinguishes_unavailable_from_mixed_live_edits() {
    // HDR glow only has a live consumer while the trail is producing glow
    // quads, so the trail master is authored here rather than inherited from
    // a platform-split default — this test classifies edits as live vs
    // unavailable, and that classification must be exercised on every host.
    let state = SettingsViewState::new(&Config {
        cursor_trail: Some(true),
        ..Config::default()
    });
    let availability = SettingsAvailability {
        backend_gpu: false,
        macos: true,
        windows: false,
        notifications: true,
        trail_audio: false,
        packages: PackageAdmission::Ready,
    };
    let edit = |key: &str, value: &str| ConfigEdit {
        key: key.to_string(),
        expected: ExpectedConfigValue::Any,
        value: Some(value.to_string()),
    };
    for (key, value, note) in [
        (
            prefs::EDIT_BACKGROUND_OPACITY,
            "0.5",
            "GPU renderer only; current CPU renderer stays solid",
        ),
        (
            prefs::EDIT_TRAIL_SOUNDS,
            "true",
            "Audio unavailable on this platform; saved for portability",
        ),
        // (allow_osc52_query left this table when the GUI's clipboard
        // callback learned to answer authorized queries — it is a live
        // security policy now, covered by the SecurityPolicy arm.)
    ] {
        let projection = config_application_projection(
            &state,
            &ConfigPatch {
                base_revision: 1,
                edits: vec![edit(key, value)],
            },
            availability,
        );
        assert!(!projection.has_live_edit, "{key} is saved but inert here");
        assert!(projection.unavailable_notes.contains(note), "{key}");
    }

    let hdr = config_application_projection(
        &state,
        &ConfigPatch {
            base_revision: 1,
            edits: vec![edit(prefs::EDIT_HDR_GLOW, "false")],
        },
        SettingsAvailability {
            backend_gpu: true,
            ..availability
        },
    );
    assert!(
        hdr.has_live_edit,
        "disabling HDR glow gates the next present in an existing GPU window"
    );
    assert!(
        hdr.application_timings
            .contains("Disabling applies now; enabling may require a new window")
    );

    let mixed = config_application_projection(
        &state,
        &ConfigPatch {
            base_revision: 1,
            edits: vec![
                edit(prefs::EDIT_BACKGROUND_OPACITY, "0.5"),
                edit(prefs::EDIT_COPY_ON_SELECT, "true"),
            ],
        },
        availability,
    );
    assert!(
        mixed.has_live_edit,
        "one real live edit makes the patch Applied"
    );
    assert!(
        mixed
            .unavailable_notes
            .iter()
            .any(|note| note.contains("CPU renderer stays solid"))
    );
}

#[test]
fn config_feedback_projection_names_durable_effect_suppression() {
    let availability = SettingsAvailability {
        backend_gpu: true,
        macos: true,
        windows: false,
        notifications: true,
        trail_audio: true,
        packages: PackageAdmission::Ready,
    };
    let patch = |edits: &[(&str, &str)]| ConfigPatch {
        base_revision: 1,
        edits: edits
            .iter()
            .map(|(key, value)| ConfigEdit {
                key: (*key).to_string(),
                expected: ExpectedConfigValue::Any,
                value: Some((*value).to_string()),
            })
            .collect(),
    };

    for (source, key, reason) in [
        (
            "serious_mode = true\n",
            prefs::EDIT_STREAM_FADE,
            "Currently inactive: Serious Mode",
        ),
        (
            "motion = \"reduced\"\n",
            prefs::EDIT_STREAM_FADE,
            "Currently inactive: Motion Reduced",
        ),
        (
            "serious_mode = true\n",
            prefs::EDIT_MATRIX_RAIN_ENABLED,
            "Currently inactive: Serious Mode",
        ),
        (
            "motion = \"reduced\"\n",
            prefs::EDIT_MATRIX_RAIN_ENABLED,
            "Currently inactive: Motion Reduced",
        ),
    ] {
        let config: Config = aterm_toml::from_str(source).unwrap();
        let state = SettingsViewState::new(&config);
        let projection =
            config_application_projection(&state, &patch(&[(key, "true")]), availability);
        assert!(!projection.has_live_edit, "{source:?} {key}");
        assert!(projection.suppression_notes.contains(reason));
        if key == prefs::EDIT_MATRIX_RAIN_ENABLED {
            assert!(
                projection
                    .application_timings
                    .contains("Applies live unless this session has a View menu override")
            );
        }
    }

    let config: Config = aterm_toml::from_str("serious_mode = true\n").unwrap();
    let state = SettingsViewState::new(&config);
    let mixed = config_application_projection(
        &state,
        &patch(&[
            (prefs::EDIT_STREAM_FADE, "true"),
            (prefs::EDIT_COPY_ON_SELECT, "true"),
        ]),
        availability,
    );
    assert!(mixed.has_live_edit);
    assert!(
        mixed
            .suppression_notes
            .contains("Currently inactive: Serious Mode")
    );
}

#[test]
fn effect_projection_exhaustively_names_platform_backend_and_admission_gates() {
    let base = audited_availability();
    let cpu = SettingsAvailability {
        backend_gpu: false,
        ..base
    };
    let linux_gpu = SettingsAvailability {
        macos: false,
        windows: false,
        ..base
    };
    let windows_gpu = SettingsAvailability {
        macos: false,
        windows: true,
        ..base
    };
    let silent = SettingsAvailability {
        trail_audio: false,
        ..base
    };
    let cases = [
        ("", prefs::EDIT_FOCUS_BOOST, "true", base, "Windows only"),
        (
            "",
            prefs::EDIT_FONT_THICKEN,
            "true",
            windows_gpu,
            "macOS only",
        ),
        (
            "",
            prefs::EDIT_TRAIL_SOUND_VOLUME,
            "0.7",
            silent,
            "Audio unavailable",
        ),
        (
            "",
            prefs::EDIT_BACKGROUND_MATERIAL,
            "hud",
            linux_gpu,
            "No backdrop consumer",
        ),
        (
            "",
            prefs::EDIT_BACKGROUND_MATERIAL,
            "hud",
            cpu,
            "background material is inactive on CPU",
        ),
        (
            "background_opacity = 1.0\n",
            prefs::EDIT_BACKGROUND_MATERIAL,
            "hud",
            base,
            "background is opaque",
        ),
        (
            "",
            prefs::EDIT_WINDOW_COLORSPACE,
            "display-p3",
            cpu,
            "macOS GPU only",
        ),
        (
            "",
            prefs::EDIT_WINDOW_COLORSPACE,
            "display-p3",
            linux_gpu,
            "macOS GPU only",
        ),
        (
            "",
            prefs::EDIT_UPDATE_ENABLED,
            "true",
            windows_gpu,
            "updater unavailable on this platform",
        ),
        (
            "",
            "update.auto_apply",
            "false",
            windows_gpu,
            "updater unavailable on this platform",
        ),
    ];
    for (source, key, value, availability, expected) in cases {
        let effect = projected_effect(
            source,
            &[(key, value)],
            key,
            availability,
            crate::native_app::ViewMotionCx::default(),
        );
        assert!(!effect.has_live_effect, "{key}");
        assert!(effect_note_contains(&effect, expected), "{key}: {effect:?}");
    }

    #[cfg(target_os = "linux")]
    for (key, value) in [
        (prefs::EDIT_UPDATE_ENABLED, "false"),
        ("update.auto_apply", "false"),
    ] {
        let effect = projected_effect(
            "",
            &[(key, value)],
            key,
            linux_gpu,
            crate::native_app::ViewMotionCx::default(),
        );
        assert!(!effect.has_live_effect, "{key} keeps its deferred timing");
        assert!(
            effect.notes.iter().all(|note| !matches!(
                note.kind,
                EffectNoteKind::Unavailable | EffectNoteKind::Inactive
            )),
            "Linux reads its update settings: {key}: {effect:?}"
        );
    }

    for key in GPU_POST_EFFECT_KEYS {
        let value = if matches!(
            *key,
            prefs::EDIT_CURSOR_TRAIL_BLOOM | prefs::EDIT_CURSOR_FIRE_SHIMMER | prefs::EDIT_HDR_GLOW
        ) {
            "true"
        } else {
            "0.8"
        };
        let effect = projected_effect(
            "cursor_trail = true\ncursor_trail_style = \"fire\"\n",
            &[(key, value)],
            key,
            cpu,
            crate::native_app::ViewMotionCx::default(),
        );
        assert!(!effect.has_live_effect, "{key}");
        assert!(effect_note_contains(&effect, "GPU renderer only"), "{key}");
    }

    for (admission, expected) in [
        (PackageAdmission::Unobserved, "status not read yet"),
        (PackageAdmission::MissingBinary, "Package tool missing"),
        (
            PackageAdmission::MissingRootKey,
            "can\u{2019}t install packages",
        ),
    ] {
        let availability = SettingsAvailability {
            packages: admission,
            ..base
        };
        for key in [
            prefs::EDIT_PACKAGES_ENABLED,
            prefs::EDIT_PACKAGES_AUTO_INSTALL,
        ] {
            let effect = projected_effect(
                "",
                &[(key, "true")],
                key,
                availability,
                crate::native_app::ViewMotionCx::default(),
            );
            assert!(!effect.has_live_effect, "{admission:?} {key}");
            assert!(effect_note_contains(&effect, expected), "{key}: {effect:?}");
        }
    }
}

#[test]
fn effect_projection_exhaustively_gates_disabled_effect_families() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    let sample = |kind: EditKind| match kind {
        EditKind::Bool => "true",
        EditKind::Integer => "5",
        EditKind::Float => "0.7",
        EditKind::Color => "#44ccff",
        EditKind::Enum { options } => options
            .first()
            .copied()
            .expect("registered native enum has an option"),
        EditKind::Text | EditKind::Theme => "matrix",
    };

    for leaf in prefs::NESTED_LEAVES.iter().filter(|leaf| {
        leaf.key.starts_with("matrix_rain.")
            && leaf.key != prefs::EDIT_MATRIX_RAIN_ENABLED
            && !native_compatibility_only_key(leaf.key)
    }) {
        let effect = projected_effect(
            "[matrix_rain]\nenabled = false\n",
            &[(leaf.key, sample(leaf.kind))],
            leaf.key,
            availability,
            motion,
        );
        assert!(
            effect_note_contains(&effect, "Matrix Rain is Off"),
            "{}: {effect:?}",
            leaf.key
        );
        assert!(!effect.has_live_effect, "{}", leaf.key);
    }

    for key in TRAIL_TUNING_KEYS {
        let kind = prefs::edit_kind(key);
        let effect = projected_effect(
            "cursor_trail = false\n",
            &[(key, sample(kind))],
            key,
            availability,
            motion,
        );
        assert!(
            effect_note_contains(&effect, "Cursor trail is Off"),
            "{key}: {effect:?}"
        );
        assert!(!effect.has_live_effect, "{key}");
    }

    for leaf in prefs::NESTED_LEAVES.iter().filter(|leaf| {
        leaf.key.starts_with("sparkle_words.")
            && leaf.key != SPARKLE_MASTER_KEY
            && !native_compatibility_only_key(leaf.key)
    }) {
        let effect = projected_effect(
            "[sparkle_words]\nenabled = false\n",
            &[(leaf.key, sample(leaf.kind))],
            leaf.key,
            availability,
            motion,
        );
        assert!(
            effect_note_contains(&effect, "Sparkle Words master is Off"),
            "{}: {effect:?}",
            leaf.key
        );
        assert!(!effect.has_live_effect, "{}", leaf.key);
    }
}

/// A TYPO'D STYLE TAKES NO TUNING ROW OFF THE AIR. The sweep above only ever
/// exercised `cursor_trail = false`, which is why the silent-disable
/// semantics could be replaced by a rendering fallback while fourteen rows
/// kept projecting `has_live_effect = false` beside a sentence that told a
/// float or colour row ITS value was unregistered.
///
/// The constraint is stated as an EQUALITY against a valid-style baseline:
/// an unrecognized `cursor_trail_style` must not change whether a tuning row
/// is live, because `resolve_trail_style` substitutes the default style and
/// the trail renders. The style row itself is the one row whose authored
/// value really is unusable, and it keeps the Unavailable shape.
#[test]
fn an_unknown_trail_style_leaves_the_tuning_rows_live() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    let sample = |kind: EditKind| match kind {
        EditKind::Bool => "true",
        EditKind::Integer => "5",
        EditKind::Float => "0.7",
        EditKind::Color => "#44ccff",
        EditKind::Enum { options } => options
            .first()
            .copied()
            .expect("registered native enum has an option"),
        EditKind::Text | EditKind::Theme => "matrix",
    };
    let typo = "phasr";
    assert_eq!(
        crate::prefs::cursor_trail_style_canonical(typo),
        None,
        "the probe value must really be unrecognized"
    );
    let good = crate::prefs::DEFAULT_CURSOR_TRAIL_STYLE;

    let mut any_live = 0usize;
    for key in TRAIL_TUNING_KEYS {
        let kind = prefs::edit_kind(key);
        let project = |style: &str| {
            projected_effect(
                &format!("cursor_trail = true\ncursor_trail_style = \"{style}\"\n"),
                &[(key, sample(kind))],
                key,
                availability,
                motion,
            )
        };
        let baseline = project(good);
        let fallback = project(typo);
        assert_eq!(
            fallback.has_live_effect, baseline.has_live_effect,
            "{key}: the unrecognized style changed the live verdict\n  valid: {baseline:?}\n  typo: {fallback:?}"
        );
        assert!(
            !effect_note_contains(&fallback, "outside this setting's registered choices"),
            "{key}: a tuning row must not be told ITS value is unregistered: {fallback:?}"
        );
        if fallback.has_live_effect {
            any_live += 1;
            assert!(
                effect_note_contains(&fallback, "this tuning applies to that fallback trail"),
                "{key}: a live tuning row must name the trail it is tuning: {fallback:?}"
            );
        } else {
            // The one honest exception, and it must be dark for ITS OWN
            // reason — the resolved fallback is the rainbow pet, not Fire.
            assert_eq!(*key, prefs::EDIT_CURSOR_FIRE_SHIMMER, "{fallback:?}");
            assert!(
                effect_note_contains(&fallback, "Fire style only"),
                "{fallback:?}"
            );
        }
    }
    // Non-vacuity: all but one of the table stays live. The exception is
    // `cursor_fire_shimmer`, which is correctly gated on the RESOLVED style
    // being Fire — the fallback is the rainbow pet, so it is genuinely
    // inactive and says so for the right reason.
    assert_eq!(
        any_live,
        TRAIL_TUNING_KEYS.len() - 1,
        "{any_live} of {} tuning rows stayed live",
        TRAIL_TUNING_KEYS.len()
    );
    for key in [
        prefs::EDIT_CURSOR_TRAIL_INTENSITY,
        prefs::EDIT_HDR_GLOW,
        prefs::EDIT_CURSOR_TRAIL_MS,
        prefs::EDIT_CURSOR_TRAIL_COLOR,
    ] {
        let effect = projected_effect(
            &format!("cursor_trail = true\ncursor_trail_style = \"{typo}\"\n"),
            &[(key, sample(prefs::edit_kind(key)))],
            key,
            availability,
            motion,
        );
        assert!(effect.has_live_effect, "{key}: {effect:?}");
    }

    // The two switches that govern the same fallback trail are not tuning
    // rows, so the sweep above cannot see them — and that shape is exactly
    // how they kept the silent-disable projection after the fallback
    // landed. Their own values stay valid, so a typo must not move their
    // verdict either.
    for key in [prefs::EDIT_CURSOR_TRAIL, prefs::EDIT_TRAIL_SOUNDS] {
        let project = |style: &str| {
            projected_effect(
                &format!("cursor_trail = true\ncursor_trail_style = \"{style}\"\n"),
                &[(key, "true")],
                key,
                availability,
                motion,
            )
        };
        let baseline = project(good);
        let fallback = project(typo);
        assert_eq!(
            fallback.has_live_effect, baseline.has_live_effect,
            "{key}: the unrecognized style changed the live verdict\n  valid: {baseline:?}\n  typo: {fallback:?}"
        );
        assert!(fallback.has_live_effect, "{key}: {fallback:?}");
        assert!(
            !effect_note_contains(&fallback, "outside this setting's registered choices"),
            "{key}: a switch must not be told ITS value is unregistered: {fallback:?}"
        );
    }

    // The STYLE row is the one row whose authored value is genuinely
    // unusable, and it keeps the generic invalid-choice shape.
    let style_row = projected_effect(
        "cursor_trail = true\n",
        &[(prefs::EDIT_CURSOR_TRAIL_STYLE, typo)],
        prefs::EDIT_CURSOR_TRAIL_STYLE,
        availability,
        motion,
    );
    assert!(
        effect_note_contains(&style_row, "Invalid trail style · Runtime fallback active"),
        "{style_row:?}"
    );
    assert!(!style_row.has_live_effect, "{style_row:?}");

    // The master switch still owns the whole family, typo or not.
    for key in TRAIL_TUNING_KEYS {
        let effect = projected_effect(
            &format!("cursor_trail = false\ncursor_trail_style = \"{typo}\"\n"),
            &[(key, sample(prefs::edit_kind(key)))],
            key,
            availability,
            motion,
        );
        assert!(
            effect_note_contains(&effect, "Cursor trail is Off"),
            "{key}: {effect:?}"
        );
        assert!(!effect.has_live_effect, "{key}");
    }

    // A `pack:<id>` that is not loaded still fails closed — there is nothing
    // to fall back to, so those rows stay dark.
    for key in TRAIL_TUNING_KEYS {
        let effect = projected_effect(
            "cursor_trail = true\ncursor_trail_style = \"pack:not-loaded\"\n",
            &[(key, sample(prefs::edit_kind(key)))],
            key,
            availability,
            motion,
        );
        assert!(!effect.has_live_effect, "{key}: {effect:?}");
    }
}

/// THE MOMENTUM GLOW ANSWERS TO THE CURSOR-EFFECTS MASTER, AND ONLY TO IT.
/// Since 2026-09-27 the glow obeys `cursor_trail` (a master-off window
/// typed into fast lights no halo), so with the master Off its row says
/// so instead of looking checked and live. It is NOT a trail tuning row:
/// the trail's style (`off` keeps the glow) and a missing pack leave it
/// lit, so it takes neither of those disclosures. The absent master is
/// the platform default, Off on Windows.
#[test]
fn the_momentum_glow_row_discloses_the_cursor_trail_master_and_nothing_else() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    let key = prefs::EDIT_CURSOR_MOMENTUM_GLOW;
    let project =
        |source: &str| projected_effect(source, &[(key, "true")], key, availability, motion);

    let off = project("cursor_trail = false\n");
    assert!(effect_note_contains(&off, "Cursor trail is Off"), "{off:?}");
    assert!(!off.has_live_effect, "{off:?}");

    for source in [
        "cursor_trail = true\n",
        "cursor_trail = true\ncursor_trail_style = \"off\"\n",
        "cursor_trail = true\ncursor_trail_style = \"pack:not-loaded\"\n",
    ] {
        let on = project(source);
        assert!(on.has_live_effect, "{source}{on:?}");
        assert!(
            !effect_note_contains(&on, "Cursor trail is Off"),
            "{source}{on:?}"
        );
    }

    let absent = project("");
    assert_eq!(
        absent.has_live_effect,
        crate::app_config::DEFAULT_DECORATIVE_EFFECTS,
        "the absent master is the platform default: {absent:?}"
    );
}

#[test]
fn effect_projection_covers_live_motion_and_specific_child_dependencies() {
    let availability = audited_availability();
    for (source, motion, expected) in [
        (
            "motion = \"reduced\"\ncursor_trail = true\n",
            crate::native_app::ViewMotionCx::default(),
            "Motion Reduced",
        ),
        (
            "motion = \"auto\"\ncursor_trail = true\n",
            crate::native_app::ViewMotionCx {
                system_reduced: true,
                ..crate::native_app::ViewMotionCx::default()
            },
            "System Reduce Motion",
        ),
        (
            "motion = \"auto\"\nload_adaptive_motion = true\ncursor_trail = true\n",
            crate::native_app::ViewMotionCx {
                performance_reduced: true,
                ..crate::native_app::ViewMotionCx::default()
            },
            "Heavy load",
        ),
        (
            "motion = \"full\"\ncursor_trail = true\n",
            crate::native_app::ViewMotionCx {
                focused: false,
                ..crate::native_app::ViewMotionCx::default()
            },
            "Window unfocused",
        ),
    ] {
        let effect = projected_effect(
            source,
            &[(prefs::EDIT_CURSOR_TRAIL_RADIUS, "1.1")],
            prefs::EDIT_CURSOR_TRAIL_RADIUS,
            availability,
            motion,
        );
        assert!(effect_note_contains(&effect, expected), "{effect:?}");
        assert!(!effect.has_live_effect);
    }

    let cases = [
        (
            "stream_fade = false\n",
            prefs::EDIT_STREAM_FADE_MS,
            "120",
            "Stream fade is Off",
        ),
        (
            "cursor_trail = true\ncursor_trail_style = \"water\"\n",
            prefs::EDIT_CURSOR_FIRE_SHIMMER,
            "true",
            "Fire trail style",
        ),
        (
            "cursor_trail = true\ncursor_trail_bloom = false\n",
            prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS,
            "2.4",
            "Cursor trail bloom is Off",
        ),
        (
            // The install consent is dormant while "Automatic updates" (was
            // "Automatic package maintenance") is off, and says so by that name.
            "[packages]\nenabled = false\n",
            prefs::EDIT_PACKAGES_AUTO_INSTALL,
            "true",
            "Automatic updates is Off",
        ),
        (
            "ligatures = false\n",
            prefs::EDIT_CURSOR_BREAK_LIGATURES,
            "true",
            "ligatures are Off",
        ),
        (
            "[sparkle_words.profanity]\nstyle = \"nova\"\n",
            "sparkle_words.profanity.supernova_chance",
            "50",
            "Rainbow style",
        ),
        (
            "[sparkle_words.profanity]\nstyle = \"rainbow\"\n",
            "sparkle_words.profanity.magic",
            "true",
            "Nova style",
        ),
        (
            "[sparkle_words.feline]\nstyle = \"paw\"\n",
            "sparkle_words.feline.magic",
            "true",
            "Cat graphic",
        ),
        (
            "[sparkle_words.profanity]\nenabled = false\n[sparkle_words.feline]\nenabled = true\n",
            "sparkle_words.ink.strength",
            "0.8",
            "Sparkle Words is Off",
        ),
        (
            "[sparkle_words.profanity]\nenabled = true\nstyle = \"rainbow\"\n[sparkle_words.feline]\nenabled = true\n",
            "sparkle_words.ink.sweep_ms",
            "1200",
            "TwoTone ink",
        ),
        (
            "[sparkle_words.emphasis]\nenabled = true\n",
            "sparkle_words.emphasis.enabled",
            "true",
            "default Emphasis",
        ),
    ];
    for (source, key, value, expected) in cases {
        let effect = projected_effect(
            source,
            &[(key, value)],
            key,
            availability,
            crate::native_app::ViewMotionCx::default(),
        );
        assert!(effect_note_contains(&effect, expected), "{key}: {effect:?}");
        assert!(!effect.has_live_effect, "{key}");
    }

    // With Automatic updates ON the install consent is live: it is what the next
    // unattended pass reads.
    let auto_install = projected_effect(
        "[packages]\nenabled = true\n",
        &[(prefs::EDIT_PACKAGES_AUTO_INSTALL, "false")],
        prefs::EDIT_PACKAGES_AUTO_INSTALL,
        availability,
        crate::native_app::ViewMotionCx::default(),
    );
    assert!(
        !effect_note_contains(&auto_install, "Automatic updates is Off"),
        "the consent is not dormant while the switch is on: {auto_install:?}"
    );
}

#[test]
fn custom_spec_dependencies_use_typed_reachable_consumers() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    let custom = |recipe: &str| {
        format!(
            "[sparkle_words.profanity]\nstyle = \"rainbow\"\n\
             [[sparkle_words.custom]]\nwords = [\"typedword\"]\n{recipe}\n"
        )
    };
    let effect = |source: &str, key: &str, value: &str| {
        projected_effect(source, &[(key, value)], key, availability, motion)
    };

    for (recipe, expected_live) in [
        ("burst = { kind = \"nova\", chance = 1 }", true),
        (
            "ink = { colorway = \"twotone:#112233,#445566\" }\n\
             burst = { kind = \"nova\", chance = 0 }",
            true,
        ),
        ("burst = { kind = \"nova\", chance = 0 }", false),
        ("burst = { kind = \"glow\", chance = 100 }", false),
        ("burst = { kind = \"supernova\", chance = 100 }", false),
        ("graphic = { collection = \"cats\" }", false),
    ] {
        let projected = effect(&custom(recipe), "sparkle_words.profanity.magic", "true");
        assert_eq!(
            !effect_note_contains(&projected, "Nova style"),
            expected_live,
            "magic consumer mismatch for {recipe}: {projected:?}"
        );
    }
    let ink_off_nova_twotone = concat!(
        "[sparkle_words.profanity]\nstyle = \"rainbow\"\n",
        "[sparkle_words.ink]\nenabled = false\n",
        "[[sparkle_words.custom]]\nwords = [\"typedword\"]\n",
        "ink = \"twotone:#112233,#445566\"\n",
        "burst = { kind = \"nova\", chance = 0 }\n",
    );
    let projected = effect(
        ink_off_nova_twotone,
        "sparkle_words.profanity.magic",
        "true",
    );
    assert!(
        effect_note_contains(&projected, "Nova style"),
        "TwoTone can consume Nova magic only while global keyword ink is On"
    );

    for (recipe, expected_live) in [
        ("burst = { kind = \"sparkle\", chance = 1 }", true),
        ("burst = { kind = \"starburst\", chance = 1 }", true),
        ("burst = { kind = \"sparkle\", chance = 0 }", false),
        ("burst = { kind = \"nova\", chance = 100 }", false),
        ("burst = { kind = \"glow\", chance = 100 }", false),
        ("graphic = { collection = \"cats\" }", false),
    ] {
        let projected = effect(
            &custom(recipe),
            "sparkle_words.profanity.palette",
            "[\"#112233\", \"#445566\"]",
        );
        assert_eq!(
            !effect_note_contains(&projected, "Sparkle/Starburst"),
            expected_live,
            "legacy burst consumer mismatch for {recipe}: {projected:?}"
        );
    }

    let shadowed = concat!(
        "[sparkle_words.profanity]\nstyle = \"rainbow\"\n",
        "[[sparkle_words.custom]]\nwords = [\"sameword\"]\n",
        "burst = { kind = \"nova\", chance = 100 }\n",
        "[[sparkle_words.custom]]\nwords = [\"sameword\"]\n",
        "graphic = { collection = \"cats\" }\n",
    );
    let state = SettingsViewState::new(&aterm_toml::from_str(shadowed).unwrap());
    assert_eq!(
        state.sparkle_spec_consumers,
        Some(aterm_effects::spec::SpecConsumerCapabilities::default()),
        "an unreachable overridden recipe cannot keep a shared setting live"
    );
    let projected = effect(shadowed, "sparkle_words.profanity.magic", "true");
    assert!(effect_note_contains(&projected, "Nova style"));

    let empty_word = custom("burst = { kind = \"nova\", chance = 100 }")
        .replace("words = [\"typedword\"]", "words = [\"   \"]");
    let projected = effect(&empty_word, "sparkle_words.profanity.magic", "true");
    assert!(
        effect_note_contains(&projected, "Nova style"),
        "an entry without an admitted word is not a consumer"
    );
}

#[test]
fn trail_dependencies_use_the_admitted_style_resolution() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    // THE THREE RESOLUTIONS THAT REALLY DO LEAVE A TUNING ROW DARK. An
    // unknown style is NOT among them any more — it resolves to the default
    // style and renders, so every tuning row stays live and names the
    // fallback — pinned in full by
    // `an_unknown_trail_style_leaves_the_tuning_rows_live`.
    let cases = [
        (
            "cursor_trail = true\ncursor_trail_style = \"pack:missing\"\n",
            prefs::EDIT_CURSOR_TRAIL_RADIUS,
            "1.0",
            "Trail Pack is missing",
        ),
        (
            "cursor_trail = true\ncursor_trail_style = \"pack:\"\n",
            prefs::EDIT_CURSOR_TRAIL_RADIUS,
            "1.0",
            "Trail Pack id is empty",
        ),
        (
            "cursor_trail = true\ncursor_trail_style = \"off\"\n",
            prefs::EDIT_CURSOR_TRAIL_RADIUS,
            "1.0",
            "Cursor trail is Off",
        ),
    ];
    for (source, key, value, expected) in cases {
        let projected = projected_effect(source, &[(key, value)], key, availability, motion);
        assert!(
            effect_note_contains(&projected, expected),
            "{source:?}: {projected:?}"
        );
        assert!(!projected.has_live_effect);
    }

    for (value, expected) in [
        ("not-a-style", "style is unknown"),
        ("pack:missing", "Trail Pack is missing"),
        ("pack:", "Trail Pack id is empty"),
    ] {
        let projected = projected_effect(
            "cursor_trail = true\n",
            &[(prefs::EDIT_CURSOR_TRAIL_STYLE, value)],
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            availability,
            motion,
        );
        assert!(effect_note_contains(&projected, expected), "{projected:?}");
        assert!(!projected.has_live_effect);
    }

    // The master switch is not the row with the unusable value: turning it
    // on draws the fallback trail, so it keeps its live effect and is never
    // told that its own `true` is outside the style's registered choices.
    let master = projected_effect(
        "cursor_trail = false\ncursor_trail_style = \"not-a-style\"\n",
        &[(prefs::EDIT_CURSOR_TRAIL, "true")],
        prefs::EDIT_CURSOR_TRAIL,
        availability,
        motion,
    );
    assert!(master.has_live_effect, "{master:?}");
    assert!(
        !effect_note_contains(&master, "outside this setting's registered choices"),
        "{master:?}"
    );
}

#[test]
fn dependent_style_projection_uses_runtime_fallbacks_not_raw_enum_text() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();

    let supernova = projected_effect(
        "[sparkle_words.profanity]\nstyle = \"laser\"\n",
        &[("sparkle_words.profanity.supernova_chance", "20")],
        "sparkle_words.profanity.supernova_chance",
        availability,
        motion,
    );
    assert!(
        !effect_note_contains(&supernova, "Rainbow style only"),
        "unknown profanity style resolves to Rainbow: {supernova:?}"
    );

    for key in ["sparkle_words.ink.sweep_ms", "sparkle_words.ink.loop"] {
        let projected = projected_effect(
            "[sparkle_words.profanity]\nstyle = \"laser\"\n",
            &[(
                key,
                if key.ends_with("loop") {
                    "true"
                } else {
                    "1200"
                },
            )],
            key,
            availability,
            motion,
        );
        assert!(
            effect_note_contains(
                &projected,
                if key.ends_with("loop") {
                    "Class TwoTone only"
                } else {
                    "TwoTone ink only"
                }
            ),
            "unknown style is Rainbow, not a synthetic TwoTone style: {projected:?}"
        );
    }

    let spaced_nova = projected_effect(
        "[sparkle_words.profanity]\nstyle = \" Nova \"\n",
        &[("sparkle_words.profanity.magic", "true")],
        "sparkle_words.profanity.magic",
        availability,
        motion,
    );
    assert!(
        !effect_note_contains(&spaced_nova, "Nova style only"),
        "trimmed case-insensitive Nova must use the owning runtime mode: {spaced_nova:?}"
    );
    let spaced_sparkle = projected_effect(
        "[sparkle_words.profanity]\nstyle = \" Sparkle \"\n",
        &[("sparkle_words.profanity.palette", "[]")],
        "sparkle_words.profanity.palette",
        availability,
        motion,
    );
    assert!(
        !effect_note_contains(&spaced_sparkle, "Sparkle/Starburst only"),
        "trimmed case-insensitive Sparkle must use the owning runtime mode: {spaced_sparkle:?}"
    );

    let cased_paw = projected_effect(
        "[sparkle_words.feline]\nstyle = \" Paw \"\n",
        &[("sparkle_words.feline.magic", "true")],
        "sparkle_words.feline.magic",
        availability,
        motion,
    );
    assert!(
        effect_note_contains(&cased_paw, "Cat graphic"),
        "trimmed case-insensitive Paw selects the legacy ink-only runtime mode"
    );
    let cased_style = projected_effect(
        "[sparkle_words.feline]\nstyle = \" Paw \"\n",
        &[("sparkle_words.feline.style", " Paw ")],
        "sparkle_words.feline.style",
        availability,
        motion,
    );
    assert!(effect_note_contains(&cased_style, "Legacy Paw"));

    let paw_product = projected_effect(
        "[sparkle_words.feline]\nenabled = true\nstyle = \"paw\"\n",
        &[(KEYWORD_KITTIES_KEY, "true")],
        KEYWORD_KITTIES_KEY,
        availability,
        motion,
    );
    assert!(effect_note_contains(&paw_product, "no kitty graphic"));
    assert!(effect_note_contains(&paw_product, "Legacy Paw ink only"));
    assert!(
        paw_product.has_live_effect,
        "Paw still has a live ink effect; Top must describe it rather than pretending the toggle is inert"
    );

    let exact_paw = projected_effect(
        "[sparkle_words.feline]\nstyle = \"paw\"\n",
        &[("sparkle_words.feline.magic", "true")],
        "sparkle_words.feline.magic",
        availability,
        motion,
    );
    assert!(effect_note_contains(&exact_paw, "Cat graphic"));
}

#[test]
fn invalid_registered_enum_and_color_values_disclose_runtime_fallbacks() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    for (source, key, value, expected) in [
        (
            "background_material = \"not-a-material\"\nbackground_opacity = 0.8\n",
            prefs::EDIT_BACKGROUND_MATERIAL,
            "not-a-material",
            "Invalid choice",
        ),
        (
            "window_colorspace = \"laser-rgb\"\n",
            prefs::EDIT_WINDOW_COLORSPACE,
            "laser-rgb",
            "Invalid choice",
        ),
        (
            "foreground = \"purple-ish\"\n",
            prefs::EDIT_FOREGROUND,
            "purple-ish",
            "Invalid color",
        ),
    ] {
        let projected = projected_effect(source, &[(key, value)], key, availability, motion);
        assert!(
            effect_note_contains(&projected, expected),
            "{key}: {projected:?}"
        );
        assert!(!projected.has_live_effect);
    }

    let valid = projected_effect(
        "foreground = \"#a0b1c2\"\n",
        &[(prefs::EDIT_FOREGROUND, "#a0b1c2")],
        prefs::EDIT_FOREGROUND,
        availability,
        motion,
    );
    assert!(!effect_note_contains(&valid, "Invalid color"));
}

#[test]
fn custom_ink_and_emphasis_dependencies_match_runtime_ownership() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    let effect = |source: &str, key: &str, value: &str| {
        projected_effect(source, &[(key, value)], key, availability, motion)
    };
    let source = |recipe: &str| {
        format!(
            "[sparkle_words.profanity]\nstyle = \"rainbow\"\n\
             [[sparkle_words.custom]]\nwords = [\"inkword\"]\n{recipe}\n"
        )
    };

    let rainbow: Config = aterm_toml::from_str(&source("ink = \"rainbow\"")).unwrap();
    let rainbow = SettingsViewState::new(&rainbow)
        .sparkle_spec_consumers
        .unwrap();
    assert!(rainbow.rainbow_ink);
    assert!(!rainbow.twotone_ink);

    let twotone_source = source("ink = \"twotone:#112233,#445566\"");
    let twotone: Config = aterm_toml::from_str(&twotone_source).unwrap();
    let twotone = SettingsViewState::new(&twotone)
        .sparkle_spec_consumers
        .unwrap();
    assert!(twotone.twotone_ink);
    assert!(!twotone.rainbow_ink);

    let graphic: Config =
        aterm_toml::from_str(&source("graphic = { collection = \"cats\" }")).unwrap();
    assert_eq!(
        SettingsViewState::new(&graphic).sparkle_spec_consumers,
        Some(aterm_effects::spec::SpecConsumerCapabilities::default())
    );

    let mut self_glow_table = aterm_effects::spec::SpecTable::default();
    self_glow_table.insert_custom(
        "glowword",
        aterm_effects::spec::WordEffectSpec {
            ink: Some(aterm_effects::spec::InkSpec {
                colorway: aterm_effects::spec::Colorway::SelfGlow {
                    lift: 0.2,
                    amp: 0.5,
                    window_ms: 900,
                },
                sweep_once: true,
            }),
            ..Default::default()
        },
    );
    assert_eq!(
        self_glow_table.consumer_capabilities(),
        aterm_effects::spec::SpecConsumerCapabilities::default(),
        "SelfGlow owns its intensity and cannot consume shared strength/sweep"
    );

    let sweep = effect(&twotone_source, "sparkle_words.ink.sweep_ms", "1200");
    assert!(
        !effect_note_contains(&sweep, "TwoTone ink only"),
        "custom TwoTone consumes the shared sweep duration"
    );
    let rainbow_sweep = effect(
        &source("ink = \"rainbow\""),
        "sparkle_words.ink.sweep_ms",
        "1200",
    );
    assert!(effect_note_contains(&rainbow_sweep, "TwoTone ink only"));

    let loop_projection = effect(&twotone_source, "sparkle_words.ink.loop", "true");
    assert!(
        effect_note_contains(&loop_projection, "Class TwoTone only"),
        "custom sweep_once ownership must not make global ink.loop live"
    );

    let custom_emphasis = effect(&twotone_source, "sparkle_words.emphasis.enabled", "true");
    assert!(
        effect_note_contains(&custom_emphasis, "default Emphasis"),
        "custom overrides bypass the emphasis class gate"
    );
    let extra_words = effect(
        "[sparkle_words.emphasis]\nenabled = true\nextra_words = [\"wow\"]\n",
        "sparkle_words.emphasis.enabled",
        "true",
    );
    assert!(!effect_note_contains(&extra_words, "default Emphasis"));

    let blank_words = effect(
        "[sparkle_words.emphasis]\nenabled = true\nextra_words = [\"\", \"   \"]\n",
        "sparkle_words.emphasis.enabled",
        "true",
    );
    assert!(effect_note_contains(&blank_words, "default Emphasis"));

    let ink_off = effect(
        "[sparkle_words.ink]\nenabled = false\n\
         [sparkle_words.emphasis]\nenabled = true\nextra_words = [\"wow\"]\n",
        "sparkle_words.emphasis.enabled",
        "true",
    );
    assert!(effect_note_contains(&ink_off, "Keyword ink Off"));
}

#[test]
fn custom_consumers_obey_master_product_and_ink_parent_gates() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    let cases = [
        (
            "[sparkle_words]\nenabled = false\n\
             [[sparkle_words.custom]]\nwords = [\"nova\"]\nburst = { kind = \"nova\", chance = 100 }\n",
            "sparkle_words.profanity.magic",
            "true",
            "Sparkle Words master is Off",
        ),
        (
            "[sparkle_words.profanity]\nenabled = false\nstyle = \"rainbow\"\n\
             [[sparkle_words.custom]]\nwords = [\"nova\"]\nburst = { kind = \"nova\", chance = 100 }\n",
            "sparkle_words.profanity.magic",
            "true",
            "keyword-toy class is Off",
        ),
        (
            "[sparkle_words.profanity]\nenabled = false\n\
             [[sparkle_words.custom]]\nwords = [\"ink\"]\nink = \"twotone:#112233,#445566\"\n",
            "sparkle_words.ink.sweep_ms",
            "1200",
            "Sparkle Words is Off",
        ),
        (
            "[sparkle_words.ink]\nenabled = false\n\
             [[sparkle_words.custom]]\nwords = [\"ink\"]\nink = \"twotone:#112233,#445566\"\n",
            "sparkle_words.ink.sweep_ms",
            "1200",
            "keyword-toy class is Off",
        ),
        (
            "[sparkle_words.profanity]\nenabled = false\n\
             [sparkle_words.feline]\nenabled = false\n",
            "sparkle_words.reduced_motion",
            "true",
            "both keyword toys are Off",
        ),
        (
            "[sparkle_words.profanity]\nenabled = false\n\
             [sparkle_words.feline]\nenabled = false\n",
            "sparkle_words.suppress_in_alt_screen",
            "true",
            "both keyword toys are Off",
        ),
        (
            "[sparkle_words.profanity]\nenabled = false\n\
             [sparkle_words.feline]\nenabled = false\n",
            "sparkle_words.ink.enabled",
            "true",
            "both keyword toys are Off",
        ),
        (
            "[sparkle_words.profanity]\nenabled = false\n\
             [sparkle_words.feline]\nenabled = false\n",
            SPARKLE_MASTER_KEY,
            "true",
            "both keyword toys are Off",
        ),
    ];
    for (source, key, value, expected) in cases {
        let projected = projected_effect(source, &[(key, value)], key, availability, motion);
        assert!(
            effect_note_contains(&projected, expected),
            "{key} did not preserve {expected:?}: {projected:?}"
        );
        assert!(!projected.has_live_effect);
    }
}

#[test]
fn settings_projection_consumes_the_admitted_toy_pack_capability_carrier() {
    let motion = crate::native_app::ViewMotionCx::default();
    let source = include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../aterm-effects/toy-packs/community/tiny-triumphs/pack.toml"
    ));
    let pack = aterm_effects::spec::compile_toy_pack_toml(source).unwrap();
    let (_, table, _) = pack.into_parts();
    let consumers = table.consumer_capabilities();
    assert!(consumers.sparkle_or_starburst_burst);

    let assets = Arc::new(crate::app_config::ConfigAssetCatalog {
        trail_packs: crate::app_config::TrailPackCatalog::empty(),
        kitty_sprite: crate::app_config::KittySpriteAsset::BuiltIn,
        wallpaper: crate::app_config::WallpaperAsset::None,
        themes: crate::app_config::ThemeCatalog::empty(),
        sparkle_spec_consumers: Some(Arc::new(consumers)),
    });
    let config: Config =
        aterm_toml::from_str("[sparkle_words.profanity]\nstyle = \"rainbow\"\n").unwrap();
    let state = SettingsViewState::from_config_and_assets(&config, assets);
    let projected = setting_effect_projection(
        &state,
        Some(&test_patch(&[("sparkle_words.profanity.palette", "[]")])),
        "sparkle_words.profanity.palette",
        audited_availability(),
        motion,
    );
    assert!(
        !effect_note_contains(&projected, "Sparkle/Starburst"),
        "Settings must use the worker-admitted Toy Pack table, not inline-path inference"
    );

    let exact_all_false = Arc::new(crate::app_config::ConfigAssetCatalog {
        trail_packs: crate::app_config::TrailPackCatalog::empty(),
        kitty_sprite: crate::app_config::KittySpriteAsset::BuiltIn,
        wallpaper: crate::app_config::WallpaperAsset::None,
        themes: crate::app_config::ThemeCatalog::empty(),
        sparkle_spec_consumers: Some(Arc::new(Default::default())),
    });
    let inline_nova: Config = aterm_toml::from_str(concat!(
        "[sparkle_words.profanity]\nstyle = \"rainbow\"\n",
        "[[sparkle_words.custom]]\nwords = [\"shadowed\"]\n",
        "burst = { kind = \"nova\", chance = 100 }\n",
    ))
    .unwrap();
    let state = SettingsViewState::from_config_and_assets(&inline_nova, exact_all_false);
    assert_eq!(
        state.sparkle_spec_consumers,
        Some(aterm_effects::spec::SpecConsumerCapabilities::default()),
        "Some(all-false) is an observed worker verdict, not an empty-catalog sentinel"
    );
    let projected = setting_effect_projection(
        &state,
        Some(&test_patch(&[("sparkle_words.profanity.magic", "true")])),
        "sparkle_words.profanity.magic",
        audited_availability(),
        motion,
    );
    assert!(
        effect_note_contains(&projected, "Nova style"),
        "a shadowed inline Nova must not leak back through fallback inference"
    );

    let preliminary = SettingsViewState::from_config_and_assets(
        &inline_nova,
        crate::app_config::ConfigAssetCatalog::empty(),
    );
    assert_eq!(preliminary.sparkle_spec_consumers, None);
    let projected = setting_effect_projection(
        &preliminary,
        Some(&test_patch(&[("sparkle_words.profanity.magic", "true")])),
        "sparkle_words.profanity.magic",
        audited_availability(),
        motion,
    );
    assert!(
        effect_note_contains(&projected, "recipe admission pending"),
        "None is an explicit unobserved state, never permission to infer inline authority"
    );
    assert!(!effect_note_contains(&projected, "Nova style"));

    let product_off: Config = aterm_toml::from_str(
        "[sparkle_words.profanity]\nenabled = false\n\
         [sparkle_words.emphasis]\nenabled = false\n",
    )
    .unwrap();
    let product_off = SettingsViewState::from_config_and_assets(
        &product_off,
        crate::app_config::ConfigAssetCatalog::empty(),
    );
    for key in [
        "sparkle_words.ink.strength",
        "sparkle_words.ink.sweep_ms",
        "sparkle_words.ink.loop",
        "sparkle_words.emphasis.enabled",
    ] {
        let value = match key {
            "sparkle_words.ink.strength" => "0.8",
            "sparkle_words.ink.sweep_ms" => "1200",
            "sparkle_words.ink.loop" | "sparkle_words.emphasis.enabled" => "true",
            _ => unreachable!("bounded pending-consumer key"),
        };
        let projected = setting_effect_projection(
            &product_off,
            Some(&test_patch(&[(key, value)])),
            key,
            audited_availability(),
            motion,
        );
        assert!(
            effect_note_contains(&projected, "Sparkle Words is Off"),
            "the hard product gate decides {key} even before recipe admission: {projected:?}"
        );
        assert!(!effect_note_contains(
            &projected,
            "recipe admission pending"
        ));
    }

    let unresolved_recipes: Config = aterm_toml::from_str(
        "[sparkle_words.profanity]\nenabled = true\nstyle = \"rainbow\"\n\
         [sparkle_words.emphasis]\nenabled = false\n",
    )
    .unwrap();
    let unresolved_recipes = SettingsViewState::from_config_and_assets(
        &unresolved_recipes,
        crate::app_config::ConfigAssetCatalog::empty(),
    );
    for (key, value) in [
        ("sparkle_words.profanity.magic", "true"),
        ("sparkle_words.profanity.palette", "[]"),
        ("sparkle_words.ink.sweep_ms", "1200"),
        ("sparkle_words.ink.loop", "true"),
        ("sparkle_words.emphasis.enabled", "true"),
    ] {
        let projected = setting_effect_projection(
            &unresolved_recipes,
            Some(&test_patch(&[(key, value)])),
            key,
            audited_availability(),
            motion,
        );
        assert!(
            effect_note_contains(&projected, "recipe admission pending"),
            "unobserved recipes can still decide {key}: {projected:?}"
        );
    }

    let strength = setting_effect_projection(
        &unresolved_recipes,
        Some(&test_patch(&[("sparkle_words.ink.strength", "0.8")])),
        "sparkle_words.ink.strength",
        audited_availability(),
        motion,
    );
    assert!(strength.has_live_effect);
    assert!(!effect_note_contains(&strength, "recipe admission pending"));

    let ink_off: Config = aterm_toml::from_str(
        "[sparkle_words.profanity]\nenabled = true\n\
         [sparkle_words.ink]\nenabled = false\n\
         [sparkle_words.emphasis]\nenabled = true\n",
    )
    .unwrap();
    let ink_off = SettingsViewState::from_config_and_assets(
        &ink_off,
        crate::app_config::ConfigAssetCatalog::empty(),
    );
    let emphasis = setting_effect_projection(
        &ink_off,
        Some(&test_patch(&[("sparkle_words.emphasis.enabled", "true")])),
        "sparkle_words.emphasis.enabled",
        audited_availability(),
        motion,
    );
    assert!(effect_note_contains(&emphasis, "Keyword ink is Off"));
    assert!(!effect_note_contains(&emphasis, "recipe admission pending"));
}

#[test]
fn effect_projection_reports_every_cross_field_effective_value() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    let cases = [
        (
            "[sparkle_words.ink]\nloop = true\nsweep_ms = 400\n",
            "sparkle_words.ink.sweep_ms",
            "400",
            "effective 600 ms",
        ),
        (
            "[sparkle_words.ink]\nloop = false\nsweep_ms = 400\n",
            "sparkle_words.ink.loop",
            "true",
            "effective 600 ms",
        ),
        (
            "[matrix_rain]\nenabled = true\nalpha = 120\nhead_alpha = 20\n",
            "matrix_rain.head_alpha",
            "20",
            "effective 120",
        ),
        (
            "[matrix_rain]\nenabled = true\nalpha = 120\nhead_alpha = 20\n",
            "matrix_rain.alpha",
            "120",
            "effective 120",
        ),
        (
            "cursor_trail = true\ncursor_trail_style = \"beam\"\ncursor_trail_radius = 1.2\n",
            prefs::EDIT_CURSOR_TRAIL_RADIUS,
            "1.2",
            "effective 0 cells",
        ),
        (
            "cursor_trail = true\ncursor_trail_style = \"beam\"\ncursor_trail_ring = true\n",
            prefs::EDIT_CURSOR_TRAIL_RING,
            "true",
            "effective Off",
        ),
    ];
    for (source, key, value, expected) in cases {
        let effect = projected_effect(source, &[(key, value)], key, availability, motion);
        assert!(effect_note_contains(&effect, expected), "{key}: {effect:?}");
    }

    let synthwave = trail_pack_asset("synthwave.toml");
    let source = trail_pack_config(std::slice::from_ref(&synthwave), "pack:synthwave");
    let snapshot = VersionedConfigService::new(source).unwrap().snapshot();
    let state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    for key in [
        prefs::EDIT_CURSOR_TRAIL_RADIUS,
        prefs::EDIT_CURSOR_TRAIL_RING,
    ] {
        let value = if key == prefs::EDIT_CURSOR_TRAIL_RING {
            "true"
        } else {
            "1.0"
        };
        let patch = test_patch(&[(key, value)]);
        let effect = setting_effect_projection(&state, Some(&patch), key, availability, motion);
        assert!(
            effect_note_contains(&effect, "Trail Pack owns"),
            "{effect:?}"
        );
        assert!(!effect.has_live_effect);
    }
}

#[test]
fn row_and_completion_share_the_exact_effect_projection() {
    let config: Config =
        aterm_toml::from_str("stream_fade = false\nstream_fade_ms = 120\n").unwrap();
    let state = SettingsViewState::new(&config);
    let (index, field) = state
        .legacy
        .fields
        .iter()
        .enumerate()
        .find(|(_, field)| field.key == prefs::EDIT_STREAM_FADE_MS)
        .unwrap();
    let effect = setting_effect_projection(
        &state,
        None,
        field.key,
        audited_availability(),
        crate::native_app::ViewMotionCx::default(),
    );
    let inactive = effect
        .notes
        .iter()
        .find(|note| note.kind == EffectNoteKind::Inactive)
        .unwrap();
    let compiled = UiTree::new(setting_row(
        &state,
        index,
        field,
        true,
        false,
        SettingsWidth::Wide,
    ))
    .compile(LogicalRect::new(0.0, 0.0, 900.0, 84.0))
    .unwrap();
    let control = compiled
        .semantic(&UiKey::new(format!("settings/control/{}", field.key)))
        .unwrap();
    assert!(control.label.contains(&inactive.semantic));

    let application = config_application_projection(
        &state,
        &test_patch(&[(prefs::EDIT_STREAM_FADE_MS, "140")]),
        audited_availability(),
    );
    assert!(application.suppression_notes.contains(&inactive.feedback));
    assert!(!application.has_live_edit);

    let mixed = config_application_projection(
        &state,
        &test_patch(&[
            (prefs::EDIT_STREAM_FADE_MS, "140"),
            (prefs::EDIT_COPY_ON_SELECT, "true"),
        ]),
        audited_availability(),
    );
    assert!(
        mixed.has_live_edit,
        "one actual live edit makes the patch Applied"
    );
    assert!(mixed.suppression_notes.contains(&inactive.feedback));
}

/// SETTINGS ▸ HARNESS SPEAKS THE RULE: the row reads `Automatic` while
/// every key is at its full-power default, names each written key as the
/// limit it is, and `Off` once the switch is — saved or in a pending patch.
/// NEGATIVE CONTROL: a written key AT its default limits nothing.
#[test]
fn the_harness_row_says_automatic_and_names_each_limit() {
    let words = |source: &str, patch: Option<&ConfigPatch>| {
        let snapshot = VersionedConfigService::new(source.to_string())
            .unwrap()
            .snapshot();
        let state = SettingsViewState::from_snapshot(&snapshot).unwrap();
        let notes = cross_field_constraints(&state, patch, prefs::EDIT_HARNESS_ENABLED);
        assert_eq!(notes.len(), 1, "{notes:?}");
        assert_eq!(notes[0].kind, EffectNoteKind::Constraint);
        notes[0].visual.clone()
    };
    assert_eq!(words("", None), "Automatic");
    assert_eq!(
        words(
            "[harness]\nenabled = true\ncontinue = true\napprove = \"all\"\n",
            None
        ),
        "Automatic",
        "a key written at its default limits nothing"
    );
    assert_eq!(
        words(
            "[harness]\napprove = \"safe\"\ncontinue = false\ncontinue_per_hour = 3\n",
            None
        ),
        "Automatic \u{b7} limited: approve: safe \u{b7} continue: off \u{b7} continue_per_hour: 3"
    );
    assert_eq!(
        words("harness.relaunch = false\n", None),
        "Automatic \u{b7} limited: relaunch: off",
        "a dotted key at the root is the same table"
    );
    assert_eq!(
        words("[harness]\nenabled = false\n", None),
        "Off: no agent session is supervised"
    );
    let switch_off = ConfigPatch {
        base_revision: 1,
        edits: vec![ConfigEdit {
            key: prefs::EDIT_HARNESS_ENABLED.to_string(),
            expected: ExpectedConfigValue::Any,
            value: Some("false".to_string()),
        }],
    };
    assert_eq!(
        words("[harness]\napprove = \"safe\"\n", Some(&switch_off)),
        "Off: no agent session is supervised"
    );
    let reset = ConfigPatch {
        base_revision: 1,
        edits: vec![ConfigEdit {
            key: "harness.approve".to_string(),
            expected: ExpectedConfigValue::Any,
            value: None,
        }],
    };
    assert_eq!(
        words("[harness]\napprove = \"safe\"\n", Some(&reset)),
        "Automatic"
    );
}

#[test]
fn constrained_window_top_padding_is_honest_in_settings_manual_and_feedback() {
    let source = "window_padding = 12\nwindow_padding_top = 64\n";
    let snapshot = VersionedConfigService::new(source.to_string())
        .unwrap()
        .snapshot();
    let state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    let (index, field) = state
        .legacy
        .fields
        .iter()
        .enumerate()
        .find(|(_, field)| field.key == prefs::EDIT_WINDOW_PADDING_TOP)
        .unwrap();
    let compiled = UiTree::new(setting_row(
        &state,
        index,
        field,
        false,
        false,
        SettingsWidth::Wide,
    ))
    .compile(LogicalRect::new(0.0, 0.0, 720.0, 80.0))
    .unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new(format!(
                "settings/label/{}",
                prefs::EDIT_WINDOW_PADDING_TOP
            )))
            .unwrap()
            .label
            .contains("Effective 12 px")
    );
    let control = compiled
        .semantic(&UiKey::new(format!(
            "settings/control/{}",
            prefs::EDIT_WINDOW_PADDING_TOP
        )))
        .unwrap();
    assert!(control.label.contains("configured 64 px"));
    assert!(control.label.contains("effective 12 px"));

    let analysis = crate::native_config_language::analyze(source);
    assert!(analysis.diagnostics.iter().any(|diagnostic| {
        diagnostic.message.contains("window_padding_top")
            && diagnostic.message.contains("effectively 12px")
    }));

    let base_snapshot = VersionedConfigService::new("window_padding = 12\n".to_string())
        .unwrap()
        .snapshot();
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(base_snapshot))
        .unwrap();
    let requested = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_WINDOW_PADDING_TOP)),
                value: Some(SemanticInput::Number(64.0)),
            }),
        )
        .unwrap();
    let operation = requested
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { reply, .. } => Some(reply.operation),
            _ => None,
        })
        .expect("padding slider reaches config service");
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ConfigPatchFinished {
                operation,
                outcome: ConfigPatchOutcome::Applied {
                    revision: 2,
                    undo: Some(9),
                },
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    assert_eq!(
        state.feedback.as_deref(),
        Some("Applied · Effective top padding is 12 px (configured 64 px) · Undo available")
    );
}

