#[test]
fn advanced_group_footnotes_are_native_semantic_and_fit_responsive_layouts() {
    at_each_text_scale(
        &[1.0, 2.0],
        "native-footnote audit",
        advanced_group_footnotes_are_native_semantic_and_fit_responsive_layouts_at_scale,
    );
}

/// One rung of [`advanced_group_footnotes_are_native_semantic_and_fit_responsive_layouts`] ([`at_each_text_scale`]).
fn advanced_group_footnotes_are_native_semantic_and_fit_responsive_layouts_at_scale(scale: f32) {
    for (viewport_width, viewport_height) in [(1_200.0, 720.0), (320.0, 568.0), (568.0, 320.0)] {
        let (mut runtime, instance, view) = setup();
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::Security),
                    value: None,
                }),
            )
            .unwrap();
        let cx = view_cx_at(viewport_width, viewport_height);
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        let expected = prefs::group_footnote("Permissions").unwrap();
        let semantic = compiled
            .semantics
            .iter()
            .find(|node| {
                node.key.as_str().starts_with("settings/group-footnote/")
                    && node.role == SemanticRole::Status
            })
            .expect("native Permissions footnote status");
        assert_eq!(semantic.label, expected);
        assert!(semantic.rect.height > 0.0);
        let visual_lines = compiled
            .paint
            .iter()
            .filter(|node| {
                node.key.as_str().starts_with("settings/group-footnote/")
                    && node.key.as_str().contains("/line-")
            })
            .collect::<Vec<_>>();
        assert!(!visual_lines.is_empty());
        assert!(visual_lines.iter().all(|line| {
            compiled.semantic(&line.key).is_none() && matches!(&line.content, UiContent::Text(_))
        }));
        // ONE footnote per group box on the page — the Security page carries
        // Permissions everywhere and, on macOS, the [machine] "This Mac" box
        // too (2026-09-14); a compact page may show only the first group.
        let painted_groups = compiled
            .semantics
            .iter()
            .filter_map(|node| node.key.as_str().strip_prefix("settings/row/"))
            .filter_map(|rest| rest.split_once('/').map(|(_, key)| key))
            .map(|key| prefs::group_of(key).0)
            .filter(|group| prefs::group_footnote(group).is_some())
            .collect::<BTreeSet<_>>();
        assert!(painted_groups.contains("Permissions"), "{painted_groups:?}");
        assert_eq!(
            compiled
                .semantics
                .iter()
                .filter(|node| {
                    node.key.as_str().starts_with("settings/group-footnote/")
                        && node.role == SemanticRole::Status
                })
                .count(),
            painted_groups.len(),
            "{viewport_width}×{viewport_height} at {scale}×: {painted_groups:?}"
        );
        let overflow = compiled
            .paint_audit_lines()
            .into_iter()
            .filter(|line| {
                line.contains("paint-text key=\"settings/group-footnote/")
                    && (line.contains("overflow=true") || line.contains("clip-truncated=true"))
            })
            .collect::<Vec<_>>();
        assert!(
            overflow.is_empty(),
            "{viewport_width}×{viewport_height} at {scale}×: {}",
            overflow.join("\n")
        );
    }

    if scale == 2.0 {
        for route in SettingsRoute::ALL {
            let Some(section) = route.section() else {
                continue;
            };
            let (mut runtime, instance, view) = setup();
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: route_action(route),
                        value: None,
                    }),
                )
                .unwrap();
            let expected = {
                let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
                    unreachable!();
                };
                state
                    .legacy
                    .fields
                    .iter()
                    .filter(|field| {
                        prefs::section_of(field.key) == section
                            && settings_field_is_visible(field.key, false, false)
                    })
                    .map(|field| field.key.to_string())
                    .collect::<BTreeSet<_>>()
            };
            if expected.is_empty() {
                // A ROUTE WITH NO ORDINARY ROWS IS NOT A VACUOUS RUN — but
                // it must be a KNOWN one. Cursor Kitty's content is its
                // companion showcase card (`cursor_kitty_card`): both keys
                // filed there are drawn by something other than the
                // ordinary registry, so this sweep — which checks that
                // every registry row is reachable, with an unelided label,
                // at 2x on a 320pt page — has nothing of its own to check
                // and would otherwise pass vacuously.
                //
                // The guard was `assert!(!expected.is_empty())`, which
                // measured "does this page have rows" as a proxy for "does
                // this page have content". That proxy failed the moment the
                // page's one row (the retired `cursor_trail_wake_ms`) was a
                // row for nothing. So: the empty set is admitted for
                // exactly this route and no other, and the thing that
                // actually makes it non-empty is pinned where it belongs,
                // by `the_cursor_kitty_page_is_its_showcase_card`.
                assert_eq!(
                    route,
                    SettingsRoute::CursorKitty,
                    "{} lost every curated field: a page with no rows must be a page \
                     whose content is a card, and only Cursor Kitty is one",
                    route.label()
                );
                continue;
            }
            let cx = view_cx_at(320.0, 568.0);
            let mut reached = BTreeSet::new();
            for page in 0..=expected.len() {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.page_scroll = page;
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                assert_zero_top_paint(
                    &compiled,
                    &format!("2× compact {} page {page}", route.label()),
                );
                let visible = compiled
                    .hits
                    .iter()
                    .filter_map(|hit| {
                        hit.key
                            .as_str()
                            .strip_prefix("settings/control/")
                            .filter(|key| expected.contains(*key))
                    })
                    .collect::<Vec<_>>();
                for key in &visible {
                    let semantic_key = UiKey::new(format!("settings/label/{key}"));
                    let semantic = compiled.semantic(&semantic_key).unwrap_or_else(|| {
                        panic!(
                            "2× compact {} page {page}: {key} lost its complete label semantics",
                            route.label()
                        )
                    });
                    assert!(
                        !semantic.label.contains('…'),
                        "2× compact {} page {page}: semantic label was elided: {}",
                        route.label(),
                        semantic.label,
                    );
                    let visual_key = format!("settings/label/{key}/visual");
                    let visual = compiled
                        .paint
                        .iter()
                        .find_map(|node| (node.key.as_str() == visual_key).then_some(&node.content))
                        .and_then(|content| {
                            let UiContent::Text(spec) = content else {
                                return None;
                            };
                            Some(spec.text.as_str())
                        })
                        .unwrap_or_else(|| panic!("{key} lost its paint-only visual label"));
                    assert!(
                        visual.chars().any(char::is_alphanumeric),
                        "2× compact {} page {page}: {key} collapsed to {visual:?}",
                        route.label(),
                    );
                    let control_key = format!("settings/control/{key}");
                    if let Some(UiContent::Button(button)) =
                        compiled.paint.iter().find_map(|node| {
                            (node.key.as_str() == control_key).then_some(&node.content)
                        })
                    {
                        let visual = button
                            .spec
                            .visual_label
                            .as_deref()
                            .unwrap_or(&button.spec.label);
                        assert!(
                            visual.chars().any(char::is_alphanumeric),
                            "2× compact {} page {page}: {key} choice collapsed to {visual:?}",
                            route.label(),
                        );
                        assert!(
                            !button.spec.label.contains('…'),
                            "2× compact {} page {page}: {key} control semantics were elided",
                            route.label(),
                        );
                    }
                }
                if visible.is_empty() {
                    assert_eq!(
                        page,
                        0,
                        "2× compact {} page {page} has fields but no actionable control\n{}",
                        route.label(),
                        compiled.paint_audit_lines().join("\n"),
                    );
                    assert!(
                        compiled
                            .paint
                            .iter()
                            .any(|node| { matches!(node.content, UiContent::SettingsPreview(_)) }),
                        "2× compact {} page 0 is empty instead of a dedicated preview",
                        route.label(),
                    );
                    continue;
                }
                reached.extend(visible.into_iter().map(str::to_string));
                assert_all_hits_material_and_contained(
                    &compiled,
                    &format!("2× compact {} page {page}", route.label()),
                );
            }
            assert_eq!(
                reached,
                expected,
                "2× compact {} must reach every curated field",
                route.label(),
            );
        }
    }
}

#[test]
fn keyboard_safety_footnote_is_fully_painted_on_desktop_and_compact_pages() {
    let expected = prefs::group_footnote("Keyboard").unwrap();
    let warning = "Always, set in Manual, can show a password.";
    for (variant, viewport_width, viewport_height) in
        [("desktop", 1_224.0, 722.0), ("compact", 568.0, 658.0)]
    {
        let (mut runtime, instance, view) = setup();
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::KeyboardInput),
                    value: None,
                }),
            )
            .unwrap();
        let cx = view_cx_at(viewport_width, viewport_height);
        let mut found = false;
        for page in 0..16 {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.page_scroll = page;
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            assert_zero_top_paint(
                &compiled,
                &format!("{variant} Keyboard & Input page {page}"),
            );
            let Some(semantic) = compiled.semantics.iter().find(|node| {
                node.role == SemanticRole::Status
                    && node.key.as_str().starts_with("settings/group-footnote/")
                    && node.label == expected
            }) else {
                continue;
            };
            let prefix = format!("{}/line-", semantic.key.as_str());
            let painted = compiled
                .paint
                .iter()
                .filter_map(|node| {
                    if !node.key.as_str().starts_with(&prefix) {
                        return None;
                    }
                    let UiContent::Text(spec) = &node.content else {
                        return None;
                    };
                    Some(spec.text.as_str())
                })
                .collect::<String>();
            assert_eq!(painted, expected, "{variant}: full authored footnote");
            assert!(painted.contains(warning), "{variant}: {painted}");
            found = true;
            break;
        }
        assert!(found, "{variant}: Keyboard safety note is reachable");
    }
}

/// The byline steps down a fixed ladder — author · company · site, then
/// author · company, then the author, then the author's short form — to the
/// longest form its hero column really fits, so no width or text scale ever
/// paints it elided. The site joined the line on 2026-09-14 and clipped a
/// 286.5pt phone column at 1× ("…alab.sy…", 223.2pt required against 206.5pt
/// available). The LAST rung is measured like every other one: `Andrew
/// Yates` was the floor until 2026-09-17, when a 240pt host at 2× gave it a
/// 164.0pt column against its 164.6pt measure and the painter clipped the
/// name itself. Below the last rung the hero authors NO byline — asserted
/// here in both directions, so the omission can never hide a form that would
/// have fitted. Every scale runs on a thread of its own ([`at_each_text_scale`]).
#[test]
fn native_about_byline_steps_down_to_the_longest_form_its_column_fits() {
    at_each_text_scale(&[1.0, 1.5, 2.0], "About byline fit audit", |scale| {
        about_byline_sweep(scale, 30.0, 0.5)
    });
}

/// THE EXHAUSTIVE SWEEP: every 7.5pt width, which the default run samples
/// (every 30pt, and every threshold between two widths that disagree,
/// bisected to 0.5pt: [`sample_where_it_changes`]). Ignored for its cost —
/// ~3x the default's CPU; run it when the About hero's layout or the byline
/// ladder changes:
/// `targo --unverified test -p aterm-gui --lib -- --ignored native_about_byline`.
#[test]
#[ignore = "every 7.5pt width (~3x the CPU); the default run takes every 30pt and bisects each threshold to 0.5pt"]
fn native_about_byline_steps_down_to_the_longest_form_its_column_fits_at_every_7_5pt_width() {
    at_each_text_scale(&[1.0, 1.5, 2.0], "About byline fit audit", |scale| {
        about_byline_sweep(scale, 7.5, 7.5)
    });
}

/// One Dynamic Type rung of the byline sweep, over widths `coarse` apart
/// from 120pt and, where two neighbours disagree about the hero (its
/// eyebrow, the rung painted, large-type narrow), bisected down to
/// `resolution` — the thresholds, which are where a byline can overflow.
///
/// WHY (30, 0.5), MEASURED 2026-09-30 by putting each of these into the
/// production ladder (temporary hooks, not committed): a fit slack of 17pt,
/// 10pt and the historical 0.6pt, a fit 3pt too tight, a 12pt measure where
/// the line paints at 13pt, the 48pt column clamp, an unmeasured floor rung,
/// and large-type narrow starting at the first rung — every one turns this
/// sweep red, as it does the every-7.5pt sweep. Thinning to every 30pt
/// ALONE misses the 0.6pt slack and the 3pt-tight fit (a window narrower
/// than the step); the bisection is what keeps them.
fn about_byline_sweep(scale: f32, coarse: f32, resolution: f32) {
    let author_company = crate::build_info::AUTHOR_COMPANY_BYLINE;
    let author = aterm_types::identity::AUTHOR;
    let author_short = crate::build_info::AUTHOR_SHORT;
    let full = format!("{author_company} \u{00b7} {}", aterm_types::identity::SITE);
    let ladder = [full.as_str(), author_company, author, author_short];
    // The byline is Text/Success: the Body step, 13pt × scale, UI face.
    let px = 13.0 * scale;
    let width_of = |line: &str| crate::tray_raster::ui_text_width(line, px);
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::About),
                value: None,
            }),
        )
        .unwrap();
    struct HeroByline {
        /// The painted line, its paint-audit row, and its semantic label —
        /// `None` when the full hero authored no byline at all.
        painted: Option<(String, String, Option<String>)>,
        column: f32,
        large_type_narrow: bool,
    }
    // `about/eyebrow` is a child of the SAME hero column and exists only in
    // the full (non short-landscape) hero, so it measures the column even
    // where no byline was authored — the one geometry a byline node cannot
    // report on. Where both exist the two measures are asserted equal, which
    // is what makes the eyebrow an honest proxy rather than a second guess.
    let byline_at = |width: f32, height: f32| {
        let cx = view_cx_at(width, height);
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        let eyebrow = compiled
            .paint
            .iter()
            .find(|node| node.key == UiKey::new("about/eyebrow"))?;
        let UiContent::Text(TextSpec {
            text: eyebrow_text, ..
        }) = &eyebrow.content
        else {
            panic!("{width}x{height} at {scale}×: the eyebrow is a text node");
        };
        let large_type_narrow = eyebrow_text == "NATIVE APP";
        let column = eyebrow.rect.width;
        let painted = compiled
            .paint
            .iter()
            .find(|node| node.key == UiKey::new("about/byline"))
            .map(|node| {
                let UiContent::Text(spec) = &node.content else {
                    panic!("{width}x{height} at {scale}×: the byline is a text node");
                };
                assert!(
                    (node.rect.width - column).abs() < 0.05,
                    "{width}x{height} at {scale}×: the byline's {}pt box and its eyebrow sibling's {column}pt box are the same hero column",
                    node.rect.width
                );
                let audit = compiled
                    .text_fit_audit_line(&UiKey::new("about/byline"))
                    .expect("the renderer audits the byline's fit");
                let label = compiled
                    .semantic(&UiKey::new("about/byline"))
                    .map(|semantic| semantic.label.clone());
                (spec.text.clone(), audit, label)
            });
        Some(HeroByline {
            painted,
            column,
            large_type_narrow,
        })
    };

    let mut rungs_seen = [0usize; 4];
    let mut omissions = 0usize;
    // One width of the sweep, every assertion it makes. What it returns —
    // whether the hero has an eyebrow at all, the rung painted (`None`: no
    // byline) and whether it is the large-type narrow one — is what
    // [`sample_where_it_changes`] compares between neighbouring widths.
    let mut at = |width: f32, height: f32| -> Option<(Option<usize>, bool)> {
        let hero = byline_at(width, height)?;
        let HeroByline {
            painted,
            column,
            large_type_narrow,
            ..
        } = hero;
        let context = format!("{width}x{height} at {scale}×");
        // Large type on a narrow host starts at the author's rungs.
        // SPELLED AS A LITERAL, not read from production's own
        // constant: a sweep that indexes the ladder by the number
        // the page indexes it by would agree with any renumbering,
        // including a wrong one. 2 is the author rung's position in
        // the ladder this test builds, and if production moves it
        // the mismatch is the finding.
        let first = if large_type_narrow { 2 } else { 0 };
        let want = ladder[first..]
            .iter()
            .position(|form| width_of(form) <= column)
            .map(|found| found + first);
        let painted_rung = if let Some((text, audit, label)) = painted {
            let rung = ladder
                .iter()
                .position(|form| *form == text)
                .unwrap_or_else(|| panic!("{context}: {text:?} is not a byline form"));
            assert!(
                audit.contains(" overflow=false "),
                "{context}: the byline paints truncated: {audit}"
            );
            assert!(
                width_of(&text) <= column,
                "{context}: {text:?} is wider than its {column}pt column"
            );
            assert_eq!(
                Some(rung),
                want,
                "{context}: the byline painted rung {rung} ({text:?}), but the longest form its {column}pt column fits is rung {want:?}"
            );
            if large_type_narrow {
                assert!(
                    rung >= 2,
                    "{context}: large-type narrow keeps the author, never the company or the site: {text:?}"
                );
            }
            assert_eq!(
                label.as_deref(),
                Some(text.as_str()),
                "{context}: the byline reads out the line it paints"
            );
            rungs_seen[rung] += 1;
            Some(rung)
        } else {
            assert_eq!(
                want, None,
                "{context}: the hero authored no byline, yet rung {want:?} fits its {column}pt column"
            );
            omissions += 1;
            None
        };
        Some((painted_rung, large_type_narrow))
    };
    // From 120pt: this product's own window floor is 164 LOGICAL points wide
    // (`App::whole_cell_min_size`), so the narrow band below the old 240pt
    // sweep start is shipping geometry, not a synthetic one.
    // 336pt tall puts a 480-760pt compact host in the landscape pager,
    // where the hero shares its row with the fixed-width side pager.
    for height in [558.0_f32, 336.0, 400.0, 820.0] {
        sample_where_it_changes(120.0, 1_320.0, coarse, resolution, |width| {
            at(width, height)
        });
    }
    assert!(
        rungs_seen[0] > 0,
        "the sweep paints the whole byline somewhere at {scale}×: {rungs_seen:?}"
    );
    assert!(
        rungs_seen[3] > 0,
        "the sweep reaches the author's short form at {scale}×: {rungs_seen:?}"
    );
    assert!(
        omissions > 0,
        "the sweep reaches a column no rung fits at {scale}×, so the omission arm above is not vacuous"
    );

    if scale == 1.0 {
        let hero = byline_at(286.5, 558.0).expect("the phone About hero paints its byline");
        let (text, audit, label) = hero.painted.expect("the phone hero keeps a byline");
        assert_eq!(
            text, author_company,
            "the phone column keeps author and company"
        );
        assert_eq!(label.as_deref(), Some(author_company));
        assert!(
            (hero.column - 206.5).abs() < 0.05,
            "phone byline column: {}",
            hero.column
        );
        assert!(audit.contains(" overflow=false "), "{audit}");
        assert!(
            rungs_seen[1] > 0,
            "the 1× sweep crosses from the whole byline to author and company: {rungs_seen:?}"
        );
        // The wide window AND the 474pt compact hero (a width the 7.5pt sweep
        // steps over) paint the WHOLE byline — author · company · site, where
        // aterm comes from, on the hero itself. Spelled as a literal rather
        // than read from the constants the ladder is built from, so a reworded
        // separator or a dropped company fails here. Company is part of that
        // shared byline, not a build-metadata row.
        let whole = format!(
            "By Andrew Yates \u{00b7} ALab \u{00b7} {}",
            aterm_types::identity::SITE
        );
        for (width, height) in [(1_200.0_f32, 820.0_f32), (474.0, 658.0)] {
            let hero = byline_at(width, height).expect("the About hero paints");
            let (text, audit, label) = hero.painted.expect("the hero keeps a byline");
            assert_eq!(text, whole, "{width}x{height}: the whole byline, rung 0");
            assert_eq!(label.as_deref(), Some(whole.as_str()), "{width}x{height}");
            assert!(
                audit.contains(" overflow=false "),
                "{width}x{height}: {audit}"
            );
            let cx = view_cx_at(width, height);
            let compiled = runtime
                .render(instance, view, &cx)
                .unwrap()
                .compile(cx.viewport)
                .unwrap();
            assert!(
                compiled
                    .semantic(&UiKey::new("about/provenance/row/company"))
                    .is_none(),
                "{width}x{height}: company is part of the shared byline, not build metadata"
            );
        }
    }

    if scale == 2.0 {
        // THE RED THAT EXTENDED THIS LADDER (2026-09-17). A 240pt host at 2×
        // gives the hero a 164.0pt column; `Andrew Yates` measured 164.6pt in
        // the UI face of the x86_64 Linux host that left that red (3091ede3b),
        // so the old floor rung painted "Andrew Yat…" there.
        //
        // THAT 0.6pt IS THE WHOLE MARGIN, and it is a font measurement, not
        // a layout one: the column is arithmetic (164.0pt on every host, so
        // it is asserted below), while the string's width is whatever this
        // host's UI face makes it. Measured 2026-09-17 on a 2017 MacBook Pro
        // (macOS 13.7.8, x86_64): the same name measures 156.884pt there and
        // FITS, so asserting the overflow made the ladder's law unprovable on
        // that host rather than wrong. The law is therefore READ from the
        // measurement — the painted rung is the longest that fits, whichever
        // that is — and the arm the host cannot exercise says so on stderr
        // instead of passing quietly.
        //
        // MEASURED AGAIN 2026-09-18 on an Apple silicon Mac (Darwin 25.6,
        // this repo's Trust toolchain), where main carried this test as red
        // at 3091ede3b: the assertion that failed there was the premise
        // `width_of(author) > hero.column` — "the full name really does not
        // fit the 240pt column: 156.884 vs 164" — the very number the Intel
        // Mac gave. Both Macs load the same UI face and measure it to the
        // same 156.884pt, so the 164.6pt was the Linux host's face and not
        // an x86_64-versus-arm64 or a headless-harness difference (the
        // harness on this host finds the UI face; `ui_text_width` only
        // falls back to 0.6 em per char when no face loads, which would
        // measure the name at 12 × 15.6pt = 187.2pt and step it DOWN). The
        // ladder code was right on every host; the test's premise was one
        // host's font width, and a16b7707e/c507804d2 replaced it with the
        // measurement below. Green here 5× alone and inside the full
        // `targo --unverified test -p aterm-gui --lib` on 2026-09-18.
        let hero = byline_at(240.0, 558.0).expect("a 240pt host paints the full About hero");
        assert!(hero.large_type_narrow);
        assert!(
            (hero.column - 164.0).abs() < 0.05,
            "the 240pt hero column: {}",
            hero.column
        );
        // THE RUNG THIS HOST'S FACE LEAVES, read the whole ladder down rather
        // than assumed one step in: the longest rung that fits is what must be
        // painted, and if the face is wide enough that even the short form
        // overflows, the honest answer is no byline at all — the same law the
        // 150pt arm below asserts. Nothing here is a font premise.
        let name_width = width_of(author);
        let want = [author, author_short]
            .into_iter()
            .find(|rung| width_of(rung) <= hero.column);
        match (want, hero.painted.as_ref()) {
            (Some(rung), Some((text, audit, label))) => {
                let law = if rung == author {
                    "a column the full name fits paints it whole and never steps below it"
                } else {
                    "a column the full name overflows steps to the author's short form"
                };
                assert_eq!(text, rung, "{law} ({name_width}pt vs {}pt)", hero.column);
                assert_eq!(label.as_deref(), Some(rung), "{law}");
                assert!(audit.contains(" overflow=false "), "{audit}");
            }
            (None, painted) => assert!(
                painted.is_none(),
                "no rung fits this host's {}pt column ({author_short:?} needs {}pt), so the \
                 hero authors NO byline rather than an elided name",
                hero.column,
                width_of(author_short)
            ),
            (Some(rung), None) => panic!(
                "{rung:?} fits the {}pt column, so the hero must paint it",
                hero.column
            ),
        }
        if want == Some(author) {
            // ONE comparison governs both the law above and this line: it is
            // keyed off the rung that was chosen, never a second copy of the
            // condition. Written to the stderr handle rather than `eprintln!`
            // so a waived measurement shows in every run, not only a failing
            // one: libtest captures the macro's output and keeps it from a
            // passing test.
            use std::io::Write as _;
            let line = format!(
                "native_about_byline_steps_down_to_the_longest_form_its_column_fits: the \
                 240pt / 2× step-down is NOT exercised at this width on this host: {author:?} measures {name_width}pt in this UI face against a {}pt \
                 column, so the full name fits. It measured 164.6pt on the x86_64 Linux \
                 host that extended this ladder (3091ede3b); the comment above this arm \
                 records both. The longest rung that fits is asserted instead, and the \
                 sweep above still reaches the short form at this scale, so the floor rung \
                 is exercised here — just not at 240pt.\n",
                hero.column
            );
            let _ = std::io::stderr().write_all(line.as_bytes());
        }

        // And the decision below the last rung: a column too small for even
        // the short form authors NO byline rather than an elided name.
        let hero = byline_at(150.0, 558.0).expect("a 150pt host still paints the About hero");
        assert!(
            width_of(author_short) > hero.column,
            "no rung fits the 150pt host's {}pt column",
            hero.column
        );
        assert!(
            hero.painted.is_none(),
            "a column no rung fits paints no byline at all"
        );
        // What makes that omission survivable rather than a loss: author,
        // company and site are PROVENANCE rows, so the route's own
        // `Copy Build Information` block still carries every fact the
        // byline would have said. That is why the hero may drop the line.
        let provenance = crate::about::provenance_text();
        for fact in [
            crate::build_info::AUTHOR_ATTRIBUTION,
            crate::build_info::COMPANY,
            aterm_types::identity::SITE,
        ] {
            assert!(
                provenance.contains(fact),
                "the About provenance block still carries {fact:?}: {provenance}"
            );
        }
    }
}

#[test]
fn watcher_warning_is_global_separate_from_action_feedback_and_recovery_clears_it() {
    let (mut runtime, instance, view) = setup();
    let AppViewState::Settings(state) = runtime.view_state_mut(view).unwrap() else {
        panic!("Settings view state");
    };
    state.feedback = Some("Undo available".to_string());
    state.config_watch_status =
        Some("aterm.toml reload rejected: the file is not valid UTF-8.".to_string());

    let cx = view_cx_at(568.0, 420.0);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert!(
        compiled
            .semantic(&UiKey::new("settings/config-watch-status/detail"))
            .is_some_and(|node| node.label.contains("not valid UTF-8")),
        "the watcher failure is visible on the current Settings route"
    );
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/status"))
            .map(|node| node.label.as_str()),
        Some("Undo available"),
        "persistent watcher status must not overwrite ordinary feedback"
    );

    let AppViewState::Settings(state) = runtime.view_state_mut(view).unwrap() else {
        panic!("Settings view state");
    };
    state.config_watch_status = None;
    let recovered = compile_settings_view(&runtime, instance, view, &cx);
    assert!(
        recovered
            .semantic(&UiKey::new("settings/config-watch-status"))
            .is_none(),
        "recovery clears only the watcher banner"
    );
    assert_eq!(
        recovered
            .semantic(&UiKey::new("settings/status"))
            .map(|node| node.label.as_str()),
        Some("Undo available")
    );
}

/// 2026-08 settings audit: a wide global search whose top match drives the
/// renderer preview ("kitty") painted page 1 as '1–1 of 3' with the Manual
/// editor card alone — ZERO native result rows — while every actual
/// control hid on later pages. A Medium/Wide page must list the Manual
/// result inline WITH the native rows it summarizes.
#[test]
fn wide_search_page_one_lists_native_rows_beside_the_manual_result() {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("settings/search"),
                value: Some(SemanticInput::Text("kitty".to_string())),
            }),
        )
        .unwrap();
    let cx = view_cx_at(1_275.0, 828.0);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new("settings/search/manual-result"))
            .is_some(),
        "the Manual editor result stays a first-class search result"
    );
    let rows: Vec<&str> = compiled
        .semantics
        .iter()
        .map(|node| node.key.as_str())
        .filter(|key| key.starts_with("settings/row/"))
        .collect();
    assert!(
        !rows.is_empty(),
        "page 1 of a wide search must list native result rows, not only the Manual card"
    );
    assert!(
        rows.iter().any(|key| key.ends_with("cursor_trail_style")),
        "the ranked native match paints on page 1: {rows:?}"
    );
    // The window the pager/summary reports covers what is actually painted:
    // the Manual card plus every native row fits this viewport, so the
    // page reports the complete roster instead of a phantom '1–1 of 3'.
    let range = compiled
        .semantic(&UiKey::new("settings/results-range"))
        .expect("search results always disclose their visible window");
    assert_eq!(range.label, "2 settings · 9 Manual config keys");
    // Later pages keep the classic one-result-per-step window (the audit
    // found only page 1 broken).
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("settings/page-down"),
                value: None,
            }),
        )
        .unwrap();
    let paged = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(
        paged
            .semantic(&UiKey::new("settings/results-range"))
            .map(|node| node.label.as_str()),
        Some("2–3 of 3")
    );
    assert!(
        paged
            .semantics
            .iter()
            .any(|node| node.key.as_str().starts_with("settings/row/")),
        "page 2 keeps its native rows"
    );
}

/// Every visual line the painter is handed for one wrapped copy block, in
/// paint order.
fn painted_copy_lines(compiled: &crate::native_ui::CompiledUi, key: &str) -> Vec<String> {
    let prefix = format!("{key}/line-");
    compiled
        .paint
        .iter()
        .filter(|node| node.key.as_str().starts_with(prefix.as_str()))
        .map(|node| match &node.content {
            UiContent::Text(spec) => spec.text.clone(),
            other => panic!("{key} paints something other than text: {other:?}"),
        })
        .collect()
}

fn settings_route_at(state: &SettingsViewState, cx: &ViewCx<'_>) -> crate::native_ui::CompiledUi {
    settings_tree(
        state,
        &UpdateState::from_status(1, "0.1.0", None, false).projection(),
        &PackagesState::unobserved().projection(),
        &MessagesState::empty(),
        cx,
    )
    .compile(cx.viewport)
    .expect("Settings compiles")
}

fn builtin_title_summary_health() -> TitleSummaryHealth {
    TitleSummaryHealth {
        state: TitleSummaryRuntimeState::Builtin,
        provider: crate::app_config::TitleSummaryProvider::Builtin,
        model: None,
        endpoint: None,
        locality: TitleSummaryLocality::NotApplicable,
        managed_install_present: false,
        model_ready: false,
        last_error: None,
        next_retry_after: None,
        next_refresh_after: None,
        timeout: None,
        proxy_mode: None,
        ca_file: None,
    }
}

/// THE SHIPPED DEFAULT WINDOW CAN READ ITS OWN EXPLANATORY COPY.
///
/// 80×24 is a 744×420 app viewport (`app_config.rs`), and three long
/// settings strings were authored as ONE fixed line there, so the painter
/// ellipsized them — 280.6, 108.7 and 209.1 points of text discarded with
/// no tooltip, wrap, scroll or selection to get any of it back (2026-09
/// settings audit):
///
/// * `settings/top/wallpaper/description` — required 968.6 against 688.0
/// * `settings/wallpaper/hint` — the ONLY pointer to where the wallpaper
///   dim and text-tint controls live, required 796.7
/// * `settings/smart-titles/health/summary` — required 897.1, losing the
///   clause that reports whether the provider errored, and in the error
///   case the error text itself, since `detail` is composed last
///
/// The first two were never a compact-layout property: [`page_insets`]
/// caps the content column at [`page_maximum`]'s 720 in EVERY width class,
/// so they were unreadable at every window size. (Both are one short line
/// now; the wrap path stays, and this still proves nothing is elided.) The
/// renderer's own fit
/// audit is the judge — `overflow=true` is the painter reporting that it
/// elided — and the complete sentence has to survive on the semantic label
/// as well as on glass.
#[test]
fn long_settings_copy_wraps_instead_of_one_elided_line() {
    // 80×24, the shipped default, and a roomy Wide host.
    for (width, height) in [(744.0_f32, 420.0_f32), (1_464.0, 796.0)] {
        let mut state = SettingsViewState::new(&Config::default());
        state.navigate(SettingsRoute::Wallpaper);
        let cx = view_cx_at(width, height);
        let compiled = settings_route_at(&state, &cx);
        let context = format!("Wallpaper at {width}×{height}");
        assert_zero_top_paint(&compiled, &context);

        for (key, tail) in [
            (
                "settings/top/wallpaper/description",
                "still paint over the picture.",
            ),
            ("settings/wallpaper/hint", "are set in Manual."),
        ] {
            let label = compiled
                .semantic(&UiKey::new(key))
                .unwrap_or_else(|| panic!("{context}: {key} is a semantic node"))
                .label
                .clone();
            assert!(
                label.ends_with(tail),
                "{context}: {key} keeps its whole sentence: {label}"
            );
            let painted = painted_copy_lines(&compiled, key);
            assert!(
                painted.iter().all(|line| !line.contains('…')),
                "{context}: {key} paints no ellipsis: {painted:?}"
            );
            assert_eq!(
                painted
                    .join(" ")
                    .split_whitespace()
                    .collect::<Vec<_>>()
                    .join(" "),
                label.split_whitespace().collect::<Vec<_>>().join(" "),
                "{context}: {key} paints every word it claims"
            );
        }
    }

    // THE WINDOW PAGE'S CONSOLIDATED RUNTIME ROW. Compact joins the four
    // composed clauses into one line; the wide layout already publishes
    // them as six separate rows, so only the join was ever clipped.
    const SUMMARY: &str = "settings/smart-titles/health/summary";
    let mut state = SettingsViewState::new(&Config::default());
    state.navigate(SettingsRoute::WindowTabs);
    assert!(state.replace_title_summary_health(builtin_title_summary_health()));
    let cx = view_cx_at(744.0, 420.0);
    let compiled = settings_route_at(&state, &cx);
    assert_zero_top_paint(&compiled, "Window at 744×420");
    let painted = painted_copy_lines(&compiled, SUMMARY);
    assert!(
        painted
            .last()
            .is_some_and(|line| line.ends_with("nothing is sent.")),
        "the whole consolidated row reaches glass: {painted:?}"
    );
    assert!(
        painted.iter().all(|line| !line.contains('…')),
        "the consolidated row paints no ellipsis: {painted:?}"
    );

    // THE ERROR CASE is the one that mattered most: `detail` is composed
    // LAST, so a single clamped line turned the row Danger-red while
    // clipping off the error text that earned the colour.
    let mut failing = builtin_title_summary_health();
    failing.state = TitleSummaryRuntimeState::Error;
    failing.provider = crate::app_config::TitleSummaryProvider::Ollama;
    failing.locality = TitleSummaryLocality::UnattestedLoopback;
    failing.endpoint = Some("http://127.0.0.1:11434/api/chat".to_string());
    failing.timeout = Some(std::time::Duration::from_secs(42));
    failing.proxy_mode = Some(crate::app_config::TitleSummaryProxyMode::Direct);
    failing.last_error = Some("managed runtime is not installed".to_string());
    assert!(state.replace_title_summary_health(failing));
    let compiled = settings_route_at(&state, &cx);
    let painted = painted_copy_lines(&compiled, SUMMARY);
    // Joined: the error may wrap across lines; it must not be clipped.
    assert!(
        painted
            .join(" ")
            .contains("managed runtime is not installed")
            && painted.iter().all(|line| !line.contains('…')),
        "the error text the Danger colour is about reaches glass: {painted:?}"
    );
}

// -----------------------------------------------------------------------
// Settings ▸ Messages (design §4.6).
// -----------------------------------------------------------------------

/// Forty entries as the host would publish them (`App::messages_state`):
/// a folded crash record with its absolute path and an `Open log`, a
/// held staged update whose `Apply now` is spent, a live toolchain meter
/// on the band, then thirty-seven folded config warnings — newest first.
fn sample_messages() -> MessagesState {
    use crate::messages_host::MessageActionView;
    const BASE: u64 = 1_758_470_000_000;
    let at = |id: u64| BASE - (41 - id) * 60_000;
    let entry = |id: u64,
                 tag: &str,
                 severity: &'static str,
                 glyph: char,
                 title: &str,
                 detail: &[&str],
                 state: &'static str,
                 actions: Vec<MessageActionView>| MessageView {
        id,
        at_unix_ms: at(id),
        tag: tag.to_string(),
        severity,
        glyph,
        title: title.to_string(),
        detail: detail.iter().map(|line| (*line).to_string()).collect(),
        state,
        on_glass: None,
        repeats: 1,
        retired_unix_ms: (!matches!(state, "live" | "held")).then_some(at(id) + 30_000),
        superseded_by: None,
        answer: None,
        actions,
        sentences: 1,
    };
    let action = |index: u8, label: &'static str, still_actionable: bool| MessageActionView {
        index,
        label,
        still_actionable,
        declines: false,
    };
    let mut entries = vec![
        entry(
            40,
            "crash",
            "error",
            '\u{2715}',
            "aterm closed unexpectedly last time",
            &[
                "crash log at /Users//w/Library/Logs/aterm/crash-signal-11-1.log.seen",
                "signal 11 (SIGSEGV) in the render thread while compositing the frame",
            ],
            "folded",
            vec![action(0, "Open log", true)],
        ),
        entry(
            39,
            "update",
            "success",
            '\u{2713}',
            "aterm 0.91.0 is ready",
            &["build 1234 \u{2014} verified and ready to apply"],
            "held",
            vec![
                action(0, "Install now", false),
                action(1, "Software Update", true),
            ],
        ),
        entry(
            38,
            "toolchain",
            "info",
            '\u{21e3}',
            "Installing ALab toolchain",
            &["trust \u{00b7} extracting"],
            "live",
            vec![action(0, "Packages", true)],
        ),
    ];
    entries[2].on_glass = Some(0);
    for id in (1..=37).rev() {
        entries.push(entry(
            id,
            "config",
            "warn",
            '\u{26a0}',
            &format!("config warning {id}"),
            &["aterm.toml: unknown key `foo` at line 12"],
            "folded",
            Vec::new(),
        ));
    }
    MessagesState {
        revision: 7,
        now_unix_ms: BASE,
        entries,
        tags: vec![
            ("crash".to_string(), 1),
            ("config".to_string(), 37),
            ("update".to_string(), 1),
            ("toolchain".to_string(), 1),
        ],
        log_folder: Some("/Users//w/Library/Logs/aterm".to_string()),
        saved: true,
        utc_offset_s: 0,
    }
}

/// [`sample_messages`] spread over the reader's calendar (design ruling
/// 273), newest first, the reader at UTC on Sunday 2025-09-21 15:53:20:
/// #40–#38 today, #37–#31 yesterday, #30–#21 on Thursday, #20–#11 on
/// Friday 12 September, #10–#1 on 17 August 2024 — each group a minute
/// apart from 3:10 PM down.
fn multi_day_messages() -> MessagesState {
    const DAY: u64 = 86_400_000;
    let mut state = sample_messages();
    let now = state.now_unix_ms;
    // 15:10:00 UTC on the reader's day.
    let afternoon = now - (43 * 60 + 20) * 1000;
    for entry in &mut state.entries {
        let (days, first) = match entry.id {
            38..=40 => continue,
            31..=37 => (1, 37),
            21..=30 => (3, 30),
            11..=20 => (9, 20),
            _ => (400, 10),
        };
        entry.at_unix_ms = afternoon - days * DAY - (first - entry.id) * 60_000;
        entry.retired_unix_ms = entry.retired_unix_ms.map(|_| entry.at_unix_ms + 30_000);
    }
    state
}

/// The day headers a compiled page shows, top to bottom.
fn message_days(compiled: &crate::native_ui::CompiledUi) -> Vec<String> {
    compiled
        .semantics
        .iter()
        .filter(|node| {
            node.key.as_str().starts_with("settings/messages/day/")
                && !node.key.as_str().ends_with("/group")
        })
        .map(|node| node.label.clone())
        .collect()
}

/// A Settings controller holding [`sample_messages`], its view on the
/// Messages route.
fn setup_with_messages() -> (
    NativeRuntime,
    crate::native_app::AppInstanceId,
    crate::native_app::ViewId,
) {
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_messages(sample_messages(), 7));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Messages),
                value: None,
            }),
        )
        .unwrap();
    (runtime, instance, view)
}

/// The deep link's action, as `App::open_messages_entry` dispatches it.
fn select_message(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    id: u64,
) {
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(MESSAGES_SELECT),
                value: Some(SemanticInput::Text(id.to_string())),
            }),
        )
        .unwrap();
}

/// One page action, by its id.
fn messages_action(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    action: &str,
) -> Vec<AppEffect> {
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(action),
                value: None,
            }),
        )
        .unwrap()
        .effects
}

/// The ids of the rows a compiled page shows, in page order.
fn message_rows(compiled: &crate::native_ui::CompiledUi) -> Vec<u64> {
    compiled
        .semantics
        .iter()
        .filter_map(|node| {
            node.key
                .as_str()
                .strip_prefix("settings/messages/row/")?
                .strip_suffix("/title")?
                .parse::<u64>()
                .ok()
        })
        .collect()
}

fn messages_view_state(
    runtime: &NativeRuntime,
    view: crate::native_app::ViewId,
) -> &SettingsViewState {
    match runtime.view_state(view) {
        Some(AppViewState::Settings(state)) => state,
        _ => panic!("a Settings view"),
    }
}

/// THE LOG SCROLLED END TO END (ruling 264): compile the page at `cx`,
/// hand each view to `visit` with its index, and scroll `step` entries on
/// — the `ScrollLines` the wheel, the arrow keys and a screen reader's
/// scroll on the list all send — until the list stops at its end.
/// Returns how many views it visited.
fn scroll_messages_through(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    cx: &ViewCx<'_>,
    step: i32,
    mut visit: impl FnMut(&crate::native_ui::CompiledUi, usize),
) -> usize {
    for k in 0..600 {
        let compiled = compile_settings_view(runtime, instance, view, cx);
        visit(&compiled, k);
        let before = messages_view_state(runtime, view)
            .messages_drawn
            .get()
            .expect("the render drew a stop");
        runtime
            .dispatch(instance, view, AppEvent::ScrollLines(step))
            .unwrap();
        if messages_view_state(runtime, view).page_scroll == before {
            return k + 1;
        }
    }
    panic!("the list never reached its end");
}

/// DAY HEADERS (design ruling 273): a log that spans more than one of
/// the reader's local days is sectioned newest first — `Today`,
/// `Yesterday`, the weekday within the week, then the date, with the year
/// only off this year. A header is a heading for a screen reader and
/// never a control (no action, not in the focus order, skipped by the
/// arrow keys); it stands at the lead column's time x, every title keeps
/// one origin, and a row under a past day says its local time. The list's
/// top entry always carries its day's header, wherever the scroll stands.
/// A filter hides a day it admits nothing from; a log of one day carries
/// none.
#[test]
fn the_log_is_sectioned_by_the_readers_local_day() {
    let (mut runtime, instance, view) = setup_with_messages();
    assert!(runtime.replace_settings_messages(multi_day_messages(), 8));
    let cx = view_cx_at(1_200.0, 820.0);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    let days = message_days(&compiled);
    assert_eq!(days.first().map(String::as_str), Some("Today"), "{days:?}");
    assert!(days.len() >= 2, "a multi-day view shows two days: {days:?}");
    let rows = message_rows(&compiled);
    let paint = |key: String| {
        compiled
            .paint
            .iter()
            .find(|node| node.key.as_str() == key)
            .unwrap_or_else(|| panic!("{key} paints"))
            .clone()
    };
    let origins: Vec<f32> = rows
        .iter()
        .map(|id| paint(format!("settings/messages/row/{id}/label")).rect.x)
        .collect();
    assert!(
        origins.iter().all(|x| (x - origins[0]).abs() < 0.01),
        "one title origin under the headers: {origins:?}"
    );
    let when_x = paint(format!("settings/messages/row/{}/when", rows[0]))
        .rect
        .x;
    for node in compiled.semantics.iter().filter(|node| {
        node.key.as_str().starts_with("settings/messages/day/")
            && !node.key.as_str().ends_with("/group")
    }) {
        assert_eq!(node.role, SemanticRole::Heading, "{}", node.label);
        assert!(node.action.is_none(), "a header is no control");
        assert!(
            !compiled.focus_order.contains(&node.key),
            "the keyboard never lands on a header"
        );
        assert!(
            (node.rect.x - when_x).abs() < 0.01,
            "the header stands over the times: {} vs {when_x}",
            node.rect.x
        );
    }
    let when = |compiled: &crate::native_ui::CompiledUi, id: u64| {
        compiled
            .paint
            .iter()
            .find(|node| node.key.as_str() == format!("settings/messages/row/{id}/when"))
            .map(|node| match &node.content {
                UiContent::Text(spec) => spec.text.clone(),
                other => panic!("{other:?}"),
            })
    };
    assert_eq!(when(&compiled, 40).as_deref(), Some("1 min ago"), "today");
    assert_eq!(when(&compiled, 37).as_deref(), Some("3:10 PM"), "yesterday");

    // Scrolled end to end: every day once, in order, each view's first
    // entry under its own day's header.
    let mut seen: Vec<String> = Vec::new();
    scroll_messages_through(&mut runtime, instance, view, &cx, 1, |compiled, k| {
        let days = message_days(compiled);
        let top_day = compiled
            .semantics
            .iter()
            .find(|node| node.key.as_str().starts_with("settings/messages/day/"))
            .unwrap_or_else(|| panic!("view {k} opens under a header"));
        let first_row = message_rows(compiled)[0];
        let row = compiled
            .semantic(&UiKey::new(format!(
                "settings/messages/row/{first_row}/title"
            )))
            .expect("the first row");
        assert!(top_day.rect.y < row.rect.y, "view {k}: the header leads");
        for day in days {
            if !seen.contains(&day) {
                seen.push(day);
            }
        }
    });
    assert_eq!(
        seen,
        [
            "Today",
            "Yesterday",
            "Thursday",
            "Friday, 12 September",
            "Saturday, 17 August 2024",
        ],
    );

    // The arrow keys step from today's last entry to yesterday's first,
    // past the header between them.
    let (mut runtime, instance, view) = setup_with_messages();
    assert!(runtime.replace_settings_messages(multi_day_messages(), 8));
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.common.last_focus = Some(UiKey::new("settings/messages/row/38/title"));
    }
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(1))
        .unwrap();
    assert_eq!(
        messages_view_state(&runtime, view)
            .common
            .last_focus
            .as_ref()
            .map(UiKey::as_str),
        Some("settings/messages/row/37/title")
    );

    // A filter hides a day it admits nothing from: the config warnings
    // start yesterday.
    let _ = messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/tag/config",
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(
        message_days(&compiled).first().map(String::as_str),
        Some("Yesterday")
    );

    // A log of one day: no header, and the rows keep their relative words.
    let (runtime, instance, view) = setup_with_messages();
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert!(message_days(&compiled).is_empty());
    assert_eq!(when(&compiled, 40).as_deref(), Some("1 min ago"));
}

// `a_stamp_from_tomorrow_is_todays` (ruling 281) pins the day clock alone and
// moved with it to the engine: `aterm_messages::page_tests` (design ruling 382).

/// ONE PAST DAY IS STILL HEADED, AND THE TITLES NEVER MOVE WITH THE
/// FILTER (round 18, day four, D12/D13): a filter that left one past day
/// showed no header and a raw `2026-09-24` in the time column, and the
/// title column stood at x 816, 788 or 718 as the filter changed.
/// NEGATIVE CONTROL: a list of only today still carries no header (the
/// test above).
#[test]
fn one_past_day_is_headed_and_the_titles_hold_their_x_across_filters() {
    const DAY: u64 = 86_400_000;
    let cx = view_cx_at(1_200.0, 820.0);
    // Every entry on ONE past local day (Thursday, three days back), a
    // minute apart: the rule before D12's fix (headed only when the
    // entries span two days) heads none of it.
    let mut past = sample_messages();
    let thursday = past.now_unix_ms - 3 * DAY;
    for entry in &mut past.entries {
        entry.at_unix_ms = thursday - (40 - entry.id) * 60_000;
        entry.retired_unix_ms = entry.retired_unix_ms.map(|_| entry.at_unix_ms + 30_000);
    }
    let (mut runtime, instance, view) = setup_with_messages();
    assert!(runtime.replace_settings_messages(past, 8));
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let days = message_days(&compiled);
    assert_eq!(
        days.len(),
        1,
        "one past day carries its one header: {days:?}"
    );
    let rows = message_rows(&compiled);
    let when_of = |compiled: &crate::native_ui::CompiledUi, id: u64| {
        compiled
            .paint
            .iter()
            .find(|node| node.key.as_str() == format!("settings/messages/row/{id}/when"))
            .map(|node| match &node.content {
                UiContent::Text(spec) => spec.text.clone(),
                other => panic!("{other:?}"),
            })
            .expect("a time")
    };
    let first = when_of(&compiled, rows[0]);
    assert!(
        !first.contains('-') && (first.ends_with("AM") || first.ends_with("PM")),
        "a clock under its day, never a date: {first}"
    );

    // The titles' x across the filters.
    let (mut runtime, instance, view) = setup_with_messages();
    assert!(runtime.replace_settings_messages(multi_day_messages(), 8));
    let title_x = |runtime: &NativeRuntime| {
        let compiled = compile_settings_view(runtime, instance, view, &cx);
        let rows = message_rows(&compiled);
        compiled
            .paint
            .iter()
            .find(|node| node.key.as_str() == format!("settings/messages/row/{}/label", rows[0]))
            .expect("a title")
            .rect
            .x
    };
    let all = title_x(&runtime);
    let _ = messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/tag/config",
    );
    let filtered = title_x(&runtime);
    assert!(
        (all - filtered).abs() < 0.01,
        "the titles hold their x: {all} vs {filtered}"
    );
}

/// Settings ▸ Messages's TOP switch (design §10.14, ruling 212): "Explain
/// heavy load" — the registry's `explain_heavy_load` Bool, resolved ON by
/// default — at its deep-link key, with a visible label the pixel tray
/// keeps, an accessible name, and the ordinary `settings/set/<key>`
/// action, at the top of the page at every width, above the log.
#[test]
fn the_messages_page_carries_the_explain_heavy_load_switch() {
    let key = prefs::EDIT_EXPLAIN_HEAVY_LOAD;
    for (width, height) in [(1_200.0, 820.0), (320.0, 568.0)] {
        // On a compact page the switch heads the list's top and scrolls
        // away with it (rulings 262 and 264).
        let (runtime, instance, view) = setup_with_messages();
        let cx = view_cx_at(width, height);
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        compiled.validate_parity().unwrap();
        let at = format!("{width}x{height}");
        let row = compiled
            .semantic(&UiKey::new(MESSAGES_EXPLAIN_LOAD))
            .unwrap_or_else(|| panic!("the switch row at its deep-link key ({at})"));
        assert_eq!(row.label, "Explain heavy load", "{at}");
        let control = compiled
            .semantic(&UiKey::new(format!("settings/control/{key}")))
            .unwrap_or_else(|| panic!("the switch ({at})"));
        assert_eq!(
            control.value,
            SemanticValue::Bool(true),
            "default ON ({at})"
        );
        assert!(
            control.label.starts_with("Explain heavy load"),
            "the accessible name ({at}): {}",
            control.label
        );
        assert_eq!(
            compiled
                .semantic(&UiKey::new(format!("settings/label/{key}")))
                .map(|node| node.label.as_str()),
            Some("Explain heavy load"),
            "a visible label ({at})"
        );
        assert!(
            compiled
                .hits
                .iter()
                .any(|hit| hit.key.as_str() == format!("settings/control/{key}")),
            "activatable ({at})"
        );
        let tray = compiled.tray(aterm_render::Theme::default(), 13.0);
        assert!(
            tray.prims.iter().any(|prim| matches!(
                prim,
                crate::widget::DrawPrim::Text { s, .. } if s == "Explain heavy load"
            )),
            "the label survives lowering into the pixel tray ({at})"
        );
        // A plain switch: no boxed `On` beside it.
        assert!(
            !tray.prims.iter().any(|prim| matches!(
                prim,
                crate::widget::DrawPrim::Text { s, .. } if s == "On" || s == "Off"
            )),
            "no On pill ({at})"
        );
        assert_eq!(
            compiled
                .semantic(&UiKey::new(format!("{MESSAGES_EXPLAIN_LOAD}/caption")))
                .map(|node| node.label.as_str()),
            Some(MESSAGES_EXPLAIN_LOAD_CAPTION),
            "its one caption line ({at})"
        );
        let first_row = compiled
            .semantics
            .iter()
            .filter(|node| node.key.as_str().ends_with("/title"))
            .find(|node| node.key.as_str().starts_with("settings/messages/row/"))
            .map(|node| node.rect.y);
        let row_y = first_row.unwrap_or_else(|| panic!("the log under it ({at})"));
        assert!(
            row.rect.bottom() <= row_y,
            "the switch above the log ({at})"
        );
        assert!(
            compiled
                .semantic(&UiKey::new("settings/messages/pagination"))
                .is_none(),
            "no pager ({at})"
        );
    }
    assert_eq!(
        prefs::section_of(key),
        prefs::Section::Performance,
        "no ordinary page double-lists it; Search and Modified find it"
    );
}

/// A SCREEN READER SCROLLS THE LOG (ruling 264): with no pager, the log's
/// card is a `List` carrying accesskit's scroll actions, and a scroll on
/// it routes to the same `ScrollLines` the wheel sends — the list moves
/// by those entries, and the rows that come into view are disclosure
/// buttons named by their titles, as before.
#[cfg(a11y_tree)]
#[test]
fn a_screen_reader_scrolls_the_log_list() {
    use crate::native_accessibility::{
        PublishedNativeAccessibility, RoutedAccessibilityAction, project_native_accessibility,
        route_accessibility_action,
    };
    use accesskit::{Action, Role, TreeId};
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx();
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let projection = project_native_accessibility(&compiled, None).unwrap();
    let list = projection
        .id_for_key(&UiKey::new("settings/messages/list"))
        .expect("the list is published");
    let node = projection
        .update()
        .nodes
        .iter()
        .find(|(id, _)| *id == list)
        .map(|(_, node)| node.clone())
        .expect("the list's node");
    assert_eq!(node.role(), Role::List);
    assert_eq!(node.label(), Some("Messages"));
    assert!(node.supports_action(Action::ScrollDown));
    assert!(node.supports_action(Action::ScrollUp));
    let (_, routes) = projection.into_update_and_routes();
    let published = PublishedNativeAccessibility::new(view, 1, routes);
    let routed = route_accessibility_action(
        &published,
        &accesskit::ActionRequest {
            action: Action::ScrollDown,
            target_tree: TreeId::ROOT,
            target_node: list,
            data: None,
        },
    )
    .expect("a scroll on the list routes");
    let RoutedAccessibilityAction::Scroll { lines, .. } = routed else {
        panic!("{routed:?}");
    };
    let before = message_rows(&compiled);
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(lines))
        .unwrap();
    let after = message_rows(&compile_settings_view(&runtime, instance, view, &cx));
    let step = usize::try_from(lines).unwrap();
    assert_eq!(
        after[0], before[step],
        "scrolled {lines} entries: {before:?} → {after:?}"
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let last = compiled
        .semantic(&UiKey::new(format!(
            "settings/messages/row/{}/title",
            after[after.len() - 1]
        )))
        .expect("the row scrolled into view");
    assert_eq!(last.role, SemanticRole::Button);
    assert_eq!(last.state.and_then(|state| state.expanded), Some(false));
}

/// The page is the log newest first; the chips are the tags PRESENT, in
/// the fixed order with their counts; a chip narrows the rows and the
/// status line counts what it admits; All puts everything back.
#[test]
fn messages_page_lists_newest_first_and_filters_by_tag() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx();
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    assert!(
        compiled
            .semantic(&UiKey::new("settings/page/messages"))
            .is_some(),
        "the /messages route owns its own page"
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/nav/messages"))
            .is_some(),
        "the rail exposes the Messages destination"
    );
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/page-heading/messages"))
            .map(|node| node.label.as_str()),
        Some("Messages")
    );
    let shown = message_rows(&compiled);
    assert!(shown.len() >= 4, "{shown:?}");
    assert_eq!(shown[0], 40, "newest first");
    assert!(shown.windows(2).all(|pair| pair[0] > pair[1]), "{shown:?}");
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/messages/status"))
            .map(|node| node.label.as_str()),
        Some("40 messages")
    );
    let chips = |compiled: &crate::native_ui::CompiledUi| {
        compiled
            .semantics
            .iter()
            .filter(|node| node.key.as_str().starts_with("settings/messages/filter/"))
            .map(|node| {
                (
                    node.label.clone(),
                    node.state.is_some_and(|state| state.selected),
                )
            })
            .collect::<Vec<_>>()
    };
    assert_eq!(
        chips(&compiled),
        [
            ("All \u{00b7} 40".to_string(), true),
            ("Problems \u{00b7} 38".to_string(), false),
            ("All tags".to_string(), true),
            ("Crashes \u{00b7} 1".to_string(), false),
            ("Config \u{00b7} 37".to_string(), false),
            ("Updates \u{00b7} 1".to_string(), false),
            ("ALab tools \u{00b7} 1".to_string(), false),
        ],
        "the severity segments, then the tags' plain chip names (rulings 66 and \
         262); the action keys keep the tags"
    );
    // ONE SCROLLING LIST (ruling 264): no pages and no pager; the
    // reducer's bound is the stop the list scrolls to, where its view
    // ends on the oldest entry.
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/pagination"))
            .is_none()
            && compiled
                .semantic(&UiKey::new("settings/messages/range"))
                .is_none(),
        "no pager"
    );
    assert!(
        shown.len() >= 14,
        "at least fourteen one-line rows at 1200\u{00d7}820: {}",
        shown.len()
    );
    let limit = messages_view_state(&runtime, view)
        .result_page_limit
        .get()
        .expect("the render bounds the reducer");
    assert_eq!(
        limit,
        40 - shown.len(),
        "the list scrolls until its oldest entry is its last row"
    );
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.page_scroll = limit;
    }
    let end = message_rows(&compile_settings_view(&runtime, instance, view, &cx));
    assert_eq!(end.last(), Some(&1), "the oldest entry closes the list");
    assert_eq!(end.len(), shown.len(), "a full view at the end: {end:?}");
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(3))
        .unwrap();
    assert_eq!(
        messages_view_state(&runtime, view).page_scroll,
        limit,
        "never scrolled past its end"
    );
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.page_scroll = 0;
    }

    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/tag/config",
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let shown = message_rows(&compiled);
    assert!(shown.iter().all(|id| *id <= 37), "config only: {shown:?}");
    assert_eq!(shown[0], 37);
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/messages/status"))
            .map(|node| node.label.as_str()),
        Some("37 of 40")
    );
    assert!(
        chips(&compiled)
            .iter()
            .any(|(label, selected)| label == "Config \u{00b7} 37" && *selected)
    );

    // The severity COMBINES with the tag (ruling 262): config's
    // warnings, the crash (another tag) out.
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/warn",
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let shown = message_rows(&compiled);
    assert_eq!(shown[0], 37, "config's newest warning");
    assert!(!shown.contains(&40), "the crash is another tag: {shown:?}");
    assert!(
        chips(&compiled)
            .iter()
            .any(|(label, selected)| label == "Config \u{00b7} 37" && *selected),
        "the tag stays down"
    );
    // Every tag, the severity kept: the warnings set.
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/tags-all",
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let shown = message_rows(&compiled);
    assert_eq!(shown[0], 40, "the crash leads the warnings set");
    assert!(
        !shown.contains(&39) && !shown.contains(&38),
        "success and info are out: {shown:?}"
    );
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/messages/status"))
            .map(|node| node.label.as_str()),
        Some("38 of 40")
    );

    messages_action(&mut runtime, instance, view, "settings/messages/filter/all");
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(message_rows(&compiled)[0], 40);
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/messages/status"))
            .map(|node| node.label.as_str()),
        Some("40 messages")
    );

    // An empty log: the invitation, no rows, no pager.
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_messages(MessagesState::empty(), 1));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Messages),
                value: None,
            }),
        )
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    assert!(message_rows(&compiled).is_empty());
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/messages/empty"))
            .map(|node| node.label.as_str()),
        Some(MESSAGES_EMPTY)
    );
    // An empty log hides the filters and the count, and has nothing to
    // copy (ruling 262).
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/status"))
            .is_none()
    );
    assert!(
        !compiled
            .semantics
            .iter()
            .any(|node| node.key.as_str().starts_with("settings/messages/filter/")),
        "no filters over nothing"
    );
    assert!(
        compiled
            .semantic(&UiKey::new(MESSAGES_COPY_ALL))
            .and_then(|node| node.state)
            .is_some_and(|state| !state.enabled),
        "Copy All has nothing to copy"
    );
    // One subtitle at every width: the package records are listed here.
    assert_eq!(
        messages_page_subtitle(SettingsWidth::Medium),
        messages_page_subtitle(SettingsWidth::Compact)
    );
    assert!(!messages_page_subtitle(SettingsWidth::Medium).contains("Packages"));
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/range"))
            .is_none()
    );
}

/// THE LOG'S LEAD COLUMN (design ruling 262): every row's title begins at
/// the same x — the severity mark, when and the tag's chip name take one
/// fixed width, measured once per page — the tag reads as its chip's plain
/// words in the page's own face, and a screen reader hears the row's
/// severity, chip and time in words, never the wire's.
#[test]
fn the_log_rows_share_one_lead_column_and_speak_plain_words() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx();
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let rows = message_rows(&compiled);
    assert!(rows.len() >= 14, "{rows:?}");
    let paint = |key: String| {
        compiled
            .paint
            .iter()
            .find(|node| node.key.as_str() == key)
            .unwrap_or_else(|| panic!("{key} paints"))
            .clone()
    };
    let origins: Vec<f32> = rows
        .iter()
        .map(|id| paint(format!("settings/messages/row/{id}/label")).rect.x)
        .collect();
    assert!(
        origins.iter().all(|x| (x - origins[0]).abs() < 0.01),
        "one title origin: {origins:?}"
    );
    // The tag as its chip's words, in the body face (never monospace).
    let tag = paint(format!("settings/messages/row/{}/tag", rows[0]));
    match &tag.content {
        UiContent::Text(spec) => {
            assert_eq!(spec.text, "Crashes");
            assert_ne!(spec.style, StyleRef::Code);
        }
        other => panic!("{other:?}"),
    }
    // The severity mark is the band's drawn icon, decorative.
    assert!(
        compiled
            .semantic(&UiKey::new(format!(
                "settings/messages/row/{}/severity",
                rows[0]
            )))
            .is_none(),
        "the mark is paint-only"
    );
    let tray = compiled.tray(aterm_render::Theme::default(), 13.0);
    assert!(
        tray.prims.iter().any(|prim| matches!(
            prim,
            crate::widget::DrawPrim::BandIcon {
                icon: aterm_render::BandIcon::Error,
                ..
            }
        )),
        "the crash row draws the band's cross"
    );
    assert!(
        tray.prims.iter().any(|prim| matches!(
            prim,
            crate::widget::DrawPrim::BandIcon {
                icon: aterm_render::BandIcon::Download,
                ..
            }
        )),
        "the toolchain row draws its own glyph's icon, as the band does (ruling 263)"
    );
    // The description: plain words.
    let title = compiled
        .semantic(&UiKey::new(format!(
            "settings/messages/row/{}/title",
            rows[0]
        )))
        .expect("the title control");
    assert_eq!(title.state.and_then(|state| state.expanded), Some(false));
    let described = compiled
        .paint
        .iter()
        .find_map(|node| match &node.content {
            UiContent::Button(control)
                if node.key.as_str() == format!("settings/messages/row/{}/title", rows[0]) =>
            {
                control.spec.description.clone()
            }
            _ => None,
        })
        .expect("a description");
    assert!(
        described.starts_with("Error, Crashes, ") && !described.contains('\u{00b7}'),
        "{described}"
    );
    // The arrow keys move between rows: the focus steps down, and a
    // step past the view's last row scrolls the list by that one row
    // (ruling 264).
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.common.last_focus = Some(UiKey::new(format!(
            "settings/messages/row/{}/title",
            rows[0]
        )));
    }
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(1))
        .unwrap();
    assert_eq!(
        messages_view_state(&runtime, view)
            .common
            .last_focus
            .as_ref()
            .map(UiKey::as_str),
        Some(format!("settings/messages/row/{}/title", rows[1]).as_str())
    );
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.common.last_focus = Some(UiKey::new(format!(
            "settings/messages/row/{}/title",
            rows[rows.len() - 1]
        )));
    }
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(1))
        .unwrap();
    assert_eq!(
        messages_view_state(&runtime, view).page_scroll,
        1,
        "the list follows the focus by one row"
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(
        message_rows(&compiled).last(),
        Some(&(rows[rows.len() - 1] - 1)),
        "the newly focused row is the view's last"
    );
}

/// A title press expands its row in place — the meta line, the detail
/// lines wrapped to the page, every authored button with its live
/// enablement, Copy — and a second press folds it back.
#[test]
fn selecting_a_row_expands_its_detail_lines_and_actions() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx();
    let before = message_rows(&compile_settings_view(&runtime, instance, view, &cx));
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/39/title",
    );
    assert_eq!(
        messages_view_state(&runtime, view).messages_selected,
        Some(39)
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    let label = |key: &str| {
        compiled
            .semantic(&UiKey::new(key))
            .map(|node| node.label.clone())
            .unwrap_or_else(|| panic!("{key} renders"))
    };
    // A DISCLOSURE (ruling 262): expanded, never `selected`.
    let title = compiled
        .semantic(&UiKey::new("settings/messages/row/39/title"))
        .and_then(|node| node.state)
        .expect("the title is the disclosure control");
    assert_eq!(title.expanded, Some(true));
    assert!(!title.selected);
    assert_eq!(
        compiled
            .semantic(&UiKey::new("settings/messages/row/40/title"))
            .and_then(|node| node.state)
            .and_then(|state| state.expanded),
        Some(false),
        "a closed entry says so"
    );
    // The meta line: the reader's local time and the state; the lead
    // column already says the tag and the severity.
    let meta = label("settings/messages/row/39/meta/0");
    assert!(
        meta.ends_with("3:51:20 PM \u{00b7} waiting to show") && !meta.contains("UTC"),
        "{meta}"
    );
    // The page's bounds do not move: the same entries, the open one grown.
    let after = message_rows(&compiled);
    assert_eq!(after.first(), before.first(), "{before:?} → {after:?}");
    assert!(
        after.iter().all(|id| before.contains(id)),
        "{before:?} → {after:?}"
    );
    assert_eq!(
        label("settings/messages/row/39/detail/0"),
        "build 1234 \u{2014} verified and ready to apply"
    );
    let enabled = |key: &str| {
        compiled
            .semantic(&UiKey::new(key))
            .unwrap_or_else(|| panic!("{key} renders"))
            .state
            .is_none_or(|state| state.enabled)
    };
    assert_eq!(label("settings/messages/row/39/action/0"), "Install now");
    assert!(
        !enabled("settings/messages/row/39/action/0"),
        "a build no longer staged cannot be applied from here"
    );
    assert_eq!(
        label("settings/messages/row/39/action/1"),
        "Open Software Update",
        "a destination reads as where it goes (ruling 262)"
    );
    assert!(enabled("settings/messages/row/39/action/1"));
    assert_eq!(label("settings/messages/row/39/copy"), "Copy");
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/row/40/meta/0"))
            .is_none(),
        "one row expands at a time"
    );
    // The expanded row is charged at its height: the rows below it still
    // fit the page, and the page is paged one row later than before.
    for node in &compiled.semantics {
        if node.key.as_str().starts_with("settings/messages/row/") {
            assert!(
                node.rect.bottom() <= cx.viewport.bottom() + 0.01,
                "{} is clipped: {:?}",
                node.key.as_str(),
                node.rect
            );
        }
    }
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/39/title",
    );
    assert_eq!(messages_view_state(&runtime, view).messages_selected, None);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/row/39/meta/0"))
            .is_none(),
        "folded back"
    );
}

/// THE PRIMARY IS THE FIRST INTENT A PRESS CAN STILL PERFORM (round 38,
/// day ten, D2; ruling 401). #39's `Install now` names a build no longer
/// staged: it stays, disabled (ruling 265: an intent that can come back),
/// and it was drawn in the accent beside a plain `Open Software Update`
/// that could be pressed — ruling 265's own complaint ("A dead `Stop
/// paste` drawn as the accent Primary read as the thing to do.") about
/// an intent it keeps. The accent, and a bare Return (`default_action`:
/// the first ENABLED Primary), go to the first later intent that can act
/// and is not a decline (ruling 403). The controls: #40's `Open log`,
/// pressable and first, leads as before; a card with nothing pressable
/// has no Primary, and Copy is never one.
#[test]
fn the_primary_is_the_first_intent_a_press_can_still_perform() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx();
    let button = |compiled: &crate::native_ui::CompiledUi, key: &str| {
        compiled
            .paint
            .iter()
            .find(|node| node.key.as_str() == key)
            .and_then(|node| match &node.content {
                UiContent::Button(control) => Some((control.style, control.state.enabled)),
                _ => None,
            })
            .unwrap_or_else(|| panic!("{key} paints a button"))
    };
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/39/title",
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(
        button(&compiled, "settings/messages/row/39/action/0"),
        (StyleRef::Secondary, false),
        "a dead Install now is not drawn as the thing to do"
    );
    assert_eq!(
        button(&compiled, "settings/messages/row/39/action/1"),
        (StyleRef::Primary, true)
    );
    assert_eq!(
        button(&compiled, "settings/messages/row/39/copy"),
        (StyleRef::Secondary, true)
    );
    assert_eq!(
        compiled
            .default_action
            .as_ref()
            .map(|(key, _)| key.as_str()),
        Some("settings/messages/row/39/action/1"),
        "Return presses the intent that can act"
    );
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/40/title",
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(
        button(&compiled, "settings/messages/row/40/action/0"),
        (StyleRef::Primary, true),
        "the control: a first intent that can act leads"
    );
    let state = sample_messages();
    let dead = |index: u8, label: &'static str| crate::messages_host::MessageActionView {
        index,
        label,
        still_actionable: false,
        declines: false,
    };
    let entry = MessageView {
        actions: vec![dead(0, "Install now"), dead(1, "Open log")],
        ..state.entries[1].clone()
    };
    let body = MessagesBody::of(&entry, 560.0, 0, state.now_unix_ms);
    assert_eq!(body.footer.iter().flatten().count(), 3, "both, and Copy");
    assert!(
        body.footer.iter().flatten().all(|b| !b.primary),
        "nothing pressable leads"
    );
}

/// A DECLINE IS NEVER PROMOTED TO THE PRIMARY (round 38's review,
/// findings 2 and 6; ruling 403). Ruling 401 moved the Primary past a
/// first intent a press cannot perform, and on an upgrade card whose
/// `Upgrade now` went dead it handed the accent, and a bare Return
/// (`default_action`), to `Skip version`: a decision drawn as the thing
/// to do, and pressed by a Return that did nothing there before. The
/// band never paints a decline in the accent (`Intent::is_consequential`).
/// Now a dead first intent hands the Primary only to a later intent that
/// is not a decline; with none, nothing leads and Return stays inert.
/// The controls: a dead `Install now` still hands it to `Open Software
/// Update` (ruling 401), and a first `Not today` a press can perform
/// keeps it (ruling 265: the reporter's order leads).
#[test]
fn a_decline_is_never_promoted_to_the_primary() {
    use crate::messages_host::MessageActionView;
    let act = |index: u8, label: &'static str, still_actionable: bool, declines: bool| {
        MessageActionView {
            index,
            label,
            still_actionable,
            declines,
        }
    };
    let cx = view_cx();
    let card = |actions: Vec<MessageActionView>| {
        let (mut runtime, instance, view) = setup();
        let mut state = sample_messages();
        assert_eq!(state.entries[1].id, 39);
        state.entries[1].actions = actions;
        assert!(runtime.replace_settings_messages(state, 7));
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::Messages),
                    value: None,
                }),
            )
            .unwrap();
        messages_action(
            &mut runtime,
            instance,
            view,
            "settings/messages/row/39/title",
        );
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let styles = (0..2)
            .map(|k| {
                let key = format!("settings/messages/row/39/action/{k}");
                compiled
                    .paint
                    .iter()
                    .find(|node| node.key.as_str() == key)
                    .and_then(|node| match &node.content {
                        UiContent::Button(control) => Some((control.style, control.state.enabled)),
                        _ => None,
                    })
                    .unwrap_or_else(|| panic!("{key} paints a button"))
            })
            .collect::<Vec<_>>();
        let default = compiled
            .default_action
            .as_ref()
            .map(|(key, _)| key.as_str().to_string());
        (styles, default)
    };
    for decline in ["Skip version", "Not today"] {
        assert_eq!(
            card(vec![
                act(0, "Upgrade now", false, false),
                act(1, decline, true, true),
            ]),
            (
                vec![(StyleRef::Secondary, false), (StyleRef::Secondary, true)],
                None
            ),
            "a dead Upgrade now does not hand {decline} the accent, nor Return"
        );
    }
    assert_eq!(
        card(vec![
            act(0, "Install now", false, false),
            act(1, "Software Update", true, false),
        ]),
        (
            vec![(StyleRef::Secondary, false), (StyleRef::Primary, true)],
            Some("settings/messages/row/39/action/1".to_string())
        ),
        "the control: a navigation still leads past a dead first intent"
    );
    assert_eq!(
        card(vec![
            act(0, "Not today", true, true),
            act(1, "Skip version", true, true),
        ]),
        (
            vec![(StyleRef::Primary, true), (StyleRef::Secondary, true)],
            Some("settings/messages/row/39/action/0".to_string())
        ),
        "the control: a first decline a press can perform keeps its place"
    );
}

/// THE FOOTER'S PRIMARY IS A POSITION IN THE OFFERED INTENTS, NOT AN
/// `ActionIndex` (the round-39 review; ruling 408): the engine's
/// `primary_index` answers a position in `entry.actions`, while each
/// button's key keeps the intent's own index, and an intent whose moment
/// passed is not offered (ruling 265), so the offered indices can start
/// past 0. Every other fixture has index equal to position. Here: the
/// first offered intent (`action/1`) leads, and past a dead `action/1` the
/// pressable `action/2` does, never the dead one.
#[test]
fn the_footer_primary_is_a_position_in_the_offered_intents() {
    use crate::messages_host::MessageActionView;
    let act = |index: u8, label: &'static str, still_actionable: bool| MessageActionView {
        index,
        label,
        still_actionable,
        declines: false,
    };
    let state = sample_messages();
    let footer = |actions: Vec<MessageActionView>| {
        let entry = MessageView {
            actions,
            ..state.entries[1].clone()
        };
        MessagesBody::of(&entry, 560.0, 0, state.now_unix_ms)
            .footer
            .into_iter()
            .flatten()
            .map(|button| (button.key, button.primary, button.enabled))
            .collect::<Vec<_>>()
    };
    let row = format!("settings/messages/row/{}", state.entries[1].id);
    assert_eq!(
        footer(vec![act(1, "Show tab 2", true), act(2, "Settings", true)]),
        [
            (format!("{row}/action/1"), true, true),
            (format!("{row}/action/2"), false, true),
            (format!("{row}/copy"), false, true),
        ],
        "the first offered intent leads, whatever its index"
    );
    assert_eq!(
        footer(vec![
            act(1, "Install now", false),
            act(2, "Software Update", true),
        ]),
        [
            (format!("{row}/action/1"), false, false),
            (format!("{row}/action/2"), true, true),
            (format!("{row}/copy"), false, true),
        ],
        "past a dead first, the pressable one leads, never the dead one"
    );
}

/// Ruling 314 (day eight E2): a tab's upgrade record set `it asks again on
/// its own at 12:55 AM; Upgrade now asks it …` — the next step, for a
/// person — as monospace code under Technical details, cut mid-sentence
/// across two code lines. The entry's leading `sentences` lines are the
/// sentence; the move and the shell spelling stay technical. Control: at
/// one sentence line the remedy is technical, as it was.
#[test]
fn an_upgrade_records_why_and_next_step_are_its_sentence() {
    let state = sample_messages();
    let remedy = "it asks again on its own at 12:55 AM; Upgrade now asks it at its next pause; \
                  Skip This Version in the tab's menu keeps it on 2.1.280";
    let entry = MessageView {
        detail: vec![
            "behind for 7 h: it has not agreed to the move yet, so the upgrade rests, then \
             asks again"
                .to_string(),
            remedy.to_string(),
            "in tab 3 \u{00b7} Claude Code 2.1.280 \u{2192} 2.1.283".to_string(),
            "the same in any shell: `aterm harness upgrade s-d35e --now` or `--skip`".to_string(),
        ],
        sentences: 2,
        ..state.entries[0].clone()
    };
    let body = MessagesBody::of(&entry, 560.0, 0, state.now_unix_ms);
    let said = body.sentence.join(" ");
    assert!(said.contains("Upgrade now asks it"), "{:?}", body.sentence);
    assert!(said.contains("keeps it on 2.1.280"), "{:?}", body.sentence);
    assert!(
        body.technical.iter().all(|l| !l.contains("Upgrade now")),
        "{:?}",
        body.technical
    );
    assert!(body.technical.iter().any(|l| l.contains("in tab 3")));
    let one = MessagesBody::of(
        &MessageView {
            sentences: 1,
            ..entry
        },
        560.0,
        0,
        state.now_unix_ms,
    );
    assert!(
        one.technical.iter().any(|l| l.contains("Upgrade now")),
        "the control: {:?}",
        one.technical
    );
}

/// A DIAGRAM KEEPS ITS COLUMNS (design ruling 36): a `toml` parse error,
/// worded by the config lane from the REAL parser, paints every detail
/// row in the monospace face and reaches the painter row for row — the
/// caret row verbatim, leading whitespace and all, so the caret sits
/// under the column it points at. On a measure too narrow for a row the
/// row is CUT, never reflowed: its pieces join back to it byte for byte
/// and none is wider than the box. A prose entry keeps the body face.
#[test]
fn a_diagram_entry_paints_its_rows_in_the_monospace_face_and_cuts_them() {
    let error = "x = [bad\n"
        .parse::<aterm_toml::edit::DocumentMut>()
        .expect_err("a malformed document")
        .to_string();
    let msg = crate::message_reporters::config_lane_error(&format!(
        "Config observation was not valid TOML: {error}"
    ));
    let caret = error
        .lines()
        .find(|row| row.contains('^'))
        .expect("the parser's caret row")
        .trim_end()
        .to_string();
    assert!(caret.starts_with(char::is_whitespace), "{caret:?}");
    let mut state = sample_messages();
    state.entries.insert(
        0,
        MessageView {
            id: 41,
            at_unix_ms: state.now_unix_ms,
            tag: "config".to_string(),
            severity: "warn",
            glyph: '\u{26a0}',
            title: msg.title.clone(),
            detail: msg.detail.clone(),
            state: "live",
            on_glass: None,
            repeats: 1,
            retired_unix_ms: None,
            superseded_by: None,
            answer: None,
            actions: Vec::new(),
            sentences: 1,
        },
    );
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_messages(state, 8));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Messages),
                value: None,
            }),
        )
        .unwrap();
    let cx = view_cx();
    // A diagram is TECHNICAL whole (ruling 262): its rows are the entry's
    // technical-details lines, in the small monospace.
    let painted_code = |compiled: &crate::native_ui::CompiledUi, id: u64| {
        let prefix = format!("settings/messages/row/{id}/code/");
        compiled
            .paint
            .iter()
            .filter(|node| node.key.as_str().starts_with(prefix.as_str()))
            .map(|node| match &node.content {
                UiContent::Text(spec) => (spec.text.clone(), spec.style),
                other => panic!("{prefix} paints something other than text: {other:?}"),
            })
            .collect::<Vec<_>>()
    };
    let painted_detail = |compiled: &crate::native_ui::CompiledUi, id: u64| {
        let prefix = format!("settings/messages/row/{id}/detail/");
        compiled
            .paint
            .iter()
            .filter(|node| node.key.as_str().starts_with(prefix.as_str()))
            .map(|node| match &node.content {
                UiContent::Text(spec) => (spec.text.clone(), spec.style),
                other => panic!("{prefix} paints something other than text: {other:?}"),
            })
            .collect::<Vec<_>>()
    };
    select_message(&mut runtime, instance, view, 41);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    let rows = painted_code(&compiled, 41);
    assert_eq!(
        rows.iter()
            .map(|(text, _)| text.clone())
            .collect::<Vec<_>>(),
        msg.detail,
        "row for row, none reflowed or trimmed"
    );
    assert!(
        painted_detail(&compiled, 41).is_empty(),
        "no prose sentence"
    );
    assert!(rows.iter().any(|(text, _)| *text == caret), "{rows:?}");
    assert!(
        rows.iter().all(|(_, style)| *style == StyleRef::Code),
        "{rows:?}"
    );
    let overflow = compiled
        .paint_audit_lines()
        .into_iter()
        .filter(|line| line.contains("overflow=true"))
        .collect::<Vec<_>>();
    assert!(overflow.is_empty(), "{}", overflow.join("\n"));
    // Prose is not a diagram: the crash entry keeps the body face.
    select_message(&mut runtime, instance, view, 40);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let prose = painted_detail(&compiled, 40);
    assert!(!prose.is_empty());
    assert!(
        prose.iter().all(|(_, style)| *style == StyleRef::Primary),
        "{prose:?}"
    );
    // Too narrow for the row: CUT, the pieces joining back to it.
    let (px, _) = crate::native_ui::text_paint_metrics(SemanticRole::Status, StyleRef::Code);
    let long = format!("{caret}{}", " here".repeat(40));
    let pieces = messages_cut_code(&long, 120.0);
    assert!(pieces.len() > 1, "{pieces:?}");
    assert_eq!(pieces.concat(), long);
    assert!(pieces[0].starts_with(char::is_whitespace), "{pieces:?}");
    for piece in &pieces {
        let width = crate::tray_raster::measure_text(piece, px, crate::widget::TextWeight::Regular);
        assert!(width <= 120.0 + 0.01, "{piece:?} is {width} wide");
    }
}

/// THE DEEP LINK MEASURES THE LIST IT LEAVES (rulings 263 and 264): a
/// chip showing one entry is a list of one, which never scrolls; a reveal
/// that drops the chip lands by the whole log's list, so an entry deep in
/// it is on the reader's screen, open — the stale list would land it at
/// the top, where it is not.
#[test]
fn the_deep_link_lands_by_the_filter_it_leaves() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx();
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/tag/crash",
    );
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(
        messages_view_state(&runtime, view).result_page_limit.get(),
        Some(0),
        "a list of one never scrolls"
    );
    // Entries run newest first: id 5 is the thirty-sixth row.
    select_message(&mut runtime, instance, view, 5);
    let top = {
        let state = messages_view_state(&runtime, view);
        assert!(state.messages_filter.is_all(), "the chip is dropped");
        state.page_scroll
    };
    assert!(top > 0, "landed deep in the whole log, not at its top");
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    assert!(
        message_rows(&compiled).contains(&5),
        "entry 5 is on the screen: {:?}",
        message_rows(&compiled)
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/row/5/detail/0"))
            .is_some(),
        "expanded"
    );
}

/// THE DEEP LINK (design §4.5; ruling 264): `settings/messages/select`
/// expands the entry, drops a chip that would hide it, and LANDS on it —
/// the list stays where the entry is already on the screen, else scrolls
/// it to the top as far as the list scrolls — on the wide page and on a
/// compact one, whose header scrolls away with the list. A link that
/// comes before any render (a Settings view opened for it) is landed by
/// that render, and the list moves on from where it drew.
#[test]
fn the_deep_link_selects_and_lands_on_the_entry() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx();
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/tag/config",
    );
    select_message(&mut runtime, instance, view, 40);
    {
        let state = messages_view_state(&runtime, view);
        assert_eq!(state.messages_selected, Some(40));
        assert!(
            state.messages_filter.is_all(),
            "the config chip would have hidden the crash: dropped"
        );
        assert_eq!(
            state.page_scroll, 0,
            "the newest entry is on the first screen"
        );
    }
    select_message(&mut runtime, instance, view, 5);
    let (top, limit) = {
        let state = messages_view_state(&runtime, view);
        (state.page_scroll, state.result_page_limit.get())
    };
    assert!(top > 0);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    let rows = message_rows(&compiled);
    assert!(rows.contains(&5), "…and it is on the screen: {rows:?}");
    assert!(
        rows.first() == Some(&5) || rows.last() == Some(&1),
        "at the top of the list, or the list at its end: {rows:?} ({top} of {limit:?})"
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/row/5/detail/0"))
            .is_some(),
        "expanded"
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/range"))
            .is_none(),
        "no pager says where: the list is where it is"
    );
    // An id the ring no longer holds: selected, the list at its top.
    select_message(&mut runtime, instance, view, 999);
    let state = messages_view_state(&runtime, view);
    assert_eq!(state.messages_selected, Some(999));
    assert_eq!(state.page_scroll, 0);

    // Compact: the header scrolls with the list; the link lands the entry
    // on the screen, open.
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx_at(320.0, 568.0);
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    select_message(&mut runtime, instance, view, 5);
    assert!(
        messages_view_state(&runtime, view).page_scroll > 0,
        "entry 5 is deep in the log"
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    compiled.validate_parity().unwrap();
    assert!(
        message_rows(&compiled).contains(&5),
        "the view holding the entry: {:?}",
        message_rows(&compiled)
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/row/5/detail/0"))
            .is_some()
    );

    // Before any render: the render lands it, and the next scroll moves
    // on from the stop it drew.
    for (width, height) in [(1_200.0, 820.0), (320.0, 568.0)] {
        let (mut runtime, instance, view) = setup_with_messages();
        select_message(&mut runtime, instance, view, 5);
        assert!(
            messages_view_state(&runtime, view).messages_reveal,
            "no render has measured the page yet"
        );
        let cx = view_cx_at(width, height);
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        assert!(
            message_rows(&compiled).contains(&5),
            "{width}: the first render lands it: {:?}",
            message_rows(&compiled)
        );
        let drawn = messages_view_state(&runtime, view)
            .messages_drawn
            .get()
            .expect("the render drew a stop");
        assert!(drawn > 0, "{width}");
        runtime
            .dispatch(instance, view, AppEvent::ScrollLines(-1))
            .unwrap();
        let state = messages_view_state(&runtime, view);
        assert!(!state.messages_reveal, "{width}: adopted");
        assert_eq!(
            state.page_scroll,
            drawn - 1,
            "{width}: one up from the drawn stop"
        );
    }
}

/// The page names an entry and a button by IDENTITY (design §4.4): the
/// effect carries an id and an index, never the path the intent holds,
/// and the host's answer becomes the feedback line; a button the
/// projection says is spent raises no effect at all.
#[test]
fn messages_entry_actions_never_carry_a_path() {
    let (mut runtime, instance, view) = setup_with_messages();
    let effects = messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/40/action/0",
    );
    let operation = effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::MessageAct {
                id: 40,
                action: 0,
                reply,
            } => Some(reply.operation),
            _ => None,
        })
        .expect("one MessageAct effect naming the entry and the button");
    assert!(
        !format!("{effects:?}").contains("crash-signal"),
        "no effect carries the crash log's path: {effects:?}"
    );
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::MessageActFinished {
                operation,
                outcome: MessageActOutcome::Performed {
                    feedback: "Opened the log".to_string(),
                },
            },
        )
        .unwrap();
    assert_eq!(
        messages_view_state(&runtime, view).feedback.as_deref(),
        Some("Opened the log")
    );
    // A spent button: the page says so and asks the host for nothing.
    let effects = messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/39/action/0",
    );
    assert!(
        !effects
            .iter()
            .any(|effect| matches!(effect, AppEffect::MessageAct { .. })),
        "{effects:?}"
    );
    assert_eq!(
        messages_view_state(&runtime, view).feedback.as_deref(),
        Some("That can no longer be done from here")
    );
    let effects = messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/999/action/0",
    );
    assert!(
        !effects
            .iter()
            .any(|effect| matches!(effect, AppEffect::MessageAct { .. }))
    );
    assert_eq!(
        messages_view_state(&runtime, view).feedback.as_deref(),
        Some("That message no longer offers this")
    );
}

/// Copy puts the title, the `stamp · tag · severity` line and every
/// detail line on the clipboard — the engine's own `copy_text` — and
/// the completion says `Copied`.
/// COPY ALL (design ruling 65): the entries the chip shows, newest first,
/// each as its own Copy puts it, under the build information — one press
/// for a report. With a chip down, only that chip's entries.
#[test]
fn copy_all_puts_every_shown_entry_and_the_build_on_the_clipboard() {
    let copied = |effects: Vec<AppEffect>| {
        effects
            .into_iter()
            .find_map(|effect| match effect {
                AppEffect::Clipboard {
                    request: ClipboardRequest::CopyText { text, sensitive },
                    ..
                } => {
                    assert!(!sensitive);
                    Some(text)
                }
                _ => None,
            })
            .expect("one clipboard effect")
    };
    let (mut runtime, instance, view) = setup_with_messages();
    let text = copied(messages_action(
        &mut runtime,
        instance,
        view,
        MESSAGES_COPY_ALL,
    ));
    assert!(text.starts_with(&crate::about::provenance_text()), "{text}");
    let all = sample_messages();
    for entry in &all.entries {
        assert!(text.contains(&entry.copy_text()), "{}", entry.title);
    }
    let crash = text.find("aterm closed unexpectedly").unwrap();
    let older = text.find("config warning 1\n").unwrap();
    assert!(crash < older, "newest first");
    // NEGATIVE CONTROL: the crash chip down, and only the crash is copied.
    let _ = messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/tag/crash",
    );
    let text = copied(messages_action(
        &mut runtime,
        instance,
        view,
        MESSAGES_COPY_ALL,
    ));
    assert!(text.contains("aterm closed unexpectedly"));
    assert!(!text.contains("config warning"), "{text}");
    let commands = runtime.commands(instance, view).unwrap();
    assert!(
        commands
            .iter()
            .any(|c| c.id.as_str() == MESSAGES_COPY_ALL && c.title == "Messages: Copy All")
    );
}

/// OPEN LOG FOLDER asks the host for its own log directory — the effect
/// carries no path, ever — and, off macOS, the page names the folder instead.
#[test]
fn open_log_folder_asks_the_host_and_never_names_a_path() {
    let (mut runtime, instance, view) = setup_with_messages();
    let effects = messages_action(&mut runtime, instance, view, MESSAGES_OPEN_FOLDER);
    let asked = effects
        .iter()
        .any(|effect| matches!(effect, AppEffect::OpenLogFolder));
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    if cfg!(target_os = "macos") {
        assert!(asked, "{effects:?}");
        assert_eq!(
            state.feedback.as_deref(),
            Some("Opening the log folder\u{2026}")
        );
    } else {
        assert!(!asked, "nothing is spawned off macOS");
        assert_eq!(
            state.feedback.as_deref(),
            Some("The log folder is /Users//w/Library/Logs/aterm")
        );
    }
    let commands = runtime.commands(instance, view).unwrap();
    assert!(
        commands
            .iter()
            .any(|c| c.id.as_str() == MESSAGES_OPEN_FOLDER && c.enabled)
    );
    // No folder: says so, and asks nothing.
    let (mut runtime, instance, view) = setup_with_messages();
    let mut none = sample_messages();
    none.log_folder = None;
    assert!(runtime.replace_settings_messages(none, 8));
    let effects = messages_action(&mut runtime, instance, view, MESSAGES_OPEN_FOLDER);
    assert!(
        !effects
            .iter()
            .any(|e| matches!(e, AppEffect::OpenLogFolder))
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert_eq!(
        state.feedback.as_deref(),
        Some("The log folder is not available.")
    );
}

/// A PAGE WITHOUT A WRITER SAYS ITS MESSAGES ARE NOT SAVED: the log dir was
/// read-only or the disk full, and the ring lives only until aterm quits.
#[test]
fn a_page_without_a_writer_says_its_messages_are_not_saved() {
    for (width, height) in [(1_200.0, 820.0), (320.0, 568.0)] {
        let (mut runtime, instance, view) = setup_with_messages();
        let cx = view_cx_at(width, height);
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        assert!(
            compiled
                .semantic(&UiKey::new("settings/messages/not-saved"))
                .is_none(),
            "{width}: saved — no note"
        );
        let mut unsaved = sample_messages();
        unsaved.saved = false;
        assert!(runtime.replace_settings_messages(unsaved, 8));
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let note = compiled
            .semantic(&UiKey::new("settings/messages/not-saved"))
            .unwrap_or_else(|| panic!("{width}: the note"));
        assert_eq!(note.label, MESSAGES_NOT_SAVED);
    }
}

/// SOFTWARE UPDATE'S LINK OPENS MESSAGES ON THE UPDATE CHIP (design ruling
/// 41 kept): the navigation first (it clears the filter), then the chip a
/// press on it would set; with no update entries, the All chip — never a
/// blank page.
#[test]
fn the_software_update_link_opens_messages_on_the_update_chip() {
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_messages(sample_messages(), 7));
    let _ = messages_action(&mut runtime, instance, view, MESSAGES_SHOW_UPDATE);
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert_eq!(state.route, SettingsRoute::Messages);
    assert_eq!(state.messages_filter.tag.as_deref(), Some("update"));
    // NEGATIVE CONTROL: no update entries — the All chip.
    let (mut runtime, instance, view) = setup();
    let mut no_update = sample_messages();
    no_update.tags.retain(|(tag, _)| tag != "update");
    no_update.entries.retain(|entry| entry.tag != "update");
    assert!(runtime.replace_settings_messages(no_update, 7));
    let _ = messages_action(&mut runtime, instance, view, MESSAGES_SHOW_UPDATE);
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert_eq!(state.route, SettingsRoute::Messages);
    assert!(state.messages_filter.is_all());
}

