/// ROUND 16, DAY TWO (ruling 267): Page Down on the compact category list
/// moved a fixed eight rows through a list that shows six — `1–6`, `9–14`,
/// `17–17` — so Packages and Messages were never shown. It moves by the
/// page shown now: every category is seen, no page skips one, and Page Up
/// comes back the same way.
#[test]
fn page_keys_move_the_compact_category_list_by_the_page_it_shows() {
    let (mut runtime, instance, view) = setup();
    let cx = view_cx_at(474.0, 572.0);
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    state.compact_navigation = true;
    let shown = |compiled: &crate::native_ui::CompiledUi| -> Vec<usize> {
        SettingsRoute::ALL
            .iter()
            .enumerate()
            .filter(|(_, route)| {
                compiled
                    .semantic(&UiKey::new(format!("settings/categories{}", route.path())))
                    .is_some()
            })
            .map(|(k, _)| k)
            .collect()
    };
    let mut seen = std::collections::BTreeSet::new();
    let mut pages = Vec::new();
    for _ in 0..SettingsRoute::ALL.len() {
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let rows = shown(&compiled);
        assert!(!rows.is_empty());
        seen.extend(rows.iter().copied());
        let last = *rows.last().unwrap();
        pages.push(rows);
        if last + 1 == SettingsRoute::ALL.len() {
            break;
        }
        runtime
            .dispatch(instance, view, AppEvent::ScrollPage(1))
            .unwrap();
    }
    assert!(
        pages[0].len() < SettingsRoute::ALL.len(),
        "the list pages at this size"
    );
    assert_eq!(
        seen.len(),
        SettingsRoute::ALL.len(),
        "every category shown: {pages:?}"
    );
    for pair in pages.windows(2) {
        assert!(
            pair[1][0] <= pair[0].last().unwrap() + 1,
            "no category skipped between pages: {pages:?}"
        );
    }
    // Page Up walks back to the top.
    for _ in 0..pages.len() {
        runtime
            .dispatch(instance, view, AppEvent::ScrollPage(-1))
            .unwrap();
    }
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(shown(&compiled), pages[0]);
}

/// ROUND 16 REVIEW (ruling 267): a page that shows ONE section per page —
/// the compact Packages pages, About's sections — indexes `page_scroll` by
/// page, and Page Down still moved it eight: from page 1 of 13 on the
/// compact Packages page it landed on page 9. Every Page Down now turns
/// one page, and Page Up turns it back.
#[test]
fn page_keys_turn_one_page_on_pages_that_show_one_section() {
    for (route, status_key) in [
        (SettingsRoute::Packages, "packages/range"),
        (SettingsRoute::About, "about/range"),
    ] {
        let (mut runtime, instance, view) = setup();
        assert!(runtime.replace_settings_packages(live_packages_state(None), 2));
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(route);
        }
        let cx = view_cx_at(474.0, 320.0);
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let total = pager_total(&compiled, status_key);
        assert!(total > 2, "{route:?} pages at this size: {total}");
        let page = |runtime: &NativeRuntime| messages_view_state(runtime, view).page_scroll;
        for expected in 1..total {
            runtime
                .dispatch(instance, view, AppEvent::ScrollPage(1))
                .unwrap();
            assert_eq!(
                page(&runtime),
                expected,
                "{route:?}: Page Down turns one page"
            );
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            assert_eq!(pager_total(&compiled, status_key), total);
        }
        for expected in (0..total - 1).rev() {
            runtime
                .dispatch(instance, view, AppEvent::ScrollPage(-1))
                .unwrap();
            assert_eq!(
                page(&runtime),
                expected,
                "{route:?}: Page Up turns one back"
            );
            let _ = compile_settings_view(&runtime, instance, view, &cx);
        }
    }
}

/// ROUND 16, DAY TWO (ruling 267): on the compact page the header scrolls
/// away with the log, and Down on a filter chip scrolled it — the chip
/// left the tree and the keyboard with it (no focused node, no ring). The
/// keyboard is on a control the page SHOWS after every step, and moves
/// into the list when its control scrolls away.
#[test]
fn the_keyboard_never_scrolls_away_with_the_compact_header() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx_at(474.0, 572.0);
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::FocusChanged(Some(UiKey::new("settings/messages/filter/all"))),
        )
        .unwrap();
    let mut reached_a_row = false;
    for step in 0..12 {
        runtime
            .dispatch(instance, view, AppEvent::ScrollLines(1))
            .unwrap();
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let focus = messages_view_state(&runtime, view)
            .common
            .last_focus
            .clone()
            .expect("a focused control");
        assert!(
            compiled.semantic(&focus).is_some(),
            "step {step}: the focused {focus:?} is on the page"
        );
        reached_a_row |= focus.as_str().starts_with("settings/messages/row/");
    }
    assert!(reached_a_row, "the keyboard went into the list");
}

/// ROUND 16, DAY TWO (ruling 267): Left and Right on the severity
/// segments did nothing. They move between `All` and `Problems` and press
/// the one they land on.
#[test]
fn left_and_right_move_between_the_severity_segments() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx_at(474.0, 572.0);
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::FocusChanged(Some(UiKey::new("settings/messages/filter/all"))),
        )
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::TextInput(TextInputEvent::Right { extend: false }),
        )
        .unwrap();
    let state = messages_view_state(&runtime, view);
    assert!(state.messages_filter.warn_only, "Problems is down");
    assert_eq!(
        state.common.last_focus.as_ref().map(UiKey::as_str),
        Some("settings/messages/filter/warn")
    );
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::TextInput(TextInputEvent::Left { extend: false }),
        )
        .unwrap();
    let state = messages_view_state(&runtime, view);
    assert!(!state.messages_filter.warn_only, "All is down again");
    assert_eq!(
        state.common.last_focus.as_ref().map(UiKey::as_str),
        Some("settings/messages/filter/all")
    );
}

/// RULING 270 (round 17, day three): `Copied` in the page's bottom bar
/// took the list's room, so an open entry that fitted no longer did and
/// the list fell from seven rows to four for five seconds. The page's
/// own confirmation rides its count line: the same rows before and
/// after, no status bar, and the words still said (the count line is a
/// Status node). At the day's geometry (100 columns, 774×612 pt).
#[test]
fn the_messages_pages_confirmation_takes_no_room_from_the_list() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx_at(774.0, 612.0);
    let first = message_rows(&compile_settings_view(&runtime, instance, view, &cx));
    assert!(first.len() >= 5, "{first:?}");
    select_message(&mut runtime, instance, view, first[4]);
    let before = message_rows(&compile_settings_view(&runtime, instance, view, &cx));
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.show_messages_feedback_for_test("Copied");
    }
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(message_rows(&compiled), before, "the list keeps its rows");
    assert!(
        compiled
            .semantic(&UiKey::new("settings/feedback"))
            .is_none(),
        "no bar under the page"
    );
    let status = compiled
        .semantic(&UiKey::new("settings/messages/status"))
        .expect("the count line");
    assert!(
        status.label.ends_with("\u{00b7} Copied"),
        "{:?}",
        status.label
    );
    // ROUND 17 REVIEW (V4): a LONG note — Open Log Folder's path, a sent
    // word — is fitted beside the count, never a reason to move the
    // buttons under it: the list keeps its rows, and the whole note is
    // still the count line's label.
    let long = "The log folder is /Users//someone/Library/Application Support/aterm/messages";
    for (w, h) in [(774.0, 612.0), (474.0, 572.0)] {
        let cx = view_cx_at(w, h);
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.feedback = None;
        }
        let quiet = message_rows(&compile_settings_view(&runtime, instance, view, &cx));
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.show_messages_feedback_for_test(long);
        }
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        assert_eq!(
            message_rows(&compiled),
            quiet,
            "{w} pt: the list keeps its rows"
        );
        let status = compiled
            .semantic(&UiKey::new("settings/messages/status"))
            .expect("the count line");
        assert!(status.label.ends_with(long), "{w} pt: {:?}", status.label);
    }
}

/// The count line's height and button placement are the COUNT's alone
/// (round 17 review, V4): at every width, a note leaves both unchanged.
/// NEGATIVE CONTROL: a count too wide for the buttons does move them —
/// the sweep reaches both placements.
#[test]
fn a_count_lines_note_never_moves_its_buttons() {
    let shape = |node: &UiNode| {
        node.children
            .iter()
            .map(|c| c.key.as_str().to_string())
            .collect::<Vec<_>>()
    };
    let notes = [
        "Copied",
        "Sent Skip version; what it did shows in this log",
        "The log folder is /Users//someone/Library/Application Support/aterm/messages",
    ];
    let mut placements = std::collections::BTreeSet::new();
    for w in (120..=900).step_by(10) {
        let w = w as f32;
        let (bare, bare_h) = messages_count_line(Some("1,234 of 5,678".into()), None, w);
        placements.insert(shape(&bare).len());
        for note in notes {
            let (with, with_h) = messages_count_line(Some("1,234 of 5,678".into()), Some(note), w);
            assert_eq!(with_h, bare_h, "{w} pt, {note:?}: the height moved");
            assert_eq!(
                shape(&with),
                shape(&bare),
                "{w} pt, {note:?}: the buttons moved"
            );
        }
    }
    assert!(
        placements.len() >= 2,
        "the sweep saw one placement: {placements:?}"
    );
}

/// ROUND 16, DAY TWO (ruling 267): `Copied` stood on the page for five
/// minutes and across filters. The next action on the page clears it, and
/// so does the first projection five seconds after one has seen it; a
/// copy of the shown messages says `Copied`, never the About page's
/// `Build information copied`.
#[test]
fn the_messages_pages_confirmation_is_transient() {
    let (mut runtime, instance, view) = setup_with_messages();
    let copy = |runtime: &mut NativeRuntime| {
        let effects = messages_action(runtime, instance, view, "settings/messages/copy-all");
        let operation = effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::Clipboard { reply, .. } => Some(reply.operation),
                _ => None,
            })
            .expect("one clipboard effect");
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::ClipboardFinished {
                    operation,
                    outcome: ClipboardOutcome::Copied,
                },
            )
            .unwrap();
    };
    copy(&mut runtime);
    assert_eq!(
        messages_view_state(&runtime, view).feedback.as_deref(),
        Some("Copied")
    );
    // The next action says its own words or none.
    let _ = messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/warn",
    );
    assert_eq!(messages_view_state(&runtime, view).feedback, None);
    // Left alone: the projection that first sees it starts the clock, one
    // five seconds on clears it.
    copy(&mut runtime);
    let publish = |runtime: &mut NativeRuntime, now: u64, revision: u64| {
        let mut state = sample_messages();
        state.now_unix_ms = now;
        state.revision = revision;
        assert!(runtime.replace_settings_messages(state, revision));
        runtime
            .dispatch(instance, view, AppEvent::MessagesChanged { revision })
            .unwrap();
    };
    let base = sample_messages().now_unix_ms;
    publish(&mut runtime, base + 60_000, 8);
    assert_eq!(
        messages_view_state(&runtime, view).feedback.as_deref(),
        Some("Copied"),
        "the first projection only starts the clock"
    );
    publish(&mut runtime, base + 62_000, 9);
    assert!(messages_view_state(&runtime, view).feedback.is_some());
    publish(&mut runtime, base + 65_000, 10);
    assert_eq!(messages_view_state(&runtime, view).feedback, None);
}

/// THE TAG CHIPS WRAP AS ONE ALIGNED, BALANCED BLOCK (design ruling 312;
/// round 21's census at 1200 pt: the chips filled the line beside the
/// severity segments, then ran on from the page's left edge under them).
/// Eleven tags at 1200 pt: two rows of chips, each row's first chip at the
/// x the first row's does, the rows within one chip's width of each other.
/// NEGATIVE CONTROLS: the second row does not start at the segments' x,
/// and the balancer is no greedy packer (ten equal chips split 5 + 5, where
/// filling the first row would leave 6 + 4).
#[test]
fn the_tag_chips_wrap_as_one_aligned_balanced_block() {
    let cx = view_cx();
    let (mut runtime, instance, view) = setup_with_messages();
    let mut state = sample_messages();
    for (k, tag) in [
        "privacy", "session", "window", "render", "a11y", "fabric", "system",
    ]
    .into_iter()
    .enumerate()
    {
        let mut entry = state.entries[3].clone();
        entry.id = 100 + k as u64;
        entry.tag = tag.to_string();
        state.entries.insert(0, entry);
        state.tags.push((tag.to_string(), 1));
    }
    assert!(runtime.replace_settings_messages(state, 8));
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert!(
        compiled.semantic(&UiKey::new(MESSAGES_TAG_MENU)).is_none(),
        "eleven tags are chips at 1200 pt"
    );
    let rect = |key: &str| {
        compiled
            .semantic(&UiKey::new(key))
            .unwrap_or_else(|| panic!("{key}"))
            .rect
    };
    let mut rows: Vec<Vec<LogicalRect>> = Vec::new();
    for node in compiled.semantics.iter().filter(|node| {
        let key = node.key.as_str();
        key.starts_with("settings/messages/filter/tag/") || key == MESSAGES_TAGS_ALL
    }) {
        match rows
            .iter_mut()
            .find(|row| (row[0].y - node.rect.y).abs() < 1.0)
        {
            Some(row) => row.push(node.rect),
            None => rows.push(vec![node.rect]),
        }
    }
    assert_eq!(rows.len(), 2, "two rows of chips: {rows:?}");
    let left = |row: &[LogicalRect]| row.iter().map(|r| r.x).fold(f32::INFINITY, f32::min);
    let right = |row: &[LogicalRect]| row.iter().map(|r| r.right()).fold(0.0_f32, f32::max);
    assert!(
        (left(&rows[0]) - left(&rows[1])).abs() < 0.5,
        "every row starts where the first chip does: {} vs {}",
        left(&rows[0]),
        left(&rows[1])
    );
    let segments = rect("settings/messages/filter/all");
    assert!(
        left(&rows[1]) > segments.right(),
        "NEGATIVE: the second row is not run on from the segments' edge"
    );
    let widest = rows
        .iter()
        .flatten()
        .map(|r| r.width)
        .fold(0.0_f32, f32::max);
    let spans: Vec<f32> = rows.iter().map(|row| right(row) - left(row)).collect();
    assert!(
        (spans[0] - spans[1]).abs() < widest,
        "balanced within one chip: {spans:?} (widest {widest})"
    );
    // The balancer, against the greedy packing it replaced.
    assert_eq!(
        messages_chip_row_lengths(&[100.0; 10], 6.0, 700.0),
        vec![5, 5]
    );
    assert_eq!(messages_chip_row_lengths(&[100.0; 3], 6.0, 700.0), vec![3]);
    assert_eq!(
        messages_chip_row_lengths(&[800.0, 50.0], 6.0, 700.0),
        vec![1, 1],
        "a chip wider than the room has its own row"
    );
}

/// DAY NINE, D4 (ruling 368): an entry's Technical details never shows
/// its `… (N more lines)` marker alone. Room for one line keeps one real
/// line and the marker when that fits, else no block at all (Copy keeps
/// every line); two lines are never one and a marker for the other.
/// Control: room for everything cuts nothing.
#[test]
fn technical_details_never_show_the_more_lines_marker_alone() {
    let body = |technical: &[&str]| MessagesBody {
        meta: vec!["Today 21:40 \u{00b7} config".to_string()],
        sentence: vec!["Misspelled setting".to_string()],
        technical: technical.iter().map(|l| (*l).to_string()).collect(),
        footer: vec![Vec::new()],
    };
    let code = messages_code_line_height();
    let with_rows = |b: &MessagesBody, rows: usize| {
        let mut b = b.clone();
        b.technical.truncate(rows);
        b.height()
    };
    // Two lines, room for one: never `… (2 more lines)` alone.
    let two = body(&["line 3: windw_padding = 20", "near miss: window_padding"]);
    let mut fitted = two.clone();
    fitted.fit(with_rows(&two, 1) + 0.5);
    assert!(
        fitted.technical.iter().all(|l| !l.starts_with('\u{2026}')),
        "{:?}",
        fitted.technical
    );
    assert!(
        fitted.technical.is_empty(),
        "no room for both: the block goes"
    );
    // Five lines, room for two rows: one real line and the marker.
    let five = body(&["a", "b", "c", "d", "e"]);
    let mut fitted = five.clone();
    fitted.fit(with_rows(&five, 2) + 0.5);
    assert_eq!(fitted.technical, vec!["a", "\u{2026} (4 more lines)"]);
    // Room for one row only: never the marker alone.
    let mut fitted = five.clone();
    fitted.fit(with_rows(&five, 1) + 0.5);
    assert!(fitted.technical.is_empty(), "{:?}", fitted.technical);
    // The bound itself keeps a real line at a bound of one.
    let mut bounded = five.clone();
    bounded.bound(1);
    assert_eq!(bounded.technical, vec!["a", "\u{2026} (4 more lines)"]);
    // Control: room for everything cuts nothing.
    let mut fitted = five.clone();
    fitted.fit(five.height() + code);
    assert_eq!(fitted.technical.len(), 5);
}

