/// ROUND 16, DAY TWO (ruling 267): a row's description (`Error, Crashes,
/// …`) and its disclosure state reached no observer but the paint node —
/// not the accessibility projection, not `inspect … tree`. Both carry
/// them now.
#[test]
fn a_rows_description_and_disclosure_reach_every_observer() {
    let (runtime, instance, view) = setup_with_messages();
    let cx = view_cx_at(1_200.0, 820.0);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let title = compiled
        .semantic(&UiKey::new("settings/messages/row/40/title"))
        .expect("the crash row");
    let description = title.description.clone().expect("a description");
    assert!(description.starts_with("Error, Crashes, "), "{description}");
    assert_eq!(title.state.and_then(|state| state.expanded), Some(false));
    let lines = crate::app_control::semantic_tree_lines_for_test(&compiled);
    let line = lines
        .iter()
        .find(|line| line.contains("key=\"settings/messages/row/40/title\""))
        .expect("the row in the tree");
    assert!(line.contains(" expanded=false"), "{line}");
    assert!(
        line.contains(&format!(" description={description:?}")),
        "{line}"
    );
    #[cfg(a11y_tree)]
    {
        let projection =
            crate::native_accessibility::project_native_accessibility(&compiled, None).unwrap();
        assert!(
            projection
                .update()
                .nodes
                .iter()
                .any(|(_, node)| node.description() == Some(description.as_str())),
            "the reader hears it"
        );
    }
}

/// REVIEW PIN (Phase 2, lens A, 2026-09-22): THE 80×24 WINDOW'S PAGE —
/// 584×348 at scale 1, a SHORT LANDSCAPE compact host — seats no item it
/// clips. `compact_page_budget` reads its insets through
/// `page_insets_for_viewport`, which zeroes the vertical insets of a
/// short landscape host, and so counts a 296 pt column; the page frame
/// takes its insets from `responsive_page_insets`, which keeps 12 pt
/// there, so the section the items were packed into is 272 pt. Captured
/// live on the headless 80×24 instance: the expanded entry's Copy laid
/// out at 38 pt (a control is 44), and the fourth head of a full page
/// hanging past the section with its stamp line cut. Every item the
/// list seats, in every view it scrolls through (ruling 264), must end
/// inside its section at its authored height — the page's own law
/// ("never promises a row it clips", design §4.4).
#[test]
fn messages_page_seats_no_item_it_clips_at_584x348() {
    let cx = view_cx_at(584.0, 348.0);
    // The one-day log, and the same log over five days, whose day headers
    // (ruling 273) are seated whole as well.
    for log in [sample_messages(), multi_day_messages()] {
        let (mut runtime, instance, view) = setup_with_messages();
        assert!(runtime.replace_settings_messages(log, 8));
        select_message(&mut runtime, instance, view, 40);
        let control = messages_small_button_height();
        let head = messages_row_height();
        let line = messages_line_height();
        let views = scroll_messages_through(&mut runtime, instance, view, &cx, 1, |compiled, k| {
            compiled.validate_parity().unwrap();
            let section = compiled
                .semantic(&UiKey::new("settings/messages/section"))
                .expect("the 80\u{d7}24 window is a compact host: one scrolling section");
            let bottom = section.rect.bottom();
            for node in &compiled.semantics {
                let key = node.key.as_str();
                if key.starts_with("settings/messages/day/") {
                    assert!(
                        node.rect.bottom() <= bottom + 0.01,
                        "{key} hangs past its section in view {k}: {:?}",
                        node.rect
                    );
                    continue;
                }
                let Some(rest) = key.strip_prefix("settings/messages/row/") else {
                    continue;
                };
                assert!(
                    node.rect.bottom() <= bottom + 0.01,
                    "{key} hangs past its section in view {k}: {:?} (section {:?})",
                    node.rect,
                    section.rect
                );
                let authored = if !rest.contains('/') || rest.ends_with("/title") {
                    Some(("a head", head))
                } else if rest.contains("/meta/") || rest.contains("/detail/") {
                    Some(("a line", line))
                } else if rest.ends_with("/copy") || rest.contains("/action/") {
                    Some(("a control", control))
                } else {
                    None
                };
                if let Some((what, height)) = authored {
                    assert!(
                        node.rect.height >= height - 0.01,
                        "{key} is laid out short of its authored height in view {k}: {:?} \
                     ({what} is {height} pt; section {:?})",
                        node.rect,
                        section.rect
                    );
                }
            }
        });
        assert!(views > 1, "the sample log scrolls at 584\u{d7}348");
    }
}

/// A log at its RING CAP ([`aterm_messages::LOG_CAP`], 512 records): the
/// sample log's crash, update and toolchain records renumbered to the
/// newest three, over 509 config warnings a minute apart.
fn full_ring_messages() -> MessagesState {
    let mut state = sample_messages();
    let cap = aterm_messages::LOG_CAP as u64;
    let template = state.entries[3].clone();
    state.entries.truncate(3);
    for (k, entry) in state.entries.iter_mut().enumerate() {
        entry.id = cap - k as u64;
    }
    let newest = template.at_unix_ms;
    state
        .entries
        .extend((1..=cap - 3).rev().map(|id| MessageView {
            id,
            at_unix_ms: newest - (cap - 3 - id) * 60_000,
            title: format!("config warning {id}"),
            ..template.clone()
        }));
    for (tag, count) in &mut state.tags {
        if tag == "config" {
            *count = (cap - 3) as usize;
        }
    }
    state
}

/// One render's WORK, counted on this thread through the real code path:
/// the entry rows `messages_head_node` built, and the times it entered the
/// font store (`crate::tray_raster::font_store_visits`) — every text
/// measure enters it once. Counts, not a stopwatch: a loaded machine
/// stretches a render's time but not its work.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct MessagesRenderWork {
    rows: usize,
    font_visits: u64,
}

fn messages_render_work(
    render: impl FnOnce() -> crate::native_ui::CompiledUi,
) -> (crate::native_ui::CompiledUi, MessagesRenderWork) {
    let rows = MESSAGES_ROWS_BUILT.with(Cell::get);
    let font_visits = crate::tray_raster::font_store_visits();
    let compiled = render();
    let work = MessagesRenderWork {
        rows: MESSAGES_ROWS_BUILT.with(Cell::get) - rows,
        font_visits: crate::tray_raster::font_store_visits() - font_visits,
    };
    (compiled, work)
}

/// THE RING AT ITS CAP IS ONE LIST, BUILT ONLY WHERE IT IS SEEN (ruling
/// 264): 512 entries lay out with only the rows the view shows built —
/// the page's semantic tree is the size of the forty-entry log's — at the
/// wide and the compact width; Cmd-End scrolls to the oldest entry, and a
/// deep link to it lands it on the screen, open. The render's WORK is
/// counted, not timed ([`MessagesRenderWork`]): it builds exactly the rows
/// its view shows; an entry out of view costs it nothing, neither a row
/// nor a measured word; and its text work stays within twice the
/// forty-entry page's.
#[test]
fn the_log_at_its_ring_cap_builds_only_the_rows_in_view() {
    // A stopwatch cannot say this: the best of nine timed renders read
    // 25.7 ms at 512 entries beside 6.4 ms at 40 in one loaded
    // merge-contract run, 29 ms beside 5.7 ms in another, where the same
    // build takes 3.8 ms beside 3.1 ms of thread CPU alone — while a lead
    // column that measures every entry's words passed, alone, at 16.4 ms
    // beside 3.6 ms, inside the "twice plus 10 ms" it was held to. Nor can
    // the semantic tree alone: the compiler materializes no clipped
    // subtree in any observer, so rows built and then clipped away — or
    // built and dropped — leave it the same size (both measured
    // 2026-09-27).
    let full = full_ring_messages();
    assert_eq!(full.entries.len(), aterm_messages::LOG_CAP);
    // The same log less its OLDEST entry, which no view below starts at:
    // its time words and its tag are its neighbours', so every row shown
    // and every word the lead column measures are the full ring's.
    let mut less = full.clone();
    let oldest = less.entries.pop().expect("a full ring");
    for (tag, count) in &mut less.tags {
        if *tag == oldest.tag {
            *count -= 1;
        }
    }
    let open = |state: MessagesState| {
        let (mut runtime, instance, view) = setup();
        assert!(runtime.replace_settings_messages(state, 9));
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::Messages),
                    value: None,
                }),
            )
            .unwrap();
        (runtime, instance, view)
    };
    for (width, height) in [(1_200.0, 820.0), (320.0, 568.0)] {
        let cx = view_cx_at(width, height);
        let (small_runtime, small_instance, small_view) = open(sample_messages());
        let (mut runtime, instance, view) = open(full.clone());
        let (less_runtime, less_instance, less_view) = open(less.clone());
        let (small, small_work) = messages_render_work(|| {
            compile_settings_view(&small_runtime, small_instance, small_view, &cx)
        });
        let (big, big_work) =
            messages_render_work(|| compile_settings_view(&runtime, instance, view, &cx));
        let (_, less_work) = messages_render_work(|| {
            compile_settings_view(&less_runtime, less_instance, less_view, &cx)
        });
        crate::logging::stderr_line!(
            "Messages at {width}x{height}: 40 entries {small_work:?} ({} semantic nodes), \
             512 entries {big_work:?} ({} semantic nodes), 511 entries {less_work:?}",
            small.semantics.len(),
            big.semantics.len()
        );
        let rows = message_rows(&big);
        assert!(rows.len() > 1, "{width}: the view shows the log");
        assert_eq!(
            rows.len(),
            message_rows(&small).len(),
            "{width}: the view holds what it held"
        );
        assert!(
            big.semantics.len() <= small.semantics.len() + 2,
            "{width}: the page's semantic tree is the forty-entry log's size: {} vs {}",
            big.semantics.len(),
            small.semantics.len()
        );
        // VIRTUAL: the render built the rows its view shows and no
        // others — not all 512, and none built only to be dropped.
        assert_eq!(
            big_work.rows,
            rows.len(),
            "{width}: the render builds the rows in view, of {} entries",
            full.entries.len()
        );
        // An entry out of view costs the render NOTHING: without the
        // oldest entry the ring renders with the same rows built and the
        // same text measured, so no work grows with the log's length.
        assert_eq!(
            big_work, less_work,
            "{width}: the oldest entry, out of view, costs the render work"
        );
        // What the cap does cost is the lead column's distinct words (a
        // few dozen "N min ago"s, each measured once): 136 font-store
        // entries beside the forty's 109 at 1200 wide, 116 beside 89 at
        // 320 (2026-10-01) — within twice.
        assert!(
            big_work.font_visits <= 2 * small_work.font_visits,
            "{width}: 512 entries measure text {} times, 40 entries {} times",
            big_work.font_visits,
            small_work.font_visits
        );
        assert_eq!(
            big.semantic(&UiKey::new("settings/messages/status"))
                .map(|node| node.label.as_str()),
            Some("512 messages")
        );
        // Cmd-End: the list's end, the oldest entry its last row.
        runtime
            .dispatch(instance, view, AppEvent::ScrollLines(10_000))
            .unwrap();
        let end = compile_settings_view(&runtime, instance, view, &cx);
        assert_eq!(message_rows(&end).last(), Some(&1), "{width}");
        // Home again, then a deep link to the oldest: landed, open.
        runtime
            .dispatch(instance, view, AppEvent::ScrollLines(-10_000))
            .unwrap();
        assert_eq!(messages_view_state(&runtime, view).page_scroll, 0);
        select_message(&mut runtime, instance, view, 1);
        let landed = compile_settings_view(&runtime, instance, view, &cx);
        assert!(message_rows(&landed).contains(&1), "{width}");
        assert!(
            landed
                .semantic(&UiKey::new("settings/messages/row/1/detail/0"))
                .is_some(),
            "{width}: open"
        );
    }
}

